  updated_at
) VALUES
    ('addictive-pulls', 'Addictive pulls', 'The tugs of substance and behavior', 'yogic', 'shadow', E'A pull is not the same as a choice. The distinction matters, because a choice can be reconsidered and a pull can only be waited out or waited for.\n\nThis is an inventory, not an accusation. It looks at what the pull is attached to, what relief is being sought, what it costs, and whether anything so far has made a real difference.', '🕸️', 6, 8, '[{"id":"addict-frequency","type":"choice","prompt":"How often does something pull at you that is hard to refuse?","domain":"frequency","options":[{"label":"Nothing repeats — nothing pulls harder than whatever is next","value":"Nothing repeats — nothing pulls harder than whatever is next","weights":{"none":1,"mild":0,"recurring":0,"compulsive":0}},{"label":"Occasionally, and it passes on its own","value":"Occasionally, and it passes on its own","weights":{"none":0.25,"mild":0.75,"recurring":0,"compulsive":0}},{"label":"A few times a week","value":"A few times a week","weights":{"none":0,"mild":0.5,"recurring":0.5,"compulsive":0}},{"label":"Most days","value":"Most days","weights":{"none":0,"mild":0,"recurring":0.75,"compulsive":0.25}},{"label":"It is the first and last thing on a great many days","value":"It is the first and last thing on a great many days","weights":{"none":0,"mild":0,"recurring":0,"compulsive":1}}]},{"id":"addict-attached","type":"choice","prompt":"What is the pull actually attached to?","domain":"object","options":[{"label":"A substance","value":"A substance","weights":{"none":0.05,"mild":0.3,"recurring":0.55,"compulsive":0.1}},{"label":"Something I do","value":"Something I do","weights":{"none":0,"mild":0.1,"recurring":0.35,"compulsive":0.55}},{"label":"Food","value":"Food","weights":{"none":0.05,"mild":0.35,"recurring":0.45,"compulsive":0.15}},{"label":"Screens and devices","value":"Screens and devices","weights":{"none":0.02,"mild":0.2,"recurring":0.6,"compulsive":0.18}}]},{"id":"addict-relief","type":"choice","prompt":"What relief is being sought?","domain":"function","options":[{"label":"I could not say","value":"I could not say","weights":{"compulsive":0}},{"label":"Something to settle, mostly","value":"Something to settle, mostly","weights":{"compulsive":0.25}},{"label":"To stop a feeling from being felt","value":"To stop a feeling from being felt","weights":{"compulsive":0.5}},{"label":"To get back to a state I can tolerate","value":"To get back to a state I can tolerate","weights":{"compulsive":0.75}},{"label":"To be somewhere else entirely","value":"To be somewhere else entirely","weights":{"compulsive":1}}]},{"id":"addict-negotiated","type":"choice","prompt":"Do you negotiate with it, or does it run on its own?","domain":"agency","options":[{"label":"I decide each time, from somewhere near the inside","value":"I decide each time, from somewhere near the inside","weights":{"mild":0,"recurring":0,"compulsive":0}},{"label":"I decide, but only after a long argument","value":"I decide, but only after a long argument","weights":{"mild":1,"recurring":0,"compulsive":0}},{"label":"It is a negotiation, and the terms keep getting worse","value":"It is a negotiation, and the terms keep getting worse","weights":{"mild":0,"recurring":1,"compulsive":0}},{"label":"I negotiate, and I mostly lose","value":"I negotiate, and I mostly lose","weights":{"mild":0,"recurring":0,"compulsive":0}},{"label":"There is no negotiation — it runs before I am consulted","value":"There is no negotiation — it runs before I am consulted","weights":{"mild":0,"recurring":0,"compulsive":1}}]},{"id":"addict-when","type":"choice","prompt":"When does it happen?","domain":"timing","options":[{"label":"Rarely, and only in particular circumstances","value":"Rarely, and only in particular circumstances","weights":{"mild":0,"recurring":0,"compulsive":0}},{"label":"Mostly in the evenings","value":"Mostly in the evenings","weights":{"mild":1,"recurring":0,"compulsive":0}},{"label":"Whenever a particular feeling arrives","value":"Whenever a particular feeling arrives","weights":{"mild":0,"recurring":1,"compulsive":0}},{"label":"Whenever there is a gap, an uncertainty, or a wait","value":"Whenever there is a gap, an uncertainty, or a wait","weights":{"mild":0,"recurring":0,"compulsive":0}},{"label":"Through the day, in short pulses","value":"Through the day, in short pulses","weights":{"mild":0,"recurring":0,"compulsive":1}}]},{"id":"addict-after","type":"choice","prompt":"What is it like in the hour afterwards?","domain":"aftermath","options":[{"label":"Afterwards I am fine, genuinely fine","value":"Afterwards I am fine, genuinely fine","weights":{"recurring":0}},{"label":"Afterwards I am flat for a while","value":"Afterwards I am flat for a while","weights":{"recurring":0.25}},{"label":"Afterwards there is a stretch of time I do not account for","value":"Afterwards there is a stretch of time I do not account for","weights":{"recurring":0.5}},{"label":"Afterwards I want it again, almost immediately","value":"Afterwards I want it again, almost immediately","weights":{"recurring":0.75}},{"label":"Afterwards the only thing that helps is doing it again","value":"Afterwards the only thing that helps is doing it again","weights":{"recurring":1}}]},{"id":"addict-cost","type":"choice","prompt":"What has it taken from you?","domain":"toll","options":[{"label":"Nothing I have noticed","value":"Nothing I have noticed","weights":{"compulsive":0}},{"label":"Time, mostly, and a few things I have not done","value":"Time, mostly, and a few things I have not done","weights":{"compulsive":0.25}},{"label":"Sleep, attention, or the quality of an ordinary day","value":"Sleep, attention, or the quality of an ordinary day","weights":{"compulsive":0.5}},{"label":"A relationship, a job, or my health","value":"A relationship, a job, or my health","weights":{"compulsive":0.75}},{"label":"Everything the rest of my life is currently arranged around","value":"Everything the rest of my life is currently arranged around","weights":{"compulsive":1}}]},{"id":"addict-help","type":"choice","prompt":"Has anything made a real difference?","domain":"what-worked","options":[{"label":"Nothing has touched it","value":"Nothing has touched it","weights":{"mild":0}},{"label":"Only good days, and good days are not a method","value":"Only good days, and good days are not a method","weights":{"mild":0.25}},{"label":"A few things, each of which worked for a while","value":"A few things, each of which worked for a while","weights":{"mild":0.5}},{"label":"One thing, reliably","value":"One thing, reliably","weights":{"mild":0.75}},{"label":"Yes, and I know exactly what makes it different","value":"Yes, and I know exactly what makes it different","weights":{"mild":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["none","mild","recurring","compulsive"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"none","label":"None","short":"Nothing here has a hold on you","description":"No pull currently runs ahead of your own choosing. This is worth recording precisely because it is easy to lose without noticing, and because it means whatever difficulty is present is coming from somewhere other than a groove.","shadow":"Looking for the pull rather than looking at the cause.","color":"slate","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.2,"body":0.15,"spirit":0.15},"practiceLevels":{"observation":1,"witnessing":1},"tags":["no-pull","uncompelled"]}},{"id":"mild","label":"Mild","short":"A pull that arrives and passes","description":"Something repeats, and it passes, and the passing is genuine. Most of what is available at this stage is not in the pull itself but in the relief it is reaching for, which is usually something that could be had another way.","shadow":"Calling it mild because it has not yet cost enough.","color":"teal","masters":["witnessing","breath"],"calibration":{"dimensions":{"emotion":0.25,"body":0.2,"thought":0.15},"practiceLevels":{"witnessing":1,"breath":1},"tags":["mild","passing"]}},{"id":"recurring","label":"Recurring","short":"The same thing, on a schedule","description":"The pull has a timetable and a set of conditions, which means it is structured rather than random. Structured things can be worked with, and the conditions are usually the most useful thing you have found in a long time.","shadow":"Managing the schedule and calling that the whole of it.","color":"amber","masters":["loop-dissolution","witnessing"],"calibration":{"dimensions":{"emotion":0.3,"body":0.2,"thought":0.2},"practiceLevels":{"loop-dissolution":1,"witnessing":1},"tags":["recurring","scheduled"]}},{"id":"compulsive","label":"Compulsive","short":"It runs ahead of the decision","description":"The mechanism has taken over the timing and the choosing, and what is wanted underneath it has become harder to locate. This is a place for accuracy rather than for self-condemnation: a mechanism that is described precisely is a mechanism that can be worked with.","shadow":"Reading the loss of control as a verdict on the person.","color":"rose","masters":["loop-dissolution","emotional-healing"],"calibration":{"dimensions":{"emotion":0.4,"body":0.25,"thought":0.15},"practiceLevels":{"loop-dissolution":1,"emotional-healing":1},"domainStress":{"state":"emotional-healing"},"tags":["compulsive","narrowed-field"]}}]'::jsonb, '{"loops_to_check":["compulsion","numbing"],"practice_affinity":["loop-dissolution","witnessing"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
