-- Ancestral loops (Loops)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('ancestral-loops', 'Ancestral loops', 'Patterns older than you', 'vedic', 'shadow', E'Some patterns arrive with you. They are not memories — they are dispositions, already installed, running before anyone had a chance to decide anything.\n\nThis looks at one of those patterns: where it came from, who else carries it, what it asks of you, and whether seeing it is in fact the whole of what changes it.', '🕯️', 6, 8, '[{"id":"ancestral-visibility","type":"choice","prompt":"How clearly can you see the pattern that runs through your family?","domain":"perception","options":[{"label":"I can feel something repeating and cannot name it","value":"I can feel something repeating and cannot name it","weights":{"unseen":1,"glimpsed":0,"named":0,"released":0}},{"label":"I have noticed it in myself and in someone older","value":"I have noticed it in myself and in someone older","weights":{"unseen":0.25,"glimpsed":0.75,"named":0,"released":0}},{"label":"I know the pattern and can say what it is in plain words","value":"I know the pattern and can say what it is in plain words","weights":{"unseen":0,"glimpsed":0.5,"named":0.5,"released":0}},{"label":"I can see exactly where it starts and what it is for","value":"I can see exactly where it starts and what it is for","weights":{"unseen":0,"glimpsed":0,"named":0.75,"released":0.25}},{"label":"I have watched it operate, and it no longer operates on me","value":"I have watched it operate, and it no longer operates on me","weights":{"unseen":0,"glimpsed":0,"named":0,"released":1}}]},{"id":"ancestral-source","type":"choice","prompt":"Where does it come from?","domain":"origin","options":[{"label":"I have no idea where it started","value":"I have no idea where it started","weights":{"named":0}},{"label":"I have a strong suspicion about one or two people","value":"I have a strong suspicion about one or two people","weights":{"named":0.25}},{"label":"I know it comes through a particular line of the family","value":"I know it comes through a particular line of the family","weights":{"named":0.5}},{"label":"I can trace it back several generations","value":"I can trace it back several generations","weights":{"named":0.75}},{"label":"I know exactly where it entered, and through what","value":"I know exactly where it entered, and through what","weights":{"named":1}}]},{"id":"ancestral-first","type":"choice","prompt":"When did it first show up in your own life?","domain":"entry","options":[{"label":"I could not point to a first time","value":"I could not point to a first time","weights":{"glimpsed":0}},{"label":"Very early, before I had any words for it","value":"Very early, before I had any words for it","weights":{"glimpsed":0.25}},{"label":"In childhood, in a particular setting","value":"In childhood, in a particular setting","weights":{"glimpsed":0.5}},{"label":"At a particular age, or around a particular event","value":"At a particular age, or around a particular event","weights":{"glimpsed":0.75}},{"label":"I can name the day it started","value":"I can name the day it started","weights":{"glimpsed":1}}]},{"id":"ancestral-others","type":"choice","prompt":"Who else carries it?","domain":"carriers","options":[{"label":"I cannot tell who else has it","value":"I cannot tell who else has it","weights":{"released":0}},{"label":"One person, possibly","value":"One person, possibly","weights":{"released":0.25}},{"label":"A few, though we have never said it out loud","value":"A few, though we have never said it out loud","weights":{"released":0.5}},{"label":"A whole side of the family, unmistakably","value":"A whole side of the family, unmistakably","weights":{"released":0.75}},{"label":"Everyone, and we have all named it","value":"Everyone, and we have all named it","weights":{"released":1}}]},{"id":"ancestral-ask","type":"choice","prompt":"What does it want from you?","domain":"demand","options":[{"label":"I could not say what it wants from me","value":"I could not say what it wants from me","weights":{"named":0}},{"label":"Something about safety, though I would not have put it that way","value":"Something about safety, though I would not have put it that way","weights":{"named":0.25}},{"label":"That I stay alert about a particular kind of thing","value":"That I stay alert about a particular kind of thing","weights":{"named":0.5}},{"label":"That I make a particular choice, over and over","value":"That I make a particular choice, over and over","weights":{"named":0.75}},{"label":"I know precisely what it is asking for","value":"I know precisely what it is asking for","weights":{"named":1}}]},{"id":"ancestral-cost","type":"choice","prompt":"What has it cost?","domain":"toll","options":[{"label":"Nothing I can put a number to","value":"Nothing I can put a number to","weights":{"unseen":0}},{"label":"Small things, repeatedly","value":"Small things, repeatedly","weights":{"unseen":0.25}},{"label":"Chances I took that were not mine to take","value":"Chances I took that were not mine to take","weights":{"unseen":0.5}},{"label":"A relationship, or a decade of work","value":"A relationship, or a decade of work","weights":{"unseen":0.75}},{"label":"Everything I am currently having to undo","value":"Everything I am currently having to undo","weights":{"unseen":1}}]},{"id":"ancestral-repeat","type":"choice","prompt":"How reliably does it run?","domain":"frequency","options":[{"label":"Rarely — a handful of times in a life","value":"Rarely — a handful of times in a life","weights":{"glimpsed":0}},{"label":"Every few years","value":"Every few years","weights":{"glimpsed":0.25}},{"label":"A few times a year","value":"A few times a year","weights":{"glimpsed":0.5}},{"label":"Several times a year, in recognisable situations","value":"Several times a year, in recognisable situations","weights":{"glimpsed":0.75}},{"label":"It is more or less weekly, in one form or another","value":"It is more or less weekly, in one form or another","weights":{"glimpsed":1}}]},{"id":"ancestral-alone","type":"choice","prompt":"Does awareness change it?","domain":"mechanism","options":[{"label":"I do not believe awareness alone can touch it","value":"I do not believe awareness alone can touch it","weights":{"released":0}},{"label":"I think it helps a little","value":"I think it helps a little","weights":{"released":0.25}},{"label":"I think awareness is most of the mechanism","value":"I think awareness is most of the mechanism","weights":{"released":0.5}},{"label":"I think awareness plus deliberate interruption is enough","value":"I think awareness plus deliberate interruption is enough","weights":{"released":0.75}},{"label":"I have watched one stop, and nothing but seeing did it","value":"I have watched one stop, and nothing but seeing did it","weights":{"released":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["unseen","glimpsed","named","released"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"unseen","label":"Unseen","short":"Something repeats and has no name","description":"The pattern is felt as a general heaviness rather than as a pattern. Nothing can be worked with here yet, because there is nothing yet to point at. What is available is the noticing itself, which is quieter than it sounds and does most of the work anyway.","shadow":"Reading the weight as a personal defect.","color":"slate","masters":["witnessing","karma"],"calibration":{"dimensions":{"thought":0.25,"emotion":0.2,"spirit":0.2},"practiceLevels":{"witnessing":1,"karma":1},"tags":["unseen","unnamed"]}},{"id":"glimpsed","label":"Glimpsed","short":"Seen in yourself and in someone older","description":"The pattern is recognisable and has a rough shape. Recognition without a name is the stage where most of the pain sits, because something can be seen but not yet referred to, and it keeps returning unaccounted for.","shadow":"Naming it too early, and stopping there.","color":"rose","masters":["witnessing","loop-dissolution"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.25,"connection":0.15},"practiceLevels":{"witnessing":1,"loop-dissolution":1},"domainStress":{"family":"relationship"},"tags":["glimpsed","recognised"]}},{"id":"named","label":"Named","short":"It has a name, an origin, and a demand","description":"The pattern can be referred to precisely: where it came from, what it wants, and what it costs. This is the point at which it becomes workable material rather than a mood, and the first moment it can be worked with deliberately.","shadow":"The name becoming a place to live.","color":"amber","masters":["loop-dissolution","jnana"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.25,"emotion":0.15},"practiceLevels":{"loop-dissolution":1,"jnana":1},"tags":["named","articulated"]}},{"id":"released","label":"Released","short":"It has been watched all the way through","description":"The pattern has been seen operating, understood, and observed no longer operating — not suppressed, not defeated, simply no longer in charge. What remains is the material itself, available to be used deliberately rather than inherited by default.","shadow":"Freedom from the pattern mistaken for freedom from the past.","color":"indigo","masters":["jnana","loop-dissolution"],"calibration":{"dimensions":{"spirit":0.4,"thought":0.2,"emotion":0.15},"practiceLevels":{"jnana":1,"loop-dissolution":1},"tags":["released","no-longer-operating"]}}]'::jsonb, '{"loops_to_check":["inherited-pattern","generational"],"practice_affinity":["witnessing","karma"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
