-- Anger signature (Heart)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('anger-signature', 'Anger signature', 'The shape of your fire', 'yogic', 'emotion', E'Anger is not the problem. It is a signal with a job, and it arrives for reasons that usually predate the occasion.\n\nThis maps where yours goes: whether it is swallowed, withdrawn into coldness, leaked sideways, said plainly, or turned back at yourself — and what it is actually saying when it shows up. The aim is not to become calmer. It is to find out what the fire is for.', '🔥', 7, 8, '[{"id":"anger-for","type":"choice","prompt":"What is your anger for, when it turns up?","domain":"function","options":[{"label":"To keep me safe","value":"To keep me safe","weights":{"suppressed":1}},{"label":"To get a result","value":"To get a result","weights":{"suppressed":1}},{"label":"To mark a limit I never set out loud","value":"To mark a limit I never set out loud","weights":{"suppressed":1}},{"label":"I do not really know","value":"I do not really know","weights":{"suppressed":1}},{"label":"I have never let myself find out","value":"I have never let myself find out","weights":{"suppressed":1}}]},{"id":"anger-exit","type":"choice","prompt":"How does anger usually get out of you?","domain":"expression","options":[{"label":"It does not get out — I swallow it","value":"It does not get out — I swallow it","weights":{"suppressed":1,"leaked":0,"expressed":0,"transmuted":0}},{"label":"It goes cold — I go quiet and distant","value":"It goes cold — I go quiet and distant","weights":{"suppressed":0.25,"leaked":0.75,"expressed":0,"transmuted":0}},{"label":"It leaks into the small things I say to people","value":"It leaks into the small things I say to people","weights":{"suppressed":0,"leaked":0.5,"expressed":0.5,"transmuted":0}},{"label":"It comes out loudly and directly","value":"It comes out loudly and directly","weights":{"suppressed":0,"leaked":0,"expressed":0.75,"transmuted":0.25}},{"label":"It comes out when it is meant to, and no more than that","value":"It comes out when it is meant to, and no more than that","weights":{"suppressed":0,"leaked":0,"expressed":0,"transmuted":1}}]},{"id":"anger-body","type":"choice","prompt":"Where do you feel it in the body?","domain":"body","options":[{"label":"I do not feel it in my body at all","value":"I do not feel it in my body at all","weights":{"suppressed":1,"leaked":0,"expressed":0,"transmuted":0}},{"label":"Jaw and face","value":"Jaw and face","weights":{"suppressed":0.25,"leaked":0.75,"expressed":0,"transmuted":0}},{"label":"Chest and throat","value":"Chest and throat","weights":{"suppressed":0,"leaked":0.5,"expressed":0.5,"transmuted":0}},{"label":"Stomach and gut","value":"Stomach and gut","weights":{"suppressed":0,"leaked":0,"expressed":0.75,"transmuted":0.25}},{"label":"Everywhere, with nowhere to put it","value":"Everywhere, with nowhere to put it","weights":{"suppressed":0,"leaked":0,"expressed":0,"transmuted":1}}]},{"id":"anger-protects","type":"choice","prompt":"What is it protecting?","domain":"protection","options":[{"label":"Nothing in particular","value":"Nothing in particular","weights":{"suppressed":1}},{"label":"My pride","value":"My pride","weights":{"suppressed":1}},{"label":"My limits","value":"My limits","weights":{"suppressed":1}},{"label":"My people","value":"My people","weights":{"suppressed":1}},{"label":"My sense of what is fair","value":"My sense of what is fair","weights":{"suppressed":1}}]},{"id":"anger-after","type":"choice","prompt":"What is left an hour after it has gone?","domain":"aftermath","options":[{"label":"Shame, and I apologise for having been there at all","value":"Shame, and I apologise for having been there at all","weights":{"suppressed":1,"leaked":0,"expressed":0,"transmuted":0}},{"label":"A long sulk, mostly at myself","value":"A long sulk, mostly at myself","weights":{"suppressed":0.25,"leaked":0.75,"expressed":0,"transmuted":0}},{"label":"Nothing much — it passes","value":"Nothing much — it passes","weights":{"suppressed":0,"leaked":0.5,"expressed":0.5,"transmuted":0}},{"label":"Relief","value":"Relief","weights":{"suppressed":0,"leaked":0,"expressed":0.75,"transmuted":0.25}},{"label":"I feel closer to the person than before","value":"I feel closer to the person than before","weights":{"suppressed":0,"leaked":0,"expressed":0,"transmuted":1}}]},{"id":"anger-inward","type":"choice","prompt":"How much of your anger is aimed at yourself?","domain":"direction","options":[{"label":"I am my own harshest critic","value":"I am my own harshest critic","weights":{"suppressed":1,"leaked":0,"expressed":0,"transmuted":0}},{"label":"Most of it is aimed at me","value":"Most of it is aimed at me","weights":{"suppressed":0.25,"leaked":0.75,"expressed":0,"transmuted":0}},{"label":"Regularly, and not gently","value":"Regularly, and not gently","weights":{"suppressed":0,"leaked":0.5,"expressed":0.5,"transmuted":0}},{"label":"A little self-criticism","value":"A little self-criticism","weights":{"suppressed":0,"leaked":0,"expressed":0.75,"transmuted":0.25}},{"label":"Not at all","value":"Not at all","weights":{"suppressed":0,"leaked":0,"expressed":0,"transmuted":1}}]},{"id":"anger-says","type":"choice","prompt":"What is it actually saying when it appears?","domain":"content","options":[{"label":"I have never asked","value":"I have never asked","weights":{"transmuted":1}},{"label":"I have a rough idea","value":"I have a rough idea","weights":{"transmuted":1}},{"label":"It is a limit I never set out loud","value":"It is a limit I never set out loud","weights":{"transmuted":1}},{"label":"It is a grief I did not finish","value":"It is a grief I did not finish","weights":{"transmuted":1}},{"label":"It is old, and it is not really about now","value":"It is old, and it is not really about now","weights":{"transmuted":1}}]},{"id":"anger-speed","type":"choice","prompt":"How quickly does it escalate?","domain":"intensity","options":[{"label":"It can go from nothing to a great deal in a second","value":"It can go from nothing to a great deal in a second","weights":{"suppressed":1,"leaked":0,"expressed":0,"transmuted":0}},{"label":"A great deal of heat","value":"A great deal of heat","weights":{"suppressed":0.25,"leaked":0.75,"expressed":0,"transmuted":0}},{"label":"Real heat","value":"Real heat","weights":{"suppressed":0,"leaked":0.5,"expressed":0.5,"transmuted":0}},{"label":"Mild irritation","value":"Mild irritation","weights":{"suppressed":0,"leaked":0,"expressed":0.75,"transmuted":0.25}},{"label":"It hardly rises at all","value":"It hardly rises at all","weights":{"suppressed":0,"leaked":0,"expressed":0,"transmuted":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["suppressed","leaked","expressed","transmuted"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"suppressed","label":"Suppressed","short":"It goes in and does not come out","description":"The fire is fully functional and has nowhere to go, which means it is being converted into something else — usually control, fatigue, or a body that is permanently braced. Swallowed anger does not disappear. It changes address.","shadow":"Reading the absence of conflict for peace.","color":"rose","masters":["emotional-healing","body"],"calibration":{"dimensions":{"emotion":0.4,"body":0.3,"thought":0.15},"practiceLevels":{"emotional-healing":2,"body":1},"domainStress":{"state":"emotional-healing"},"tags":["anger-swallowed","inward"]}},{"id":"leaked","label":"Leaked","short":"It comes out sideways and small","description":"The anger is not addressed, so it distributes. It turns up as irritation with people who did not cause it, as short temper, and as a general lowering of the tone of a relationship. The people who receive it are almost never the right recipients.","shadow":"Mistaking the target for the source.","color":"orange","masters":["emotional-healing","relationship"],"calibration":{"dimensions":{"emotion":0.35,"connection":0.3,"action":0.15},"practiceLevels":{"emotional-healing":1,"relationship":1},"domainStress":{"relation":"relationship"},"tags":["anger-leaked","displaced"]}},{"id":"expressed","label":"Expressed","short":"It comes out, and it is said","description":"The signal gets delivered rather than stored. There is a cost in the room while it is happening, and a real reduction in what has to be carried afterwards. This is workable ground for a practice.","shadow":"Volume mistaken for honesty.","color":"teal","masters":["emotional-healing","karma"],"calibration":{"dimensions":{"emotion":0.3,"action":0.25,"connection":0.2},"practiceLevels":{"emotional-healing":1,"karma":1},"tags":["anger-expressed","direct"]}},{"id":"transmuted","label":"Transmuted","short":"It has become fuel","description":"The heat is available to you and it is no longer only a thing that happens to you. It shows up as capacity, as boundary, and as the energy for the work itself. Most people who get here report that the thing they feared turned out to be the thing they were short of.","shadow":"Righteous heat used to settle arguments rather than end them.","color":"amber","masters":["body","witnessing"],"calibration":{"dimensions":{"body":0.3,"emotion":0.25,"spirit":0.25},"practiceLevels":{"body":1,"witnessing":1},"tags":["anger-transmuted","fuel"]}}]'::jsonb, '{"loops_to_check":["anger","resentment"],"practice_affinity":["emotional-healing","body"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
