-- Attachment style (Heart)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('attachment-style', 'Attachment style', 'How you hold on', 'vedic', 'attachment', E'Attachment is a prediction the nervous system makes about how far it can safely reach. It is formed early, usually before there was any choice in it, and it is not a character judgement — it is a strategy that worked once, when the options were smaller.\n\nThese questions ask which strategy you default to when someone gets close enough to matter. There is no prize at the far end of this one. Secure is simply less defended, and being less defended cuts both ways.', '🧲', 7, 7, '[{"id":"attach-independence","type":"choice","prompt":"Someone close to you is doing well and does not need you. What happens?","domain":"proximity","options":[{"label":"I find a reason to step back from it","value":"I find a reason to step back from it","weights":{"avoidant":1,"anxious":0,"disorganised":0,"secure":0}},{"label":"I look for what I could add, or what I might have missed","value":"I look for what I could add, or what I might have missed","weights":{"avoidant":0,"anxious":1,"disorganised":0,"secure":0}},{"label":"I feel relieved and then unsure what to do with myself","value":"I feel relieved and then unsure what to do with myself","weights":{"avoidant":0,"anxious":0,"disorganised":1,"secure":0}},{"label":"I am glad for them, and it costs me nothing to say so","value":"I am glad for them, and it costs me nothing to say so","weights":{"avoidant":0,"anxious":0,"disorganised":0,"secure":1}}]},{"id":"attach-silence","type":"choice","prompt":"When someone you care about goes quiet for a day, how do you handle it?","domain":"contact","options":[{"label":"I leave it entirely alone","value":"I leave it entirely alone","weights":{"anxious":0}},{"label":"I check a few times and say nothing","value":"I check a few times and say nothing","weights":{"anxious":0.25}},{"label":"I read into it and usually keep quiet","value":"I read into it and usually keep quiet","weights":{"anxious":0.5}},{"label":"I ask, and find I needed to","value":"I ask, and find I needed to","weights":{"anxious":0.75}},{"label":"I ask, and I can sit with an ordinary answer","value":"I ask, and I can sit with an ordinary answer","weights":{"anxious":1}}]},{"id":"attach-alone","type":"choice","prompt":"How easy is it to spend an evening alone when you had planned to be with someone?","domain":"withdrawal","options":[{"label":"Very hard — I find a reason not to","value":"Very hard — I find a reason not to","weights":{"avoidant":0}},{"label":"Harder than I would like","value":"Harder than I would like","weights":{"avoidant":0.25}},{"label":"About as expected","value":"About as expected","weights":{"avoidant":0.5}},{"label":"Comfortable","value":"Comfortable","weights":{"avoidant":0.75}},{"label":"I have time alone that I would protect","value":"I have time alone that I would protect","weights":{"avoidant":1}}]},{"id":"attach-rupture","type":"choice","prompt":"A disagreement with someone close lands as what?","domain":"rupture","options":[{"label":"A reason to withdraw, usually a good one","value":"A reason to withdraw, usually a good one","weights":{"avoidant":1,"anxious":0,"disorganised":0,"secure":0}},{"label":"Something to be repaired at once, at almost any cost","value":"Something to be repaired at once, at almost any cost","weights":{"avoidant":0,"anxious":1,"disorganised":0,"secure":0}},{"label":"A mess I cannot hold, and usually make worse by trying","value":"A mess I cannot hold, and usually make worse by trying","weights":{"avoidant":0,"anxious":0,"disorganised":1,"secure":0}},{"label":"Information — usually less serious than it felt in the first minute","value":"Information — usually less serious than it felt in the first minute","weights":{"avoidant":0,"anxious":0,"disorganised":0,"secure":1}}]},{"id":"attach-ask","type":"choice","prompt":"How easily do you say out loud that you want something from someone?","domain":"need","options":[{"label":"I do not say it, and it comes out later as something else","value":"I do not say it, and it comes out later as something else","weights":{"avoidant":1,"anxious":0,"disorganised":0,"secure":0}},{"label":"I say it late, usually once I have already decided what it means","value":"I say it late, usually once I have already decided what it means","weights":{"avoidant":0.25,"anxious":0.75,"disorganised":0,"secure":0}},{"label":"I ask while I am still annoyed, and notice the tone afterwards","value":"I ask while I am still annoyed, and notice the tone afterwards","weights":{"avoidant":0,"anxious":0.5,"disorganised":0.5,"secure":0}},{"label":"I ask, and I can stay in the conversation even if the answer is no","value":"I ask, and I can stay in the conversation even if the answer is no","weights":{"avoidant":0,"anxious":0,"disorganised":0.75,"secure":0.25}},{"label":"I say what I want while it is still happening, plainly","value":"I say what I want while it is still happening, plainly","weights":{"avoidant":0,"anxious":0,"disorganised":0,"secure":1}}]},{"id":"attach-load","type":"choice","prompt":"When you are under a lot of pressure, what changes first?","domain":"load","options":[{"label":"I stop telling people anything at all","value":"I stop telling people anything at all","weights":{"avoidant":1}},{"label":"I start checking, and needing more reassurance than is reasonable","value":"I start checking, and needing more reassurance than is reasonable","weights":{"anxious":1}},{"label":"Both at once, and I lose track of which one is running","value":"Both at once, and I lose track of which one is running","weights":{"disorganised":1}},{"label":"I get clearer and more direct, not less","value":"I get clearer and more direct, not less","weights":{"secure":1}}]},{"id":"attach-repair","type":"choice","prompt":"After a small falling-out, how soon are things ordinary again?","domain":"repair","options":[{"label":"It is not — I let it sit","value":"It is not — I let it sit","weights":{"secure":0}},{"label":"I apologise and leave it there","value":"I apologise and leave it there","weights":{"secure":0.25}},{"label":"We talk about it once and it settles","value":"We talk about it once and it settles","weights":{"secure":0.5}},{"label":"We can talk about it properly","value":"We can talk about it properly","weights":{"secure":0.75}},{"label":"I can take my own part of it without collapsing","value":"I can take my own part of it without collapsing","weights":{"secure":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["avoidant","anxious","disorganised","secure"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"avoidant","label":"Averaging","short":"Distance does the work","description":"You widen the gap when it gets narrow. This reads as independence from the outside and is often genuinely useful — but the widening tends to happen before the closeness becomes uncomfortable, which means it is already underway by the time you notice it.","shadow":"Calling the withdrawal freedom and never rechecking it.","color":"slate","masters":["observation","self-inquiry"],"calibration":{"dimensions":{"connection":0.35,"emotion":0.25,"thought":0.15},"practiceLevels":{"observation":1,"self-inquiry":1},"domainStress":{"intimacy":"relationship"},"tags":["avoidant","self-sufficient"]}},{"id":"anxious","label":"Reaching","short":"Contact is reassurance","description":"You reach when the signal goes quiet, and the reaching is not really about the other person — it is about lowering an internal alarm. The effort involved in a relationship like this is substantial and is almost entirely invisible to the person on the other side.","shadow":"Reading the alarm as information about them.","color":"rose","masters":["breath","emotional-healing"],"calibration":{"dimensions":{"emotion":0.4,"connection":0.3,"body":0.15},"practiceLevels":{"breath":1,"emotional-healing":1},"domainStress":{"intimacy":"relationship"},"tags":["anxious","reassurance-seeking"]}},{"id":"disorganised","label":"Unsteady","short":"Nobody is clearly holding it","description":"Both strategies run, and neither finishes. You can pull back and reach within the same conversation, and the switching tends to arrive with a body that has already gone somewhere the words have not caught up with.","shadow":"Treating the oscillation as something to decide about.","color":"orange","masters":["witnessing","emotional-healing"],"calibration":{"dimensions":{"emotion":0.35,"body":0.25,"connection":0.2},"practiceLevels":{"witnessing":2,"emotional-healing":1},"domainStress":{"intimacy":"relationship"},"tags":["disorganised","switching"]}},{"id":"secure","label":"Held","short":"Close, and not gripping","description":"You can be close without monitoring, and apart without interpreting. This is partly temperament and partly accumulated experience, and both parts are trainable — the first thing that gets easier is noticing how rarely you are bracing.","shadow":"Comfort enough to stop checking on the people you are with.","color":"teal","masters":["relationship","witnessing"],"calibration":{"dimensions":{"connection":0.3,"emotion":0.2,"spirit":0.2},"practiceLevels":{"relationship":1,"witnessing":1},"tags":["secure","unbraced"]}}]'::jsonb, '{"loops_to_check":["avoidance","approval-seeking","conflict-avoidance"],"practice_affinity":["relationship","witnessing"],"deepens_with":["inner-council","relationship-roles","inner-child"]}'::jsonb, 1, true, false, 100, now())
