-- Attention diet (Welcome)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('attention-diet', 'Attention diet', 'What you consume becomes what you are', 'yogic', 'attention', E'Traditions use the word diet deliberately. Attention behaves like food: it is consumed, it has a residue, and what you take in repeatedly becomes the texture of the mind.\n\nThis is not about guilt. It is about looking at what you actually take in, because most of it was never chosen.', '📡', 6, 8, '[{"id":"diet-input","type":"choice","prompt":"What takes the largest share of your attention on a normal day?","domain":"input","options":[{"label":"My phone and messages","value":"My phone and messages","weights":{"stimulant":1}},{"label":"Work and tasks","value":"Work and tasks","weights":{"stimulant":1}},{"label":"Other people’s problems","value":"Other people’s problems","weights":{"stimulant":1}},{"label":"News and what is happening","value":"News and what is happening","weights":{"stimulant":1}},{"label":"My own thinking","value":"My own thinking","weights":{"stimulant":1}}]},{"id":"diet-chosen","type":"choice","prompt":"How much of what you take in did you actually choose?","domain":"input","options":[{"label":"Almost none of it","value":"Almost none of it","weights":{"scattered":1,"stimulant":0,"absorbed":0,"sustained":0}},{"label":"Very little","value":"Very little","weights":{"scattered":0.25,"stimulant":0.75,"absorbed":0,"sustained":0}},{"label":"A bit","value":"A bit","weights":{"scattered":0,"stimulant":0.5,"absorbed":0.5,"sustained":0}},{"label":"A fair amount","value":"A fair amount","weights":{"scattered":0,"stimulant":0,"absorbed":0.75,"sustained":0.25}},{"label":"Nearly all of it","value":"Nearly all of it","weights":{"scattered":0,"stimulant":0,"absorbed":0,"sustained":1}}]},{"id":"diet-residue","type":"choice","prompt":"After a few hours of input, do you feel more alive or more flat?","domain":"input","options":[{"label":"Completely flat","value":"Completely flat","weights":{"scattered":1,"stimulant":0,"absorbed":0,"sustained":0}},{"label":"Flatter than I would like","value":"Flatter than I would like","weights":{"scattered":0.25,"stimulant":0.75,"absorbed":0,"sustained":0}},{"label":"About the same","value":"About the same","weights":{"scattered":0,"stimulant":0.5,"absorbed":0.5,"sustained":0}},{"label":"Brighter","value":"Brighter","weights":{"scattered":0,"stimulant":0,"absorbed":0.75,"sustained":0.25}},{"label":"Genuinely energised","value":"Genuinely energised","weights":{"scattered":0,"stimulant":0,"absorbed":0,"sustained":1}}]},{"id":"diet-length","type":"choice","prompt":"How long is your attention before it needs a new input?","domain":"input","options":[{"label":"Under a minute","value":"Under a minute","weights":{"sustained":0}},{"label":"A few minutes","value":"A few minutes","weights":{"sustained":0}},{"label":"Twenty minutes or so","value":"Twenty minutes or so","weights":{"sustained":0}},{"label":"An hour","value":"An hour","weights":{"sustained":0}},{"label":"I can sit with something a long time","value":"I can sit with something a long time","weights":{"sustained":1}}]},{"id":"diet-nostalgia","type":"choice","prompt":"How much of what you consume is about feeling a feeling rather than learning a thing?","domain":"input","options":[{"label":"Almost all of it","value":"Almost all of it","weights":{"scattered":1,"stimulant":0,"absorbed":0,"sustained":0}},{"label":"Most of it","value":"Most of it","weights":{"scattered":0.25,"stimulant":0.75,"absorbed":0,"sustained":0}},{"label":"A fair amount","value":"A fair amount","weights":{"scattered":0,"stimulant":0.5,"absorbed":0.5,"sustained":0}},{"label":"Some","value":"Some","weights":{"scattered":0,"stimulant":0,"absorbed":0.75,"sustained":0.25}},{"label":"Very little","value":"Very little","weights":{"scattered":0,"stimulant":0,"absorbed":0,"sustained":1}}]},{"id":"diet-silence","type":"choice","prompt":"How much of your day is spent with no input at all?","domain":"input","options":[{"label":"None at all","value":"None at all","weights":{"scattered":1,"stimulant":0,"absorbed":0,"sustained":0}},{"label":"Very little","value":"Very little","weights":{"scattered":0.25,"stimulant":0.75,"absorbed":0,"sustained":0}},{"label":"A few minutes","value":"A few minutes","weights":{"scattered":0,"stimulant":0.5,"absorbed":0.5,"sustained":0}},{"label":"Maybe an hour","value":"Maybe an hour","weights":{"scattered":0,"stimulant":0,"absorbed":0.75,"sustained":0.25}},{"label":"Real periods of it","value":"Real periods of it","weights":{"scattered":0,"stimulant":0,"absorbed":0,"sustained":1}}]},{"id":"diet-taste","type":"choice","prompt":"If your attention were a diet, would you call it nourishing or mostly filling?","domain":"input","options":[{"label":"Mostly filling","value":"Mostly filling","weights":{"scattered":1,"stimulant":0,"absorbed":0,"sustained":0}},{"label":"Mostly filling, with some nourishment","value":"Mostly filling, with some nourishment","weights":{"scattered":0.25,"stimulant":0.75,"absorbed":0,"sustained":0}},{"label":"About half and half","value":"About half and half","weights":{"scattered":0,"stimulant":0.5,"absorbed":0.5,"sustained":0}},{"label":"Mostly nourishing","value":"Mostly nourishing","weights":{"scattered":0,"stimulant":0,"absorbed":0.75,"sustained":0.25}},{"label":"Genuinely nourishing","value":"Genuinely nourishing","weights":{"scattered":0,"stimulant":0,"absorbed":0,"sustained":1}}]},{"id":"diet-keep","type":"choice","prompt":"If you could only keep one kind of input, which would it be?","domain":"input","options":[{"label":"Whatever is loudest at the time","value":"Whatever is loudest at the time","weights":{"scattered":1,"stimulant":0,"absorbed":0,"sustained":0}},{"label":"Something to fill a gap with","value":"Something to fill a gap with","weights":{"scattered":0.25,"stimulant":0.75,"absorbed":0,"sustained":0}},{"label":"Something I actually take something from","value":"Something I actually take something from","weights":{"scattered":0,"stimulant":0.5,"absorbed":0.5,"sustained":0}},{"label":"Something I would genuinely miss","value":"Something I would genuinely miss","weights":{"scattered":0,"stimulant":0,"absorbed":0.75,"sustained":0.25}},{"label":"The only one I would keep","value":"The only one I would keep","weights":{"scattered":0,"stimulant":0,"absorbed":0,"sustained":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["scattered","stimulant","absorbed","sustained"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"scattered","label":"Scattered","short":"Attention is being taken more than given","description":"Your attention is responsive rather than directed — the environment decides where it goes. This is a trainable condition, not a fixed trait, and it responds quickly to structured input changes.","shadow":"Believing you have no attention to spare.","color":"rose","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.4,"spirit":0.2,"body":0.1},"practiceLevels":{"observation":2,"witnessing":1},"domainStress":{"attention":"observation"},"tags":["scattered","stimulus-driven"]}},{"id":"stimulant","label":"Stimulant-fed","short":"Reaching for a jolt more often than rest","description":"Input is being used to manage how you feel rather than to feed your curiosity. It works, and it costs more than it appears to.","shadow":"Calling the jolt focus.","color":"orange","masters":["breath","witnessing"],"calibration":{"dimensions":{"emotion":0.3,"thought":0.25,"body":0.15},"practiceLevels":{"breath":1,"witnessing":1},"domainStress":{"attention":"observation"},"tags":["stimulant","numb"]}},{"id":"absorbed","label":"Absorbed","short":"Taking in a lot, retaining a little","description":"The volume of input is high and the residue is thin. You finish much of what you start and keep very little of it, which is a retention problem more than a volume problem.","shadow":"Confusing consumption with study.","color":"amber","masters":["observation","jnana"],"calibration":{"dimensions":{"thought":0.3,"spirit":0.15},"practiceLevels":{"observation":1,"jnana":1},"tags":["consumer","low-retention"]}},{"id":"sustained","label":"Sustained","short":"You feed attention and it feeds you back","description":"You have a real diet and you choose it. Input is doing work for you rather than against you, and you know the difference between the two.","shadow":"Rigidity, when the diet stops being examined.","color":"emerald","masters":["witnessing","jnana"],"calibration":{"dimensions":{"thought":0.2,"spirit":0.3,"emotion":0.15},"practiceLevels":{"witnessing":2,"jnana":1},"tags":["disciplined","focused"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["observation","witnessing"],"deepens_with":["silence-tolerance","mind-wandering"]}'::jsonb, 1, true, false, 100, now())
