  updated_at
) VALUES
    ('authenticity-index', 'Authenticity index', 'The gap between self and act', 'yogic', 'shadow', E'Karma yoga asks a plain question about every act: was this done for the sake of the act, or for the sake of what the act produces for the one doing it.\n\nThis measures the gap between what is wanted and what is done, and asks whether the gap is noticed, whether plainness ever costs anything, and whether authenticity is a value or a reflex.', '🎯', 6, 8, '[{"id":"auth-gap","type":"choice","prompt":"How much of what you do is not what you would have chosen?","domain":"gap","options":[{"label":"There is no gap — what is wanted and what is done are the same thing","value":"There is no gap — what is wanted and what is done are the same thing","weights":{"performed":0}},{"label":"A small gap","value":"A small gap","weights":{"performed":0.25}},{"label":"A gap that is often noticeable","value":"A gap that is often noticeable","weights":{"performed":0.5}},{"label":"A large gap","value":"A large gap","weights":{"performed":0.75}},{"label":"Most of what I do is not what I would choose","value":"Most of what I do is not what I would choose","weights":{"performed":1}}]},{"id":"auth-motive","type":"choice","prompt":"What usually decides what you do?","domain":"driver","options":[{"label":"What other people will make of it","value":"What other people will make of it","weights":{"performed":1}},{"label":"What was expected of me in this situation","value":"What was expected of me in this situation","weights":{"compliant":1}},{"label":"What I would actually choose","value":"What I would actually choose","weights":{"mostly-real":1}},{"label":"What the moment itself seemed to ask for","value":"What the moment itself seemed to ask for","weights":{"unforced":1}}]},{"id":"auth-noticed","type":"choice","prompt":"Do you notice the gap as it opens?","domain":"awareness","options":[{"label":"I catch it as it is happening","value":"I catch it as it is happening","weights":{"compliant":0}},{"label":"Often, just after","value":"Often, just after","weights":{"compliant":0.25}},{"label":"Sometimes, when something makes it obvious","value":"Sometimes, when something makes it obvious","weights":{"compliant":0.5}},{"label":"Rarely — I usually see it only in the results","value":"Rarely — I usually see it only in the results","weights":{"compliant":0.75}},{"label":"It runs, and I only find out much later","value":"It runs, and I only find out much later","weights":{"compliant":1}}]},{"id":"auth-cost","type":"choice","prompt":"How often does being straightforward actually cost you?","domain":"price","options":[{"label":"Every single time — plainness is genuinely unsafe here","value":"Every single time — plainness is genuinely unsafe here","weights":{"compliant":0,"mostly-real":0,"unforced":0}},{"label":"Most times","value":"Most times","weights":{"compliant":1,"mostly-real":0,"unforced":0}},{"label":"Sometimes, and usually only socially","value":"Sometimes, and usually only socially","weights":{"compliant":0,"mostly-real":0,"unforced":0}},{"label":"Rarely, and never for long","value":"Rarely, and never for long","weights":{"compliant":0,"mostly-real":1,"unforced":0}},{"label":"Never — being direct is always safe","value":"Never — being direct is always safe","weights":{"compliant":0,"mostly-real":0,"unforced":1}}]},{"id":"auth-practice","type":"choice","prompt":"What does being real actually look like for you?","domain":"form","options":[{"label":"I would not know where to start","value":"I would not know where to start","weights":{"performed":1}},{"label":"I manage it in a few situations I have practised","value":"I manage it in a few situations I have practised","weights":{"compliant":1}},{"label":"I do it when I remember to","value":"I do it when I remember to","weights":{"mostly-real":1}},{"label":"It is simply how I act, most of the time","value":"It is simply how I act, most of the time","weights":{"unforced":1}}]},{"id":"auth-value","type":"choice","prompt":"Is this a principle you hold, or something that happens to you?","domain":"reflex","options":[{"label":"I say it matters and rarely act on it","value":"I say it matters and rarely act on it","weights":{"unforced":0}},{"label":"I try to live it in the big things","value":"I try to live it in the big things","weights":{"unforced":0.25}},{"label":"I live it deliberately, when I am paying attention","value":"I live it deliberately, when I am paying attention","weights":{"unforced":0.5}},{"label":"It has become natural rather than a rule","value":"It has become natural rather than a rule","weights":{"unforced":0.75}},{"label":"It is not a principle at all, just what happens","value":"It is not a principle at all, just what happens","weights":{"unforced":1}}]},{"id":"auth-body","type":"choice","prompt":"What does the body do when you act against what you want?","domain":"signal","options":[{"label":"Nothing physical at all","value":"Nothing physical at all","weights":{"performed":0}},{"label":"A slight signal, easy to miss","value":"A slight signal, easy to miss","weights":{"performed":0.25}},{"label":"Tension, but familiar enough to ignore","value":"Tension, but familiar enough to ignore","weights":{"performed":0.5}},{"label":"A strong push, hard to argue with","value":"A strong push, hard to argue with","weights":{"performed":0.75}},{"label":"A surge that overrides everything else in the room","value":"A surge that overrides everything else in the room","weights":{"performed":1}}]},{"id":"auth-yes","type":"choice","prompt":"How often do you agree to something you do not want?","domain":"agreement","options":[{"label":"Never, or almost never","value":"Never, or almost never","weights":{"compliant":0}},{"label":"Rarely","value":"Rarely","weights":{"compliant":0.25}},{"label":"Sometimes","value":"Sometimes","weights":{"compliant":0.5}},{"label":"Most times","value":"Most times","weights":{"compliant":0.75}},{"label":"Almost every time, and I resent it afterwards","value":"Almost every time, and I resent it afterwards","weights":{"compliant":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["performed","compliant","mostly-real","unforced"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"performed","label":"Performed","short":"The act is produced for the room","description":"A large share of what is done is done for its effect on others, and the split between wanting and doing is wide. This is expensive in energy, because each act has to be manufactured rather than drawn on — and it is also the place where self-knowledge has the most to give.","shadow":"Reading the effect as the point.","color":"rose","masters":["karma","self-inquiry"],"calibration":{"dimensions":{"connection":0.3,"action":0.2,"emotion":0.15},"practiceLevels":{"karma":1,"self-inquiry":1},"domainStress":{"contact":"relationship"},"tags":["performed","outward-directed"]}},{"id":"compliant","label":"Compliant","short":"The yes arrives before the want","description":"Agreement is given quickly and examined later, so the gap is usually discovered after the fact. The material here is speed — almost all of the available change sits in the interval between wanting and answering.","shadow":"Mistaking ease for consent.","color":"orange","masters":["karma","witnessing"],"calibration":{"dimensions":{"action":0.3,"connection":0.2,"thought":0.15},"practiceLevels":{"karma":1,"witnessing":1},"tags":["compliant","reactive-consent"]}},{"id":"mostly-real","label":"Mostly real","short":"What is done usually matches what is wanted","description":"The gap is small and gets noticed when it appears. This is the workable middle of the range: enough alignment for actions to feel like yours, enough gap to stay alert about the moments where they are not.","shadow":"Complacency in the moments that work.","color":"teal","masters":["karma","raja"],"calibration":{"dimensions":{"action":0.25,"connection":0.2,"spirit":0.15},"practiceLevels":{"karma":1},"tags":["mostly-real","aligned"]}},{"id":"unforced","label":"Unforced","short":"The act is not driving itself","description":"What is done comes from the moment rather than from an expectation of it, which usually means less deliberation and less residue. Worth watching: when nothing drives the act, the choice of whether to act at all becomes the live question.","shadow":"Spontaneity used to avoid the harder, deliberate act.","color":"emerald","masters":["karma","self-inquiry"],"calibration":{"dimensions":{"action":0.2,"spirit":0.3,"connection":0.15},"practiceLevels":{"karma":1,"self-inquiry":1},"tags":["unforced","non-coercive"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["karma","self-inquiry"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
