-- Avoidance map (Loops)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('avoidance-map', 'Avoidance map', 'What you keep walking around', 'yogic', 'shadow', E'The mind is very good at arranging the day so that one particular question never has to be answered. It does this so smoothly that the arranging is usually invisible.\n\nThis is a map of what is being walked around, what the walking costs, what is on the other side of it, and the arithmetic that is currently running underneath.', '🔄', 6, 8, '[{"id":"avoid-clarity","type":"choice","prompt":"How clearly do you know what you are not looking at?","domain":"clarity","options":[{"label":"I do not even know what it is","value":"I do not even know what it is","weights":{"unaware":1,"named":0,"scheduled":0,"entered":0}},{"label":"I know roughly what it is and keep it at arm’s length","value":"I know roughly what it is and keep it at arm’s length","weights":{"unaware":0,"named":0,"scheduled":0,"entered":0}},{"label":"I can name it precisely, and I do not go there","value":"I can name it precisely, and I do not go there","weights":{"unaware":0,"named":1,"scheduled":0,"entered":0}},{"label":"I have put time aside to face it","value":"I have put time aside to face it","weights":{"unaware":0,"named":0,"scheduled":1,"entered":0}},{"label":"I have been into it, more than once","value":"I have been into it, more than once","weights":{"unaware":0,"named":0,"scheduled":0,"entered":1}}]},{"id":"avoid-form","type":"choice","prompt":"What does the avoiding actually look like day to day?","domain":"shape","options":[{"label":"I would not call it avoidance — it is simply how things go","value":"I would not call it avoidance — it is simply how things go","weights":{"unaware":0,"named":0,"scheduled":0,"entered":0}},{"label":"I stay busy so that the question does not come up","value":"I stay busy so that the question does not come up","weights":{"unaware":1,"named":0,"scheduled":0,"entered":0}},{"label":"I know I am doing it, and I keep doing it","value":"I know I am doing it, and I keep doing it","weights":{"unaware":0,"named":1,"scheduled":0,"entered":0}},{"label":"I put it in the diary, and move it when the day arrives","value":"I put it in the diary, and move it when the day arrives","weights":{"unaware":0,"named":0,"scheduled":1,"entered":0}},{"label":"I go in deliberately, and stay for as long as it takes","value":"I go in deliberately, and stay for as long as it takes","weights":{"unaware":0,"named":0,"scheduled":0,"entered":1}}]},{"id":"avoid-fear","type":"choice","prompt":"What is on the other side of it?","domain":"far-side","options":[{"label":"I could not say","value":"I could not say","weights":{"named":0}},{"label":"That it will be as bad as I think","value":"That it will be as bad as I think","weights":{"named":0.25}},{"label":"That I will not know what to do once I am there","value":"That I will not know what to do once I am there","weights":{"named":0.5}},{"label":"That it will change something I cannot change back","value":"That it will change something I cannot change back","weights":{"named":0.75}},{"label":"I have been through it, and it was survivable","value":"I have been through it, and it was survivable","weights":{"named":1}}]},{"id":"avoid-if","type":"choice","prompt":"What happens if you go there?","domain":"approach","options":[{"label":"Something explodes, or I leave and do not return","value":"Something explodes, or I leave and do not return","weights":{"scheduled":0}},{"label":"I freeze, or find a reason to stop","value":"I freeze, or find a reason to stop","weights":{"scheduled":0.25}},{"label":"I go, and it is uncomfortable, and ordinary","value":"I go, and it is uncomfortable, and ordinary","weights":{"scheduled":0.5}},{"label":"I go, and something useful happens","value":"I go, and something useful happens","weights":{"scheduled":0.75}},{"label":"I go, and it is mostly fine","value":"I go, and it is mostly fine","weights":{"scheduled":1}}]},{"id":"avoid-cost","type":"choice","prompt":"What is the avoidance costing you?","domain":"running-cost","options":[{"label":"The bill is smaller than the thing itself would be","value":"The bill is smaller than the thing itself would be","weights":{"unaware":0}},{"label":"They are about the same","value":"They are about the same","weights":{"unaware":0.25}},{"label":"The bill is somewhat larger","value":"The bill is somewhat larger","weights":{"unaware":0.5}},{"label":"The bill is much larger","value":"The bill is much larger","weights":{"unaware":0.75}},{"label":"I can no longer compare — the bill is all there is","value":"I can no longer compare — the bill is all there is","weights":{"unaware":1}}]},{"id":"avoid-repeat","type":"choice","prompt":"How wide is the avoided area?","domain":"scope","options":[{"label":"It is one particular situation","value":"It is one particular situation","weights":{"unaware":0}},{"label":"A category of situations","value":"A category of situations","weights":{"unaware":0.25}},{"label":"Something in me that most situations touch","value":"Something in me that most situations touch","weights":{"unaware":0.5}},{"label":"Almost everything of a certain kind","value":"Almost everything of a certain kind","weights":{"unaware":0.75}},{"label":"Nearly all of it","value":"Nearly all of it","weights":{"unaware":1}}]},{"id":"avoid-others","type":"choice","prompt":"What happens when someone else goes there?","domain":"company","options":[{"label":"They are not allowed to either","value":"They are not allowed to either","weights":{"named":0,"scheduled":0,"entered":0}},{"label":"They do it, and I keep quiet","value":"They do it, and I keep quiet","weights":{"named":1,"scheduled":0,"entered":0}},{"label":"We approach it together, carefully","value":"We approach it together, carefully","weights":{"named":0,"scheduled":0,"entered":0}},{"label":"We can talk about it directly now","value":"We can talk about it directly now","weights":{"named":0,"scheduled":1,"entered":0}},{"label":"It is entirely ordinary between us","value":"It is entirely ordinary between us","weights":{"named":0,"scheduled":0,"entered":1}}]},{"id":"avoid-signal","type":"choice","prompt":"How does the body react when you are near it?","domain":"body","options":[{"label":"Nothing physical at all — only a preference","value":"Nothing physical at all — only a preference","weights":{"named":0}},{"label":"A slight heaviness in the chest","value":"A slight heaviness in the chest","weights":{"named":0.25}},{"label":"Tension in the shoulders or jaw","value":"Tension in the shoulders or jaw","weights":{"named":0.5}},{"label":"A distinct physical avoidance — the body simply does not go there","value":"A distinct physical avoidance — the body simply does not go there","weights":{"named":0.75}},{"label":"The whole system reorganises to get me out of it","value":"The whole system reorganises to get me out of it","weights":{"named":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["unaware","named","scheduled","entered"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"unaware","label":"Unaware","short":"Something is being avoided and not registered","description":"The arrangement is not being made consciously, which means there is no target to aim at and no way of knowing how large the cost has become. The useful move is naming, not resolution — a name makes the rest of the map possible.","shadow":"Treating the current arrangement as the only arrangement.","color":"slate","masters":["observation","self-inquiry"],"calibration":{"dimensions":{"thought":0.25,"action":0.2,"emotion":0.2},"practiceLevels":{"observation":1,"self-inquiry":1},"tags":["unaware","unmapped"]}},{"id":"named","label":"Named","short":"It has a name and it stays at arm’s length","description":"The thing is identified and still not approached. This is an honest and common position, and it is where most of the wasted effort accumulates, because a name that is never used for anything tends to be renamed as insight.","shadow":"Confusing the naming with the arriving.","color":"rose","masters":["self-inquiry","loop-dissolution"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.25,"action":0.15},"practiceLevels":{"self-inquiry":1,"loop-dissolution":1},"tags":["named","circling"]}},{"id":"scheduled","label":"Scheduled","short":"It has a place in the diary","description":"The avoidance has become an appointment rather than a background process. Time is being held open for it, which means the structure is already in place and what is left is attendance.","shadow":"Rescheduling as a way of not having to find out.","color":"amber","masters":["loop-dissolution","raja"],"calibration":{"dimensions":{"action":0.3,"thought":0.2,"emotion":0.2},"practiceLevels":{"loop-dissolution":1,"raja":1},"tags":["scheduled","held-open"]}},{"id":"entered","label":"Entered","short":"It has been approached, more than once","description":"The avoided material has been faced deliberately and repeatedly, and the fog has thinned. What is left on the other side is usually specific and much smaller than the shape it was given in the imagination.","shadow":"Making a practice out of the approach itself.","color":"teal","masters":["loop-dissolution","jnana"],"calibration":{"dimensions":{"spirit":0.3,"action":0.2,"emotion":0.2},"practiceLevels":{"loop-dissolution":1,"jnana":1},"tags":["entered","approached"]}}]'::jsonb, '{"loops_to_check":["avoidance","distraction"],"practice_affinity":["loop-dissolution","self-inquiry"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
