  sort_order,
  updated_at
) VALUES
    ('awe-frequency', 'Awe frequency', 'How often wonder finds you', NULL, 'spirit', E'Awe is the feeling that something is larger than you and you are nonetheless part of it. Most people have it as a visitor rather than a resident.\n\nThe question is not whether you feel it. It is whether you can call it.', '✨', 5, 6, '[{"id":"awe-how","type":"choice","prompt":"How often do you feel genuinely awed?","domain":"frequency","options":[{"label":"Almost never","value":"Almost never","weights":{"rare":0,"occasional":0,"regular":0,"constant":0}},{"label":"A few times a year","value":"A few times a year","weights":{"rare":1,"occasional":0,"regular":0,"constant":0}},{"label":"A few times a month","value":"A few times a month","weights":{"rare":0,"occasional":1,"regular":0,"constant":0}},{"label":"Most weeks, in small ways","value":"Most weeks, in small ways","weights":{"rare":0,"occasional":0,"regular":1,"constant":0}},{"label":"It is close to the default state","value":"It is close to the default state","weights":{"rare":0,"occasional":0,"regular":0,"constant":1}}]},{"id":"awe-trigger","type":"choice","prompt":"What brings it, when it comes?","domain":"source","options":[{"label":"I could not say — it just happens","value":"I could not say — it just happens","weights":{"occasional":1}},{"label":"Nature, mostly","value":"Nature, mostly","weights":{"occasional":1}},{"label":"Music or art","value":"Music or art","weights":{"occasional":1}},{"label":"Other people","value":"Other people","weights":{"occasional":1}},{"label":"Scale — the size or the smallness of something","value":"Scale — the size or the smallness of something","weights":{"occasional":1}}]},{"id":"awe-call","type":"choice","prompt":"Can you bring it on deliberately?","domain":"invitation","options":[{"label":"Not at all","value":"Not at all","weights":{"rare":1,"occasional":0,"regular":0,"constant":0}},{"label":"Rarely, and by accident","value":"Rarely, and by accident","weights":{"rare":0.25,"occasional":0.75,"regular":0,"constant":0}},{"label":"Sometimes, with the right setting","value":"Sometimes, with the right setting","weights":{"rare":0,"occasional":0.5,"regular":0.5,"constant":0}},{"label":"Fairly reliably","value":"Fairly reliably","weights":{"rare":0,"occasional":0,"regular":0.75,"constant":0.25}},{"label":"I can get there fairly deliberately","value":"I can get there fairly deliberately","weights":{"rare":0,"occasional":0,"regular":0,"constant":1}}]},{"id":"awe-disappear","type":"choice","prompt":"What makes it go away?","domain":"fading","options":[{"label":"Getting used to it","value":"Getting used to it","weights":{"regular":1}},{"label":"Interrupting me","value":"Interrupting me","weights":{"regular":1}},{"label":"Crowds or noise","value":"Crowds or noise","weights":{"regular":1}},{"label":"My own thoughts","value":"My own thoughts","weights":{"regular":1}},{"label":"Nothing, once it is there it stays a while","value":"Nothing, once it is there it stays a while","weights":{"regular":1}}]},{"id":"awe-trend","type":"choice","prompt":"Is it happening more or less than it used to?","domain":"direction","options":[{"label":"Much less than it used to","value":"Much less than it used to","weights":{"rare":1,"occasional":0,"regular":0,"constant":0}},{"label":"Somewhat less","value":"Somewhat less","weights":{"rare":0.25,"occasional":0.75,"regular":0,"constant":0}},{"label":"About the same","value":"About the same","weights":{"rare":0,"occasional":0.5,"regular":0.5,"constant":0}},{"label":"Somewhat more","value":"Somewhat more","weights":{"rare":0,"occasional":0,"regular":0.75,"constant":0.25}},{"label":"Far more than it used to","value":"Far more than it used to","weights":{"rare":0,"occasional":0,"regular":0,"constant":1}}]},{"id":"awe-shared","type":"choice","prompt":"Do you say it out loud, or keep it to yourself?","domain":"communication","options":[{"label":"I keep it entirely to myself","value":"I keep it entirely to myself","weights":{"constant":1}},{"label":"Rarely — it feels like too much","value":"Rarely — it feels like too much","weights":{"constant":1}},{"label":"Sometimes, with the right person","value":"Sometimes, with the right person","weights":{"constant":1}},{"label":"I share it fairly freely","value":"I share it fairly freely","weights":{"constant":1}},{"label":"It is one of the main things I talk about","value":"It is one of the main things I talk about","weights":{"constant":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["rare","occasional","regular","constant"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"rare","label":"Rare","short":"Wonder is a visitor you do not expect","description":"Awe is genuinely rare for you, and this usually tracks with how much of your attention is taken up by the practical. It is the most fixable of the four, because the intervention is exposure rather than effort.","shadow":"Reading the absence of awe as the absence of something in you.","color":"slate","masters":["witnessing","body"],"calibration":{"dimensions":{"spirit":0.3,"body":0.2,"thought":0.15},"practiceLevels":{"witnessing":1,"body":1},"tags":["awe","rare"]}},{"id":"occasional","label":"Occasional","short":"It finds you, a few times a month","description":"Awe arrives on its own now and then, and you have no real control over when. The natural next step is to look at what is reliably present in those moments — there is usually a pattern.","shadow":"Waiting for it instead of noticing what invites it.","color":"amber","masters":["witnessing","raja"],"calibration":{"dimensions":{"spirit":0.35,"emotion":0.2},"practiceLevels":{"witnessing":1,"raja":1},"tags":["awe","occasional"]}},{"id":"regular","label":"Regular","short":"It is part of the week","description":"Awe is a regular part of your life and you have begun to recognise what invites it. The work at this stage is durability — keeping it while everything else is demanding.","shadow":"Losing the edge through routine.","color":"teal","masters":["witnessing","tantra"],"calibration":{"dimensions":{"spirit":0.4,"emotion":0.2,"body":0.15},"practiceLevels":{"witnessing":2,"raja":1},"tags":["awe","regular"]}},{"id":"constant","label":"Constant","short":"Close to the default state","description":"Wonder is close to continuous for you. This is worth handling carefully: a state that is always available can stop registering, and there is a version of this that is really a way of not being present to what is ordinary.","shadow":"Permanence dulling the thing it was protecting.","color":"indigo","masters":["witnessing","tantra"],"calibration":{"dimensions":{"spirit":0.45,"body":0.2},"practiceLevels":{"witnessing":2,"tantra":1},"tags":["awe","constant"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["witnessing","tantra"],"deepens_with":["non-dual-glimpses","awe-frequency"]}'::jsonb, 1, true, false, 100, now())
