  updated_at
) VALUES
    ('boundary-style', 'Boundary style', 'Walls, fences, or open field', 'yogic', 'connection', E'Yama and niyama are, among other things, a description of limits — what may not be taken, what must not be given away, and what is chosen rather than imposed.\n\nThis looks at the shape of your limits. A wall, a fence, a gate and an open field are four different instruments, and each one solves a different problem and creates a different cost.', '🚧', 6, 8, '[{"id":"boundary-no","type":"choice","prompt":"Is a no available to you when you need one?","domain":"limit","options":[{"label":"There is no no available to me at all","value":"There is no no available to me at all","weights":{"wall":1,"fence":0,"gate":0,"open-field":0}},{"label":"A no exists, but it is very hard to produce","value":"A no exists, but it is very hard to produce","weights":{"wall":0.25,"fence":0.75,"gate":0,"open-field":0}},{"label":"I can say no when I have to","value":"I can say no when I have to","weights":{"wall":0,"fence":0.5,"gate":0.5,"open-field":0}},{"label":"I say no fairly comfortably, and without apologising","value":"I say no fairly comfortably, and without apologising","weights":{"wall":0,"fence":0,"gate":0.75,"open-field":0.25}},{"label":"I can decline freely, and the relationship usually survives it","value":"I can decline freely, and the relationship usually survives it","weights":{"wall":0,"fence":0,"gate":0,"open-field":1}}]},{"id":"boundary-visible","type":"choice","prompt":"Do other people know where your limits are?","domain":"legibility","options":[{"label":"People cross it without noticing it was there","value":"People cross it without noticing it was there","weights":{"wall":0,"gate":0,"open-field":0}},{"label":"I know it is there; they usually do not","value":"I know it is there; they usually do not","weights":{"wall":1,"gate":0,"open-field":0}},{"label":"I say that it exists; whether it is heard is another matter","value":"I say that it exists; whether it is heard is another matter","weights":{"wall":0,"gate":0,"open-field":0}},{"label":"It is stated clearly, and taken seriously","value":"It is stated clearly, and taken seriously","weights":{"wall":0,"gate":1,"open-field":0}},{"label":"There is no wall to be visible — access is simply there","value":"There is no wall to be visible — access is simply there","weights":{"wall":0,"gate":0,"open-field":1}}]},{"id":"boundary-rigidity","type":"choice","prompt":"Does the limit hold whatever the cost of holding it?","domain":"flexibility","options":[{"label":"Nothing bends it, whatever the reason","value":"Nothing bends it, whatever the reason","weights":{"wall":1,"fence":0,"gate":0,"open-field":0}},{"label":"It bends under enough pressure, slowly","value":"It bends under enough pressure, slowly","weights":{"wall":0.25,"fence":0.75,"gate":0,"open-field":0}},{"label":"It bends when the reason is good enough","value":"It bends when the reason is good enough","weights":{"wall":0,"fence":0.5,"gate":0.5,"open-field":0}},{"label":"It bends fairly freely, and still stands","value":"It bends fairly freely, and still stands","weights":{"wall":0,"fence":0,"gate":0.75,"open-field":0.25}},{"label":"There is nothing fixed to bend — the ground is open","value":"There is nothing fixed to bend — the ground is open","weights":{"wall":0,"fence":0,"gate":0,"open-field":1}}]},{"id":"boundary-resentment","type":"choice","prompt":"Do your limits come from resentment rather than choice?","domain":"source","options":[{"label":"I hold a limit only after being pushed past it","value":"I hold a limit only after being pushed past it","weights":{"wall":0}},{"label":"Mostly after a build-up I did not name at the time","value":"Mostly after a build-up I did not name at the time","weights":{"wall":0.25}},{"label":"Some come from resentment, some from choice","value":"Some come from resentment, some from choice","weights":{"wall":0.5}},{"label":"Rarely — most of my limits are chosen rather than accumulated","value":"Rarely — most of my limits are chosen rather than accumulated","weights":{"wall":0.75}},{"label":"I do not know what resentment has to do with my limits","value":"I do not know what resentment has to do with my limits","weights":{"wall":1}}]},{"id":"boundary-crossed","type":"choice","prompt":"What happens when someone crosses a limit?","domain":"consequence","options":[{"label":"I harden completely, and it is never discussed","value":"I harden completely, and it is never discussed","weights":{"wall":1,"fence":0,"gate":0,"open-field":0}},{"label":"I withdraw, and the whole relationship goes quiet","value":"I withdraw, and the whole relationship goes quiet","weights":{"wall":0.25,"fence":0.75,"gate":0,"open-field":0}},{"label":"I say something at the time, badly","value":"I say something at the time, badly","weights":{"wall":0,"fence":0.5,"gate":0.5,"open-field":0}},{"label":"I raise it directly, once, and it does not happen again","value":"I raise it directly, once, and it does not happen again","weights":{"wall":0,"fence":0,"gate":0.75,"open-field":0.25}},{"label":"I notice it in the moment and say so","value":"I notice it in the moment and say so","weights":{"wall":0,"fence":0,"gate":0,"open-field":1}}]},{"id":"boundary-ask","type":"choice","prompt":"Can you ask other people for what you need?","domain":"need","options":[{"label":"I never ask for anything","value":"I never ask for anything","weights":{"wall":1,"fence":0,"gate":0,"open-field":0}},{"label":"I ask, badly, and drop it if there is no answer","value":"I ask, badly, and drop it if there is no answer","weights":{"wall":0.25,"fence":0.75,"gate":0,"open-field":0}},{"label":"I ask when I have to","value":"I ask when I have to","weights":{"wall":0,"fence":0.5,"gate":0.5,"open-field":0}},{"label":"I ask fairly readily","value":"I ask fairly readily","weights":{"wall":0,"fence":0,"gate":0.75,"open-field":0.25}},{"label":"I ask freely, and expect an answer","value":"I ask freely, and expect an answer","weights":{"wall":0,"fence":0,"gate":0,"open-field":1}}]},{"id":"boundary-others","type":"choice","prompt":"Do you take other people’s limits as seriously as your own?","domain":"reciprocity","options":[{"label":"I take what I want and assume it is available","value":"I take what I want and assume it is available","weights":{"open-field":0}},{"label":"I take what I need and rarely ask","value":"I take what I need and rarely ask","weights":{"open-field":0.25}},{"label":"I ask when I remember to","value":"I ask when I remember to","weights":{"open-field":0.5}},{"label":"I ask, and I accept the answer","value":"I ask, and I accept the answer","weights":{"open-field":0.75}},{"label":"I take other people’s limits as seriously as my own","value":"I take other people’s limits as seriously as my own","weights":{"open-field":1}}]},{"id":"boundary-cost","type":"choice","prompt":"What has this style cost you?","domain":"price","options":[{"label":"Nothing, as far as I can tell","value":"Nothing, as far as I can tell","weights":{"wall":0}},{"label":"A little distance, mostly manageable","value":"A little distance, mostly manageable","weights":{"wall":0.25}},{"label":"Relationships that go quiet and do not come back","value":"Relationships that go quiet and do not come back","weights":{"wall":0.5}},{"label":"People who care about me and do not come close","value":"People who care about me and do not come close","weights":{"wall":0.75}},{"label":"A life I have organised around not being let in","value":"A life I have organised around not being let in","weights":{"wall":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["wall","fence","gate","open-field"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"wall","label":"Wall","short":"The limit does not move and is rarely said","description":"Protection is absolute and mostly unspoken. A wall is effective, and it also ends the conversation before anything can happen in it. Most of the movement available from here is in naming the limit, not in removing it.","shadow":"Mistaking the wall for the whole of the structure.","color":"slate","masters":["witnessing","relationship"],"calibration":{"dimensions":{"connection":0.25,"emotion":0.25,"body":0.15},"practiceLevels":{"witnessing":1,"relationship":1},"domainStress":{"safety":"health"},"tags":["wall","closed"]}},{"id":"fence","label":"Fence","short":"A line that holds, and holds some things back","description":"The limit is real and enforced, and the enforcement is the problem: it is usually arrived at after a build-up rather than stated at the outset. Fences work, and they also teach everyone nearby that you are hard to reach.","shadow":"The limit arriving as accumulated resentment.","color":"rose","masters":["relationship","karma"],"calibration":{"dimensions":{"connection":0.3,"emotion":0.3,"action":0.15},"practiceLevels":{"relationship":1,"karma":1},"domainStress":{"relation":"relationship"},"tags":["fence","reactive-limit"]}},{"id":"gate","label":"Gate","short":"The limit is clear, stated, and adjustable","description":"The line is legible and negotiable: other people know it exists, it holds, and it can move when the reason is good enough. This is the form most traditions mean when they describe discipline — a limit that is chosen, held, and not defended for its own sake.","shadow":"The gate kept shut more often than it needs to be.","color":"teal","masters":["relationship","karma"],"calibration":{"dimensions":{"connection":0.3,"action":0.2,"spirit":0.15},"practiceLevels":{"relationship":1,"karma":1},"tags":["gate","legible-limit"]}},{"id":"open-field","label":"Open field","short":"Few fixed lines, and the request instead of the wall","description":"Access to you is broadly available, and what you have instead of walls is the ability to ask for what you need. The work of this position is not protection but attention: an open field requires you to know where you are standing.","shadow":"Availability mistaken for the absence of a limit.","color":"emerald","masters":["karma","bhakti"],"calibration":{"dimensions":{"connection":0.35,"action":0.2,"spirit":0.15},"practiceLevels":{"karma":1,"bhakti":1},"tags":["open-field","porous"]}}]'::jsonb, '{"loops_to_check":["people-pleasing","resentment-accumulation"],"practice_affinity":["relationship","karma"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
