    ('breath-pattern', 'Breath pattern', 'The depth and pace of your prāṇa', 'yogic', 'vitality', E'The breath is the only part of the autonomic system that is both automatic and voluntary. Everything else about the body decides for itself. This one can be listened to.\n\nTraditions use prāṇa here to mean more than air — the movement that moves everything else. What this reads is where your breath sits, how it behaves under load, and how much of it is actually available to you as a working instrument.', '🫁', 6, 9, '[{"id":"breath-where","type":"choice","prompt":"Where in your body does most of the breathing actually happen?","domain":"location","options":[{"label":"High in the chest","value":"High in the chest","weights":{"shallow":1}},{"label":"All over — I could not say where","value":"All over — I could not say where","weights":{"irregular":1}},{"label":"Low, in the belly","value":"Low, in the belly","weights":{"deep":1}},{"label":"Quiet and unobtrusive, wherever it is","value":"Quiet and unobtrusive, wherever it is","weights":{"still":1}}]},{"id":"breath-audible","type":"choice","prompt":"Can other people hear you breathing from across the room?","domain":"habit","options":[{"label":"I can hear it from across the room","value":"I can hear it from across the room","weights":{"shallow":1}},{"label":"Loud enough that people mention it","value":"Loud enough that people mention it","weights":{"shallow":0.75,"irregular":0.25}},{"label":"I notice it when I think about it","value":"I notice it when I think about it","weights":{"irregular":1}},{"label":"Almost silent","value":"Almost silent","weights":{"irregular":0.25,"deep":0.75}},{"label":"I genuinely do not know it is there","value":"I genuinely do not know it is there","weights":{"still":1}}]},{"id":"breath-emotion","type":"choice","prompt":"What happens to your breathing when a feeling arrives?","domain":"emotion","options":[{"label":"It stops, or catches in my throat","value":"It stops, or catches in my throat","weights":{"irregular":1}},{"label":"It goes fast and high","value":"It goes fast and high","weights":{"shallow":1}},{"label":"It becomes heavy and drops low","value":"It becomes heavy and drops low","weights":{"deep":1}},{"label":"It changes a little, and I stay in charge of it","value":"It changes a little, and I stay in charge of it","weights":{"still":1}}]},{"id":"breath-exhale","type":"choice","prompt":"How much longer can your out-breath be than your in-breath?","domain":"capacity","options":[{"label":"I cannot lengthen it at all","value":"I cannot lengthen it at all","weights":{"shallow":1}},{"label":"A few extra seconds, and it feels like effort","value":"A few extra seconds, and it feels like effort","weights":{"shallow":0.75,"irregular":0.25}},{"label":"About twice the length of the in-breath","value":"About twice the length of the in-breath","weights":{"irregular":0.5,"deep":0.5}},{"label":"Much longer than the in-breath","value":"Much longer than the in-breath","weights":{"deep":1}},{"label":"It can go on for as long as I want it to","value":"It can go on for as long as I want it to","weights":{"deep":0.75,"still":0.25}}]},{"id":"breath-slowing","type":"choice","prompt":"What happens when you try to slow your breathing down?","domain":"effort","options":[{"label":"Nothing happens — I cannot change it","value":"Nothing happens — I cannot change it","weights":{"irregular":1}},{"label":"It fights me and I give up","value":"It fights me and I give up","weights":{"shallow":1}},{"label":"It slows for a while, then drifts back","value":"It slows for a while, then drifts back","weights":{"deep":1}},{"label":"It settles and stays slower","value":"It settles and stays slower","weights":{"still":1}}]},{"id":"breath-sigh","type":"choice","prompt":"How often do you yawn, sigh, or take one big unplanned breath?","domain":"reflex","options":[{"label":"Several times an hour","value":"Several times an hour","weights":{"shallow":1}},{"label":"A few times a day, constantly","value":"A few times a day, constantly","weights":{"shallow":0.75,"irregular":0.25}},{"label":"Now and then","value":"Now and then","weights":{"irregular":1}},{"label":"Rarely","value":"Rarely","weights":{"irregular":0.25,"deep":0.75}},{"label":"Almost never, even when I am tired","value":"Almost never, even when I am tired","weights":{"deep":0.75,"still":0.25}}]},{"id":"breath-rest","type":"choice","prompt":"When you sit down with nothing to do, what does your breathing do?","domain":"rest","options":[{"label":"Nothing — it stays exactly as it was","value":"Nothing — it stays exactly as it was","weights":{"irregular":1}},{"label":"It gets shallower, oddly","value":"It gets shallower, oddly","weights":{"shallow":1}},{"label":"It slows and drops lower","value":"It slows and drops lower","weights":{"deep":1}},{"label":"It becomes slow, deep and steady","value":"It becomes slow, deep and steady","weights":{"still":1}}]},{"id":"breath-load","type":"choice","prompt":"Under pressure, what happens to your breath?","domain":"load","options":[{"label":"It stops, or catches","value":"It stops, or catches","weights":{"irregular":1}},{"label":"It goes fast and high","value":"It goes fast and high","weights":{"shallow":1}},{"label":"It stays steady, whatever happens","value":"It stays steady, whatever happens","weights":{"still":1}},{"label":"It becomes slow and deliberate on purpose","value":"It becomes slow and deliberate on purpose","weights":{"deep":1}}]},{"id":"breath-noticed","type":"choice","prompt":"How much of the day do you actually notice yourself breathing?","domain":"attention","options":[{"label":"Only when something has gone wrong with it","value":"Only when something has gone wrong with it","weights":{"shallow":1}},{"label":"When I remember to","value":"When I remember to","weights":{"shallow":0.75,"irregular":0.25}},{"label":"Often enough to notice it going on","value":"Often enough to notice it going on","weights":{"irregular":1}},{"label":"Most of the time","value":"Most of the time","weights":{"irregular":0.25,"deep":0.75}},{"label":"It is continuous, whether I am attending to it or not","value":"It is continuous, whether I am attending to it or not","weights":{"deep":0.5,"still":0.5}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["shallow","irregular","deep","still"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"shallow","label":"Shallow prāṇa","short":"High, fast, and out of sight","description":"The breath sits high and the body gets the minimum it needs and no more. This reads less as a problem than as a habit that has never been questioned — most people have never once checked what their breathing actually does.","shadow":"Believing shallow breathing is simply how you breathe.","color":"slate","masters":["breath","kriya"],"calibration":{"dimensions":{"body":0.35,"spirit":0.2,"thought":0.15},"practiceLevels":{"breath":2},"domainStress":{"rest":"health"},"tags":["shallow","unexamined"]}},{"id":"irregular","label":"Irregular prāṇa","short":"Arrhythmic, and not under your hand","description":"The breath has no dependable shape and does not respond cleanly to intention. This is common wherever the system is running hot, and it makes the early stages of breath work harder than they otherwise need to be.","shadow":"Reading the unsteadiness as a lack of discipline.","color":"orange","masters":["breath","body"],"calibration":{"dimensions":{"body":0.3,"emotion":0.3,"thought":0.15},"practiceLevels":{"breath":1,"body":1},"tags":["arrhythmic","hot"]}},{"id":"deep","label":"Deep prāṇa","short":"Low, long, and responsive","description":"The breath has depth and responds to what is asked of it. There is real range here, which means real material to work with — the practice at this level is refinement rather than repair.","shadow":"Depth mistaken for completion.","color":"teal","masters":["breath","raja"],"calibration":{"dimensions":{"body":0.3,"spirit":0.25,"action":0.15},"practiceLevels":{"breath":2,"raja":1},"tags":["deep","responsive"]}},{"id":"still","label":"Still prāṇa","short":"It has become the background it should be","description":"The breath is quiet, unremarkable and available, and it holds its shape under load. This is the condition most of the breath practices are actually aiming at, and it is easy to mistake for a person with no inner weather.","shadow":"Stillness that is no longer being looked at.","color":"indigo","masters":["raja","witnessing"],"calibration":{"dimensions":{"spirit":0.3,"body":0.25,"thought":0.2},"practiceLevels":{"raja":1,"witnessing":1},"tags":["still","integrated"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["breath","body"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
