  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('chakra-balance', 'Cakra balance', 'Where your energy actually sits', 'yogic', 'vitality', E'Seven centres, seven places where a life is felt rather than thought about. The model is a working map — a way of describing where energy moves, gathers, and stops, not a claim about the structure of a body.\n\nRead it by feel. Nothing here depends on being able to locate anything in yourself, and none of the seven is the correct one to be centred in.', '🌈', 7, 7, '[{"id":"cakra-alive","type":"choice","prompt":"Which of the seven is most alive in you?","domain":"most alive","options":[{"label":"Rooted — steady, physical, hard to knock over","value":"Rooted — steady, physical, hard to knock over","weights":{"root":1}},{"label":"Alive with wanting — drive, appetite, creative motion","value":"Alive with wanting — drive, appetite, creative motion","weights":{"sacral":1}},{"label":"Warm — recognised, energised, willing to show up","value":"Warm — recognised, energised, willing to show up","weights":{"solar":1}},{"label":"Tender — connected, open to others, easily moved","value":"Tender — connected, open to others, easily moved","weights":{"heart":1}},{"label":"Expressive — able to say it and be heard","value":"Expressive — able to say it and be heard","weights":{"throat":1}},{"label":"Perceptive — able to see what is underneath the surface","value":"Perceptive — able to see what is underneath the surface","weights":{"third-eye":1}},{"label":"Spacious — something wider than the personal, at rest","value":"Spacious — something wider than the personal, at rest","weights":{"crown":1}}]},{"id":"cakra-blocked","type":"choice","prompt":"Which of the seven is least available to you?","domain":"least available","options":[{"label":"Safety and footing — being steady is hard to reach for","value":"Safety and footing — being steady is hard to reach for","weights":{"root":1}},{"label":"Appetite — wanting does not come easily any more","value":"Appetite — wanting does not come easily any more","weights":{"sacral":1}},{"label":"Will — taking up room does not feel available","value":"Will — taking up room does not feel available","weights":{"solar":1}},{"label":"Openness — letting someone close in is difficult","value":"Openness — letting someone close in is difficult","weights":{"heart":1}},{"label":"Expression — the true thing does not reach anyone","value":"Expression — the true thing does not reach anyone","weights":{"throat":1}},{"label":"Perception — the pattern underneath is not visible","value":"Perception — the pattern underneath is not visible","weights":{"third-eye":1}},{"label":"Spaciousness — everything stays inside my own edges","value":"Spaciousness — everything stays inside my own edges","weights":{"crown":1}}]},{"id":"cakra-root","type":"choice","prompt":"How steady do you feel in your body when things are uncertain?","domain":"footing","options":[{"label":"I am rarely sure where I stand","value":"I am rarely sure where I stand","weights":{"root":0}},{"label":"I steady myself constantly without noticing","value":"I steady myself constantly without noticing","weights":{"root":0.25}},{"label":"I am mostly steady, and wobble occasionally","value":"I am mostly steady, and wobble occasionally","weights":{"root":0.5}},{"label":"I am steady in most situations","value":"I am steady in most situations","weights":{"root":0.75}},{"label":"I am at home in my body, and it stays that way under pressure","value":"I am at home in my body, and it stays that way under pressure","weights":{"root":1}}]},{"id":"cakra-solar","type":"choice","prompt":"How readily do you take up space when you want something?","domain":"warmth","options":[{"label":"I take up no space at all","value":"I take up no space at all","weights":{"solar":0}},{"label":"Only when I cannot help it","value":"Only when I cannot help it","weights":{"solar":0.25}},{"label":"Some, when I am reasonably sure of the ground","value":"Some, when I am reasonably sure of the ground","weights":{"solar":0.5}},{"label":"Reliably, without apologising for it","value":"Reliably, without apologising for it","weights":{"solar":0.75}},{"label":"I take up space with no sense of it being a risk","value":"I take up space with no sense of it being a risk","weights":{"solar":1}}]},{"id":"cakra-throat","type":"choice","prompt":"When you need to ask for something, what happens?","domain":"expression","options":[{"label":"I say almost nothing","value":"I say almost nothing","weights":{"throat":0}},{"label":"I say things, but not the important ones","value":"I say things, but not the important ones","weights":{"throat":0.25}},{"label":"I say what I mean when I have to","value":"I say what I mean when I have to","weights":{"throat":0.5}},{"label":"I ask for what I need most of the time","value":"I ask for what I need most of the time","weights":{"throat":0.75}},{"label":"I say the true thing as soon as I know it","value":"I say the true thing as soon as I know it","weights":{"throat":1}}]},{"id":"cakra-crown","type":"choice","prompt":"How often do you feel part of something larger than yourself?","domain":"openness","options":[{"label":"My edges are the whole of what there is","value":"My edges are the whole of what there is","weights":{"crown":0}},{"label":"Mostly I stay inside myself","value":"Mostly I stay inside myself","weights":{"crown":0.25}},{"label":"Sometimes I feel something beyond the personal","value":"Sometimes I feel something beyond the personal","weights":{"crown":0.5}},{"label":"Often, and without having to arrange it","value":"Often, and without having to arrange it","weights":{"crown":0.75}},{"label":"It is an ordinary condition, and rarely absent","value":"It is an ordinary condition, and rarely absent","weights":{"crown":1}}]},{"id":"cakra-flow","type":"choice","prompt":"Where does your energy settle when you are not doing anything?","domain":"movement","options":[{"label":"It pools low and stays there","value":"It pools low and stays there","weights":{"root":1,"sacral":0,"solar":0,"heart":0,"throat":0,"third-eye":0,"crown":0}},{"label":"It sits low, with some heat above it","value":"It sits low, with some heat above it","weights":{"root":0,"sacral":0.5,"solar":0.5,"heart":0,"throat":0,"third-eye":0,"crown":0}},{"label":"It comes up to the middle of me","value":"It comes up to the middle of me","weights":{"root":0,"sacral":0,"solar":0,"heart":1,"throat":0,"third-eye":0,"crown":0}},{"label":"It rises through the throat and the head","value":"It rises through the throat and the head","weights":{"root":0,"sacral":0,"solar":0,"heart":0,"throat":0.5,"third-eye":0.5,"crown":0}},{"label":"It is everywhere at once, and hard to locate","value":"It is everywhere at once, and hard to locate","weights":{"root":0,"sacral":0,"solar":0,"heart":0,"throat":0,"third-eye":0,"crown":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["root","sacral","solar","heart","throat","third-eye","crown"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"root","label":"Root","short":"You can stand here","description":"There is a floor under you that does not move with the week. Stability is not stillness — it is being able to take a knock, recover, and stay in the body while it happens. From here, most of the other centres become reachable rather than aspirational.","shadow":"Stability hardened into never changing.","color":"slate","masters":["body","breath"],"calibration":{"dimensions":{"body":0.4,"thought":0.15,"emotion":0.1},"practiceLevels":{"body":2,"breath":1},"domainStress":{"ground":"health"},"tags":["grounded","stable"]}},{"id":"sacral","label":"Sacral","short":"Wanting, appetite, creative motion","description":"The middle-lower centre, where wanting lives. Drive, appetite, the pull towards making something — including the desire to make a life rather than to keep one running. Its characteristic problem is not the absence of desire but directing it well.","shadow":"Wanting turned entirely into consumption.","color":"orange","masters":["body","kriya"],"calibration":{"dimensions":{"body":0.3,"emotion":0.2,"action":0.15},"practiceLevels":{"body":1,"kriya":1},"domainStress":{"drive":"work-career"},"tags":["desire","creative"]}},{"id":"solar","label":"Solar","short":"Will, warmth, and room for yourself","description":"The centre of confidence and self-respect. Here the question is whether you take up the space you occupy — whether wanting something lets you go after it, and whether you can be visible while doing it. This is the centre most often arranged around other people’s permission.","shadow":"Confidence that has become identity, and has to be defended.","color":"amber","masters":["raja","body"],"calibration":{"dimensions":{"emotion":0.3,"body":0.2,"action":0.15},"practiceLevels":{"raja":1,"body":1},"domainStress":{"confidence":"work-career"},"tags":["confident","will"]}},{"id":"heart","label":"Heart","short":"Openness, and the cost of it","description":"The centre where care becomes visible — in both directions. It holds love, grief, loyalty, and the willingness to be affected by another person, which is what makes it generous and what makes it expensive. Its characteristic difficulty is not coldness but the cost of staying open.","shadow":"Staying open until there is nothing left to feel with.","color":"rose","masters":["bhakti","relationship"],"calibration":{"dimensions":{"connection":0.4,"emotion":0.2,"spirit":0.1},"practiceLevels":{"bhakti":1,"relationship":1},"domainStress":{"relation":"relationship"},"tags":["tender","connected"]}},{"id":"throat","label":"Throat","short":"What is true, reaching someone","description":"The centre of expression and truthfulness. What is known inwardly has to travel a short distance to become real between people, and this is where that journey happens or fails. Work here tends to show up as a change in what can be asked for, and then in what can be refused.","shadow":"Truth told accurately and used as a weapon.","color":"sky","masters":["bhakti","jnana"],"calibration":{"dimensions":{"connection":0.3,"action":0.2,"emotion":0.15},"practiceLevels":{"bhakti":1,"jnana":1},"domainStress":{"expression":"relationship"},"tags":["expressive","clear-voice"]}},{"id":"third-eye","label":"Third eye","short":"Seeing what is underneath","description":"The centre of perception and discrimination. Its work is seeing clearly enough to tell a true pattern from a story about one — which requires as much interest as it does scepticism. Practised well it sharpens judgment; overused it can become the habit of watching instead of living.","shadow":"Seeing so much that nothing is taken part in.","color":"indigo","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.4,"thought":0.2},"practiceLevels":{"witnessing":2,"jnana":1},"tags":["perceptive","discerning"]}},{"id":"crown","label":"Crown","short":"Something wider than the personal","description":"The top of the map: a sense of belonging to something that includes more than this particular life. It is not reached by the others and it does not replace them — a person can be entirely grounded and entirely ordinary about it. What it changes is the size of the thing being asked about.","shadow":"Wide open, and indistinguishable from nowhere to stand.","color":"violet","masters":["witnessing","raja"],"calibration":{"dimensions":{"spirit":0.45,"connection":0.1},"practiceLevels":{"witnessing":2,"raja":1},"tags":["spacious","unbounded"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["body","raja"],"deepens_with":["energy-baseline","pranayama-capacity"]}'::jsonb, 1, true, false, 100, now())
