-- Community rooting (Launch)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('community-rooting', 'Community rooting', 'Your sangha — the ones who see you', 'vedic', 'connection', E'Sangha is not a group of like-minded people. It is the specific people who see the whole of you, including the parts you have not shown anyone.\n\nThat is a much shorter list than most people think, and the count is the finding.', '🪷', 6, 6, '[{"id":"community-count","type":"choice","prompt":"How many people know the whole of you?","domain":"depth","options":[{"label":"None","value":"None","weights":{"isolated":1,"surface-level":0,"belonging":0,"rooted":0}},{"label":"One, and it is not who I would choose","value":"One, and it is not who I would choose","weights":{"isolated":0.25,"surface-level":0.75,"belonging":0,"rooted":0}},{"label":"One or two","value":"One or two","weights":{"isolated":0,"surface-level":0.5,"belonging":0.5,"rooted":0}},{"label":"A few, and I would be surprised if anything changed for them","value":"A few, and I would be surprised if anything changed for them","weights":{"isolated":0,"surface-level":0,"belonging":0.75,"rooted":0.25}},{"label":"Enough that I am not managing how I come across","value":"Enough that I am not managing how I come across","weights":{"isolated":0,"surface-level":0,"belonging":0,"rooted":1}}]},{"id":"community-given","type":"choice","prompt":"What do you give to them, and what do you get?","domain":"generosity","options":[{"label":"I give more than I get","value":"I give more than I get","weights":{"belonging":1}},{"label":"I get more than I give","value":"I get more than I give","weights":{"belonging":1}},{"label":"It is roughly even","value":"It is roughly even","weights":{"belonging":1}},{"label":"We give each other different things","value":"We give each other different things","weights":{"belonging":1}},{"label":"I am not sure it works like that","value":"I am not sure it works like that","weights":{"belonging":1}}]},{"id":"community-chosen","type":"choice","prompt":"Did you find them, or did they find you?","domain":"formation","options":[{"label":"I have not had this","value":"I have not had this","weights":{"belonging":1}},{"label":"They arrived, and I did not choose it","value":"They arrived, and I did not choose it","weights":{"belonging":1}},{"label":"A bit of both","value":"A bit of both","weights":{"belonging":1}},{"label":"I looked for it deliberately","value":"I looked for it deliberately","weights":{"belonging":1}},{"label":"It grew out of something I did not plan","value":"It grew out of something I did not plan","weights":{"belonging":1}}]},{"id":"community-seen","type":"choice","prompt":"How comfortable is it to be fully seen?","domain":"exposure","options":[{"label":"I avoid it entirely","value":"I avoid it entirely","weights":{"isolated":1,"surface-level":0,"belonging":0,"rooted":0}},{"label":"It is uncomfortable","value":"It is uncomfortable","weights":{"isolated":0.25,"surface-level":0.75,"belonging":0,"rooted":0}},{"label":"I tolerate it in a few people","value":"I tolerate it in a few people","weights":{"isolated":0,"surface-level":0.5,"belonging":0.5,"rooted":0}},{"label":"I find it mostly fine","value":"I find it mostly fine","weights":{"isolated":0,"surface-level":0,"belonging":0.75,"rooted":0.25}},{"label":"I would rather be known than not","value":"I would rather be known than not","weights":{"isolated":0,"surface-level":0,"belonging":0,"rooted":1}}]},{"id":"community-practice","type":"choice","prompt":"Is there anything you do together, regularly?","domain":"rhythm","options":[{"label":"Nothing — it is purely social","value":"Nothing — it is purely social","weights":{"isolated":1,"surface-level":0,"belonging":0,"rooted":0}},{"label":"Occasionally, when something comes up","value":"Occasionally, when something comes up","weights":{"isolated":0.25,"surface-level":0.75,"belonging":0,"rooted":0}},{"label":"There is a regular thing, loosely","value":"There is a regular thing, loosely","weights":{"isolated":0,"surface-level":0.5,"belonging":0.5,"rooted":0}},{"label":"Something regular and reliable","value":"Something regular and reliable","weights":{"isolated":0,"surface-level":0,"belonging":0.75,"rooted":0.25}},{"label":"A real shared practice with a rhythm","value":"A real shared practice with a rhythm","weights":{"isolated":0,"surface-level":0,"belonging":0,"rooted":1}}]},{"id":"community-loss","type":"choice","prompt":"What would you do if the circle dissolved?","domain":"fragility","options":[{"label":"It would be a real loss, and survivable","value":"It would be a real loss, and survivable","weights":{"rooted":1}},{"label":"It would be very difficult","value":"It would be very difficult","weights":{"rooted":1}},{"label":"I do not know what I would do","value":"I do not know what I would do","weights":{"rooted":1}},{"label":"I would be devastated","value":"I would be devastated","weights":{"rooted":1}},{"label":"I have thought about this and have other footing","value":"I have thought about this and have other footing","weights":{"rooted":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["isolated","surface-level","belonging","rooted"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"isolated","label":"Isolated","short":"No one has the whole picture","description":"There is no one who sees all of you. This is the most common reading and the most uncomfortable, because it is usually disguised by a large number of contacts. The count, not the loneliness, is the finding.","shadow":"Number of contacts mistaken for depth of connection.","color":"rose","masters":["relationship","bhakti"],"calibration":{"dimensions":{"connection":0.4,"emotion":0.2},"practiceLevels":{"relationship":1,"bhakti":1},"domainStress":{"contact":"relationship"},"tags":["community","isolated"]}},{"id":"surface-level","label":"Surface level","short":"Contacts, without the one who sees everything","description":"You are well-connected and reasonably known — just not all the way. There are one or two people close to it, and the gap between what they know and what they would know is where the work is.","shadow":"Depth with a few people being assumed to cover the rest.","color":"slate","masters":["relationship","witnessing"],"calibration":{"dimensions":{"connection":0.3,"emotion":0.2},"practiceLevels":{"relationship":1,"witnessing":1},"domainStress":{"contact":"relationship"},"tags":["community","partial"]}},{"id":"belonging","label":"Belonging","short":"A circle that holds you","description":"There is a real circle and you are properly inside it. The next thing worth examining is fragility — how much of your own stability depends on the circle continuing to exist as it is.","shadow":"Mistaking a supportive circle for a permanent one.","color":"teal","masters":["relationship","bhakti"],"calibration":{"dimensions":{"connection":0.35,"emotion":0.25,"spirit":0.15},"practiceLevels":{"relationship":2,"bhakti":1},"tags":["community","belonging"]}},{"id":"rooted","label":"Rooted","short":"Rooted, and not entirely dependent on it","description":"You are rooted — genuinely known, with a shared rhythm — and the root does not depend entirely on the circle holding. This is what sangha is actually for, and it is the position the tradition treats as mature.","shadow":"Assuming the circle will always be available.","color":"emerald","masters":["relationship","witnessing"],"calibration":{"dimensions":{"connection":0.35,"spirit":0.3,"emotion":0.2},"practiceLevels":{"relationship":2,"witnessing":1},"tags":["community","rooted"]}}]'::jsonb, '{"loops_to_check":["isolation"],"practice_affinity":["relationship","bhakti"],"deepens_with":["service-radius","trust-baseline"]}'::jsonb, 1, true, false, 100, now())
