-- Daily rhythm (Welcome)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('daily-rhythm', 'Daily rhythm', 'How the day actually moves', 'yogic', 'rhythm', E'Almost nobody lives the day they plan. The gap between the intended shape and the actual one is where most of a life is spent.\n\nThis looks at that gap — not to correct it, but to see it. A rhythm you can see is a rhythm you can work with.', '🕰️', 6, 8, '[{"id":"rhythm-expected","type":"choice","prompt":"How different is your actual day from the one you meant to have?","domain":"shape","options":[{"label":"I stopped planning days entirely","value":"I stopped planning days entirely","weights":{"dissonance":1,"absorption":0,"flow":0,"recovery":0}},{"label":"They are almost unrelated","value":"They are almost unrelated","weights":{"dissonance":0.25,"absorption":0.75,"flow":0,"recovery":0}},{"label":"The real day is always busier","value":"The real day is always busier","weights":{"dissonance":0,"absorption":0.5,"flow":0.5,"recovery":0}},{"label":"Close enough","value":"Close enough","weights":{"dissonance":0,"absorption":0,"flow":0.75,"recovery":0.25}},{"label":"They are nearly the same","value":"They are nearly the same","weights":{"dissonance":0,"absorption":0,"flow":0,"recovery":1}}]},{"id":"rhythm-anchors","type":"choice","prompt":"How many fixed points does your day have — meals, times you get up, places you go?","domain":"shape","options":[{"label":"None at all","value":"None at all","weights":{"dissonance":1,"absorption":0,"flow":0,"recovery":0}},{"label":"One or two, loosely","value":"One or two, loosely","weights":{"dissonance":0.25,"absorption":0.75,"flow":0,"recovery":0}},{"label":"A few, fairly reliable","value":"A few, fairly reliable","weights":{"dissonance":0,"absorption":0.5,"flow":0.5,"recovery":0}},{"label":"Most of the day is anchored","value":"Most of the day is anchored","weights":{"dissonance":0,"absorption":0,"flow":0.75,"recovery":0.25}},{"label":"Everything is anchored","value":"Everything is anchored","weights":{"dissonance":0,"absorption":0,"flow":0,"recovery":1}}]},{"id":"rhythm-switches","type":"choice","prompt":"How often does something unexpected pull you off what you were doing?","domain":"shape","options":[{"label":"I have stopped being able to focus at all","value":"I have stopped being able to focus at all","weights":{"dissonance":1,"absorption":0,"flow":0,"recovery":0}},{"label":"Constantly","value":"Constantly","weights":{"dissonance":0.25,"absorption":0.75,"flow":0,"recovery":0}},{"label":"Several a day","value":"Several a day","weights":{"dissonance":0,"absorption":0.5,"flow":0.5,"recovery":0}},{"label":"A few a week","value":"A few a week","weights":{"dissonance":0,"absorption":0,"flow":0.75,"recovery":0.25}},{"label":"Almost never","value":"Almost never","weights":{"dissonance":0,"absorption":0,"flow":0,"recovery":1}}]},{"id":"rhythm-best-hour","type":"choice","prompt":"What time of day are you most yourself?","domain":"shape","options":[{"label":"Early morning","value":"Early morning","weights":{"flow":1}},{"label":"Late morning","value":"Late morning","weights":{"flow":1}},{"label":"Afternoon","value":"Afternoon","weights":{"flow":1}},{"label":"Early evening","value":"Early evening","weights":{"flow":1}},{"label":"Late night","value":"Late night","weights":{"flow":1}}]},{"id":"rhythm-worst-hour","type":"choice","prompt":"Which part of the day do you most often dread or limp through?","domain":"shape","options":[{"label":"Early morning","value":"Early morning","weights":{"dissonance":1}},{"label":"Late morning","value":"Late morning","weights":{"dissonance":1}},{"label":"Afternoon","value":"Afternoon","weights":{"dissonance":1}},{"label":"Early evening","value":"Early evening","weights":{"dissonance":1}},{"label":"Late night","value":"Late night","weights":{"dissonance":1}}]},{"id":"rhythm-load","type":"choice","prompt":"Is there anything you carry that you have not agreed to carry?","domain":"shape","options":[{"label":"Almost everything","value":"Almost everything","weights":{"dissonance":1,"absorption":0,"flow":0,"recovery":0}},{"label":"Most of it","value":"Most of it","weights":{"dissonance":0.25,"absorption":0.75,"flow":0,"recovery":0}},{"label":"A fair share","value":"A fair share","weights":{"dissonance":0,"absorption":0.5,"flow":0.5,"recovery":0}},{"label":"A little","value":"A little","weights":{"dissonance":0,"absorption":0,"flow":0.75,"recovery":0.25}},{"label":"Nearly none of it","value":"Nearly none of it","weights":{"dissonance":0,"absorption":0,"flow":0,"recovery":1}}]},{"id":"rhythm-rest","type":"choice","prompt":"How easily do you stop, when stopping is the right thing to do?","domain":"shape","options":[{"label":"I cannot stop at all","value":"I cannot stop at all","weights":{"dissonance":1,"absorption":0,"flow":0,"recovery":0}},{"label":"Only if I have to","value":"Only if I have to","weights":{"dissonance":0.25,"absorption":0.75,"flow":0,"recovery":0}},{"label":"With some effort","value":"With some effort","weights":{"dissonance":0,"absorption":0.5,"flow":0.5,"recovery":0}},{"label":"Quite easily","value":"Quite easily","weights":{"dissonance":0,"absorption":0,"flow":0.75,"recovery":0.25}},{"label":"I stop whenever I need to","value":"I stop whenever I need to","weights":{"dissonance":0,"absorption":0,"flow":0,"recovery":1}}]},{"id":"rhythm-evening","type":"choice","prompt":"How do you usually end the day — engaged with something, or already gone?","domain":"shape","options":[{"label":"I collapse before I finish","value":"I collapse before I finish","weights":{"dissonance":1,"absorption":0,"flow":0,"recovery":0}},{"label":"I scroll until I stop","value":"I scroll until I stop","weights":{"dissonance":0.25,"absorption":0.75,"flow":0,"recovery":0}},{"label":"I am still wired","value":"I am still wired","weights":{"dissonance":0,"absorption":0.5,"flow":0.5,"recovery":0}},{"label":"I close it deliberately","value":"I close it deliberately","weights":{"dissonance":0,"absorption":0,"flow":0.75,"recovery":0.25}},{"label":"I finish the day and I am actually there","value":"I finish the day and I am actually there","weights":{"dissonance":0,"absorption":0,"flow":0,"recovery":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["dissonance","absorption","flow","recovery"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"dissonance","label":"High dissonance","short":"The day runs you","description":"There is a large gap between the day you intend and the day you get. The intention is still there, which means something in you is still reaching for a life it has not made room for. This is exhausting because the gap is a constant, small, repeating loss.","shadow":"Mistaking busyness for a schedule.","color":"rose","masters":["observation","breath"],"calibration":{"dimensions":{"thought":0.3,"body":0.2,"spirit":0.15},"practiceLevels":{"observation":1,"breath":1},"domainStress":{"routine":"observation"},"tags":["scattered","over-committed"]}},{"id":"absorption","label":"Absorbed","short":"Engaged but not choosing","description":"The days are full and you are in them, but a lot of what fills them was decided for you. You are rarely idle and rarely choosing. Activity has quietly replaced intention.","shadow":"Confusing being busy with being present.","color":"orange","masters":["observation","karma"],"calibration":{"dimensions":{"action":0.25,"emotion":0.2,"thought":0.15},"practiceLevels":{"observation":1},"tags":["occupied","reactive"]}},{"id":"flow","label":"Flowing","short":"The day has a shape you trust","description":"Your days hold a rhythm you mostly chose, and it mostly works. The anchor is real, the interruptions are survivable, and the hours have distinct textures you can read.","shadow":"Rigidity disguised as virtue.","color":"teal","masters":["raja","karma"],"calibration":{"dimensions":{"action":0.2,"body":0.2,"connection":0.15},"practiceLevels":{"raja":1,"karma":1},"tags":["structured","stable"]}},{"id":"recovery","label":"Rhythmic with recovery","short":"The day holds and lets you rest","description":"You have built a day that includes its own recovery. Stopping does not require justification, and the day has enough slack to absorb what arrives.","shadow":"A structure that has stopped challenging you.","color":"sky","masters":["breath","raja"],"calibration":{"dimensions":{"body":0.3,"spirit":0.2,"action":0.15},"practiceLevels":{"breath":1,"raja":1},"tags":["sustainable","grounded"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["breath","observation"],"deepens_with":["energy-baseline","attention-diet"]}'::jsonb, 1, true, false, 100, now())
