-- Death awareness (Launch)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('death-awareness', 'Death awareness', 'Your relationship to your own ending', 'vedic', 'spirit', E'Every ending is described to us by people who are not going through one, which gives the subject a permanent second-hand quality. That is a large part of why it is easier to put down than to look at.\n\nThis asks a narrower thing: what your current relationship to your own ending is like, described in terms you would actually use for it. It is not an exercise, and nothing here asks you to sit with anything.', '🕯️', 6, 6, '[{"id":"death-arrival","type":"choice","prompt":"How often does the fact that you will die come up for you?","domain":"how often it arrives","options":[{"label":"It does not come up for me","value":"It does not come up for me","weights":{"avoided":1,"acknowledged":0,"contemplated":0,"familiar":0}},{"label":"It comes up now and then, and passes","value":"It comes up now and then, and passes","weights":{"avoided":0.25,"acknowledged":0.75,"contemplated":0,"familiar":0}},{"label":"It comes up fairly often, usually without anything having happened","value":"It comes up fairly often, usually without anything having happened","weights":{"avoided":0,"acknowledged":0.5,"contemplated":0.5,"familiar":0}},{"label":"It is usually in the background of an ordinary day","value":"It is usually in the background of an ordinary day","weights":{"avoided":0,"acknowledged":0,"contemplated":0.75,"familiar":0.25}},{"label":"It is one of the facts I hold, alongside the others","value":"It is one of the facts I hold, alongside the others","weights":{"avoided":0,"acknowledged":0,"contemplated":0,"familiar":1}}]},{"id":"death-conversation","type":"choice","prompt":"When it comes up with other people, what do you do?","domain":"in conversation","options":[{"label":"I move away from it as soon as I can","value":"I move away from it as soon as I can","weights":{"avoided":1,"acknowledged":0,"contemplated":0,"familiar":0}},{"label":"I steer the conversation somewhere else","value":"I steer the conversation somewhere else","weights":{"avoided":0.25,"acknowledged":0.75,"contemplated":0,"familiar":0}},{"label":"I can stay in it for a while without it becoming difficult","value":"I can stay in it for a while without it becoming difficult","weights":{"avoided":0,"acknowledged":0.5,"contemplated":0.5,"familiar":0}},{"label":"I have had a real conversation about it with someone","value":"I have had a real conversation about it with someone","weights":{"avoided":0,"acknowledged":0,"contemplated":0.75,"familiar":0.25}},{"label":"It is ordinary talk — I have discussed it plainly, and often","value":"It is ordinary talk — I have discussed it plainly, and often","weights":{"avoided":0,"acknowledged":0,"contemplated":0,"familiar":1}}]},{"id":"death-arrangements","type":"choice","prompt":"How much of what would need arranging have you actually arranged?","domain":"the practical part","options":[{"label":"I have never thought about any of it","value":"I have never thought about any of it","weights":{"avoided":1,"acknowledged":0,"contemplated":0,"familiar":0}},{"label":"It has occurred to me and I have not acted on it","value":"It has occurred to me and I have not acted on it","weights":{"avoided":0.25,"acknowledged":0.75,"contemplated":0,"familiar":0}},{"label":"Some of it is in order","value":"Some of it is in order","weights":{"avoided":0,"acknowledged":0.5,"contemplated":0.5,"familiar":0}},{"label":"Most of it is arranged and written down","value":"Most of it is arranged and written down","weights":{"avoided":0,"acknowledged":0,"contemplated":0.75,"familiar":0.25}},{"label":"It is all arranged, and the people who need to know have been told","value":"It is all arranged, and the people who need to know have been told","weights":{"avoided":0,"acknowledged":0,"contemplated":0,"familiar":1}}]},{"id":"death-language","type":"choice","prompt":"Which words do you use for it?","domain":"the words for it","options":[{"label":"I avoid the subject, so I have no words for it","value":"I avoid the subject, so I have no words for it","weights":{"avoided":1}},{"label":"I use the softened ones — passing on, losing someone","value":"I use the softened ones — passing on, losing someone","weights":{"acknowledged":1}},{"label":"I use the plain words, when they come up","value":"I use the plain words, when they come up","weights":{"contemplated":1}},{"label":"The plain words are ordinary vocabulary to me","value":"The plain words are ordinary vocabulary to me","weights":{"familiar":1}}]},{"id":"death-in-the-body","type":"choice","prompt":"What happens in your body when you think about it?","domain":"what happens in you","options":[{"label":"It tightens, and I look away","value":"It tightens, and I look away","weights":{"avoided":1,"acknowledged":0,"contemplated":0,"familiar":0}},{"label":"Something in me closes and the subject changes","value":"Something in me closes and the subject changes","weights":{"avoided":0.25,"acknowledged":0.75,"contemplated":0,"familiar":0}},{"label":"It is uncomfortable, and I stay with it","value":"It is uncomfortable, and I stay with it","weights":{"avoided":0,"acknowledged":0.5,"contemplated":0.5,"familiar":0}},{"label":"It is quiet, and I am still here afterwards","value":"It is quiet, and I am still here afterwards","weights":{"avoided":0,"acknowledged":0,"contemplated":0.75,"familiar":0.25}},{"label":"There is very little happening in me at all","value":"There is very little happening in me at all","weights":{"avoided":0,"acknowledged":0,"contemplated":0,"familiar":1}}]},{"id":"death-others","type":"choice","prompt":"How much do you know about how the people nearest you would want it to go?","domain":"the people close to you","options":[{"label":"No idea, and I have not wanted to","value":"No idea, and I have not wanted to","weights":{"avoided":1,"acknowledged":0,"contemplated":0,"familiar":0}},{"label":"We have never spoken about it","value":"We have never spoken about it","weights":{"avoided":0.25,"acknowledged":0.75,"contemplated":0,"familiar":0}},{"label":"They have told me some of it","value":"They have told me some of it","weights":{"avoided":0,"acknowledged":0.5,"contemplated":0.5,"familiar":0}},{"label":"We have talked it through","value":"We have talked it through","weights":{"avoided":0,"acknowledged":0,"contemplated":0.75,"familiar":0.25}},{"label":"It is settled between us — we have both said what we want","value":"It is settled between us — we have both said what we want","weights":{"avoided":0,"acknowledged":0,"contemplated":0,"familiar":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["avoided","acknowledged","contemplated","familiar"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"avoided","label":"Not in view","short":"The subject is somewhere else at the moment","description":"It is not present in your thinking, and there is no particular charge attached to it. That is not a fear of it and not a decision against it — most people have simply not arrived at it, and their attention has gone somewhere else entirely. Nothing here needs to change. It is worth knowing where your attention actually is.","shadow":"Reading a subject you have not reached as one you failed at.","color":"slate","masters":["witnessing","observation"],"calibration":{"dimensions":{"thought":0.2,"emotion":0.2,"spirit":0.1},"practiceLevels":{"witnessing":1,"observation":1},"tags":["not-present","out-of-view"]}},{"id":"acknowledged","label":"Present","short":"A background fact, not a special event","description":"It arrives and goes without being chased away and without asking for attention. Most of your life is organised as though this were certain for everyone else and only eventually for you, which is the ordinary arrangement rather than a stage to be got past. From here the subject is held without being worked on.","shadow":"Assuming it is settled because it is quiet.","color":"sky","masters":["witnessing","jnana"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.25,"emotion":0.1},"practiceLevels":{"witnessing":1,"jnana":1},"tags":["background","acknowledged"]}},{"id":"contemplated","label":"Looked at directly","short":"You have been here before, more than once","description":"You have gone into it deliberately, on more than one occasion, and can describe what that is like without the description turning into advice for anyone else. It is not comfortable and it is not meant to be — it is a subject you have been present for rather than one you keep at a distance, and what you make of it afterwards is your own business.","shadow":"The directness of the experience turning into a position on it.","color":"indigo","masters":["self-inquiry","witnessing"],"calibration":{"dimensions":{"spirit":0.35,"thought":0.25,"emotion":0.15},"practiceLevels":{"self-inquiry":1,"witnessing":2},"tags":["contemplated","been-here"]}},{"id":"familiar","label":"Ordinary company","short":"A fact you keep company with","description":"It sits with you as part of the shape of a life, alongside weather, age, and the deaths of other people, and asks for no special handling. Worth stating plainly, because this reading can be misread as an achievement: it is not the correct answer, and it does not make the other three wrong. Four people reading this will find four different places, and each of them is simply where they are.","shadow":"Familiarity assumed to be a conclusion rather than a location.","color":"violet","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.4,"thought":0.15,"emotion":0.1},"practiceLevels":{"witnessing":2,"jnana":1},"tags":["familiar","undramatic"]}}]'::jsonb, '{"loops_to_check":["grief-avoidance","distraction"],"practice_affinity":["witnessing","self-inquiry"],"deepens_with":["non-dual-glimpses","grief-reservoir"]}'::jsonb, 1, true, false, 100, now())
