-- Detachment grade (4 Yogas)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('detachment-grade', 'Detachment grade', 'Free, not cold', 'vedic', 'attachment', E'Karma yoga asks for action without attachment to the result. The requirement is specific: not caring less about the outcome, but needing it less in order to act.\n\nMost people who claim detachment have actually achieved indifference, which is a different thing.', '⚖️', 6, 6, '[{"id":"detach-outcome","type":"choice","prompt":"How much does the result matter to you when you have done the work?","domain":"outcome","options":[{"label":"Enormously — it is most of what I am working for","value":"Enormously — it is most of what I am working for","weights":{"detached":0}},{"label":"A great deal","value":"A great deal","weights":{"detached":0.25}},{"label":"Quite a lot, honestly","value":"Quite a lot, honestly","weights":{"detached":0.5}},{"label":"Some, but not so much that it changes what I do","value":"Some, but not so much that it changes what I do","weights":{"detached":0.75}},{"label":"Much less than most people would expect","value":"Much less than most people would expect","weights":{"detached":1}}]},{"id":"detach-effort","type":"choice","prompt":"If the result were guaranteed, would you work as hard?","domain":"effort","options":[{"label":"Yes — I would stop almost immediately","value":"Yes — I would stop almost immediately","weights":{"reactive":1,"distancing":0,"detached":0,"free":0}},{"label":"Yes, considerably","value":"Yes, considerably","weights":{"reactive":0.25,"distancing":0.75,"detached":0,"free":0}},{"label":"Less, but I would still do it","value":"Less, but I would still do it","weights":{"reactive":0,"distancing":0.5,"detached":0.5,"free":0}},{"label":"A little less","value":"A little less","weights":{"reactive":0,"distancing":0,"detached":0.75,"free":0.25}},{"label":"No — the work is the point anyway","value":"No — the work is the point anyway","weights":{"reactive":0,"distancing":0,"detached":0,"free":1}}]},{"id":"detach-warmth","type":"choice","prompt":"Do you still enjoy the people involved, or only the work?","domain":"warmth","options":[{"label":"The people have become part of the problem","value":"The people have become part of the problem","weights":{"free":0}},{"label":"I am cooler with them than I used to be","value":"I am cooler with them than I used to be","weights":{"free":0.25}},{"label":"It depends on the person","value":"It depends on the person","weights":{"free":0.5}},{"label":"Yes, I still enjoy them","value":"Yes, I still enjoy them","weights":{"free":0.75}},{"label":"I enjoy them more, now that I am not managing them","value":"I enjoy them more, now that I am not managing them","weights":{"free":1}}]},{"id":"detach-defence","type":"choice","prompt":"Does it protect you from disappointment?","domain":"defence","options":[{"label":"That is exactly what it is for","value":"That is exactly what it is for","weights":{"reactive":1,"distancing":0,"detached":0,"free":0}},{"label":"Most of the reason I do it this way","value":"Most of the reason I do it this way","weights":{"reactive":0.25,"distancing":0.75,"detached":0,"free":0}},{"label":"Quite a lot","value":"Quite a lot","weights":{"reactive":0,"distancing":0.5,"detached":0.5,"free":0}},{"label":"A little — it lowers the stakes","value":"A little — it lowers the stakes","weights":{"reactive":0,"distancing":0,"detached":0.75,"free":0.25}},{"label":"It genuinely does not protect me","value":"It genuinely does not protect me","weights":{"reactive":0,"distancing":0,"detached":0,"free":1}}]},{"id":"detach-difficulty","type":"choice","prompt":"Does the freedom include the hard days?","domain":"difficulty","options":[{"label":"I only feel it when things are going well","value":"I only feel it when things are going well","weights":{"reactive":1,"distancing":0,"detached":0,"free":0}},{"label":"Mostly, but not when it goes wrong","value":"Mostly, but not when it goes wrong","weights":{"reactive":0.25,"distancing":0.75,"detached":0,"free":0}},{"label":"Yes, reasonably","value":"Yes, reasonably","weights":{"reactive":0,"distancing":0.5,"detached":0.5,"free":0}},{"label":"Yes, even then","value":"Yes, even then","weights":{"reactive":0,"distancing":0,"detached":0.75,"free":0.25}},{"label":"Especially then","value":"Especially then","weights":{"reactive":0,"distancing":0,"detached":0,"free":1}}]},{"id":"detach-joy","type":"choice","prompt":"Do you enjoy what you are doing?","domain":"quality","options":[{"label":"No — it is obligation","value":"No — it is obligation","weights":{"distancing":0}},{"label":"Only occasionally","value":"Only occasionally","weights":{"distancing":0.25}},{"label":"Some of the time","value":"Some of the time","weights":{"distancing":0.5}},{"label":"Most of the time","value":"Most of the time","weights":{"distancing":0.75}},{"label":"Yes — I would do it even unwatched and unpaid","value":"Yes — I would do it even unwatched and unpaid","weights":{"distancing":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["reactive","distancing","detached","free"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"reactive","label":"Reactive","short":"The outcome is doing the driving","description":"The result genuinely matters and your effort is organised around it. Nothing wrong with this — it is where most of the world operates, and it is only a problem because you are looking at it.","shadow":"Calling the stake in the result a motivation problem.","color":"rose","masters":["karma","observation"],"calibration":{"dimensions":{"action":0.25,"thought":0.2,"emotion":0.2},"practiceLevels":{"karma":1,"observation":1},"domainStress":{"work":"work-career"},"tags":["detachment","outcome-led"]}},{"id":"distancing","label":"Distancing","short":"You have stepped back, and it went cold","description":"You have reduced your investment and something cooled along with it. Distancing is a real stage and it is often mistaken for the thing after it, which is not.","shadow":"Cool being mistaken for free.","color":"slate","masters":["witnessing","karma"],"calibration":{"dimensions":{"emotion":0.25,"connection":0.2,"action":0.2},"practiceLevels":{"witnessing":1,"karma":1},"tags":["detachment","cool"]}},{"id":"detached","label":"Detached","short":"Free of the need, still in it","description":"You can act fully and need the result less in order to do it. The warmth is largely intact and the work is still enjoyable, which makes this a working rather than a theoretical detachment.","shadow":"Relaxing into work that no longer asks anything of you.","color":"teal","masters":["karma","raja"],"calibration":{"dimensions":{"action":0.3,"spirit":0.25,"emotion":0.2},"practiceLevels":{"karma":2,"raja":1},"tags":["detachment","free"]}},{"id":"free","label":"Free","short":"The action is the whole of it","description":"The need for the outcome is not driving anything, the warmth is intact, and the work is enjoyable on its own terms. Nishkāma karma, in the description rather than the aspiration.","shadow":"Becoming attached to being detached.","color":"emerald","masters":["karma","witnessing"],"calibration":{"dimensions":{"spirit":0.4,"action":0.25,"emotion":0.2},"practiceLevels":{"karma":2,"witnessing":1},"tags":["detachment","nishkama"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["karma","witnessing"],"deepens_with":["vairagya","service-instinct"]}'::jsonb, 1, true, false, 100, now())
