-- Devotion capacity (12 Skills)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('devotion-capacity', 'Devotion capacity', 'Your ability to surrender to something bigger', 'vedic', 'path', E'Devotion is usually described as surrender. Very few people meet it that way. Most meet it first as a duty, a longing, or a set of words that have outlived their meaning.\n\nThis asks what actually happens when you pray, what you are handing over, and what stands in the way of handing it over.', '🙏', 6, 8, '[{"id":"devotion-texture","type":"choice","prompt":"On an ordinary weekday, which of these comes closest to what praying feels like?","domain":"texture","options":[{"label":"A responsibility I keep","value":"A responsibility I keep","weights":{"practical":1}},{"label":"Something that moves me whether I ask or not","value":"Something that moves me whether I ask or not","weights":{"devotional":1}},{"label":"A willingness to hand over what I was managing","value":"A willingness to hand over what I was managing","weights":{"surrendering":1}},{"label":"A sense of standing in front of something total","value":"A sense of standing in front of something total","weights":{"absolute":1}}]},{"id":"devotion-day","type":"choice","prompt":"After you have prayed or practised, what happens to the rest of the day?","domain":"texture","options":[{"label":"Nothing carries over at all","value":"Nothing carries over at all","weights":{"devotional":0}},{"label":"A slightly better mood, briefly","value":"A slightly better mood, briefly","weights":{"devotional":0.25}},{"label":"I am steadier for a while","value":"I am steadier for a while","weights":{"devotional":0.5}},{"label":"Something of it stays with me all day","value":"Something of it stays with me all day","weights":{"devotional":0.75}},{"label":"The day arranges itself differently afterwards","value":"The day arranges itself differently afterwards","weights":{"devotional":1}}]},{"id":"devotion-act","type":"choice","prompt":"When you sit down to pray, what are you actually doing?","domain":"practice","options":[{"label":"Asking for something specific","value":"Asking for something specific","weights":{"practical":1}},{"label":"Repeating words until something seems to answer","value":"Repeating words until something seems to answer","weights":{"devotional":1}},{"label":"Letting the outcome go, even for a moment","value":"Letting the outcome go, even for a moment","weights":{"surrendering":1}},{"label":"Not knowing what I am doing, and doing it anyway","value":"Not knowing what I am doing, and doing it anyway","weights":{"absolute":1}}]},{"id":"devotion-block","type":"choice","prompt":"What gets in the way when you try to let something go?","domain":"block","options":[{"label":"I have never seriously tried to let go of anything","value":"I have never seriously tried to let go of anything","weights":{"practical":1}},{"label":"I need some sign that letting go worked before I can do it again","value":"I need some sign that letting go worked before I can do it again","weights":{"devotional":1}},{"label":"I am responsible for the outcome, and I cannot stop being responsible","value":"I am responsible for the outcome, and I cannot stop being responsible","weights":{"surrendering":1}},{"label":"I cannot tell whether there is anything there to surrender to","value":"I cannot tell whether there is anything there to surrender to","weights":{"absolute":1}}]},{"id":"devotion-in-life","type":"choice","prompt":"How much of what you would call spiritual is part of ordinary life rather than set aside for it?","domain":"practice","options":[{"label":"None of it — it is completely separate","value":"None of it — it is completely separate","weights":{"practical":0}},{"label":"Occasional moments, and nothing more","value":"Occasional moments, and nothing more","weights":{"practical":0.25}},{"label":"Some of it, in places","value":"Some of it, in places","weights":{"practical":0.5}},{"label":"Most days carry some of it","value":"Most days carry some of it","weights":{"practical":0.75}},{"label":"It runs through nearly everything I do","value":"It runs through nearly everything I do","weights":{"practical":1}}]},{"id":"devotion-given","type":"choice","prompt":"Think of the hardest thing in your life. How much of it have you actually handed over?","domain":"release","options":[{"label":"I hold on to nearly everything","value":"I hold on to nearly everything","weights":{"practical":0,"devotional":0,"surrendering":0}},{"label":"I hand over the small things","value":"I hand over the small things","weights":{"practical":1,"devotional":0,"surrendering":0}},{"label":"It depends entirely on the situation","value":"It depends entirely on the situation","weights":{"practical":0,"devotional":1,"surrendering":0}},{"label":"I hand over what I genuinely cannot control","value":"I hand over what I genuinely cannot control","weights":{"practical":0,"devotional":0,"surrendering":0}},{"label":"I hand over the outcome itself","value":"I hand over the outcome itself","weights":{"practical":0,"devotional":0,"surrendering":1}}]},{"id":"devotion-larger","type":"choice","prompt":"When you pray, how often is there a sense of something larger on the other side?","domain":"object","options":[{"label":"Never — it is words into a quiet room","value":"Never — it is words into a quiet room","weights":{"absolute":0}},{"label":"Rarely","value":"Rarely","weights":{"absolute":0.25}},{"label":"Sometimes","value":"Sometimes","weights":{"absolute":0.5}},{"label":"Often","value":"Often","weights":{"absolute":0.75}},{"label":"Almost always, and it changes what I say","value":"Almost always, and it changes what I say","weights":{"absolute":1}}]},{"id":"devotion-moment","type":"choice","prompt":"Recall the last time you truly let go of something. What happened next?","domain":"release","options":[{"label":"Nothing happened, and I went back to what I was doing","value":"Nothing happened, and I went back to what I was doing","weights":{"practical":1}},{"label":"I felt lighter for a while","value":"I felt lighter for a while","weights":{"devotional":1}},{"label":"I let go of a decision I had already made","value":"I let go of a decision I had already made","weights":{"surrendering":1}},{"label":"The question of who was doing the letting stopped mattering","value":"The question of who was doing the letting stopped mattering","weights":{"absolute":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["practical","devotional","surrendering","absolute"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"practical","label":"Kept as a duty","short":"The practice is maintained, not entered","description":"The form is intact and something real is inside it, held at arm’s length. Nothing has gone wrong here — the practice simply has not yet become somewhere you go rather than something you complete.","shadow":"Mistaking consistency for closeness.","color":"slate","masters":["bhakti","observation"],"calibration":{"dimensions":{"action":0.25,"thought":0.15,"spirit":0.1},"practiceLevels":{"bhakti":1,"observation":1},"tags":["kept-as-duty","formal"]}},{"id":"devotional","label":"Felt as longing","short":"It moves you more than you direct it","description":"There is genuine feeling here, and it arrives on its own schedule rather than on command. The edge to watch is making the feeling the measure of the practice — days without it can be mistaken for days without progress.","shadow":"Measuring practice by whether it felt like something.","color":"rose","masters":["bhakti","emotional-healing"],"calibration":{"dimensions":{"emotion":0.35,"connection":0.25,"spirit":0.15},"practiceLevels":{"bhakti":1,"emotional-healing":1},"domainStress":{"heart":"emotional-healing"},"tags":["longing","felt"]}},{"id":"surrendering","label":"Open hand","short":"Something can genuinely be handed over","description":"Release is available to you, at least in part. The work now is not learning to let go but noticing how much of what you carry you chose to pick up in the first place.","shadow":"Using surrender as a way of avoiding a decision.","color":"teal","masters":["bhakti","witnessing"],"calibration":{"dimensions":{"spirit":0.3,"action":0.2,"emotion":0.15},"practiceLevels":{"bhakti":2,"witnessing":1},"tags":["releasing","willing"]}},{"id":"absolute","label":"Facing the total","short":"There is something larger on the other side","description":"What you bow to is not a figure or an idea but the whole of it, and the practice has started to reorganise the rest of your life around that. This is worth handling carefully — a sense of the total can also become an excellent way of not looking at what is in front of you.","shadow":"Seeking the infinite in order to avoid the immediate.","color":"indigo","masters":["bhakti","witnessing"],"calibration":{"dimensions":{"spirit":0.45,"connection":0.2},"practiceLevels":{"bhakti":2,"witnessing":2},"domainStress":{"contact":"relationship"},"tags":["total","formless"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["bhakti","witnessing"],"deepens_with":["devotional-object","vairagya"]}'::jsonb, 1, true, false, 100, now())
