  updated_at
) VALUES
    ('devotional-object', 'Devotional object', 'To what — or whom — do you bow?', 'vedic', 'path', E'Most devotion has an address. Something is being addressed, and the address shapes the experience entirely — a personal god and a universal one are not the same practice.\n\nThis asks what yours is, and whether you chose it.', '🕉️', 6, 6, '[{"id":"devotion-object","type":"choice","prompt":"When you pray, who or what is being addressed?","domain":"address","options":[{"label":"Nothing — I do not pray","value":"Nothing — I do not pray","weights":{"none":1,"external-figure":0,"universal":0,"formless":0}},{"label":"Someone specific: a person, a deity, a teacher","value":"Someone specific: a person, a deity, a teacher","weights":{"none":0.25,"external-figure":0.75,"universal":0,"formless":0}},{"label":"Something larger and impersonal: the universe, existence, the source","value":"Something larger and impersonal: the universe, existence, the source","weights":{"none":0,"external-figure":0.5,"universal":0.5,"formless":0}},{"label":"It has no form at all — just a direction of attention","value":"It has no form at all — just a direction of attention","weights":{"none":0,"external-figure":0,"universal":0.75,"formless":0.25}},{"label":"I have never framed it, I just do it","value":"I have never framed it, I just do it","weights":{"none":0,"external-figure":0,"universal":0,"formless":1}}]},{"id":"devotion-chosen","type":"choice","prompt":"Did you choose that, or did you inherit it?","domain":"inheritance","options":[{"label":"Inherited, and I have never questioned it","value":"Inherited, and I have never questioned it","weights":{"none":1,"external-figure":0,"universal":0,"formless":0}},{"label":"Inherited, and I have accepted it","value":"Inherited, and I have accepted it","weights":{"none":0.25,"external-figure":0.75,"universal":0,"formless":0}},{"label":"Inherited, but I have softened it","value":"Inherited, but I have softened it","weights":{"none":0,"external-figure":0.5,"universal":0.5,"formless":0}},{"label":"Chosen for myself, deliberately","value":"Chosen for myself, deliberately","weights":{"none":0,"external-figure":0,"universal":0.75,"formless":0.25}},{"label":"It keeps changing as I do","value":"It keeps changing as I do","weights":{"none":0,"external-figure":0,"universal":0,"formless":1}}]},{"id":"devotion-answered","type":"choice","prompt":"Does anything answer?","domain":"response","options":[{"label":"I do not expect a response","value":"I do not expect a response","weights":{"none":1}},{"label":"Occasionally, and I cannot be sure","value":"Occasionally, and I cannot be sure","weights":{"none":0}},{"label":"At certain times, fairly clearly","value":"At certain times, fairly clearly","weights":{"none":0}},{"label":"Regularly, and specifically","value":"Regularly, and specifically","weights":{"none":0}},{"label":"I have stopped distinguishing asking from being answered","value":"I have stopped distinguishing asking from being answered","weights":{"none":0}}]},{"id":"devotion-need","type":"choice","prompt":"What do you actually want from it?","domain":"need","options":[{"label":"Comfort in difficulty","value":"Comfort in difficulty","weights":{"universal":1}},{"label":"Absolution from wrongdoing","value":"Absolution from wrongdoing","weights":{"universal":1}},{"label":"A better outcome","value":"A better outcome","weights":{"universal":1}},{"label":"To not be alone","value":"To not be alone","weights":{"universal":1}},{"label":"To be shown what is true","value":"To be shown what is true","weights":{"universal":1}}]},{"id":"devotion-without","type":"choice","prompt":"Could you do it with nothing to bow to?","domain":"objectless","options":[{"label":"No — without it there is nothing","value":"No — without it there is nothing","weights":{"none":1,"external-figure":0,"universal":0,"formless":0}},{"label":"It feels thin and slightly wrong","value":"It feels thin and slightly wrong","weights":{"none":0.25,"external-figure":0.75,"universal":0,"formless":0}},{"label":"Something remains but weaker","value":"Something remains but weaker","weights":{"none":0,"external-figure":0.5,"universal":0.5,"formless":0}},{"label":"Yes, largely unchanged","value":"Yes, largely unchanged","weights":{"none":0,"external-figure":0,"universal":0.75,"formless":0.25}},{"label":"That is closer to how it already is","value":"That is closer to how it already is","weights":{"none":0,"external-figure":0,"universal":0,"formless":1}}]},{"id":"devotion-quality","type":"choice","prompt":"When devotion is strong, how does it feel from the inside?","domain":"quality","options":[{"label":"Relief, mostly","value":"Relief, mostly","weights":{"formless":1}},{"label":"Comfort and closeness","value":"Comfort and closeness","weights":{"formless":1}},{"label":"A settling, and being held","value":"A settling, and being held","weights":{"formless":1}},{"label":"An intensity, and a narrowing","value":"An intensity, and a narrowing","weights":{"formless":1}},{"label":"A dissolving, and a great lightness","value":"A dissolving, and a great lightness","weights":{"formless":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["none","external-figure","universal","formless"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"none","label":"No object","short":"Practice without an address","description":"There is no devotional structure in your life. This is common and not a deficiency. What tends to fill the space is usually a practice that asks the same question by a different route.","shadow":"Assuming the missing piece is the problem.","color":"slate","masters":["observation","raja"],"calibration":{"dimensions":{"spirit":0.2,"thought":0.2,"connection":0.15},"practiceLevels":{"observation":1},"tags":["devotion","unaddressed"]}},{"id":"external-figure","label":"An external figure","short":"Someone, and you know who","description":"Your devotion has a personal address, usually inherited. That is a real and functional relationship rather than a weakness, and the thing worth examining is whether you ever chose the address or simply inherited it.","shadow":"Inheriting a relationship and treating it as a discovery.","color":"amber","masters":["bhakti","karma"],"calibration":{"dimensions":{"emotion":0.3,"connection":0.3,"spirit":0.2},"practiceLevels":{"bhakti":1},"domainStress":{"relation":"relationship"},"tags":["devotion","personal"]}},{"id":"universal","label":"Something larger","short":"Personal, but not particular","description":"Your devotion is directed at something larger than any individual, and it is usually paired with a real sense that something is listening. This is where most of the tradition lives.","shadow":"Abstraction standing in for intimacy.","color":"teal","masters":["bhakti","witnessing"],"calibration":{"dimensions":{"spirit":0.35,"emotion":0.25,"connection":0.2},"practiceLevels":{"bhakti":2,"witnessing":1},"tags":["devotion","universal"]}},{"id":"formless","label":"Formless","short":"The address is the direction of attention","description":"The practice has no object and does not need one. What remains is an orientation, and it holds up under examination in a way that most devotional structures do not.","shadow":"Adding an object back the moment it gets uncomfortable.","color":"indigo","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.45,"emotion":0.15},"practiceLevels":{"witnessing":2,"jnana":1},"tags":["devotion","formless"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["bhakti","raja"],"deepens_with":["devotion-capacity","non-dual-glimpse"]}'::jsonb, 1, true, false, 100, now())
