  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('dharana', 'Dhāraṇā', 'Your concentration muscle', 'yogic', 'witness', E'The sixth limb is holding one thing. Not noticing many things, not finding a state — holding.\n\nThe interesting part of concentration is not the holding. It is what happens in the interval between losing it and noticing you lost it.', '🎯', 6, 6, '[{"id":"dhara-object","type":"choice","prompt":"What do you hold onto when you concentrate?","domain":"object","options":[{"label":"A sound, or a part of it","value":"A sound, or a part of it","weights":{"sustained":1}},{"label":"The breath","value":"The breath","weights":{"sustained":1}},{"label":"A single sensation in the body","value":"A single sensation in the body","weights":{"sustained":1}},{"label":"A thought, held open","value":"A thought, held open","weights":{"sustained":1}},{"label":"A name, a mantra, or a word","value":"A name, a mantra, or a word","weights":{"sustained":1}}]},{"id":"dhara-length","type":"choice","prompt":"How long can you hold before the mind leaves?","domain":"duration","options":[{"label":"A few seconds","value":"A few seconds","weights":{"wandering":1,"returning":0,"sustained":0,"one-pointed":0}},{"label":"Under a minute","value":"Under a minute","weights":{"wandering":0.25,"returning":0.75,"sustained":0,"one-pointed":0}},{"label":"A few minutes","value":"A few minutes","weights":{"wandering":0,"returning":0.5,"sustained":0.5,"one-pointed":0}},{"label":"Ten minutes or more","value":"Ten minutes or more","weights":{"wandering":0,"returning":0,"sustained":0.75,"one-pointed":0.25}},{"label":"It holds longer than I can pay attention to","value":"It holds longer than I can pay attention to","weights":{"wandering":0,"returning":0,"sustained":0,"one-pointed":1}}]},{"id":"dhara-return","type":"choice","prompt":"When you notice you have drifted, what brings you back?","domain":"return","options":[{"label":"Nothing — I usually do not notice","value":"Nothing — I usually do not notice","weights":{"returning":1}},{"label":"A jolt of frustration","value":"A jolt of frustration","weights":{"returning":1}},{"label":"A fresh start on the breath","value":"A fresh start on the breath","weights":{"returning":1}},{"label":"A deliberate re-aiming","value":"A deliberate re-aiming","weights":{"returning":1}},{"label":"Something quite subtle","value":"Something quite subtle","weights":{"returning":1}}]},{"id":"dhara-effort","type":"choice","prompt":"How hard is it to hold — gripping, or leaning?","domain":"effort","options":[{"label":"I grip, and it slips","value":"I grip, and it slips","weights":{"wandering":1,"returning":0,"sustained":0,"one-pointed":0}},{"label":"It takes constant effort","value":"It takes constant effort","weights":{"wandering":0.25,"returning":0.75,"sustained":0,"one-pointed":0}},{"label":"Some effort, mostly stable","value":"Some effort, mostly stable","weights":{"wandering":0,"returning":0.5,"sustained":0.5,"one-pointed":0}},{"label":"Relaxed and steady","value":"Relaxed and steady","weights":{"wandering":0,"returning":0,"sustained":0.75,"one-pointed":0.25}},{"label":"Effortless, and the object holds itself","value":"Effortless, and the object holds itself","weights":{"wandering":0,"returning":0,"sustained":0,"one-pointed":1}}]},{"id":"dhara-obstacle","type":"choice","prompt":"What most reliably breaks your concentration?","domain":"obstacle","options":[{"label":"Boredom and restlessness","value":"Boredom and restlessness","weights":{"wandering":1,"returning":0,"sustained":0,"one-pointed":0}},{"label":"Physical discomfort","value":"Physical discomfort","weights":{"wandering":0.25,"returning":0.75,"sustained":0,"one-pointed":0}},{"label":"Emotion — something arising","value":"Emotion — something arising","weights":{"wandering":0,"returning":0.5,"sustained":0.5,"one-pointed":0}},{"label":"Noise, or the people around me","value":"Noise, or the people around me","weights":{"wandering":0,"returning":0,"sustained":0.75,"one-pointed":0.25}},{"label":"Nothing in particular; it just goes","value":"Nothing in particular; it just goes","weights":{"wandering":0,"returning":0,"sustained":0,"one-pointed":1}}]},{"id":"dhara-off","type":"choice","prompt":"Does that concentration follow you out of sitting?","domain":"transfer","options":[{"label":"Not at all — it stays there","value":"Not at all — it stays there","weights":{"sustained":0}},{"label":"Briefly, right afterwards","value":"Briefly, right afterwards","weights":{"sustained":0.25}},{"label":"For a while, in low-stakes situations","value":"For a while, in low-stakes situations","weights":{"sustained":0.5}},{"label":"In most situations, if I remember to use it","value":"In most situations, if I remember to use it","weights":{"sustained":0.75}},{"label":"It has become how I work, not just how I sit","value":"It has become how I work, not just how I sit","weights":{"sustained":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["wandering","returning","sustained","one-pointed"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"wandering","label":"Wandering","short":"Leaving before you notice","description":"Attention is not staying, and — more importantly — you often do not notice it leaving. This is the most common starting point and the most improvable one, because the noticing is what develops first.","shadow":"Reading the wandering as a failure of discipline.","color":"rose","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.3,"spirit":0.2},"practiceLevels":{"observation":1,"witnessing":1},"tags":["dharana","unstable"]}},{"id":"returning","label":"Returning","short":"The return is the practice","description":"You leave and you come back. The coming-back is the whole mechanism of dhāraṇā, and doing it many times is not a failure to concentrate — it is concentrating.","shadow":"Judging each return by how long you were gone.","color":"amber","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.25,"body":0.1},"practiceLevels":{"observation":1,"witnessing":1},"tags":["dharana","returning"]}},{"id":"sustained","label":"Sustained","short":"It holds, without much fight","description":"You can hold one thing for a real stretch and it is not costing you much. The next question is what happens when the object stops being pleasant.","shadow":"Concentration that only works on pleasant objects.","color":"teal","masters":["raja","witnessing"],"calibration":{"dimensions":{"thought":0.2,"spirit":0.3},"practiceLevels":{"raja":1,"witnessing":1},"tags":["dharana","sustained"]}},{"id":"one-pointed","label":"One-pointed","short":"The object holds itself","description":"Concentration has become natural rather than applied. The interesting edge case is whether it survives contact with something unpleasant — that is where the next limb begins.","shadow":"Retreat into the comfortable object.","color":"indigo","masters":["raja","kriya"],"calibration":{"dimensions":{"spirit":0.4,"thought":0.2},"practiceLevels":{"raja":2},"tags":["dharana","one-pointed"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["raja","witnessing"],"deepens_with":["dhyana","meditation-depth"]}'::jsonb, 1, true, false, 100, now())
