-- Dhyāna (Patanjali)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('dhyana', 'Dhyāna', 'The flow of unbroken attention', 'yogic', 'witness', E'Dhāraṇā is holding. Dhyāna is what holding becomes when you stop having to do it.\n\nThe distinction is not a technicality. Holding is effort; flowing is what effort was for.', '🌊', 6, 6, '[{"id":"dhyana-flow","type":"choice","prompt":"When attention settles, is it steady or does it keep breaking?","domain":"quality","options":[{"label":"It breaks constantly","value":"It breaks constantly","weights":{"broken":0,"flowing":0,"continuous":0}},{"label":"It breaks regularly","value":"It breaks regularly","weights":{"broken":1,"flowing":0,"continuous":0}},{"label":"It holds, with gaps","value":"It holds, with gaps","weights":{"broken":0,"flowing":0,"continuous":0}},{"label":"It flows for a real stretch","value":"It flows for a real stretch","weights":{"broken":0,"flowing":1,"continuous":0}},{"label":"It does not break at all","value":"It does not break at all","weights":{"broken":0,"flowing":0,"continuous":1}}]},{"id":"dhyana-noticed","type":"choice","prompt":"Do you notice the flow while it is happening?","domain":"awareness","options":[{"label":"I am completely inside it","value":"I am completely inside it","weights":{"broken":1,"flowing":0,"continuous":0,"expanded":0}},{"label":"I am inside it, and also know I am","value":"I am inside it, and also know I am","weights":{"broken":0.25,"flowing":0.75,"continuous":0,"expanded":0}},{"label":"I am watching it from a slight distance","value":"I am watching it from a slight distance","weights":{"broken":0,"flowing":0.5,"continuous":0.5,"expanded":0}},{"label":"I am the one watching it happen","value":"I am the one watching it happen","weights":{"broken":0,"flowing":0,"continuous":0.75,"expanded":0.25}},{"label":"I can no longer tell the difference","value":"I can no longer tell the difference","weights":{"broken":0,"flowing":0,"continuous":0,"expanded":1}}]},{"id":"dhyana-content","type":"choice","prompt":"What is present during the flow — thoughts, or something else?","domain":"content","options":[{"label":"Thoughts, flowing smoothly","value":"Thoughts, flowing smoothly","weights":{"broken":1,"flowing":0,"continuous":0,"expanded":0}},{"label":"Mostly thoughts, with gaps","value":"Mostly thoughts, with gaps","weights":{"broken":0.25,"flowing":0.75,"continuous":0,"expanded":0}},{"label":"A mix of both","value":"A mix of both","weights":{"broken":0,"flowing":0.5,"continuous":0.5,"expanded":0}},{"label":"Clarity more than content","value":"Clarity more than content","weights":{"broken":0,"flowing":0,"continuous":0.75,"expanded":0.25}},{"label":"Something with no content at all","value":"Something with no content at all","weights":{"broken":0,"flowing":0,"continuous":0,"expanded":1}}]},{"id":"dhyana-elsewhere","type":"choice","prompt":"Does this happen outside formal sitting?","domain":"transfer","options":[{"label":"Never — it is a sitting-only state","value":"Never — it is a sitting-only state","weights":{"continuous":0}},{"label":"Rarely, and briefly","value":"Rarely, and briefly","weights":{"continuous":0}},{"label":"Sometimes, in quiet moments","value":"Sometimes, in quiet moments","weights":{"continuous":0}},{"label":"Often, in ordinary activity","value":"Often, in ordinary activity","weights":{"continuous":0}},{"label":"It is more or less continuous now","value":"It is more or less continuous now","weights":{"continuous":1}}]},{"id":"dhyana-after","type":"choice","prompt":"How do you feel for some time after a session like that?","domain":"residue","options":[{"label":"Drained, or mildly worse","value":"Drained, or mildly worse","weights":{"continuous":0}},{"label":"About the same as before","value":"About the same as before","weights":{"continuous":0.25}},{"label":"Slightly clearer","value":"Slightly clearer","weights":{"continuous":0.5}},{"label":"Clearly settled for a while","value":"Clearly settled for a while","weights":{"continuous":0.75}},{"label":"Changed — and still changed later in the day","value":"Changed — and still changed later in the day","weights":{"continuous":1}}]},{"id":"dhyana-seek","type":"choice","prompt":"Do you try to reach it, or wait for it?","domain":"direction","options":[{"label":"I chase it hard","value":"I chase it hard","weights":{"flowing":1}},{"label":"I try to set it up","value":"I try to set it up","weights":{"flowing":1}},{"label":"I make the conditions and wait","value":"I make the conditions and wait","weights":{"flowing":1}},{"label":"It comes and goes regardless","value":"It comes and goes regardless","weights":{"flowing":1}},{"label":"I stopped trying to produce it","value":"I stopped trying to produce it","weights":{"flowing":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["broken","flowing","continuous","expanded"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"broken","label":"Broken","short":"The flow keeps restarting","description":"Attention reaches a settled state and then returns to the surface. Dhyāna is not here yet, and the good news is that this is what dhāraṇā is for.","shadow":"Reaching for a depth the foundation is not built for.","color":"rose","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.3,"spirit":0.15},"practiceLevels":{"observation":1,"witnessing":1},"tags":["dhyana","restless"]}},{"id":"flowing","label":"Flowing","short":"It flows, with gaps","description":"There are real stretches of unbroken attention. They are not long yet, and they are fragile, but the capacity is present and the gaps are getting shorter.","shadow":"Reaching for a depth the foundation is not built for.","color":"amber","masters":["raja","witnessing"],"calibration":{"dimensions":{"thought":0.2,"spirit":0.3},"practiceLevels":{"raja":1,"witnessing":1},"tags":["dhyana","flowing"]}},{"id":"continuous","label":"Continuous","short":"Unbroken, and it leaves something behind","description":"Unbroken attention is genuinely available and it has a lasting residue. This is dhyāna proper, and it is doing real work on the rest of your life whether you notice or not.","shadow":"Noticing the state more than the change it produces.","color":"teal","masters":["raja","witnessing"],"calibration":{"dimensions":{"spirit":0.4,"thought":0.2,"emotion":0.15},"practiceLevels":{"raja":2},"tags":["dhyana","continuous"]}},{"id":"expanded","label":"Expanded","short":"It no longer has an inside","description":"The distinction between the one concentrating and the thing concentrated upon has become unreliable. Patañjali describes what remains as samādhi. Practically: the state travels, and it is difficult to get back to ordinary life afterwards.","shadow":"Preferring the state to what it was for.","color":"indigo","masters":["raja","jnana"],"calibration":{"dimensions":{"spirit":0.45,"thought":0.2},"practiceLevels":{"raja":2,"jnana":1},"tags":["dhyana","wide"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["raja","witnessing"],"deepens_with":["meditation-depth","dharana"]}'::jsonb, 1, true, false, 100, now())
