-- Discipline style (Skills)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('discipline-style', 'Discipline style', 'How you sustain effort', 'yogic', 'practice', E'Discipline is not a single thing. Some people hold it in a structure; some find it in the doing itself; some need it to be shared; some need it to be felt in the body before it is real.\n\nThere is no correct style. What matters is whether the style you are using is the one that actually works for you, because using the wrong one produces a lot of effort and very little progress.', '🏋️', 6, 6, '[{"id":"discipline-routine","type":"choice","prompt":"How do you hold a routine?","domain":"routine","options":[{"label":"I need a clear structure, or I drift","value":"I need a clear structure, or I drift","weights":{"structured":1}},{"label":"I need it to feel fresh, or I get bored","value":"I need it to feel fresh, or I get bored","weights":{"spontaneous":1}},{"label":"I need someone else in it, or I drop it","value":"I need someone else in it, or I drop it","weights":{"relational":1}},{"label":"I need to feel it in my body, or it is empty","value":"I need to feel it in my body, or it is empty","weights":{"somatic":1}}]},{"id":"discipline-start","type":"choice","prompt":"What gets you started on something hard?","domain":"starting","options":[{"label":"A plan, and a time, and a place","value":"A plan, and a time, and a place","weights":{"structured":1,"spontaneous":0,"relational":0,"somatic":0}},{"label":"A spark, and the willingness to follow it","value":"A spark, and the willingness to follow it","weights":{"structured":0,"spontaneous":1,"relational":0,"somatic":0}},{"label":"Someone else counting on me","value":"Someone else counting on me","weights":{"structured":0,"spontaneous":0,"relational":1,"somatic":0}},{"label":"A feeling in the body that it is time","value":"A feeling in the body that it is time","weights":{"structured":0,"spontaneous":0,"relational":0,"somatic":1}}]},{"id":"discipline-sustain","type":"choice","prompt":"What keeps you going when it gets hard?","domain":"sustaining","options":[{"label":"The structure holds, and I stay inside it","value":"The structure holds, and I stay inside it","weights":{"structured":1,"spontaneous":0,"relational":0,"somatic":0}},{"label":"The doing itself becomes interesting again","value":"The doing itself becomes interesting again","weights":{"structured":0,"spontaneous":1,"relational":0,"somatic":0}},{"label":"I cannot let the other person down","value":"I cannot let the other person down","weights":{"structured":0,"spontaneous":0,"relational":1,"somatic":0}},{"label":"I can feel the shift, and I stay for it","value":"I can feel the shift, and I stay for it","weights":{"structured":0,"spontaneous":0,"relational":0,"somatic":1}}]},{"id":"discipline-slips","type":"choice","prompt":"What happens when you miss a session?","domain":"slips","options":[{"label":"I lose the thread and do not go back","value":"I lose the thread and do not go back","weights":{"structured":0}},{"label":"I feel bad about it, and return with effort","value":"I feel bad about it, and return with effort","weights":{"structured":0.25}},{"label":"I pick it up again, and it is fine","value":"I pick it up again, and it is fine","weights":{"structured":0.5}},{"label":"I notice the gap, and close it easily","value":"I notice the gap, and close it easily","weights":{"structured":0.75}},{"label":"It does not matter — the practice is not the session","value":"It does not matter — the practice is not the session","weights":{"structured":1}}]},{"id":"discipline-feedback","type":"choice","prompt":"How do you know practice is working?","domain":"feedback","options":[{"label":"I track it — numbers, streaks, records","value":"I track it — numbers, streaks, records","weights":{"structured":1}},{"label":"I notice when something in me changes","value":"I notice when something in me changes","weights":{"spontaneous":1}},{"label":"I hear it from someone who knows me","value":"I hear it from someone who knows me","weights":{"relational":1}},{"label":"I feel it in the body before I think it","value":"I feel it in the body before I think it","weights":{"somatic":1}}]},{"id":"discipline-alone","type":"choice","prompt":"How do you practise when nobody is watching?","domain":"alone","options":[{"label":"I need a schedule, or it does not happen","value":"I need a schedule, or it does not happen","weights":{"structured":1,"spontaneous":0,"relational":0,"somatic":0}},{"label":"I do it when the mood is right","value":"I do it when the mood is right","weights":{"structured":0,"spontaneous":1,"relational":0,"somatic":0}},{"label":"I do it because someone else is doing it","value":"I do it because someone else is doing it","weights":{"structured":0,"spontaneous":0,"relational":1,"somatic":0}},{"label":"I do it because the body needs it","value":"I do it because the body needs it","weights":{"structured":0,"spontaneous":0,"relational":0,"somatic":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["structured","spontaneous","relational","somatic"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"structured","label":"Structured","short":"The frame does the work","description":"You hold discipline in a shape — a time, a place, a sequence — and the shape does the holding for you. The strength of this is reliability: practice becomes inevitable rather than optional. The risk is that the frame becomes the point, and the person inside it stops being consulted.","shadow":"The structure replacing the inquiry.","color":"slate","masters":["raja","karma"],"calibration":{"dimensions":{"action":0.35,"thought":0.2,"body":0.15},"practiceLevels":{"raja":1,"karma":1},"domainStress":{"routine":"raja"},"tags":["structured","reliable"]}},{"id":"spontaneous","label":"Spontaneous","short":"The doing itself is the guide","description":"You hold discipline in the act of doing, and the doing has to feel alive or it stops. The strength is freshness: practice never becomes empty because it is always being found again. The risk is that it disappears whenever the mood does.","shadow":"Waiting for the right feeling instead of finding it in the doing.","color":"amber","masters":["kriya","bhakti"],"calibration":{"dimensions":{"spirit":0.3,"emotion":0.25,"action":0.2},"practiceLevels":{"kriya":1,"bhakti":1},"domainStress":{"spontaneity":"kriya"},"tags":["alive","mood-dependent"]}},{"id":"relational","label":"Relational","short":"The other person makes it real","description":"You hold discipline in relationship, and practice is sustained by the presence of someone else who is also doing it. The strength is accountability: the other person keeps you honest without having to say anything. The risk is that the practice is theirs, not yours.","shadow":"Practising for the other person instead of with them.","color":"rose","masters":["relationship","bhakti"],"calibration":{"dimensions":{"connection":0.35,"emotion":0.25,"action":0.15},"practiceLevels":{"relationship":1,"bhakti":1},"domainStress":{"relation":"relationship"},"tags":["shared","other-anchored"]}},{"id":"somatic","label":"Somatic","short":"The body has to feel it first","description":"You hold discipline through the body, and practice is only real once it has been felt. The strength is honesty: you cannot fake your way past a body that knows the difference between going through the motions and being present. The risk is that the body is asked to do the mind''s work.","shadow":"Waiting for the body to feel ready instead of moving it.","color":"teal","masters":["body","breath"],"calibration":{"dimensions":{"body":0.4,"emotion":0.2,"spirit":0.15},"practiceLevels":{"body":2,"breath":1},"domainStress":{"sensation":"body"},"tags":["somatic","felt"]}}]'::jsonb, '{"loops_to_check":["drift","approval-seeking"],"practice_affinity":["raja","karma","relationship"],"deepens_with":["practice-level-calibration","sankalpa-shakti"]}'::jsonb, 1, true, false, 100, now())
