-- Doṣa constitution (Engines)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('dosha-constitution', 'Doṣa constitution', 'Your Ayurvedic balance', 'ayurvedic', 'constitution', E'Āyurveda reads health as a balance between three forces that are always in motion: vāta, the movement of wind; pitta, the metabolism of heat and light; and kapha, the structure and lubrication of water and earth. Each person is read as a proportion rather than a type, and the proportion shifts with the season, the food and the life being lived.\n\nThis is a working description, not a diagnosis, and it is not a substitute for any medical opinion about the body. What it is genuinely useful for is noticing which of your own tendencies is currently running hottest, because a great deal of what people call their personality is one doṣa behaving predictably.', '🌿', 7, 6, '[{"id":"dosha-tempo","type":"choice","prompt":"How does your mind normally move?","domain":"tempo","options":[{"label":"Quick, light, several things at once","value":"Quick, light, several things at once","weights":{"vata":1}},{"label":"Sharp, hot, focused to the point of narrowing","value":"Sharp, hot, focused to the point of narrowing","weights":{"pitta":1}},{"label":"Slow, heavy, hard to shift once set","value":"Slow, heavy, hard to shift once set","weights":{"kapha":1}}]},{"id":"dosha-frame","type":"choice","prompt":"How does your body usually feel to live in?","domain":"frame","options":[{"label":"Light and dry, and I feel the cold","value":"Light and dry, and I feel the cold","weights":{"vata":1}},{"label":"Warm and sharp, and I run hot","value":"Warm and sharp, and I run hot","weights":{"pitta":1}},{"label":"Solid and slow, and it takes a while to warm up","value":"Solid and slow, and it takes a while to warm up","weights":{"kapha":1}}]},{"id":"dosha-appetite","type":"choice","prompt":"What is your appetite like on an ordinary day?","domain":"appetite","options":[{"label":"Irregular — some days I forget to eat","value":"Irregular — some days I forget to eat","weights":{"vata":1,"pitta":0,"kapha":0}},{"label":"Sharp — I am hungry and I want it now","value":"Sharp — I am hungry and I want it now","weights":{"vata":0,"pitta":1,"kapha":0}},{"label":"Steady, and I can skip without noticing","value":"Steady, and I can skip without noticing","weights":{"vata":0,"pitta":0,"kapha":1}}]},{"id":"dosha-sleep","type":"choice","prompt":"What is your sleep actually like?","domain":"sleep","options":[{"label":"Light, and easily broken","value":"Light, and easily broken","weights":{"vata":1,"pitta":0,"kapha":0}},{"label":"Short, and I wake up alert","value":"Short, and I wake up alert","weights":{"vata":0,"pitta":1,"kapha":0}},{"label":"Deep and long, and hard to leave","value":"Deep and long, and hard to leave","weights":{"vata":0,"pitta":0,"kapha":1}}]},{"id":"dosha-unwell","type":"choice","prompt":"When you are unwell, what changes in you first?","domain":"fever","options":[{"label":"I become restless, and I cannot settle anywhere","value":"I become restless, and I cannot settle anywhere","weights":{"vata":1}},{"label":"I become hot, irritable, and unable to sleep","value":"I become hot, irritable, and unable to sleep","weights":{"pitta":1}},{"label":"I become heavy, slow, and want to be left alone","value":"I become heavy, slow, and want to be left alone","weights":{"kapha":1}}]},{"id":"dosha-weather","type":"choice","prompt":"What is the weather inside you on a normal day?","domain":"weather","options":[{"label":"Constantly changing; I am never the same twice","value":"Constantly changing; I am never the same twice","weights":{"vata":0,"pitta":0,"kapha":0}},{"label":"Mostly changing, but in a consistent direction","value":"Mostly changing, but in a consistent direction","weights":{"vata":1,"pitta":0,"kapha":0}},{"label":"Warm and steady, with sharp edges now and then","value":"Warm and steady, with sharp edges now and then","weights":{"vata":0,"pitta":0,"kapha":0}},{"label":"Slow and consistent, occasionally heating up","value":"Slow and consistent, occasionally heating up","weights":{"vata":0,"pitta":1,"kapha":0}},{"label":"Almost unchanging","value":"Almost unchanging","weights":{"vata":0,"pitta":0,"kapha":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["vata","pitta","kapha"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"vata","label":"Vāta-dominant","short":"Movement with very little holding it","description":"Movement, lightness and change dominate: quick thought, variable appetite, light sleep, a body that feels the cold. The strength is adaptability — this constitution can go anywhere and learn anything. The difficulty is that nothing accumulates, and a life without something heavy in it keeps resetting rather than building.","shadow":"Mistaking restlessness for freedom, and reinvention for progress.","color":"sky","masters":["breath","body"],"calibration":{"dimensions":{"body":0.25,"spirit":0.2,"thought":0.2},"practiceLevels":{"breath":1,"body":1},"domainStress":{"grounding":"health"},"tags":["mobile","lightly-held"]}},{"id":"pitta","label":"Pitta-dominant","short":"Heat, focus, and a narrowing edge","description":"Heat and light dominate: sharp attention, strong appetite, short efficient sleep, a body that runs warm. This is the constitution of people who get things done, and it works until the heat starts costing sleep, digestion and patience. Pitta in excess is not aggression; it is heat with nowhere to go.","shadow":"Confusing the sharpness of the focus with the whole truth.","color":"orange","masters":["body","kriya"],"calibration":{"dimensions":{"emotion":0.25,"body":0.25,"action":0.2},"practiceLevels":{"body":1,"kriya":1},"domainStress":{"heat":"health"},"tags":["hot","focused"]}},{"id":"kapha","label":"Kapha-dominant","short":"Structure, with a cost in inertia","description":"Structure and lubrication dominate: steady appetite, deep sleep, a solid frame, a mind that does not move until it decides to. The strength is that things built in this constitution last. The difficulty is that the same stability that holds also resists change, and the resistance is felt from the inside as reluctance.","shadow":"Reading immobility as rest, and rest as enough.","color":"teal","masters":["raja","breath"],"calibration":{"dimensions":{"body":0.3,"emotion":0.15,"spirit":0.15},"practiceLevels":{"raja":1,"breath":1},"tags":["heavy","slow"]}}]'::jsonb, '{"loops_to_check":["over-committed","avoidance-map"],"practice_affinity":["body","breath","raja"],"deepens_with":["nervous-system-tone","sleep-signature"]}'::jsonb, 1, true, false, 100, now())
