-- Ego structure (Levels)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('ego-structure', 'Ego structure', 'Your defences, mapped', 'jungian', 'shadow', E'Defences are not faults. They are the arrangements that let a life keep running when something in it would otherwise be unmanageable, and every one of them was installed for a reason that made sense at the time.\n\nThe question is not whether they exist. It is which one runs most, whether it can be seen from the inside, what it is holding off, and whether it can be chosen rather than inherited.', '🛡️', 7, 8, '[{"id":"defence-main","type":"choice","prompt":"When something gets difficult, what do you usually do with it?","domain":"mechanism","options":[{"label":"I do not appear to register it until long afterwards","value":"I do not appear to register it until long afterwards","weights":{"undiscovered":0.6,"known":0.3,"named":0.1,"transparent":0}},{"label":"I explain it away, in a way that holds up","value":"I explain it away, in a way that holds up","weights":{"undiscovered":0.2,"known":0.5,"named":0.2,"transparent":0.1}},{"label":"I work out whose feeling it is and deal with that instead","value":"I work out whose feeling it is and deal with that instead","weights":{"undiscovered":0.45,"known":0.35,"named":0.2,"transparent":0}},{"label":"I turn it into a problem I can think my way through","value":"I turn it into a problem I can think my way through","weights":{"undiscovered":0.15,"known":0.5,"named":0.25,"transparent":0.1}}]},{"id":"defence-seen","type":"choice","prompt":"Do you know it is running while it runs?","domain":"visibility","options":[{"label":"It runs with no awareness at all","value":"It runs with no awareness at all","weights":{"known":0}},{"label":"Something is happening, but I cannot name it","value":"Something is happening, but I cannot name it","weights":{"known":0.25}},{"label":"I catch it in the act now and then","value":"I catch it in the act now and then","weights":{"known":0.5}},{"label":"I can usually see it starting","value":"I can usually see it starting","weights":{"known":0.75}},{"label":"I can see it as clearly as an action, with the reason for it","value":"I can see it as clearly as an action, with the reason for it","weights":{"known":1}}]},{"id":"defence-protects","type":"choice","prompt":"What is it actually keeping out?","domain":"function","options":[{"label":"It protects something specific, and I know exactly what","value":"It protects something specific, and I know exactly what","weights":{"transparent":1}},{"label":"It protects something, and I have a fair idea of what","value":"It protects something, and I have a fair idea of what","weights":{"named":1}},{"label":"I know it deflects, but not what it is holding off","value":"I know it deflects, but not what it is holding off","weights":{"known":1}},{"label":"I have never linked it to anything at all","value":"I have never linked it to anything at all","weights":{"undiscovered":1}}]},{"id":"defence-frequency","type":"choice","prompt":"How often does it run?","domain":"default","options":[{"label":"Rarely — only in extreme situations","value":"Rarely — only in extreme situations","weights":{"undiscovered":0}},{"label":"Occasionally, when the pressure is high","value":"Occasionally, when the pressure is high","weights":{"undiscovered":0.25}},{"label":"In most situations that would call for it","value":"In most situations that would call for it","weights":{"undiscovered":0.5}},{"label":"Nearly every situation that could trigger it","value":"Nearly every situation that could trigger it","weights":{"undiscovered":0.75}},{"label":"It is the first response, before anything else is considered","value":"It is the first response, before anything else is considered","weights":{"undiscovered":1}}]},{"id":"defence-cost","type":"choice","prompt":"What has it cost you?","domain":"price","options":[{"label":"A great deal, and I have never been able to see how","value":"A great deal, and I have never been able to see how","weights":{"transparent":0}},{"label":"Things I only noticed afterwards, one way or another","value":"Things I only noticed afterwards, one way or another","weights":{"transparent":0.25}},{"label":"A cost I can describe in general terms","value":"A cost I can describe in general terms","weights":{"transparent":0.5}},{"label":"A cost I can name fairly precisely","value":"A cost I can name fairly precisely","weights":{"transparent":0.75}},{"label":"A cost I can see while it is being incurred, and adjust for","value":"A cost I can see while it is being incurred, and adjust for","weights":{"transparent":1}}]},{"id":"defence-choice","type":"choice","prompt":"Can you decide to use it, or does it simply arrive?","domain":"agency","options":[{"label":"Entirely involuntary — it happens to me","value":"Entirely involuntary — it happens to me","weights":{"known":1,"named":0,"transparent":0}},{"label":"Only rarely, and only under a great deal of pressure","value":"Only rarely, and only under a great deal of pressure","weights":{"known":0,"named":0,"transparent":0}},{"label":"With effort and warning I can catch it","value":"With effort and warning I can catch it","weights":{"known":0,"named":1,"transparent":0}},{"label":"I can usually choose whether to use it","value":"I can usually choose whether to use it","weights":{"known":0,"named":0,"transparent":0}},{"label":"I use it deliberately, and I know when I am using it","value":"I use it deliberately, and I know when I am using it","weights":{"known":0,"named":0,"transparent":1}}]},{"id":"defence-failure","type":"choice","prompt":"What happens when it stops working?","domain":"collapse","options":[{"label":"It collapses and I never learn what it was holding","value":"It collapses and I never learn what it was holding","weights":{"named":0}},{"label":"It collapses and I am left shaken for days","value":"It collapses and I am left shaken for days","weights":{"named":0.25}},{"label":"It collapses and I work it out within a day or two","value":"It collapses and I work it out within a day or two","weights":{"named":0.5}},{"label":"I can usually name what it was while it is crumbling","value":"I can usually name what it was while it is crumbling","weights":{"named":0.75}},{"label":"I know in advance that it is about to fail, and what for","value":"I know in advance that it is about to fail, and what for","weights":{"named":1}}]},{"id":"defence-trust","type":"choice","prompt":"How much of it is yours to keep?","domain":"inherited","options":[{"label":"I would keep none of it, if I could help it","value":"I would keep none of it, if I could help it","weights":{"undiscovered":0}},{"label":"Most of it, given the circumstances I was living in","value":"Most of it, given the circumstances I was living in","weights":{"undiscovered":0.25}},{"label":"Partly — some of it earned its place, some of it did not","value":"Partly — some of it earned its place, some of it did not","weights":{"undiscovered":0.5}},{"label":"Nearly all of it, now that I can see what it is doing","value":"Nearly all of it, now that I can see what it is doing","weights":{"undiscovered":0.75}},{"label":"I keep it deliberately, and I know the terms it is running on","value":"I keep it deliberately, and I know the terms it is running on","weights":{"undiscovered":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["undiscovered","known","named","transparent"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"undiscovered","label":"Undiscovered","short":"The machinery is running out of sight","description":"The defence is close to invisible from the inside, which is exactly what makes it effective. The cost is not felt as a cost — it is felt as the shape of things. This is the stage where naming the mechanism does more than any effort to change it.","shadow":"Reading the effect as the situation.","color":"slate","masters":["witnessing","self-inquiry"],"calibration":{"dimensions":{"thought":0.25,"emotion":0.2,"connection":0.15},"practiceLevels":{"witnessing":2,"self-inquiry":1},"tags":["undiscovered","reflexive"]}},{"id":"known","label":"Known","short":"Something is visible, nothing is named","description":"The deflection is sensed as something happening, but the reason behind it is still unformed. Most of the useful information is in the gap between noticing a pattern and being able to say what it is for.","shadow":"Noticing repeatedly without arriving anywhere.","color":"rose","masters":["witnessing","loop-dissolution"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.25,"body":0.1},"practiceLevels":{"witnessing":1,"loop-dissolution":1},"tags":["known","not-yet-named"]}},{"id":"named","label":"Named","short":"It has a name and a reason","description":"The defence can be identified, described, and its function recalled under pressure. Naming is what turns a structure from something that happens to you into something you can recognise in others as well.","shadow":"A name mistaken for an understanding.","color":"amber","masters":["self-inquiry","witnessing"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.2,"emotion":0.2},"practiceLevels":{"self-inquiry":1,"witnessing":1},"tags":["named","articulated"]}},{"id":"transparent","label":"Transparent","short":"It can be chosen, watched, and let go","description":"The defence is fully available to awareness: it can be seen starting, its purpose named, and its use chosen or declined. Structures at this level stop being architecture and become technique — usable, and no longer invisible.","shadow":"The technique becoming a style of its own.","color":"teal","masters":["self-inquiry","jnana"],"calibration":{"dimensions":{"spirit":0.3,"thought":0.2,"body":0.15},"practiceLevels":{"self-inquiry":2,"jnana":1},"tags":["transparent","self-regulated"]}}]'::jsonb, '{"loops_to_check":["defence","self-sabotage"],"practice_affinity":["witnessing","self-inquiry"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
