-- Emotional range (Observation)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('emotional-range', 'Emotional range', 'The full width of what you feel', 'yogic', 'emotion', E'Yoga spends a great deal of its early work on feeling, almost all of it on the assumption that most people feel less than they think they do. The assumption is often right, and it is not a criticism: a nervous system that has been doing useful work for a long time tends to narrow its range deliberately, because breadth is expensive.\n\nRange is a capacity, not a mood, and the four positions here describe the width of what is available to you rather than how much you feel at any one time. Volume and range are different things, and they are easy to confuse from the inside.', '🎚️', 6, 6, '[{"id":"emotion-vocabulary","type":"choice","prompt":"How many words do you have for how you feel?","domain":"naming","options":[{"label":"Two or three, and they cover nearly everything","value":"Two or three, and they cover nearly everything","weights":{"narrow":1}},{"label":"Plenty, though most of them are good or bad","value":"Plenty, though most of them are good or bad","weights":{"reactive":1}},{"label":"A fair number, and I can be precise about them","value":"A fair number, and I can be precise about them","weights":{"wide":1}},{"label":"Enough to describe things I have not felt before","value":"Enough to describe things I have not felt before","weights":{"vast":1}}]},{"id":"emotion-breadth","type":"choice","prompt":"Over a month, how wide is the range of what you feel?","domain":"breadth","options":[{"label":"Much the same few things","value":"Much the same few things","weights":{"narrow":1,"reactive":0,"wide":0,"vast":0}},{"label":"Strong things, but few of them","value":"Strong things, but few of them","weights":{"narrow":0,"reactive":1,"wide":0,"vast":0}},{"label":"A good spread, most weeks","value":"A good spread, most weeks","weights":{"narrow":0,"reactive":0,"wide":1,"vast":0}},{"label":"Something new almost every week","value":"Something new almost every week","weights":{"narrow":0,"reactive":0,"wide":0,"vast":1}}]},{"id":"emotion-volume","type":"choice","prompt":"How large do your feelings get?","domain":"volume","options":[{"label":"Quiet, even when it matters","value":"Quiet, even when it matters","weights":{"reactive":0}},{"label":"Moderate, and no more than the moment needs","value":"Moderate, and no more than the moment needs","weights":{"reactive":0.25}},{"label":"As large as the moment calls for","value":"As large as the moment calls for","weights":{"reactive":0.5}},{"label":"Quickly, and at full volume","value":"Quickly, and at full volume","weights":{"reactive":0.75}},{"label":"Overwhelmingly, and for a long time afterwards","value":"Overwhelmingly, and for a long time afterwards","weights":{"reactive":1}}]},{"id":"emotion-location","type":"choice","prompt":"Where do your feelings show up in the body?","domain":"location","options":[{"label":"Somewhere I cannot identify at all","value":"Somewhere I cannot identify at all","weights":{"narrow":1,"reactive":0,"wide":0,"vast":0}},{"label":"All over at once, and loudly","value":"All over at once, and loudly","weights":{"narrow":0,"reactive":1,"wide":0,"vast":0}},{"label":"In one place I know well","value":"In one place I know well","weights":{"narrow":0,"reactive":0,"wide":1,"vast":0}},{"label":"In fine detail, all over, and moving","value":"In fine detail, all over, and moving","weights":{"narrow":0,"reactive":0,"wide":0,"vast":1}}]},{"id":"emotion-aftermath","type":"choice","prompt":"After a strong feeling has passed, what is left?","domain":"aftermath","options":[{"label":"Nothing — it goes and I do not know where it went","value":"Nothing — it goes and I do not know where it went","weights":{"narrow":1,"reactive":0,"wide":0,"vast":0}},{"label":"Tiredness, and a long tail","value":"Tiredness, and a long tail","weights":{"narrow":0,"reactive":1,"wide":0,"vast":0}},{"label":"A clear sense of what it was about","value":"A clear sense of what it was about","weights":{"narrow":0,"reactive":0,"wide":1,"vast":0}},{"label":"Something that has changed in me and stayed changed","value":"Something that has changed in me and stayed changed","weights":{"narrow":0,"reactive":0,"wide":0,"vast":1}}]},{"id":"emotion-others","type":"choice","prompt":"How much of what you feel do other people get to see?","domain":"others","options":[{"label":"Almost none of it","value":"Almost none of it","weights":{"narrow":1,"reactive":0,"wide":0,"vast":0}},{"label":"All of it, and immediately","value":"All of it, and immediately","weights":{"narrow":0,"reactive":1,"wide":0,"vast":0}},{"label":"A fair amount, when I choose to","value":"A fair amount, when I choose to","weights":{"narrow":0,"reactive":0,"wide":1,"vast":0}},{"label":"Whatever is actually there, as it is","value":"Whatever is actually there, as it is","weights":{"narrow":0,"reactive":0,"wide":0,"vast":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["narrow","reactive","wide","vast"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"narrow","label":"Narrow","short":"The range is small and unusually reliable","description":"A small number of states, held consistently, with a limited vocabulary for them. This is efficient and it is often the result of a system that narrowed its range on purpose a long time ago. It is worth testing rather than assuming — a narrow range and a suppressed range can look identical from the inside, and they are not the same thing.","shadow":"Reading suppression as simplicity because both feel quiet.","color":"slate","masters":["observation","body"],"calibration":{"dimensions":{"emotion":0.2,"body":0.2,"thought":0.15},"practiceLevels":{"observation":1,"body":1},"domainStress":{"feeling":"emotional-healing"},"tags":["under-felt","narrow"]}},{"id":"reactive","label":"Reactive","short":"Big, immediate, and gone by morning","description":"Strong feelings with few of them: everything arrives at full volume, resolves quickly, and leaves a residue rather than a result. The energy in this is considerable and it is genuinely felt. What is missing is not depth but continuity, and it is usually developed by staying with one feeling past the point where it would normally resolve.","shadow":"Mistaking the size of the feeling for its depth.","color":"rose","masters":["emotional-healing","breath"],"calibration":{"dimensions":{"emotion":0.4,"body":0.2,"thought":0.1},"practiceLevels":{"emotional-healing":1,"breath":1},"domainStress":{"feeling":"emotional-healing"},"tags":["reactive","high-volume"]}},{"id":"wide","label":"Wide","short":"A full range, and enough language for it","description":"A wide range with a workable vocabulary: many states, locatable in the body, and mostly comprehensible while they are happening. This is the position most people are working towards and it is genuinely useful. What it can hide is depth — everything is felt, and some of it is felt shallowly, which feels like breadth without it being depth.","shadow":"Collecting states without staying in any of them.","color":"teal","masters":["observation","emotional-healing"],"calibration":{"dimensions":{"emotion":0.3,"body":0.2,"spirit":0.15},"practiceLevels":{"observation":1,"emotional-healing":1},"tags":["full-range","precise"]}},{"id":"vast","label":"Vast","short":"It keeps going past what you expected","description":"Range and depth together: states arrive that you had no word for, the body registers them finely, and what is left afterwards has altered something. The difficulty is that the world is built for people with a narrower range, and a wide one puts a distance between you and almost everyone you meet. The range is rarely the problem. Living with it is.","shadow":"The distance that a wide range puts between you and everyone else.","color":"violet","masters":["witnessing","bhakti"],"calibration":{"dimensions":{"spirit":0.35,"emotion":0.3},"practiceLevels":{"witnessing":1,"bhakti":1},"tags":["deep-feeling","expansive"]}}]'::jsonb, '{"loops_to_check":["suppression","reactivity"],"practice_affinity":["observation","emotional-healing","body"],"deepens_with":["ground-state","sensory-awareness"]}'::jsonb, 1, true, false, 100, now())
