-- Energy baseline (Welcome)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('energy-baseline', 'Energy baseline', 'Morning self against night self', 'yogic', 'vitality', E'A baseline is the floor you return to, not the peak you reach on a good day. The interesting question is not how good your best days are — it is what you drop back to when nothing is going well.\n\nThis looks at that floor, and at the gap between your morning self and your night self.', '🔋', 6, 8, '[{"id":"energy-floor","type":"choice","prompt":"When everything is going badly, how much do you have left?","domain":"vitality","options":[{"label":"Nothing left at all","value":"Nothing left at all","weights":{"depletion":1,"oscillation":0,"capacity":0,"reserve":0}},{"label":"Almost nothing","value":"Almost nothing","weights":{"depletion":0.25,"oscillation":0.75,"capacity":0,"reserve":0}},{"label":"Enough to get by","value":"Enough to get by","weights":{"depletion":0,"oscillation":0.5,"capacity":0.5,"reserve":0}},{"label":"Enough to be present","value":"Enough to be present","weights":{"depletion":0,"oscillation":0,"capacity":0.75,"reserve":0.25}},{"label":"Even then I have room","value":"Even then I have room","weights":{"depletion":0,"oscillation":0,"capacity":0,"reserve":1}}]},{"id":"energy-morning","type":"choice","prompt":"How do you feel in the first hour after waking?","domain":"vitality","options":[{"label":"I wake up already tired","value":"I wake up already tired","weights":{"depletion":1,"oscillation":0,"capacity":0,"reserve":0}},{"label":"Heavy, slow to start","value":"Heavy, slow to start","weights":{"depletion":0.25,"oscillation":0.75,"capacity":0,"reserve":0}},{"label":"Functional","value":"Functional","weights":{"depletion":0,"oscillation":0.5,"capacity":0.5,"reserve":0}},{"label":"Clear and ready","value":"Clear and ready","weights":{"depletion":0,"oscillation":0,"capacity":0.75,"reserve":0.25}},{"label":"I am most alive at this hour","value":"I am most alive at this hour","weights":{"depletion":0,"oscillation":0,"capacity":0,"reserve":1}}]},{"id":"energy-night","type":"choice","prompt":"And how do you feel in the last hour before sleep?","domain":"vitality","options":[{"label":"Completely spent","value":"Completely spent","weights":{"depletion":1,"oscillation":0,"capacity":0,"reserve":0}},{"label":"Running on empty","value":"Running on empty","weights":{"depletion":0.25,"oscillation":0.75,"capacity":0,"reserve":0}},{"label":"Wired but running out","value":"Wired but running out","weights":{"depletion":0,"oscillation":0.5,"capacity":0.5,"reserve":0}},{"label":"Tired but settled","value":"Tired but settled","weights":{"depletion":0,"oscillation":0,"capacity":0.75,"reserve":0.25}},{"label":"Still going, easily","value":"Still going, easily","weights":{"depletion":0,"oscillation":0,"capacity":0,"reserve":1}}]},{"id":"energy-gap","type":"choice","prompt":"How different are your morning and evening selves?","domain":"vitality","options":[{"label":"We are two different people","value":"We are two different people","weights":{"depletion":1,"oscillation":0,"capacity":0,"reserve":0}},{"label":"Very different","value":"Very different","weights":{"depletion":0.25,"oscillation":0.75,"capacity":0,"reserve":0}},{"label":"Noticeably different","value":"Noticeably different","weights":{"depletion":0,"oscillation":0.5,"capacity":0.5,"reserve":0}},{"label":"A little different","value":"A little different","weights":{"depletion":0,"oscillation":0,"capacity":0.75,"reserve":0.25}},{"label":"Much the same throughout","value":"Much the same throughout","weights":{"depletion":0,"oscillation":0,"capacity":0,"reserve":1}}]},{"id":"energy-cause","type":"choice","prompt":"When your energy drops, is it mostly your body, or mostly your mind?","domain":"vitality","options":[{"label":"Sleep — if it is bad, everything is bad","value":"Sleep — if it is bad, everything is bad","weights":{"depletion":1}},{"label":"What I am doing all day","value":"What I am doing all day","weights":{"depletion":1}},{"label":"What I am carrying for other people","value":"What I am carrying for other people","weights":{"depletion":1}},{"label":"My own thinking, mostly","value":"My own thinking, mostly","weights":{"depletion":1}},{"label":"I could not say","value":"I could not say","weights":{"depletion":1}}]},{"id":"energy-consistent","type":"choice","prompt":"How predictable is your energy from one day to the next?","domain":"vitality","options":[{"label":"Wildly unpredictable","value":"Wildly unpredictable","weights":{"depletion":1,"oscillation":0,"capacity":0,"reserve":0}},{"label":"Very changeable","value":"Very changeable","weights":{"depletion":0.25,"oscillation":0.75,"capacity":0,"reserve":0}},{"label":"Somewhat variable","value":"Somewhat variable","weights":{"depletion":0,"oscillation":0.5,"capacity":0.5,"reserve":0}},{"label":"Fairly steady","value":"Fairly steady","weights":{"depletion":0,"oscillation":0,"capacity":0.75,"reserve":0.25}},{"label":"The same every day","value":"The same every day","weights":{"depletion":0,"oscillation":0,"capacity":0,"reserve":1}}]},{"id":"energy-peak","type":"choice","prompt":"Do you know what actually gives you energy, as opposed to what only excites you?","domain":"vitality","options":[{"label":"I have no idea","value":"I have no idea","weights":{"depletion":1,"oscillation":0,"capacity":0,"reserve":0}},{"label":"A few things, loosely","value":"A few things, loosely","weights":{"depletion":0.25,"oscillation":0.75,"capacity":0,"reserve":0}},{"label":"A few things, reliably","value":"A few things, reliably","weights":{"depletion":0,"oscillation":0.5,"capacity":0.5,"reserve":0}},{"label":"I know most of them","value":"I know most of them","weights":{"depletion":0,"oscillation":0,"capacity":0.75,"reserve":0.25}},{"label":"I know exactly, and I rely on them","value":"I know exactly, and I rely on them","weights":{"depletion":0,"oscillation":0,"capacity":0,"reserve":1}}]},{"id":"energy-borrowed","type":"choice","prompt":"Are you running on your own energy, or on someone else’s?","domain":"vitality","options":[{"label":"Nearly all of it is borrowed","value":"Nearly all of it is borrowed","weights":{"depletion":1,"oscillation":0,"capacity":0,"reserve":0}},{"label":"A good deal","value":"A good deal","weights":{"depletion":0.25,"oscillation":0.75,"capacity":0,"reserve":0}},{"label":"Some","value":"Some","weights":{"depletion":0,"oscillation":0.5,"capacity":0.5,"reserve":0}},{"label":"Mostly my own","value":"Mostly my own","weights":{"depletion":0,"oscillation":0,"capacity":0.75,"reserve":0.25}},{"label":"Entirely my own","value":"Entirely my own","weights":{"depletion":0,"oscillation":0,"capacity":0,"reserve":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["depletion","oscillation","capacity","reserve"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"depletion","label":"Depleted baseline","short":"The floor is low","description":"Your reserve is smaller than your day requires. This is a body-first situation: the mind is asking for more than the system can currently produce, and pushing harder usually deepens the hole.","shadow":"Reading depletion as a character flaw.","color":"rose","masters":["body","breath"],"calibration":{"dimensions":{"body":0.4,"thought":0.15,"spirit":0.1},"practiceLevels":{"body":1,"breath":1},"domainStress":{"health":"health"},"tags":["depleted","needs-rest"]}},{"id":"oscillation","label":"Oscillating","short":"High and low, without much middle","description":"The energy is there but it is unreliable — it spikes and collapses, often against the same triggers. Because the peaks feel genuinely good, the troughs tend to get explained away rather than examined.","shadow":"Chasing the peaks and calling it consistency.","color":"orange","masters":["breath","observation"],"calibration":{"dimensions":{"body":0.25,"emotion":0.3,"thought":0.15},"practiceLevels":{"breath":1,"observation":1},"domainStress":{"health":"health"},"tags":["unstable","wired"]}},{"id":"capacity","label":"Steady capacity","short":"Reliable, if not abundant","description":"You have a workable amount and it comes fairly predictably. The ceiling is not high, but the floor is not low either, and you can mostly do what you have set out to do.","shadow":"Mistaking consistency for a ceiling.","color":"teal","masters":["breath","raja"],"calibration":{"dimensions":{"body":0.2,"action":0.2,"spirit":0.15},"practiceLevels":{"breath":1,"raja":1},"tags":["steady","adequate"]}},{"id":"reserve","label":"Deep reserve","short":"You have more than you are using","description":"There is genuine depth available to you, and some of it is going unused. The question at this stage is not how to build more, but what you are saving it for.","shadow":"Reserve hoarded rather than spent.","color":"emerald","masters":["raja","karma"],"calibration":{"dimensions":{"body":0.25,"action":0.25,"spirit":0.2},"practiceLevels":{"raja":1,"karma":1},"tags":["resourced","under-used"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["breath","body"],"deepens_with":["sleep-signature","vitality-index"]}'::jsonb, 1, true, false, 100, now())
