-- Energy bodies (Observation)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('energy-bodies', 'Energy bodies', 'The prāṇa bodies', 'yogic', 'vitality', E'Tantra and the kośa tradition describe the human being as layered: the physical body, the emotional body, the mental body, and the subtlest sheath of all. The layers are not stacked like boxes and the order is not a hierarchy of worth — they are progressively finer, and each one is harder to feel than the one below it.\n\nSo the question this mirror really asks is simple and slightly disorienting: of the four, which can you actually feel? The last is the subtlest, which means the least visible and the hardest to put a name to — and its absence of a name is not evidence that it is not there.', '🌬️', 6, 6, '[{"id":"bodies-feel","type":"choice","prompt":"When you say you can feel something, which of these do you mean?","domain":"access","options":[{"label":"Weight, heat, tension — the physical body","value":"Weight, heat, tension — the physical body","weights":{"physical":1}},{"label":"The feeling in the chest, and the want behind it","value":"The feeling in the chest, and the want behind it","weights":{"emotional":1}},{"label":"The working of thought, and the clarity or fog in it","value":"The working of thought, and the clarity or fog in it","weights":{"mental":1}},{"label":"Something with no location and no name","value":"Something with no location and no name","weights":{"spiritual":1}}]},{"id":"bodies-depth","type":"choice","prompt":"How far down does your attention reach?","domain":"subtlety","options":[{"label":"The body and nothing finer than it","value":"The body and nothing finer than it","weights":{"physical":1,"emotional":0,"mental":0,"spiritual":0}},{"label":"As far as the feeling","value":"As far as the feeling","weights":{"physical":0,"emotional":1,"mental":0,"spiritual":0}},{"label":"As far as the thinking","value":"As far as the thinking","weights":{"physical":0,"emotional":0,"mental":1,"spiritual":0}},{"label":"All the way through to whatever is behind all of it","value":"All the way through to whatever is behind all of it","weights":{"physical":0,"emotional":0,"mental":0,"spiritual":1}}]},{"id":"bodies-texture","type":"choice","prompt":"Where does your sense of being solid actually sit?","domain":"density","options":[{"label":"Solid all the way through","value":"Solid all the way through","weights":{"physical":0,"emotional":0,"mental":0,"spiritual":0}},{"label":"Mostly solid, softer somewhere around the feeling","value":"Mostly solid, softer somewhere around the feeling","weights":{"physical":1,"emotional":0,"mental":0,"spiritual":0}},{"label":"It thins around the middle of the stack","value":"It thins around the middle of the stack","weights":{"physical":0,"emotional":1,"mental":0,"spiritual":0}},{"label":"Thin for most of it, with one dense place left","value":"Thin for most of it, with one dense place left","weights":{"physical":0,"emotional":0,"mental":1,"spiritual":0}},{"label":"Nothing feels solid at all","value":"Nothing feels solid at all","weights":{"physical":0,"emotional":0,"mental":0,"spiritual":1}}]},{"id":"bodies-settles","type":"choice","prompt":"What actually settles you?","domain":"method","options":[{"label":"Movement, food, water, sleep","value":"Movement, food, water, sleep","weights":{"physical":1}},{"label":"Music, other people, being held","value":"Music, other people, being held","weights":{"emotional":1}},{"label":"Reading, solving, being alone with a hard problem","value":"Reading, solving, being alone with a hard problem","weights":{"mental":1}},{"label":"Stillness, with nothing added to it","value":"Stillness, with nothing added to it","weights":{"spiritual":1}}]},{"id":"bodies-night","type":"choice","prompt":"As you go under, what lets go first?","domain":"night","options":[{"label":"The body gives out first","value":"The body gives out first","weights":{"physical":1,"emotional":0,"mental":0,"spiritual":0}},{"label":"The feelings loosen","value":"The feelings loosen","weights":{"physical":0,"emotional":1,"mental":0,"spiritual":0}},{"label":"The thinking stops being interesting","value":"The thinking stops being interesting","weights":{"physical":0,"emotional":0,"mental":1,"spiritual":0}},{"label":"The last thing to go is the sense of being someone","value":"The last thing to go is the sense of being someone","weights":{"physical":0,"emotional":0,"mental":0,"spiritual":1}}]},{"id":"bodies-finest","type":"choice","prompt":"How often do you notice the subtlest of the four?","domain":"finest","options":[{"label":"Never, and I have no way of telling whether it is there","value":"Never, and I have no way of telling whether it is there","weights":{"spiritual":0}},{"label":"Rarely","value":"Rarely","weights":{"spiritual":0.25}},{"label":"Sometimes, and briefly","value":"Sometimes, and briefly","weights":{"spiritual":0.5}},{"label":"Often, in quiet moments","value":"Often, in quiet moments","weights":{"spiritual":0.75}},{"label":"It is the first thing I notice","value":"It is the first thing I notice","weights":{"spiritual":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["physical","emotional","mental","spiritual"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"physical","label":"Physical body","short":"The layer you actually live in","description":"Weight, heat, breath, fatigue — the outermost layer is the one with edges, and it is where most of a life is spent. That is not a limitation; the body is the only layer that has to be maintained, and everything built above it is built on it. What is worth knowing is where its limits currently sit, because the layers above are usually built on what it can supply.","shadow":"Taking the outermost layer for the whole of what is there.","color":"slate","masters":["body","breath"],"calibration":{"dimensions":{"body":0.4,"thought":0.1},"practiceLevels":{"body":2,"breath":1},"domainStress":{"energy":"health"},"tags":["gross-layer","grounded"]}},{"id":"emotional","label":"Emotional body","short":"The layer you feel most","description":"Feeling is the layer with the most traffic: it is close to the surface, it is constantly available, and it colours everything above it. Living here gives a life its warmth and its relationships much of their meaning. It also means other people’s states are as legible as your own, which is a gift and an exposure in equal measure.","shadow":"Carrying other people’s states as if they were your own.","color":"rose","masters":["emotional-healing","bhakti"],"calibration":{"dimensions":{"emotion":0.4,"connection":0.15},"practiceLevels":{"emotional-healing":1,"bhakti":1},"domainStress":{"feeling":"emotional-healing"},"tags":["emotional-layer","felt"]}},{"id":"mental","label":"Mental body","short":"The layer that does the work","description":"The mind’s own layer: the working of thought, the plans, the arguments, the clarity and the fog. It is the layer most modern life runs on, and it is excellent at everything it was built for. What it is not built for is rest, which is why a mind that lives in this layer can be busy and unoccupied at the same time.","shadow":"Confusing a mind full of activity with a mind at work.","color":"sky","masters":["jnana","observation"],"calibration":{"dimensions":{"thought":0.4,"spirit":0.15},"practiceLevels":{"jnana":1,"observation":1},"tags":["mental-layer","refined"]}},{"id":"spiritual","label":"Spiritual body","short":"The layer behind the other three","description":"The subtlest of the four, with no edges, no location, and no name — which is why it is the last to be recognised and the easiest to insist does not exist. It is not rarer than the others, only harder to point at. Working from here is not a better position than the others; it is a thinner one, and thinner is more easily disturbed.","shadow":"Inferring from the absence of a name that the layer is not there.","color":"indigo","masters":["witnessing","kriya"],"calibration":{"dimensions":{"spirit":0.45,"thought":0.15},"practiceLevels":{"witnessing":2,"kriya":1},"tags":["subtle-layer","subtlest"]}}]'::jsonb, '{"loops_to_check":["avoidance-map","over-thinking"],"practice_affinity":["body","witnessing","kriya"],"deepens_with":["witness-capacity","presence-quality"]}'::jsonb, 1, true, false, 100, now())
