  updated_at
) VALUES
    ('fantasy-loops', 'Fantasy loops', 'The diet of your daydreams', 'yogic', 'thought', E'A daydream is a rehearsal or an escape, and the difference is not in the content but in what happens after it.\n\nThis looks at what the mind is running when it is not being given something, whether the running is noticed, and what the running is standing in for.', '💭', 5, 7, '[{"id":"fantasy-volume","type":"choice","prompt":"How often are you somewhere else in your head?","domain":"volume","options":[{"label":"I do not daydream","value":"I do not daydream","weights":{"none":1,"pleasant-escape":0,"ambition-fantasy":0,"rehearsal":0}},{"label":"Occasionally — in the car, in the shower, while washing up","value":"Occasionally — in the car, in the shower, while washing up","weights":{"none":0.25,"pleasant-escape":0.75,"ambition-fantasy":0,"rehearsal":0}},{"label":"Most of the free moments","value":"Most of the free moments","weights":{"none":0,"pleasant-escape":0.5,"ambition-fantasy":0.5,"rehearsal":0}},{"label":"A great deal of most days","value":"A great deal of most days","weights":{"none":0,"pleasant-escape":0,"ambition-fantasy":0.75,"rehearsal":0.25}},{"label":"Almost continuously, in the background of everything","value":"Almost continuously, in the background of everything","weights":{"none":0,"pleasant-escape":0,"ambition-fantasy":0,"rehearsal":1}}]},{"id":"fantasy-function","type":"choice","prompt":"What are they actually for?","domain":"function","options":[{"label":"Escape — to get away from where I am","value":"Escape — to get away from where I am","weights":{"pleasant-escape":1}},{"label":"Wish — a life, an achievement, a version of things I do not have","value":"Wish — a life, an achievement, a version of things I do not have","weights":{"ambition-fantasy":1}},{"label":"Rehearsal — something I might actually do","value":"Rehearsal — something I might actually do","weights":{"rehearsal":1}}]},{"id":"fantasy-noticed","type":"choice","prompt":"Do you notice them while they are running?","domain":"awareness","options":[{"label":"Not at all — they arrive and vanish","value":"Not at all — they arrive and vanish","weights":{"rehearsal":0}},{"label":"Only once they have stopped","value":"Only once they have stopped","weights":{"rehearsal":0.25}},{"label":"Sometimes, in the gaps","value":"Sometimes, in the gaps","weights":{"rehearsal":0.5}},{"label":"Usually, and I follow them","value":"Usually, and I follow them","weights":{"rehearsal":0.75}},{"label":"I watch the whole sequence build, from the outside","value":"I watch the whole sequence build, from the outside","weights":{"rehearsal":1}}]},{"id":"fantasy-night","type":"choice","prompt":"What happens to it at night?","domain":"night","options":[{"label":"I sleep much as I should","value":"I sleep much as I should","weights":{"pleasant-escape":0,"ambition-fantasy":0,"rehearsal":0}},{"label":"My mind gets busier as the day ends","value":"My mind gets busier as the day ends","weights":{"pleasant-escape":1,"ambition-fantasy":0,"rehearsal":0}},{"label":"The day replays, mostly the parts I got wrong","value":"The day replays, mostly the parts I got wrong","weights":{"pleasant-escape":0,"ambition-fantasy":0,"rehearsal":0}},{"label":"Long imagined sequences, usually the same one","value":"Long imagined sequences, usually the same one","weights":{"pleasant-escape":0,"ambition-fantasy":1,"rehearsal":0}},{"label":"I go to sleep inside one and wake up still in it","value":"I go to sleep inside one and wake up still in it","weights":{"pleasant-escape":0,"ambition-fantasy":0,"rehearsal":1}}]},{"id":"fantasy-substitute","type":"choice","prompt":"What do they stand in for?","domain":"substitution","options":[{"label":"Nothing in particular — they are just idle","value":"Nothing in particular — they are just idle","weights":{"ambition-fantasy":0}},{"label":"Something small: waiting, boredom, a queue","value":"Something small: waiting, boredom, a queue","weights":{"ambition-fantasy":0.25}},{"label":"A conversation I do not want to have","value":"A conversation I do not want to have","weights":{"ambition-fantasy":0.5}},{"label":"A life that is not happening","value":"A life that is not happening","weights":{"ambition-fantasy":0.75}},{"label":"Whatever I have not actually built","value":"Whatever I have not actually built","weights":{"ambition-fantasy":1}}]},{"id":"fantasy-use","type":"choice","prompt":"Are they enjoyed, or used?","domain":"enjoyment","options":[{"label":"Almost entirely enjoyed, and I would not call that a problem","value":"Almost entirely enjoyed, and I would not call that a problem","weights":{"ambition-fantasy":0}},{"label":"Enjoyed, and I choose them","value":"Enjoyed, and I choose them","weights":{"ambition-fantasy":0.25}},{"label":"Both — enjoyed sometimes, worked with at others","value":"Both — enjoyed sometimes, worked with at others","weights":{"ambition-fantasy":0.5}},{"label":"Mostly used rather than enjoyed","value":"Mostly used rather than enjoyed","weights":{"ambition-fantasy":0.75}},{"label":"Almost entirely functional, with no pleasure left in it at all","value":"Almost entirely functional, with no pleasure left in it at all","weights":{"ambition-fantasy":1}}]},{"id":"fantasy-interrupt","type":"choice","prompt":"Can you be interrupted?","domain":"interruption","options":[{"label":"No — nothing interrupts it","value":"No — nothing interrupts it","weights":{"pleasant-escape":0,"ambition-fantasy":0,"rehearsal":0}},{"label":"Only something painful or very loud","value":"Only something painful or very loud","weights":{"pleasant-escape":1,"ambition-fantasy":0,"rehearsal":0}},{"label":"A task, if I am given one","value":"A task, if I am given one","weights":{"pleasant-escape":0,"ambition-fantasy":1,"rehearsal":0}},{"label":"By deciding to stop, with a real effort","value":"By deciding to stop, with a real effort","weights":{"pleasant-escape":0,"ambition-fantasy":0,"rehearsal":0}},{"label":"I can go into one, notice, and come back out","value":"I can go into one, notice, and come back out","weights":{"pleasant-escape":0,"ambition-fantasy":0,"rehearsal":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["none","pleasant-escape","ambition-fantasy","rehearsal"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"none","label":"None","short":"The mind is not running stories on its own","description":"There is very little self-started imagined material, which means the mind is being given enough to do. This is worth recording because it tends to change with the shape of a life rather than with effort, and it is useful to know what yours depends on.","shadow":"Assuming the calm is a permanent condition.","color":"slate","masters":["observation","raja"],"calibration":{"dimensions":{"thought":0.2,"spirit":0.2,"body":0.15},"practiceLevels":{"observation":1,"raja":1},"tags":["no-fantasy","occupied-mind"]}},{"id":"pleasant-escape","label":"Pleasant escape","short":"Somewhere better, whenever here gets difficult","description":"The imagined material is largely a way of leaving, and the leaving is pleasant. It does the job it is doing, and it is also the cheapest possible exit — which is why it is chosen so readily over the alternatives that would actually resolve something.","shadow":"Mistaking the quality of the escape for the resolution of the thing.","color":"rose","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.25,"spirit":0.15},"practiceLevels":{"observation":1,"witnessing":1},"tags":["escape","imagined-exit"]}},{"id":"ambition-fantasy","label":"Ambition fantasy","short":"A life or an achievement, held in the mind","description":"The material is a picture of something wanted, and it is doing real work: it keeps the aim present, rehearses it, and carries it across the days when nothing is moving. Its weakness is that the picture can substitute for the doing, indefinitely, and feel like progress while it does.","shadow":"The picture standing in for the work, and feeling earned.","color":"amber","masters":["jnana","karma"],"calibration":{"dimensions":{"thought":0.3,"action":0.25,"spirit":0.15},"practiceLevels":{"jnana":1,"karma":1},"domainStress":{"work":"work-career"},"tags":["ambition","imagined-future"]}},{"id":"rehearsal","label":"Rehearsal","short":"Run deliberately, and watched while it runs","description":"The imagined material is being used as practice — a conversation, a piece of work, a decision being tried out before it is made — and it is being run with some awareness rather than inside itself. This is the most useful of the four, and also the easiest to turn into a substitute for acting.","shadow":"The rehearsal becoming a life of its own.","color":"teal","masters":["jnana","karma"],"calibration":{"dimensions":{"action":0.25,"thought":0.25,"spirit":0.2},"practiceLevels":{"jnana":1,"karma":1},"tags":["rehearsal","deliberate-imagining"]}}]'::jsonb, '{"loops_to_check":["fantasy","scrolling"],"practice_affinity":["observation","jnana"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
