  updated_at
) VALUES
    ('forgiveness-capacity', 'Forgiveness capacity', 'Your ability to release the debt', 'vedic', 'emotion', E'Forgiveness is usually taught as a decision. It behaves more like a capacity — and a capacity can be strained, measured, and trained.\n\nThis asks what you are holding against people, what the holding is doing, and what would actually have to be given up for it to be released. Nothing here asks you to forgive anyone, or to hurry.', '🕊️', 7, 8, '[{"id":"forgive-who","type":"choice","prompt":"Who are you currently holding something against?","domain":"account","options":[{"label":"No one","value":"No one","weights":{"grudging":1}},{"label":"One person, and it is old","value":"One person, and it is old","weights":{"grudging":1}},{"label":"A handful of people","value":"A handful of people","weights":{"grudging":1}},{"label":"My family, in general","value":"My family, in general","weights":{"grudging":1}},{"label":"Mostly myself","value":"Mostly myself","weights":{"grudging":1}}]},{"id":"forgive-recurrence","type":"choice","prompt":"How often does the old thing come back to you?","domain":"frequency","options":[{"label":"It runs underneath most of my days","value":"It runs underneath most of my days","weights":{"stored":1,"grudging":0,"releasing":0,"freeing":0}},{"label":"Most days","value":"Most days","weights":{"stored":0.25,"grudging":0.75,"releasing":0,"freeing":0}},{"label":"Often","value":"Often","weights":{"stored":0,"grudging":0.5,"releasing":0.5,"freeing":0}},{"label":"Now and then","value":"Now and then","weights":{"stored":0,"grudging":0,"releasing":0.75,"freeing":0.25}},{"label":"It has gone quiet — barely ever","value":"It has gone quiet — barely ever","weights":{"stored":0,"grudging":0,"releasing":0,"freeing":1}}]},{"id":"forgive-purpose","type":"choice","prompt":"Is there a reason you keep holding on to it?","domain":"function","options":[{"label":"No reason — it is just there","value":"No reason — it is just there","weights":{"stored":1}},{"label":"It keeps that relationship defined","value":"It keeps that relationship defined","weights":{"stored":1}},{"label":"It keeps the other person in their place","value":"It keeps the other person in their place","weights":{"stored":1}},{"label":"It keeps me from being the one who has to admit things","value":"It keeps me from being the one who has to admit things","weights":{"stored":1}},{"label":"I have never looked at it","value":"I have never looked at it","weights":{"stored":1}}]},{"id":"forgive-cost","type":"choice","prompt":"If you let it go, what would it actually cost you?","domain":"cost","options":[{"label":"Nothing I can see","value":"Nothing I can see","weights":{"releasing":1}},{"label":"The story I have told everyone","value":"The story I have told everyone","weights":{"releasing":1}},{"label":"The distance it has kept for me","value":"The distance it has kept for me","weights":{"releasing":1}},{"label":"My leverage with them","value":"My leverage with them","weights":{"releasing":1}},{"label":"More than I want to go and find out","value":"More than I want to go and find out","weights":{"releasing":1}}]},{"id":"forgive-performance","type":"choice","prompt":"When you have said you have forgiven someone, what actually happened?","domain":"sincerity","options":[{"label":"I have not forgiven anyone","value":"I have not forgiven anyone","weights":{"stored":1,"grudging":0,"releasing":0,"freeing":0}},{"label":"I have said it, and not done it","value":"I have said it, and not done it","weights":{"stored":0.25,"grudging":0.75,"releasing":0,"freeing":0}},{"label":"Partly — the rest is still there","value":"Partly — the rest is still there","weights":{"stored":0,"grudging":0.5,"releasing":0.5,"freeing":0}},{"label":"Yes, and something loosened","value":"Yes, and something loosened","weights":{"stored":0,"grudging":0,"releasing":0.75,"freeing":0.25}},{"label":"Yes, and it is genuinely finished","value":"Yes, and it is genuinely finished","weights":{"stored":0,"grudging":0,"releasing":0,"freeing":1}}]},{"id":"forgive-body","type":"choice","prompt":"What happens physically when it comes up?","domain":"somatic","options":[{"label":"It tightens straight away","value":"It tightens straight away","weights":{"stored":1}},{"label":"My chest narrows","value":"My chest narrows","weights":{"stored":1}},{"label":"I feel heavy and slow","value":"I feel heavy and slow","weights":{"stored":1}},{"label":"A wave, and then it passes","value":"A wave, and then it passes","weights":{"stored":1}},{"label":"Almost nothing at all","value":"Almost nothing at all","weights":{"stored":1}}]},{"id":"forgive-received","type":"choice","prompt":"Can you take forgiveness for what you have done?","domain":"reception","options":[{"label":"Not at all","value":"Not at all","weights":{"stored":1,"grudging":0,"releasing":0,"freeing":0}},{"label":"It bounces off me","value":"It bounces off me","weights":{"stored":0.25,"grudging":0.75,"releasing":0,"freeing":0}},{"label":"I hear it, but I do not take it","value":"I hear it, but I do not take it","weights":{"stored":0,"grudging":0.5,"releasing":0.5,"freeing":0}},{"label":"I take it, slowly","value":"I take it, slowly","weights":{"stored":0,"grudging":0,"releasing":0.75,"freeing":0.25}},{"label":"Yes — I let it land","value":"Yes — I let it land","weights":{"stored":0,"grudging":0,"releasing":0,"freeing":1}}]},{"id":"forgive-beyond","type":"choice","prompt":"What would be different if it were genuinely released?","domain":"freedom","options":[{"label":"I do not know","value":"I do not know","weights":{"freeing":1}},{"label":"A little less heaviness","value":"A little less heaviness","weights":{"freeing":1}},{"label":"More room in the day","value":"More room in the day","weights":{"freeing":1}},{"label":"A relationship I could actually have","value":"A relationship I could actually have","weights":{"freeing":1}},{"label":"A version of me I would recognise","value":"A version of me I would recognise","weights":{"freeing":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["stored","grudging","releasing","freeing"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"stored","label":"Stored","short":"The account is open and unexamined","description":"There is a considerable amount held, and much of it has not been looked at directly. It is not being used for anything, which usually means it is simply occupying space. Nothing has to be resolved for this to shift — only seen.","shadow":"Believing the grudge is justified, and therefore finished.","color":"rose","masters":["emotional-healing","witnessing"],"calibration":{"dimensions":{"emotion":0.4,"connection":0.25,"thought":0.15},"practiceLevels":{"emotional-healing":2,"witnessing":1},"domainStress":{"relation":"relationship"},"tags":["debt-stored","unexamined"]}},{"id":"grudging","label":"Grudging","short":"It is being used","description":"The holding has become a position — the other person is kept in their place, and the story is told. This is functional in the short term, because it reliably produces distance. In the long term it is the main thing holding the relationship in the shape it already is.","shadow":"Confusing distance with peace.","color":"amber","masters":["emotional-healing","relationship"],"calibration":{"dimensions":{"connection":0.3,"emotion":0.3,"action":0.15},"practiceLevels":{"emotional-healing":1,"relationship":1},"domainStress":{"relation":"relationship"},"tags":["grudge-maintained","debt-serving"]}},{"id":"releasing","label":"Releasing","short":"It is genuinely moving, unevenly","description":"The account is being worked on rather than merely held. Some of it has already loosened and some of it is still in place, and the two can be lived with in the same person on the same day. This is the middle of the work rather than its end.","shadow":"Measuring progress instead of doing it.","color":"sky","masters":["emotional-healing","bhakti"],"calibration":{"dimensions":{"emotion":0.3,"spirit":0.25,"connection":0.2},"practiceLevels":{"emotional-healing":1,"bhakti":1},"tags":["releasing","uneven"]}},{"id":"freeing","label":"Freeing","short":"You can let accounts close","description":"Something has been given that was not owed and did not have to be returned. The capacity is real and repeatable, which means it can be used on the next thing rather than spent on the last.","shadow":"Compassion performed, for people who did not ask for it.","color":"emerald","masters":["bhakti","jnana"],"calibration":{"dimensions":{"spirit":0.3,"emotion":0.25,"connection":0.2},"practiceLevels":{"bhakti":2,"jnana":1},"tags":["releasing-cleanly","unburdened"]}}]'::jsonb, '{"loops_to_check":["grudge","debt-keeping"],"practice_affinity":["emotional-healing","bhakti"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
