-- Grief reservoir (Heart)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('grief-reservoir', 'Grief reservoir', 'The tears not yet wept', 'yogic', 'emotion', E'Grief is not one event. It is a long process, and most people lose it somewhere — usually by carrying on before it has finished.\n\nThis looks at what is still in the reservoir: what has not been grieved, what is being carried on other people’s behalf, and what the withholding is actually doing. It does not ask you to open anything. It asks you to read the level.', '🌧️', 7, 8, '[{"id":"grief-what","type":"choice","prompt":"Is there something you have not properly grieved?","domain":"inventory","options":[{"label":"Something recent and specific","value":"Something recent and specific","weights":{"unfelt":1}},{"label":"A person who died","value":"A person who died","weights":{"unfelt":1}},{"label":"A relationship or a friendship that ended","value":"A relationship or a friendship that ended","weights":{"unfelt":1}},{"label":"A version of my life that did not happen","value":"A version of my life that did not happen","weights":{"unfelt":1}},{"label":"Nothing in particular — it is everywhere at once","value":"Nothing in particular — it is everywhere at once","weights":{"unfelt":1}}]},{"id":"grief-tears","type":"choice","prompt":"When something touches you, do the tears actually come?","domain":"body","options":[{"label":"I do not seem to produce them","value":"I do not seem to produce them","weights":{"unfelt":1,"held":0,"surfacing":0,"moved-through":0}},{"label":"Only rarely, and I stop them","value":"Only rarely, and I stop them","weights":{"unfelt":0.25,"held":0.75,"surfacing":0,"moved-through":0}},{"label":"They come and I let them finish","value":"They come and I let them finish","weights":{"unfelt":0,"held":0.5,"surfacing":0.5,"moved-through":0}},{"label":"Quite easily","value":"Quite easily","weights":{"unfelt":0,"held":0,"surfacing":0.75,"moved-through":0.25}},{"label":"Very easily — it is the only thing that helps","value":"Very easily — it is the only thing that helps","weights":{"unfelt":0,"held":0,"surfacing":0,"moved-through":1}}]},{"id":"grief-carrying","type":"choice","prompt":"Are you carrying anything on behalf of other people?","domain":"carrying","options":[{"label":"None of it","value":"None of it","weights":{"unfelt":1,"held":0,"surfacing":0,"moved-through":0}},{"label":"One person’s","value":"One person’s","weights":{"unfelt":0.25,"held":0.75,"surfacing":0,"moved-through":0}},{"label":"A few people’s","value":"A few people’s","weights":{"unfelt":0,"held":0.5,"surfacing":0.5,"moved-through":0}},{"label":"A great deal of it","value":"A great deal of it","weights":{"unfelt":0,"held":0,"surfacing":0.75,"moved-through":0.25}},{"label":"Almost everything I carry is other people’s","value":"Almost everything I carry is other people’s","weights":{"unfelt":0,"held":0,"surfacing":0,"moved-through":1}}]},{"id":"grief-obstacle","type":"choice","prompt":"What is stopping the grieving?","domain":"block","options":[{"label":"I do not know how to","value":"I do not know how to","weights":{"unfelt":1,"held":0,"surfacing":0,"moved-through":0}},{"label":"It feels like weakness, or self-indulgence","value":"It feels like weakness, or self-indulgence","weights":{"unfelt":0.25,"held":0.75,"surfacing":0,"moved-through":0}},{"label":"I believe I would not come back from it","value":"I believe I would not come back from it","weights":{"unfelt":0,"held":0.5,"surfacing":0.5,"moved-through":0}},{"label":"I would not know what to do with what came out","value":"I would not know what to do with what came out","weights":{"unfelt":0,"held":0,"surfacing":0.75,"moved-through":0.25}},{"label":"I suspect there is nothing on the other side","value":"I suspect there is nothing on the other side","weights":{"unfelt":0,"held":0,"surfacing":0,"moved-through":1}}]},{"id":"grief-volume","type":"choice","prompt":"If it moved, how much do you think would come out?","domain":"volume","options":[{"label":"I would rather not find out","value":"I would rather not find out","weights":{"held":1}},{"label":"A little","value":"A little","weights":{"held":1}},{"label":"A lot of years","value":"A lot of years","weights":{"held":1}},{"label":"Everything from one year onwards","value":"Everything from one year onwards","weights":{"held":1}},{"label":"I have no idea how much is in there","value":"I have no idea how much is in there","weights":{"held":1}}]},{"id":"grief-function","type":"choice","prompt":"Is there a reason the grief is still where it is?","domain":"function","options":[{"label":"No reason — it is simply still there","value":"No reason — it is simply still there","weights":{"moved-through":1}},{"label":"It keeps something else in place","value":"It keeps something else in place","weights":{"moved-through":1}},{"label":"It explains my life to me","value":"It explains my life to me","weights":{"moved-through":1}},{"label":"It keeps that period from being over","value":"It keeps that period from being over","weights":{"moved-through":1}},{"label":"It has become who I am","value":"It has become who I am","weights":{"moved-through":1}}]},{"id":"grief-witnessed","type":"choice","prompt":"Has anyone ever actually seen you grieve?","domain":"witness","options":[{"label":"No one has","value":"No one has","weights":{"held":0}},{"label":"Once, briefly","value":"Once, briefly","weights":{"held":0}},{"label":"In a room full of people, but not really","value":"In a room full of people, but not really","weights":{"held":0}},{"label":"A few times, with someone safe","value":"A few times, with someone safe","weights":{"held":0}},{"label":"Yes, and it changed something","value":"Yes, and it changed something","weights":{"held":1}}]},{"id":"grief-deliberate","type":"choice","prompt":"How much of the withholding is on purpose?","domain":"containment","options":[{"label":"None of it is deliberate","value":"None of it is deliberate","weights":{"unfelt":1,"held":0,"surfacing":0,"moved-through":0}},{"label":"A little","value":"A little","weights":{"unfelt":0.25,"held":0.75,"surfacing":0,"moved-through":0}},{"label":"A fair amount","value":"A fair amount","weights":{"unfelt":0,"held":0.5,"surfacing":0.5,"moved-through":0}},{"label":"Most of it","value":"Most of it","weights":{"unfelt":0,"held":0,"surfacing":0.75,"moved-through":0.25}},{"label":"All of it, and I know exactly where I hold it","value":"All of it, and I know exactly where I hold it","weights":{"unfelt":0,"held":0,"surfacing":0,"moved-through":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["unfelt","held","surfacing","moved-through"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"unfelt","label":"Unfelt","short":"Still in there, untouched","description":"The loss has been filed rather than processed, and it is stored with the accuracy it was given. Nothing has been avoided on purpose, which is what makes it hard to find from the inside. Contact is the route, not resolution.","shadow":"Believing time alone was the treatment.","color":"rose","masters":["emotional-healing","bhakti"],"calibration":{"dimensions":{"emotion":0.4,"body":0.25,"thought":0.1},"practiceLevels":{"emotional-healing":2,"bhakti":1},"domainStress":{"state":"emotional-healing"},"tags":["grief-unprocessed","filed"]}},{"id":"held","label":"Held","short":"Carried rather than felt","description":"You are holding a considerable amount — often on behalf of other people, often without being asked. It is being carried competently. The cost is that carrying is not the same as moving, and the weight does not get lighter while it is held.","shadow":"Mistaking strength for having processed it.","color":"amber","masters":["emotional-healing","relationship"],"calibration":{"dimensions":{"emotion":0.35,"connection":0.25,"action":0.15},"practiceLevels":{"emotional-healing":1,"relationship":1},"domainStress":{"relation":"relationship"},"tags":["carrying-others","contained"]}},{"id":"surfacing","label":"Surfacing","short":"It is starting to move on its own","description":"The process is under way, sometimes deliberately and sometimes without your permission. Waves are arriving, and the experience is not always comfortable. What surfaces now does not have to be the biggest thing — it is the next thing.","shadow":"Rushing the whole reservoir at once.","color":"orange","masters":["emotional-healing","body"],"calibration":{"dimensions":{"emotion":0.35,"body":0.3,"spirit":0.15},"practiceLevels":{"emotional-healing":2,"body":1},"domainStress":{"state":"emotional-healing"},"tags":["grief-moving","active-process"]}},{"id":"moved-through","label":"Moved through","short":"You have been through it and come out","description":"The work has been done, and the capacity to feel it is intact — which is why this can be lost again later and felt honestly. Having moved through grief once does not immunise you from it. It does tell you that you can.","shadow":"Staying on the far side of it, out of reach.","color":"emerald","masters":["bhakti","emotional-healing"],"calibration":{"dimensions":{"emotion":0.2,"spirit":0.3,"connection":0.2},"practiceLevels":{"bhakti":1,"emotional-healing":1},"tags":["grieved","capacity-intact"]}}]'::jsonb, '{"loops_to_check":["grief-avoidance","holding-space"],"practice_affinity":["emotional-healing","bhakti"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
