-- Ground state (Welcome)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('ground-state', 'Ground state', 'Your default mood underneath the weather', 'yogic', 'emotion', E'Every day has weather, and every person has a climate. The climate is what is there when nothing is happening — the mood that shows up before the day adds anything to it.\n\nThis looks at the climate, not the weather.', '🌤️', 5, 8, '[{"id":"ground-default","type":"choice","prompt":"If nothing in particular happened today, how would you feel?","domain":"climate","options":[{"label":"Worried or on edge","value":"Worried or on edge","weights":{"anxious":0,"neutral":0,"settled":0,"content":0}},{"label":"A little tense","value":"A little tense","weights":{"anxious":1,"neutral":0,"settled":0,"content":0}},{"label":"Pretty neutral","value":"Pretty neutral","weights":{"anxious":0,"neutral":1,"settled":0,"content":0}},{"label":"Calm","value":"Calm","weights":{"anxious":0,"neutral":0,"settled":1,"content":0}},{"label":"Genuinely glad to be here","value":"Genuinely glad to be here","weights":{"anxious":0,"neutral":0,"settled":0,"content":1}}]},{"id":"ground-wake","type":"choice","prompt":"How do you feel in the moment before you get out of bed?","domain":"climate","options":[{"label":"Dread","value":"Dread","weights":{"neutral":0}},{"label":"Resignation","value":"Resignation","weights":{"neutral":0}},{"label":"Neutral","value":"Neutral","weights":{"neutral":1}},{"label":"Anticipation","value":"Anticipation","weights":{"neutral":0}},{"label":"Genuine willingness","value":"Genuine willingness","weights":{"neutral":0}}]},{"id":"ground-when","type":"choice","prompt":"How often do you actually reach a settled state during a day?","domain":"climate","options":[{"label":"Rarely or never","value":"Rarely or never","weights":{"anxious":1,"neutral":0,"settled":0,"content":0}},{"label":"Occasionally","value":"Occasionally","weights":{"anxious":0.25,"neutral":0.75,"settled":0,"content":0}},{"label":"A few times","value":"A few times","weights":{"anxious":0,"neutral":0.5,"settled":0.5,"content":0}},{"label":"Most of the day","value":"Most of the day","weights":{"anxious":0,"neutral":0,"settled":0.75,"content":0.25}},{"label":"Almost continuously","value":"Almost continuously","weights":{"anxious":0,"neutral":0,"settled":0,"content":1}}]},{"id":"ground-unsettled","type":"choice","prompt":"When you are not settled, what is usually running?","domain":"climate","options":[{"label":"A stream of thoughts","value":"A stream of thoughts","weights":{"anxious":1}},{"label":"Physical tension","value":"Physical tension","weights":{"anxious":1}},{"label":"A low hum of worry","value":"A low hum of worry","weights":{"anxious":1}},{"label":"Irritability I snap at people over","value":"Irritability I snap at people over","weights":{"anxious":1}},{"label":"Something I genuinely cannot name","value":"Something I genuinely cannot name","weights":{"anxious":1}}]},{"id":"ground-ease","type":"choice","prompt":"How easy is your body to be in, day to day?","domain":"climate","options":[{"label":"Rarely comfortable","value":"Rarely comfortable","weights":{"anxious":1,"neutral":0,"settled":0,"content":0}},{"label":"Usually tense","value":"Usually tense","weights":{"anxious":0.25,"neutral":0.75,"settled":0,"content":0}},{"label":"About average","value":"About average","weights":{"anxious":0,"neutral":0.5,"settled":0.5,"content":0}},{"label":"Mostly at ease","value":"Mostly at ease","weights":{"anxious":0,"neutral":0,"settled":0.75,"content":0.25}},{"label":"Genuinely comfortable most of the time","value":"Genuinely comfortable most of the time","weights":{"anxious":0,"neutral":0,"settled":0,"content":1}}]},{"id":"ground-appreciate","type":"choice","prompt":"How often do you notice something good that is already happening?","domain":"climate","options":[{"label":"Almost never","value":"Almost never","weights":{"anxious":1,"neutral":0,"settled":0,"content":0}},{"label":"Rarely","value":"Rarely","weights":{"anxious":0.25,"neutral":0.75,"settled":0,"content":0}},{"label":"Sometimes","value":"Sometimes","weights":{"anxious":0,"neutral":0.5,"settled":0.5,"content":0}},{"label":"Fairly often","value":"Fairly often","weights":{"anxious":0,"neutral":0,"settled":0.75,"content":0.25}},{"label":"Most days, without trying","value":"Most days, without trying","weights":{"anxious":0,"neutral":0,"settled":0,"content":1}}]},{"id":"ground-depends","type":"choice","prompt":"How much does how you feel depend on how the last conversation went?","domain":"climate","options":[{"label":"Entirely","value":"Entirely","weights":{"anxious":1,"neutral":0,"settled":0,"content":0}},{"label":"Very much","value":"Very much","weights":{"anxious":0.25,"neutral":0.75,"settled":0,"content":0}},{"label":"Quite a lot","value":"Quite a lot","weights":{"anxious":0,"neutral":0.5,"settled":0.5,"content":0}},{"label":"A little","value":"A little","weights":{"anxious":0,"neutral":0,"settled":0.75,"content":0.25}},{"label":"Barely at all","value":"Barely at all","weights":{"anxious":0,"neutral":0,"settled":0,"content":1}}]},{"id":"ground-rainy","type":"choice","prompt":"Imagine a bad day. What is underneath it?","domain":"climate","options":[{"label":"Despair or panic","value":"Despair or panic","weights":{"anxious":1,"neutral":0,"settled":0,"content":0}},{"label":"Heavy discouragement","value":"Heavy discouragement","weights":{"anxious":0.25,"neutral":0.75,"settled":0,"content":0}},{"label":"Irritability","value":"Irritability","weights":{"anxious":0,"neutral":0.5,"settled":0.5,"content":0}},{"label":"Quiet disappointment","value":"Quiet disappointment","weights":{"anxious":0,"neutral":0,"settled":0.75,"content":0.25}},{"label":"Sadness, but steady underneath","value":"Sadness, but steady underneath","weights":{"anxious":0,"neutral":0,"settled":0,"content":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["anxious","neutral","settled","content"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"anxious","label":"Anxious climate","short":"The baseline is alert","description":"Your default state has a background charge to it. Because it is constant, it tends to be read as normal, and the absence of anxiety gets mistaken for an achievement rather than a return to baseline.","shadow":"Thinking the current state is fine because it is familiar.","color":"rose","masters":["breath","body"],"calibration":{"dimensions":{"emotion":0.4,"body":0.3,"thought":0.15},"practiceLevels":{"breath":2,"body":1},"domainStress":{"state":"emotional-healing"},"tags":["anxious","high-baseline-alertness"]}},{"id":"neutral","label":"Neutral climate","short":"Flat is your normal","description":"Your baseline is genuinely even, which is a real strength — and it can also mean that feeling is being under-registered. Neutral and numb are easy to confuse from the inside.","shadow":"Calling numbness stability.","color":"slate","masters":["observation","witnessing"],"calibration":{"dimensions":{"emotion":0.25,"thought":0.2,"spirit":0.15},"practiceLevels":{"observation":1,"witnessing":1},"tags":["even","under-felt"]}},{"id":"settled","label":"Settled climate","short":"Calm is your default","description":"There is a real floor of steadiness under your days. You can return to it, which means your practice has something solid to build on rather than something to rescue.","shadow":"Settling into the comfortable and staying there.","color":"teal","masters":["breath","witnessing"],"calibration":{"dimensions":{"emotion":0.25,"body":0.2,"spirit":0.25},"practiceLevels":{"breath":1,"witnessing":1},"tags":["settled","steady"]}},{"id":"content","label":"Content climate","short":"You are mostly here","description":"Your ordinary state has genuine ease in it. This is worth noticing precisely because it is easy to lose without noticing, and easy to mistake for something you got rather than something you have.","shadow":"Contentment that stops asking questions.","color":"emerald","masters":["witnessing","raja"],"calibration":{"dimensions":{"spirit":0.35,"emotion":0.25,"body":0.15},"practiceLevels":{"witnessing":1,"raja":1},"tags":["content","ease"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["body","breath"],"deepens_with":["emotional-range","ground-state"]}'::jsonb, 1, true, false, 100, now())
