-- Hunger cues (Engines)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('hunger-cues', 'Hunger cues', 'True hunger against emotional hunger', 'yogic', 'body', E'Hunger is not a single signal. There is a signal from the body, and there are several from everything else — the hour, the boredom, the argument, the advertisement, the plain sense that a break is due.\n\nThis is not about what to eat. It is about which signal is actually doing the talking, because the two kinds of hunger are received in completely different places, and only one of them is ever satisfied by food.', '🍽️', 6, 8, '[{"id":"hunger-tell","type":"choice","prompt":"Can you tell the difference between real hunger and eating for some other reason?","domain":"distinction","options":[{"label":"Not at all — I eat whenever I notice I could","value":"Not at all — I eat whenever I notice I could","weights":{"habitual":1}},{"label":"Rarely, and usually afterwards","value":"Rarely, and usually afterwards","weights":{"habitual":0.75,"attentional":0.25}},{"label":"Sometimes, once it has started","value":"Sometimes, once it has started","weights":{"attentional":1}},{"label":"Usually, before I begin","value":"Usually, before I begin","weights":{"attentional":0.25,"physiological":0.75}},{"label":"Almost always, from the first small signal","value":"Almost always, from the first small signal","weights":{"physiological":1}}]},{"id":"hunger-speed","type":"choice","prompt":"How fast do you normally eat?","domain":"pace","options":[{"label":"Fast, and afterwards I would not know what I ate","value":"Fast, and afterwards I would not know what I ate","weights":{"habitual":1}},{"label":"Quickly, though I do taste it","value":"Quickly, though I do taste it","weights":{"emotional":1}},{"label":"At an ordinary pace, tasting what I eat","value":"At an ordinary pace, tasting what I eat","weights":{"physiological":1}},{"label":"Slowly, with my attention on the food itself","value":"Slowly, with my attention on the food itself","weights":{"attentional":1}}]},{"id":"hunger-screens","type":"choice","prompt":"How often do you eat with a screen on, or in a car?","domain":"context","options":[{"label":"At almost every meal","value":"At almost every meal","weights":{"habitual":1}},{"label":"Most meals","value":"Most meals","weights":{"habitual":0.75,"attentional":0.25}},{"label":"Often","value":"Often","weights":{"habitual":0.5,"attentional":0.5}},{"label":"Sometimes","value":"Sometimes","weights":{"habitual":0.25,"attentional":0.75}},{"label":"Rarely — I am usually just eating","value":"Rarely — I am usually just eating","weights":{"attentional":1}}]},{"id":"hunger-full","type":"choice","prompt":"Do you ever eat when you already know you are full?","domain":"limits","options":[{"label":"Most of the time","value":"Most of the time","weights":{"emotional":1}},{"label":"Often","value":"Often","weights":{"emotional":0.75,"habitual":0.25}},{"label":"Sometimes","value":"Sometimes","weights":{"habitual":1}},{"label":"Rarely","value":"Rarely","weights":{"habitual":0.25,"physiological":0.75}},{"label":"Almost never — when I am full, I stop","value":"Almost never — when I am full, I stop","weights":{"physiological":1}}]},{"id":"hunger-after","type":"choice","prompt":"How do you feel an hour after eating for a reason other than hunger?","domain":"aftermath","options":[{"label":"Worse than before I started","value":"Worse than before I started","weights":{"emotional":1}},{"label":"Unsettled, and still thinking about it","value":"Unsettled, and still thinking about it","weights":{"emotional":0.75,"habitual":0.25}},{"label":"About the same as before","value":"About the same as before","weights":{"habitual":0.5,"attentional":0.5}},{"label":"A little better","value":"A little better","weights":{"habitual":0.25,"attentional":0.75}},{"label":"Genuinely soothed","value":"Genuinely soothed","weights":{"attentional":1}}]},{"id":"hunger-regular","type":"choice","prompt":"What decides when you eat?","domain":"rhythm","options":[{"label":"Nothing much — I go long, then eat a great deal","value":"Nothing much — I go long, then eat a great deal","weights":{"habitual":1}},{"label":"Whatever is in front of me at the time","value":"Whatever is in front of me at the time","weights":{"attentional":1}},{"label":"The clock, mostly","value":"The clock, mostly","weights":{"physiological":1}},{"label":"How I am feeling, more than the hour","value":"How I am feeling, more than the hour","weights":{"emotional":1}}]},{"id":"hunger-noticed","type":"choice","prompt":"How early do you notice that you are getting hungry?","domain":"signal","options":[{"label":"Only once it is already urgent","value":"Only once it is already urgent","weights":{"habitual":1}},{"label":"Quite late in the process","value":"Quite late in the process","weights":{"habitual":0.75,"attentional":0.25}},{"label":"A little before it is urgent","value":"A little before it is urgent","weights":{"attentional":1}},{"label":"Well before","value":"Well before","weights":{"attentional":0.25,"physiological":0.75}},{"label":"At the first small sign, easily","value":"At the first small sign, easily","weights":{"physiological":1}}]},{"id":"hunger-sought","type":"choice","prompt":"What is the eating actually doing for you?","domain":"motive","options":[{"label":"It settles something that is switched on","value":"It settles something that is switched on","weights":{"emotional":1}},{"label":"It gives me a break from what I am feeling","value":"It gives me a break from what I am feeling","weights":{"attentional":1}},{"label":"It happens without my having decided anything","value":"It happens without my having decided anything","weights":{"habitual":1}},{"label":"It feeds me, and that is genuinely all it is","value":"It feeds me, and that is genuinely all it is","weights":{"physiological":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["physiological","emotional","habitual","attentional"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"physiological","label":"Bodily hunger","short":"The signal and the meal agree","description":"Hunger arrives, you eat, and it settles. The body and the appetite are in conversation and the answer works. The value here is that the signal is available as information — and it is usually more accurate about the whole day than the mind is.","shadow":"A reliable signal that never gets questioned.","color":"emerald","masters":["body","observation"],"calibration":{"dimensions":{"body":0.3,"emotion":0.2,"action":0.15},"practiceLevels":{"body":1,"observation":1},"tags":["listening","regular"]}},{"id":"emotional","label":"Emotional hunger","short":"The appetite is doing other work","description":"A large share of the eating is aimed at a state rather than at nourishment. It works in the moment, which is exactly why it is easy to miss — the relief arrives before the question gets asked.","shadow":"Confusing what settles with what is fed.","color":"rose","masters":["emotional-healing","body"],"calibration":{"dimensions":{"emotion":0.4,"body":0.2,"thought":0.15},"practiceLevels":{"emotional-healing":1},"domainStress":{"state":"emotional-healing"},"tags":["emotional-eating","seeking-settlement"]}},{"id":"habitual","label":"Habitual eating","short":"It happens because it is time","description":"The eating runs on schedule and circumstance rather than on signal. Nothing is wrong with it, and it is also the shape most easily changed — because a habit is the one thing here that does not need your attention in order to keep going.","shadow":"Mistaking a habit for a preference.","color":"amber","masters":["observation","raja"],"calibration":{"dimensions":{"body":0.25,"action":0.2,"thought":0.2},"practiceLevels":{"observation":1,"raja":1},"tags":["routed","automatic"]}},{"id":"attentional","label":"Unattended eating","short":"The meal is a gap, filled in","description":"The eating is not primarily about the body or the mood — it is what the attention is doing while it happens. Often the most changeable of the four, and the least about discipline.","shadow":"Calling it a lack of willpower rather than a lack of attention.","color":"sky","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.35,"body":0.2,"emotion":0.15},"practiceLevels":{"observation":2,"witnessing":1},"tags":["unattended","numb"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["body","observation"],"deepens_with":["ground-state"]}'::jsonb, 1, true, false, 100, now())
