-- Individuation stage (Levels)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('individuation-stage', 'Individuation stage', 'How much of you is truly yours', 'jungian', 'shadow', E'Jung held that a person is born into a family, a class, a country, a religion and a time, and arrives with a set of answers already in place. Individuation is the long, unglamorous business of finding out which of them are actually yours.\n\nThis looks at the proportion, at what has been chosen against expectation, at what is still unexamined, and at what has been refused from the family story.', '🧩', 7, 8, '[{"id":"indiv-inherit","type":"choice","prompt":"How much of what you think and do came from the people you grew up with?","domain":"proportion","options":[{"label":"Nearly everything I think and do came from my family","value":"Nearly everything I think and do came from my family","weights":{"collective":1,"borrowed":0,"distinguishing":0,"individuated":0}},{"label":"Most of it","value":"Most of it","weights":{"collective":0.25,"borrowed":0.75,"distinguishing":0,"individuated":0}},{"label":"A substantial part, with real exceptions","value":"A substantial part, with real exceptions","weights":{"collective":0,"borrowed":0.5,"distinguishing":0.5,"individuated":0}},{"label":"Some of it, and I know which parts","value":"Some of it, and I know which parts","weights":{"collective":0,"borrowed":0,"distinguishing":0.75,"individuated":0.25}},{"label":"Little enough that I could name the source of most of it","value":"Little enough that I could name the source of most of it","weights":{"collective":0,"borrowed":0,"distinguishing":0,"individuated":1}}]},{"id":"indiv-chosen","type":"choice","prompt":"How much of it did you pick?","domain":"selection","options":[{"label":"I have not chosen anything that matters yet","value":"I have not chosen anything that matters yet","weights":{"collective":1,"borrowed":0,"distinguishing":0,"individuated":0}},{"label":"I have made choices, but they were the ones available to me","value":"I have made choices, but they were the ones available to me","weights":{"collective":0.25,"borrowed":0.75,"distinguishing":0,"individuated":0}},{"label":"I have chosen some things against what was expected of me","value":"I have chosen some things against what was expected of me","weights":{"collective":0,"borrowed":0.5,"distinguishing":0.5,"individuated":0}},{"label":"I have chosen deliberately, and against several things","value":"I have chosen deliberately, and against several things","weights":{"collective":0,"borrowed":0,"distinguishing":0.75,"individuated":0.25}},{"label":"I have chosen most of what I hold, and I can show the working","value":"I have chosen most of what I hold, and I can show the working","weights":{"collective":0,"borrowed":0,"distinguishing":0,"individuated":1}}]},{"id":"indiv-unexamined","type":"choice","prompt":"How much of what you hold have you never actually looked at?","domain":"untouched","options":[{"label":"Almost everything I hold","value":"Almost everything I hold","weights":{"collective":0}},{"label":"Most of what I hold","value":"Most of what I hold","weights":{"collective":0.25}},{"label":"A substantial part, which I have not looked at","value":"A substantial part, which I have not looked at","weights":{"collective":0.5}},{"label":"A smaller part that I have left alone deliberately","value":"A smaller part that I have left alone deliberately","weights":{"collective":0.75}},{"label":"Very little that has not been looked at","value":"Very little that has not been looked at","weights":{"collective":1}}]},{"id":"indiv-difference","type":"choice","prompt":"Are you different from the people you came from?","domain":"distinctness","options":[{"label":"Difference is not something I have around me","value":"Difference is not something I have around me","weights":{"borrowed":0,"distinguishing":0,"individuated":0}},{"label":"I am told I may be different, as long as it is not visible","value":"I am told I may be different, as long as it is not visible","weights":{"borrowed":1,"distinguishing":0,"individuated":0}},{"label":"I can be different, within limits I set myself","value":"I can be different, within limits I set myself","weights":{"borrowed":0,"distinguishing":0,"individuated":0}},{"label":"I live visibly differently from most of the people I know","value":"I live visibly differently from most of the people I know","weights":{"borrowed":0,"distinguishing":1,"individuated":0}},{"label":"My life does not look like the one it would have by default","value":"My life does not look like the one it would have by default","weights":{"borrowed":0,"distinguishing":0,"individuated":1}}]},{"id":"indiv-story","type":"choice","prompt":"What does the family story say you are for?","domain":"family-brief","options":[{"label":"There was never any such story","value":"There was never any such story","weights":{"collective":0}},{"label":"It is written into how we treat one another","value":"It is written into how we treat one another","weights":{"collective":0.25}},{"label":"I have heard it said plainly, more than once","value":"I have heard it said plainly, more than once","weights":{"collective":0.5}},{"label":"I have been told directly what is expected of me","value":"I have been told directly what is expected of me","weights":{"collective":0.75}},{"label":"I have been told, in effect, what I am for","value":"I have been told, in effect, what I am for","weights":{"collective":1}}]},{"id":"indiv-refused","type":"choice","prompt":"What have you refused from it?","domain":"refusal","options":[{"label":"I have refused nothing","value":"I have refused nothing","weights":{"borrowed":0,"distinguishing":0,"individuated":0}},{"label":"Small things, without saying so","value":"Small things, without saying so","weights":{"borrowed":1,"distinguishing":0,"individuated":0}},{"label":"Some things, out loud","value":"Some things, out loud","weights":{"borrowed":0,"distinguishing":0,"individuated":0}},{"label":"Things that mattered to me, and I said why","value":"Things that mattered to me, and I said why","weights":{"borrowed":0,"distinguishing":1,"individuated":0}},{"label":"The central instruction of my family","value":"The central instruction of my family","weights":{"borrowed":0,"distinguishing":0,"individuated":1}}]},{"id":"indiv-tolerated","type":"choice","prompt":"Is your difference tolerated by the people around you?","domain":"price-of-difference","options":[{"label":"I keep it small enough that nobody objects","value":"I keep it small enough that nobody objects","weights":{"individuated":0}},{"label":"I hide the parts that would cause friction","value":"I hide the parts that would cause friction","weights":{"individuated":0.25}},{"label":"Some of it is visible and accepted","value":"Some of it is visible and accepted","weights":{"individuated":0.5}},{"label":"Most of it is visible, and it has been tested","value":"Most of it is visible, and it has been tested","weights":{"individuated":0.75}},{"label":"I live entirely in my own key, and have stopped testing it","value":"I live entirely in my own key, and have stopped testing it","weights":{"individuated":1}}]},{"id":"indiv-separation","type":"choice","prompt":"What did separating from the family story cost you?","domain":"cost","options":[{"label":"I have not separated at all, and the sameness is comfortable","value":"I have not separated at all, and the sameness is comfortable","weights":{"distinguishing":0}},{"label":"A little separation, at a cost I have paid quietly","value":"A little separation, at a cost I have paid quietly","weights":{"distinguishing":0.25}},{"label":"Real separation, and I have paid for it","value":"Real separation, and I have paid for it","weights":{"distinguishing":0.5}},{"label":"Real separation, and it has been worth what it cost","value":"Real separation, and it has been worth what it cost","weights":{"distinguishing":0.75}},{"label":"I have separated, and I have not gone back to check","value":"I have separated, and I have not gone back to check","weights":{"distinguishing":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["collective","borrowed","distinguishing","individuated"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"collective","label":"Collective","short":"The family brief is still running the life","description":"Most of what is held has arrived unchosen and remains unexamined, and the family story is still doing the deciding. This is the ordinary condition of a life, and it is the condition from which every other possibility in this module begins.","shadow":"Mistaking the inherited arrangement for the person.","color":"slate","masters":["self-inquiry","witnessing"],"calibration":{"dimensions":{"connection":0.25,"spirit":0.2,"thought":0.2},"practiceLevels":{"self-inquiry":1,"witnessing":1},"domainStress":{"family":"relationship"},"tags":["collective","unexamined"]}},{"id":"borrowed","label":"Borrowed","short":"Held, and still mostly on loan","description":"The material is real and it has begun to be questioned, but most of it is still running without a decision behind it. This is where individuation actually happens: slowly, one item at a time, with a lot of ordinary life in between.","shadow":"Inheriting the freedom and not the responsibility.","color":"rose","masters":["self-inquiry","jnana"],"calibration":{"dimensions":{"thought":0.25,"connection":0.25,"spirit":0.15},"practiceLevels":{"self-inquiry":1,"jnana":1},"tags":["borrowed","in-question"]}},{"id":"distinguishing","label":"Distinguishing","short":"The difference is being lived, and it costs something","description":"A clear seam has developed between what was handed down and what was chosen, and the difference is visible to the people around you. The price is paid in some closeness, and the benefit is that the choices are actually choices.","shadow":"Difference turned into a family of its own.","color":"amber","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"spirit":0.3,"connection":0.2,"thought":0.2},"practiceLevels":{"jnana":1,"self-inquiry":1},"domainStress":{"family":"relationship"},"tags":["distinguishing","separated"]}},{"id":"individuated","label":"Individuated","short":"Most of it was selected, and you know the terms","description":"The great majority of what is held has been examined and selected, including the material that was not refused but simply found not to fit. The remaining work is less about separation and more about living well inside a life that is genuinely your own arrangement.","shadow":"The arrangement mistaken for the whole of the person.","color":"indigo","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"spirit":0.4,"thought":0.2,"action":0.15},"practiceLevels":{"jnana":2,"self-inquiry":1},"tags":["individuated","self-authored"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["self-inquiry","jnana"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
