) VALUES
    ('inner-compass', 'Inner compass', 'Name what actually matters to you', 'vedic', 'values', E'Most people know their reasons by the shape of their reactions — what they defend, what they are quietly proud of, what they would not give up. Nobody draws the map directly; it is inferred from behaviour, and it is often out of date.\n\nFive things are named here, in the order most people find them: what others think, safety, going further, being free, and being of use. The order is not a ranking of virtue. It is the order in which they usually become loud.', '🧭', 6, 6, '[{"id":"compass-driver","type":"choice","prompt":"When a decision that matters has to be made, what do you actually check first?","domain":"motive","options":[{"label":"What the people close to me will make of it","value":"What the people close to me will make of it","weights":{"approval":1}},{"label":"Whether it is safe and whether it will hold","value":"Whether it is safe and whether it will hold","weights":{"security":1}},{"label":"Whether it moves me further forward","value":"Whether it moves me further forward","weights":{"achievement":1}},{"label":"Whether it leaves me free to decide again tomorrow","value":"Whether it leaves me free to decide again tomorrow","weights":{"autonomy":1}},{"label":"Whether it is useful to anyone besides me","value":"Whether it is useful to anyone besides me","weights":{"service":1}}]},{"id":"compass-give-up","type":"choice","prompt":"Which of these is hardest for you to give up?","domain":"attachment","options":[{"label":"Being liked","value":"Being liked","weights":{"approval":1,"security":0,"achievement":0,"autonomy":0,"service":0}},{"label":"Being safe","value":"Being safe","weights":{"approval":0,"security":1,"achievement":0,"autonomy":0,"service":0}},{"label":"Getting further than I have","value":"Getting further than I have","weights":{"approval":0,"security":0,"achievement":1,"autonomy":0,"service":0}},{"label":"Being free to choose","value":"Being free to choose","weights":{"approval":0,"security":0,"achievement":0,"autonomy":1,"service":0}},{"label":"Being of use to someone","value":"Being of use to someone","weights":{"approval":0,"security":0,"achievement":0,"autonomy":0,"service":1}}]},{"id":"compass-regard","type":"choice","prompt":"How much does a decision feel right only once other people have approved of it?","domain":"regard","options":[{"label":"It has to be broadly right first, then I relax","value":"It has to be broadly right first, then I relax","weights":{"approval":0}},{"label":"I do reasonably well without it","value":"I do reasonably well without it","weights":{"approval":0.25}},{"label":"I notice its absence, and it matters","value":"I notice its absence, and it matters","weights":{"approval":0.5}},{"label":"I think about it constantly","value":"I think about it constantly","weights":{"approval":0.75}},{"label":"I could hardly act if nobody agreed","value":"I could hardly act if nobody agreed","weights":{"approval":1}}]},{"id":"compass-unseen","type":"choice","prompt":"If nobody would ever find out, what would change?","domain":"unwitnessed","options":[{"label":"Almost all of it would stop","value":"Almost all of it would stop","weights":{"approval":1}},{"label":"I would still take the safe option, but more cheaply","value":"I would still take the safe option, but more cheaply","weights":{"security":1}},{"label":"I would still push, because the result is the point to me","value":"I would still push, because the result is the point to me","weights":{"achievement":1}},{"label":"I would do far more of the things I actually like","value":"I would do far more of the things I actually like","weights":{"autonomy":1}},{"label":"I would probably do more, not less","value":"I would probably do more, not less","weights":{"service":1}}]},{"id":"compass-surplus","type":"choice","prompt":"When you have more than you need, what happens to the extra?","domain":"others","options":[{"label":"It stays with me — I am the one it is for","value":"It stays with me — I am the one it is for","weights":{"approval":1,"security":0,"achievement":0,"autonomy":0,"service":0}},{"label":"Most of it stays close","value":"Most of it stays close","weights":{"approval":0,"security":1,"achievement":0,"autonomy":0,"service":0}},{"label":"Some of it goes out to other people","value":"Some of it goes out to other people","weights":{"approval":0,"security":0,"achievement":1,"autonomy":0,"service":0}},{"label":"A good deal of it goes out to other people","value":"A good deal of it goes out to other people","weights":{"approval":0,"security":0,"achievement":0,"autonomy":1,"service":0}},{"label":"It goes out of my hands without a decision being needed","value":"It goes out of my hands without a decision being needed","weights":{"approval":0,"security":0,"achievement":0,"autonomy":0,"service":1}}]},{"id":"compass-free","type":"choice","prompt":"Suppose a week arrived where nothing was at stake. What would you do with it?","domain":"freedom","options":[{"label":"I would be as lost as ever, and I would not know what to do","value":"I would be as lost as ever, and I would not know what to do","weights":{"approval":1,"security":0,"achievement":0,"autonomy":0,"service":0}},{"label":"I would finally rest, properly","value":"I would finally rest, properly","weights":{"approval":0,"security":1,"achievement":0,"autonomy":0,"service":0}},{"label":"I would fill it with something that counts","value":"I would fill it with something that counts","weights":{"approval":0,"security":0,"achievement":1,"autonomy":0,"service":0}},{"label":"I would do the things I have been putting off for months","value":"I would do the things I have been putting off for months","weights":{"approval":0,"security":0,"achievement":0,"autonomy":1,"service":0}},{"label":"I would spend it with people, and not be counting the hours","value":"I would spend it with people, and not be counting the hours","weights":{"approval":0,"security":0,"achievement":0,"autonomy":0,"service":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["approval","security","achievement","autonomy","service"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"approval","label":"Approval-led","short":"The audience is in the room with you","description":"Your decisions are made with an imagined witness present, and that witness is a demanding one. The strength in it is real: you notice things other people miss, because reading the room has made you fluent in it. The cost is that your own verdict on your own life arrives second, if at all.","shadow":"Treating the absence of disapproval as approval.","color":"rose","masters":["observation","self-inquiry"],"calibration":{"dimensions":{"connection":0.3,"emotion":0.25,"thought":0.15},"practiceLevels":{"observation":1,"self-inquiry":1},"domainStress":{"relation":"relationship"},"tags":["approval-led","externally-referenced"]}},{"id":"security","label":"Security-led","short":"Safety is the first question, every time","description":"Stability, predictability and safety are the frame everything else is judged inside. That frame is not timidity — it is an accurate reading of how much can be lost, and it has probably served you well. It becomes worth examining when the cost of holding on starts to exceed the cost of the risk.","shadow":"Calling the refusal to move prudence.","color":"amber","masters":["body","raja"],"calibration":{"dimensions":{"body":0.25,"emotion":0.2,"action":0.15},"practiceLevels":{"body":1,"raja":1},"domainStress":{"safety":"health"},"tags":["risk-averse","protective"]}},{"id":"achievement","label":"Achievement-led","short":"Forward motion is the measure","description":"You orient by distance travelled, and the future is doing most of the work. This is how most careers and most ambitions are actually built, and it is not shallow. What it hides is the question of whether the thing being built is one you would want to live inside.","shadow":"Confusing the measure with the destination.","color":"orange","masters":["karma","raja"],"calibration":{"dimensions":{"action":0.35,"thought":0.2,"connection":0.15},"practiceLevels":{"karma":1,"raja":1},"domainStress":{"work":"work-career"},"tags":["driven","future-referenced"]}},{"id":"autonomy","label":"Autonomy-led","short":"Nothing worth having should require permission","description":"Your organising value is that the decision has to be yours, and a great deal of your energy goes towards keeping it so. This produces real independence and a low tolerance for being steered. The edge of it is that freedom can be defended so carefully that nothing new is ever permitted through it.","shadow":"Choosing autonomy over the relationship it costs.","color":"sky","masters":["jnana","raja"],"calibration":{"dimensions":{"thought":0.25,"action":0.2,"spirit":0.2},"practiceLevels":{"jnana":1,"raja":1},"tags":["self-directed","choice-centred"]}},{"id":"service","label":"Service-led","short":"The measure sits outside you","description":"You orient by what is useful to somebody, which puts your decisions in a wider frame than most people work in. It can become its own escape, though — a person who is always serving has a reliable way of not looking at their own condition, and the people being served are often the last to notice.","shadow":"Spending a life on others to avoid being in one.","color":"emerald","masters":["karma","bhakti"],"calibration":{"dimensions":{"connection":0.35,"action":0.25,"spirit":0.2},"practiceLevels":{"karma":1,"bhakti":1},"domainStress":{"relation":"relationship"},"tags":["service-oriented","outward"]}}]'::jsonb, '{"loops_to_check":["approval-seeking","control-seeking"],"practice_affinity":["self-inquiry","jnana","karma"],"deepens_with":["spiritual-stage","work-dharma"]}'::jsonb, 1, true, false, 100, now())
