-- Inner council (Levels)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('inner-council', 'Inner council', 'The parts of you that disagree', 'vedic', 'shadow', E'The mind does not speak with one voice. It runs a council, and the council has members with different appetites, different tolerances for risk, and wildly different ideas about what a good Tuesday looks like.\n\nThis looks at the council itself — how many members take part, whether they can be heard, and whether they ever agree on anything.', '🧑‍⚖️', 6, 7, '[{"id":"council-membership","type":"choice","prompt":"When you sit with a decision, how many distinct things in you have an opinion?","domain":"voices","options":[{"label":"One, and it does the deciding","value":"One, and it does the deciding","weights":{"one-voice":1,"conflict":0,"negotiation":0,"integration":0}},{"label":"One, and an argument whenever I stop listening to it","value":"One, and an argument whenever I stop listening to it","weights":{"one-voice":0.25,"conflict":0.75,"negotiation":0,"integration":0}},{"label":"Two or three, and they tend to cancel each other out","value":"Two or three, and they tend to cancel each other out","weights":{"one-voice":0,"conflict":0.5,"negotiation":0.5,"integration":0}},{"label":"Several, and I can hear what each of them wants","value":"Several, and I can hear what each of them wants","weights":{"one-voice":0,"conflict":0,"negotiation":0.75,"integration":0.25}},{"label":"Several, and they mostly arrive already in agreement","value":"Several, and they mostly arrive already in agreement","weights":{"one-voice":0,"conflict":0,"negotiation":0,"integration":1}}]},{"id":"council-interrupt","type":"choice","prompt":"How often does the internal argument get loud enough to stop you doing something?","domain":"disagreement","options":[{"label":"It never gets that far","value":"It never gets that far","weights":{"conflict":0}},{"label":"Rarely — I usually decide before it starts","value":"Rarely — I usually decide before it starts","weights":{"conflict":0.25}},{"label":"Often enough to cost me real time","value":"Often enough to cost me real time","weights":{"conflict":0.5}},{"label":"Most of the decisions I would call ordinary","value":"Most of the decisions I would call ordinary","weights":{"conflict":0.75}},{"label":"It is currently the main thing running my days","value":"It is currently the main thing running my days","weights":{"conflict":1}}]},{"id":"council-speed","type":"choice","prompt":"How long do you sit with an unsettled decision before acting?","domain":"speed","options":[{"label":"Not at all — I act first","value":"Not at all — I act first","weights":{"one-voice":0}},{"label":"A few minutes","value":"A few minutes","weights":{"one-voice":0.25}},{"label":"Long enough to feel indecent about it","value":"Long enough to feel indecent about it","weights":{"one-voice":0.5}},{"label":"Long enough to have a real look round","value":"Long enough to have a real look round","weights":{"one-voice":0.75}},{"label":"As long as it takes, and I am comfortable there","value":"As long as it takes, and I am comfortable there","weights":{"one-voice":1}}]},{"id":"council-authority","type":"choice","prompt":"Which part of you usually gets its way?","domain":"authority","options":[{"label":"The one that has never had to argue for anything","value":"The one that has never had to argue for anything","weights":{"one-voice":1}},{"label":"The one that can refuse the longest","value":"The one that can refuse the longest","weights":{"conflict":1}},{"label":"The one that finds the compromise","value":"The one that finds the compromise","weights":{"negotiation":1}},{"label":"None of them alone — it comes out of all of them together","value":"None of them alone — it comes out of all of them together","weights":{"integration":1}}]},{"id":"council-listening","type":"choice","prompt":"How easily can you let one part of you make its case without answering it?","domain":"listening","options":[{"label":"I answer it straight away, every time","value":"I answer it straight away, every time","weights":{"negotiation":0}},{"label":"I catch myself and let it run a little further","value":"I catch myself and let it run a little further","weights":{"negotiation":0.25}},{"label":"I let it finish if it is not going badly","value":"I let it finish if it is not going badly","weights":{"negotiation":0.5}},{"label":"I let it finish without taking it personally","value":"I let it finish without taking it personally","weights":{"negotiation":0.75}},{"label":"I listen to the whole of it, including the parts I would rather not hear","value":"I listen to the whole of it, including the parts I would rather not hear","weights":{"negotiation":1}}]},{"id":"council-body","type":"choice","prompt":"When one part of you speaks up, where do you notice it?","domain":"body","options":[{"label":"Something moves before I know what is moving","value":"Something moves before I know what is moving","weights":{"one-voice":1,"conflict":0,"negotiation":0,"integration":0}},{"label":"A tightening across the chest, early","value":"A tightening across the chest, early","weights":{"one-voice":0,"conflict":1,"negotiation":0,"integration":0}},{"label":"The jaw and the shoulders","value":"The jaw and the shoulders","weights":{"one-voice":0,"conflict":0,"negotiation":1,"integration":0}},{"label":"Very little — it is all fairly quiet until it is not","value":"Very little — it is all fairly quiet until it is not","weights":{"one-voice":0,"conflict":0,"negotiation":0,"integration":1}}]},{"id":"council-consent","type":"choice","prompt":"When a decision is finally made, how much of you is actually behind it?","domain":"commitment","options":[{"label":"I act on it and quietly carry the rest","value":"I act on it and quietly carry the rest","weights":{"integration":0}},{"label":"I go along, and one part stays in open revolt","value":"I go along, and one part stays in open revolt","weights":{"integration":0.25}},{"label":"I go along, and I stop asking questions","value":"I go along, and I stop asking questions","weights":{"integration":0.5}},{"label":"I am mostly behind it, with one reservation","value":"I am mostly behind it, with one reservation","weights":{"integration":0.75}},{"label":"I am entirely behind it, and I did not have to talk myself into it","value":"I am entirely behind it, and I did not have to talk myself into it","weights":{"integration":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["one-voice","conflict","negotiation","integration"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"one-voice","label":"Single voice","short":"One voice, running everything","description":"There is one authority and it is not questioned. Speed comes from this, and so does the narrowness — a council of one cannot check itself, and by the time the objection arrives it has usually been acted on.","shadow":"Mistaking never being contradicted for never being wrong.","color":"slate","masters":["observation","self-inquiry"],"calibration":{"dimensions":{"thought":0.3,"action":0.25,"emotion":0.15},"practiceLevels":{"observation":1,"self-inquiry":1},"tags":["one-voice","undivided"]}},{"id":"conflict","label":"Standing conflict","short":"The argument never resolves","description":"The members disagree and stay disagreed. Nothing here is unusual — it is what a council does when it is never allowed to finish a round. The practical effect is that a great deal of capacity goes into the argument itself.","shadow":"Keeping the fight alive because the outcome is unclear.","color":"orange","masters":["witnessing","loop-dissolution"],"calibration":{"dimensions":{"emotion":0.35,"thought":0.25,"body":0.15},"practiceLevels":{"witnessing":2,"loop-dissolution":1},"domainStress":{"indecision":"work-career"},"tags":["conflict","unresolved"]}},{"id":"negotiation","label":"Negotiating","short":"The members are actually heard","description":"Your parts are being listened to and traded off against each other. This is real deliberation and it is slow, but it produces decisions that hold, because everything with a stake got a say.","shadow":"Compromise mistaken for the absence of a position.","color":"amber","masters":["witnessing","jnana"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.2,"action":0.15},"practiceLevels":{"witnessing":1,"jnana":1},"tags":["negotiation","deliberating"]}},{"id":"integration","label":"Integrated council","short":"They mostly arrive in agreement","description":"The parts talk to each other before they talk to you, and most decisions are already settled by the time they reach the surface. This is not the absence of disagreement; it is disagreement that has somewhere to go.","shadow":"Agreement arriving quickly enough that nobody checks it.","color":"teal","masters":["witnessing","self-inquiry"],"calibration":{"dimensions":{"spirit":0.3,"thought":0.2,"emotion":0.2},"practiceLevels":{"witnessing":2,"self-inquiry":1},"tags":["integration","coherent"]}}]'::jsonb, '{"loops_to_check":["indecision","self-criticism","reactivity"],"practice_affinity":["witnessing","self-inquiry"],"deepens_with":["shadow-inventory","attachment-style","non-dual-glimpses"]}'::jsonb, 1, true, false, 100, now())
