-- Inner silence (Observation)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('inner-silence', 'Inner silence', 'The gap between two thoughts', 'vedic', 'witness', E'There is a gap between one thought and the next. It is not a philosophical idea — it is a feature of what thinking actually is, and everyone has already been in one without knowing it.\n\nThe gap is also the only place in the mind where nothing is being produced. This looks at whether that place can be felt, whether it can be returned to, and what closes it when it opens.', '🕳️', 7, 8, '[{"id":"gap-felt","type":"choice","prompt":"Have you ever actually felt the gap between two thoughts?","domain":"existence","options":[{"label":"I do not believe I have","value":"I do not believe I have","weights":{"absent":1}},{"label":"Once or twice, and I was not sure what it was","value":"Once or twice, and I was not sure what it was","weights":{"fleeting":1}},{"label":"Often enough to recognise it when it comes","value":"Often enough to recognise it when it comes","weights":{"encounterable":1}},{"label":"Regularly, and I know it well","value":"Regularly, and I know it well","weights":{"inhabitable":1}}]},{"id":"gap-length","type":"choice","prompt":"When it happens, how long does it last?","domain":"duration","options":[{"label":"A fraction of a second, and gone","value":"A fraction of a second, and gone","weights":{"absent":1}},{"label":"A second or two","value":"A second or two","weights":{"absent":0.75,"fleeting":0.25}},{"label":"A few seconds, enough to notice","value":"A few seconds, enough to notice","weights":{"fleeting":1}},{"label":"Long enough to be clear about it","value":"Long enough to be clear about it","weights":{"fleeting":0.25,"encounterable":0.75}},{"label":"It opens out, and it stays open","value":"It opens out, and it stays open","weights":{"encounterable":0.5,"inhabitable":0.5}}]},{"id":"gap-quality","type":"choice","prompt":"What is it like, when it happens?","domain":"texture","options":[{"label":"A blank nothing — I was not there for it","value":"A blank nothing — I was not there for it","weights":{"absent":1}},{"label":"A brief emptiness, gone before it registers","value":"A brief emptiness, gone before it registers","weights":{"fleeting":1}},{"label":"A clear, open space","value":"A clear, open space","weights":{"encounterable":1}},{"label":"Stillness with a great deal in it","value":"Stillness with a great deal in it","weights":{"inhabitable":1}}]},{"id":"gap-heard","type":"choice","prompt":"Is anything there when the gap opens?","domain":"contents","options":[{"label":"Nothing at all — I was not there","value":"Nothing at all — I was not there","weights":{"absent":1}},{"label":"Not that I could say afterwards","value":"Not that I could say afterwards","weights":{"fleeting":1}},{"label":"A presence, or a sense of being","value":"A presence, or a sense of being","weights":{"encounterable":1}},{"label":"Something that seemed aware of me looking","value":"Something that seemed aware of me looking","weights":{"inhabitable":1}}]},{"id":"gap-return","type":"choice","prompt":"How hard is it to return to it on purpose?","domain":"access","options":[{"label":"I cannot find it when I look","value":"I cannot find it when I look","weights":{"absent":1}},{"label":"It takes a great deal of trying","value":"It takes a great deal of trying","weights":{"absent":0.75,"fleeting":0.25}},{"label":"It takes sustained practice","value":"It takes sustained practice","weights":{"fleeting":1}},{"label":"I can get there with a little effort","value":"I can get there with a little effort","weights":{"fleeting":0.25,"encounterable":0.75}},{"label":"I can settle into it deliberately","value":"I can settle into it deliberately","weights":{"encounterable":0.5,"inhabitable":0.5}}]},{"id":"gap-enter","type":"choice","prompt":"Is silence something you can enter, or only something that arrives?","domain":"direction","options":[{"label":"Only ever something that happens to me","value":"Only ever something that happens to me","weights":{"absent":1}},{"label":"It happens, and then it goes","value":"It happens, and then it goes","weights":{"fleeting":1}},{"label":"I can go towards it","value":"I can go towards it","weights":{"encounterable":1}},{"label":"I go in, and I know the way there","value":"I go in, and I know the way there","weights":{"inhabitable":1}}]},{"id":"gap-closes","type":"choice","prompt":"What ends it, once it has opened?","domain":"interruption","options":[{"label":"I never get far enough for it to end","value":"I never get far enough for it to end","weights":{"absent":1}},{"label":"I notice it, and losing it is the noticing","value":"I notice it, and losing it is the noticing","weights":{"fleeting":1}},{"label":"A thought arrives, and closes it","value":"A thought arrives, and closes it","weights":{"encounterable":1}},{"label":"Nothing much closes it, and I can stay","value":"Nothing much closes it, and I can stay","weights":{"inhabitable":1}}]},{"id":"gap-daily","type":"choice","prompt":"How much of your life has any of this in it?","domain":"presence","options":[{"label":"None at all","value":"None at all","weights":{"absent":1}},{"label":"Occasionally, by accident","value":"Occasionally, by accident","weights":{"absent":0.75,"fleeting":0.25}},{"label":"Now and then, on purpose","value":"Now and then, on purpose","weights":{"fleeting":1}},{"label":"Regularly, if briefly","value":"Regularly, if briefly","weights":{"fleeting":0.25,"encounterable":0.75}},{"label":"It is a real part of how I move through the day","value":"It is a real part of how I move through the day","weights":{"encounterable":0.5,"inhabitable":0.5}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["absent","fleeting","encounterable","inhabitable"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"absent","label":"Gap unavailable","short":"The space has never been felt","description":"There is no report of the space between thoughts, and no reliable way of getting there on purpose. This is the ordinary starting condition, and it is far more common than people expect. What is not available is also not missing — it has simply never been introduced.","shadow":"Assuming there is nothing there because nothing has been reported.","color":"slate","masters":["witnessing","breath"],"calibration":{"dimensions":{"spirit":0.35,"thought":0.3},"practiceLevels":{"witnessing":1,"breath":1},"tags":["unavailable","not-yet-introduced"]}},{"id":"fleeting","label":"Fleeting contact","short":"It has been there, and it went quickly","description":"The gap has been felt, briefly, and usually by not looking for it. It closes as soon as attention arrives, which is not a failure of the attempt but the ordinary condition of the thing itself. The skill here is arriving without arriving.","shadow":"Grieving the gap that closes as you notice it.","color":"amber","masters":["witnessing","breath"],"calibration":{"dimensions":{"spirit":0.3,"thought":0.25,"body":0.15},"practiceLevels":{"witnessing":1,"breath":1},"tags":["brief","closes-on-noticing"]}},{"id":"encounterable","label":"Encounterable","short":"It can be found, and it is recognisable","description":"The gap can be reached deliberately, and it is recognisable when it arrives. What usually comes next is a question: if the space is not empty, and the thought is not what closes it, then what exactly is doing the closing?","shadow":"Reaching for it and calling the reaching a failure of practice.","color":"teal","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.35,"thought":0.25},"practiceLevels":{"witnessing":2,"jnana":1},"tags":["findable","reliable"]}},{"id":"inhabitable","label":"Inhabitable","short":"It is a place, and it can be lived in","description":"The silence is something you go into rather than something that happens to you, and it can be stayed in. Worth watching what else gets decided in there, because a place that resolves everything on its own can start to be preferred to the conversations that do not.","shadow":"Silence preferred to the difficult thing that is waiting.","color":"indigo","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.45,"thought":0.2},"practiceLevels":{"witnessing":2,"jnana":2},"domainStress":{"contact":"relationship"},"tags":["inhabited","chosen"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["witnessing","raja"],"deepens_with":["silence-tolerance","non-dual-glimpses"]}'::jsonb, 1, true, false, 100, now())
