-- Inquiry sharpness (12 Skills)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('inquiry-sharpness', 'Inquiry sharpness', 'The edge of your Jnana blade', 'vedic', 'path', E'Inquiry is not the amount of thinking you do. It is what happens when a question gets past the explanation and reaches the thing that was being explained.\n\nThis measures the sharpness of the blade — whether a belief can be examined without being defended, and whether an answer you have arrived at belongs to you.', '🗡️', 6, 8, '[{"id":"inquiry-wobble","type":"choice","prompt":"When somebody questions a belief of yours, how much does it wobble?","domain":"defence","options":[{"label":"Not at all — it is simply true","value":"Not at all — it is simply true","weights":{"discriminating":0}},{"label":"A little, then I argue","value":"A little, then I argue","weights":{"discriminating":0.25}},{"label":"Some, and I take a while to come back to it","value":"Some, and I take a while to come back to it","weights":{"discriminating":0.5}},{"label":"Most of it goes","value":"Most of it goes","weights":{"discriminating":0.75}},{"label":"It does not survive the question at all","value":"It does not survive the question at all","weights":{"discriminating":1}}]},{"id":"inquiry-borrowed","type":"choice","prompt":"Before you state something as true, do you know where you got it from?","domain":"ownership","options":[{"label":"I mostly repeat what I was taught","value":"I mostly repeat what I was taught","weights":{"intellectual":1}},{"label":"I can hear when I am quoting someone","value":"I can hear when I am quoting someone","weights":{"discriminating":1}},{"label":"I have to test it before I will call it mine","value":"I have to test it before I will call it mine","weights":{"penetrating":1}},{"label":"I know which thoughts are mine before I have had them","value":"I know which thoughts are mine before I have had them","weights":{"razor-sharp":1}}]},{"id":"inquiry-language","type":"choice","prompt":"How accurately can you describe what is happening inside you right now?","domain":"precision","options":[{"label":"I use the same few words for everything","value":"I use the same few words for everything","weights":{"intellectual":0,"discriminating":0,"penetrating":0,"razor-sharp":0}},{"label":"Some of my words land accurately","value":"Some of my words land accurately","weights":{"intellectual":1,"discriminating":0,"penetrating":0,"razor-sharp":0}},{"label":"I can be exact about feelings","value":"I can be exact about feelings","weights":{"intellectual":0,"discriminating":1,"penetrating":0,"razor-sharp":0}},{"label":"I can be exact about feelings and thoughts both","value":"I can be exact about feelings and thoughts both","weights":{"intellectual":0,"discriminating":0,"penetrating":1,"razor-sharp":0}},{"label":"The words match the experience exactly","value":"The words match the experience exactly","weights":{"intellectual":0,"discriminating":0,"penetrating":0,"razor-sharp":1}}]},{"id":"inquiry-follow","type":"choice","prompt":"When a question really matters, how far do you take it?","domain":"reach","options":[{"label":"I drop it quickly","value":"I drop it quickly","weights":{"penetrating":0}},{"label":"A little way, then I move on","value":"A little way, then I move on","weights":{"penetrating":0.25}},{"label":"Quite far, if I have the time","value":"Quite far, if I have the time","weights":{"penetrating":0.5}},{"label":"All the way, however long it takes","value":"All the way, however long it takes","weights":{"penetrating":0.75}},{"label":"It answers itself before I reach the end of it","value":"It answers itself before I reach the end of it","weights":{"penetrating":1}}]},{"id":"inquiry-block","type":"choice","prompt":"What most often stops a question from being finished?","domain":"block","options":[{"label":"No time for questions like that","value":"No time for questions like that","weights":{"intellectual":1}},{"label":"Asking it makes me look foolish","value":"Asking it makes me look foolish","weights":{"discriminating":1}},{"label":"The answer would change what I have to do next","value":"The answer would change what I have to do next","weights":{"penetrating":1}},{"label":"I am not sure I could live with not finding out","value":"I am not sure I could live with not finding out","weights":{"razor-sharp":1}}]},{"id":"inquiry-defence","type":"choice","prompt":"How do you react to being shown that you are wrong about something?","domain":"defence","options":[{"label":"I argue straight away","value":"I argue straight away","weights":{"razor-sharp":0}},{"label":"I usually push back","value":"I usually push back","weights":{"razor-sharp":0.25}},{"label":"I ask questions before I answer","value":"I ask questions before I answer","weights":{"razor-sharp":0.5}},{"label":"I stay curious past the discomfort","value":"I stay curious past the discomfort","weights":{"razor-sharp":0.75}},{"label":"I am genuinely glad to be shown wrong","value":"I am genuinely glad to be shown wrong","weights":{"razor-sharp":1}}]},{"id":"inquiry-unbidden","type":"choice","prompt":"Has understanding ever arrived without you working for it?","domain":"arrival","options":[{"label":"Never — everything I know, I looked up","value":"Never — everything I know, I looked up","weights":{"intellectual":1}},{"label":"Once or twice, and I dismissed it","value":"Once or twice, and I dismissed it","weights":{"discriminating":1}},{"label":"It happens, usually once I stop working on it","value":"It happens, usually once I stop working on it","weights":{"penetrating":1}},{"label":"It arrives and I recognise it immediately","value":"It arrives and I recognise it immediately","weights":{"razor-sharp":1}}]},{"id":"inquiry-answer","type":"choice","prompt":"How often does a question end in something you could actually act on?","domain":"reach","options":[{"label":"Almost never — I know more, and do not change","value":"Almost never — I know more, and do not change","weights":{"penetrating":0}},{"label":"Rarely","value":"Rarely","weights":{"penetrating":0.25}},{"label":"Sometimes","value":"Sometimes","weights":{"penetrating":0.5}},{"label":"Often","value":"Often","weights":{"penetrating":0.75}},{"label":"It cuts straight through and I act on it","value":"It cuts straight through and I act on it","weights":{"penetrating":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["intellectual","discriminating","penetrating","razor-sharp"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"intellectual","label":"Working in concepts","short":"Clear about the map, not yet the territory","description":"You think well in frameworks and gain real fluency in them. What is being described has not yet been separated from the description, which makes this a generous place to begin — the vocabulary is already there.","shadow":"Collecting explanations instead of meeting the thing.","color":"sky","masters":["jnana","neuroscience"],"calibration":{"dimensions":{"thought":0.35,"spirit":0.15},"practiceLevels":{"jnana":1,"neuroscience":1},"tags":["conceptual","fluent"]}},{"id":"discriminating","label":"Discriminating","short":"You can tell one thing from another","description":"The capacity to separate what is actually there from what has been added to it is already working. Most of what remains is not the absence of the ability but the places where it is not yet pointed at itself.","shadow":"Using precision on others rather than on the mind.","color":"teal","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"thought":0.3,"spirit":0.2,"emotion":0.1},"practiceLevels":{"jnana":2,"self-inquiry":1},"tags":["discerning","accurate"]}},{"id":"penetrating","label":"Penetrating","short":"Questions reach past the explanation","description":"You follow things further than most people do, and the mechanism underneath is genuinely available to you. The next edge is usually not another layer of understanding — it is asking the question of the one asking.","shadow":"Reading your own layers without ever arriving.","color":"violet","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.35,"emotion":0.1},"practiceLevels":{"jnana":2,"self-inquiry":2},"tags":["reaching","unfinished-by-nature"]}},{"id":"razor-sharp","label":"Razor edge","short":"The question cuts, and something answers","description":"Inquiry is close to automatic here: the belief is held loosely enough to be tested, the answer arrives without being summoned, and it usually makes a difference. The remaining risk is the confidence that comes with a blade this well-honed.","shadow":"Certainty sharpening into something harder to argue with.","color":"indigo","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.45,"thought":0.25},"practiceLevels":{"witnessing":2,"jnana":2},"tags":["sharp","unborrowed"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["jnana","self-inquiry"],"deepens_with":["meta-cognition","jnana-aptitude"]}'::jsonb, 1, true, false, 100, now())
