-- Jnana aptitude (4 Yogas)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('jnana-aptitude', 'Jnana aptitude', 'Your capacity to discriminate real from unreal', 'vedic', 'path', E'Jnāna is not knowing things. It is the capacity to tell the real from the plausible — and the tradition is blunt that this takes longer than any other path.\n\nWhat matters here is not how much you know. It is what happens when an idea you have held for years stops holding.', '📖', 6, 6, '[{"id":"jnana-abstraction","type":"choice","prompt":"Do you prefer things that are concrete or things that are abstract?","domain":"comfort","options":[{"label":"Only concrete things","value":"Only concrete things","weights":{"abstract":0}},{"label":"Concrete, with occasional abstract stretches","value":"Concrete, with occasional abstract stretches","weights":{"abstract":0}},{"label":"Either, depending on the subject","value":"Either, depending on the subject","weights":{"abstract":0}},{"label":"Abstract, comfortably","value":"Abstract, comfortably","weights":{"abstract":0}},{"label":"I live in the abstract by default","value":"I live in the abstract by default","weights":{"abstract":1}}]},{"id":"jnana-moment","type":"choice","prompt":"Has there ever been a moment you suddenly saw through something you had believed?","domain":"recognition","options":[{"label":"Never","value":"Never","weights":{"abstract":1,"analytical":0,"discriminating":0,"seeing":0}},{"label":"Once, a long time ago","value":"Once, a long time ago","weights":{"abstract":0.25,"analytical":0.75,"discriminating":0,"seeing":0}},{"label":"A few times","value":"A few times","weights":{"abstract":0,"analytical":0.5,"discriminating":0.5,"seeing":0}},{"label":"More than once, and recently","value":"More than once, and recently","weights":{"abstract":0,"analytical":0,"discriminating":0.75,"seeing":0.25}},{"label":"It happens regularly","value":"It happens regularly","weights":{"abstract":0,"analytical":0,"discriminating":0,"seeing":1}}]},{"id":"jnana-level","type":"choice","prompt":"When you understand something, do you go further than the explanation?","domain":"depth","options":[{"label":"At the explanation — that is enough","value":"At the explanation — that is enough","weights":{"analytical":1}},{"label":"A little past it, into the implications","value":"A little past it, into the implications","weights":{"analytical":1}},{"label":"Further, into how it fits other things","value":"Further, into how it fits other things","weights":{"analytical":1}},{"label":"All the way down to what it actually is","value":"All the way down to what it actually is","weights":{"analytical":1}},{"label":"I rarely go past the explanation","value":"I rarely go past the explanation","weights":{"analytical":1}}]},{"id":"jnana-defence","type":"choice","prompt":"What happens to your analysis when it turns on you?","domain":"resistance","options":[{"label":"I stop analysing immediately","value":"I stop analysing immediately","weights":{"discriminating":0}},{"label":"I notice and redirect","value":"I notice and redirect","weights":{"discriminating":0.25}},{"label":"I push through, mostly","value":"I push through, mostly","weights":{"discriminating":0.5}},{"label":"I go straight at it","value":"I go straight at it","weights":{"discriminating":0.75}},{"label":"I do not notice that it applies to me","value":"I do not notice that it applies to me","weights":{"discriminating":1}}]},{"id":"jnana-concept","type":"choice","prompt":"When someone gives you a beautiful idea, do you use it or collect it?","domain":"holding","options":[{"label":"I gather them","value":"I gather them","weights":{"discriminating":1}},{"label":"I gather quite a lot of them","value":"I gather quite a lot of them","weights":{"discriminating":1}},{"label":"Some pass through, some stay","value":"Some pass through, some stay","weights":{"discriminating":1}},{"label":"Most change how I see something","value":"Most change how I see something","weights":{"discriminating":1}},{"label":"They change me immediately and I cannot hold them lightly","value":"They change me immediately and I cannot hold them lightly","weights":{"discriminating":1}}]},{"id":"jnana-block","type":"choice","prompt":"What stops the analysis from going further?","domain":"obstruction","options":[{"label":"Lack of knowledge","value":"Lack of knowledge","weights":{"abstract":1,"analytical":0,"discriminating":0,"seeing":0}},{"label":"Lack of time or energy","value":"Lack of time or energy","weights":{"abstract":0.25,"analytical":0.75,"discriminating":0,"seeing":0}},{"label":"Fear of what I would find","value":"Fear of what I would find","weights":{"abstract":0,"analytical":0.5,"discriminating":0.5,"seeing":0}},{"label":"Attachment to the conclusion","value":"Attachment to the conclusion","weights":{"abstract":0,"analytical":0,"discriminating":0.75,"seeing":0.25}},{"label":"I have not hit a wall yet","value":"I have not hit a wall yet","weights":{"abstract":0,"analytical":0,"discriminating":0,"seeing":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["abstract","analytical","discriminating","seeing"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"abstract","label":"Abstract comfort","short":"You think in shapes rather than instances","description":"Your mind works naturally in the general. This makes pattern-spotting easy and precision hard — you will grasp the architecture of a situation before its particulars, and occasionally get burned by the particulars.","shadow":"Preferring the model to the thing it describes.","color":"sky","masters":["jnana","observation"],"calibration":{"dimensions":{"thought":0.3,"spirit":0.2},"practiceLevels":{"jnana":1,"observation":1},"tags":["jnana","abstract"]}},{"id":"analytical","label":"Analytical","short":"You go deep on the explanation","description":"You analyse well and thoroughly. What is harder is the step from understanding to recognising, because analysis can satisfy the appetite for clarity without ever asking what is actually true.","shadow":"Mistaking a complete explanation for a direct one.","color":"amber","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"thought":0.35,"spirit":0.15},"practiceLevels":{"jnana":1,"self-inquiry":1},"tags":["jnana","analytical"]}},{"id":"discriminating","label":"Discriminating","short":"You can tell what is real from what is borrowed","description":"You have real discrimination — the ability to sort the genuine from the plausible, the felt from the assumed. The next edge is that discrimination applied to your own conclusions, which is where most jnāna practitioners stall.","shadow":"Using the tool on others and not on the conclusions.","color":"teal","masters":["jnana","witnessing"],"calibration":{"dimensions":{"thought":0.3,"spirit":0.3},"practiceLevels":{"jnana":2,"witnessing":1},"tags":["jnana","discriminating"]}},{"id":"seeing","label":"Seeing","short":"The explanation has stopped being the point","description":"You are past the analysis and the analysis no longer feels necessary. What is left is direct recognition, and the practical difficulty is that it cannot be held in place for long once attention turns back to ordinary life.","shadow":"Preferring the seeing to what was being seen.","color":"indigo","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.45,"thought":0.2},"practiceLevels":{"jnana":2,"witnessing":1},"tags":["jnana","direct"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["jnana","self-inquiry"],"deepens_with":["inquiry-sharpness","non-dual-glimpses"]}'::jsonb, 1, true, false, 100, now())
