-- Jungian archetypes (Levels)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('jungian-archetypes', 'Jungian archetypes', 'Which one is running you', 'jungian', 'shadow', E'Jung proposed that character is assembled from a small number of recurring figures, and that each one arrives with a strength and a liability that are the same thing seen from two sides.\n\nThese five are placed in ascending order of how much shadow they carry — not from best to worst. The last one is not the highest; it is simply the one with the most authority to go to your head.', '🎭', 7, 7, '[{"id":"archetype-runner","type":"choice","prompt":"Which of these would the people who know you recognise most easily?","domain":"character","options":[{"label":"The one who wants things to turn out well","value":"The one who wants things to turn out well","weights":{"innocent":1}},{"label":"The one who looks after everyone and needs to be looked after back","value":"The one who looks after everyone and needs to be looked after back","weights":{"saint":1}},{"label":"The one who works things out and is not always right","value":"The one who works things out and is not always right","weights":{"sage":1}},{"label":"The one who says no, loudly","value":"The one who says no, loudly","weights":{"rebel":1}},{"label":"The one who takes charge","value":"The one who takes charge","weights":{"king":1}}]},{"id":"archetype-fuel","type":"choice","prompt":"What does your role need in order to keep going?","domain":"supply","options":[{"label":"Evidence that nothing is actually wrong","value":"Evidence that nothing is actually wrong","weights":{"innocent":1}},{"label":"Evidence that the people I care about are all right","value":"Evidence that the people I care about are all right","weights":{"saint":1}},{"label":"Evidence that I have understood it correctly","value":"Evidence that I have understood it correctly","weights":{"sage":1}},{"label":"Permission to be angry","value":"Permission to be angry","weights":{"rebel":1}},{"label":"Being respected","value":"Being respected","weights":{"king":1}}]},{"id":"archetype-crisis","type":"choice","prompt":"When something goes badly and you have no plan, what arrives first?","domain":"crisis","options":[{"label":"The conviction that it will probably sort itself out","value":"The conviction that it will probably sort itself out","weights":{"innocent":1}},{"label":"An immediate calculation of how it lands on everyone else","value":"An immediate calculation of how it lands on everyone else","weights":{"saint":1}},{"label":"A search for what I have misunderstood","value":"A search for what I have misunderstood","weights":{"sage":1}},{"label":"A strong wish to break something","value":"A strong wish to break something","weights":{"rebel":1}},{"label":"Taking charge before anyone has asked me to","value":"Taking charge before anyone has asked me to","weights":{"king":1}}]},{"id":"archetype-expectation","type":"choice","prompt":"How much do you still expect things to work out?","domain":"expectation","options":[{"label":"I stopped expecting that a long time ago","value":"I stopped expecting that a long time ago","weights":{"innocent":0}},{"label":"I expect it less than I used to","value":"I expect it less than I used to","weights":{"innocent":0.25}},{"label":"It depends entirely on the day","value":"It depends entirely on the day","weights":{"innocent":0.5}},{"label":"I genuinely expect most things to work out","value":"I genuinely expect most things to work out","weights":{"innocent":0.75}},{"label":"I am open either way, which is not the same as hoping","value":"I am open either way, which is not the same as hoping","weights":{"innocent":1}}]},{"id":"archetype-care","type":"choice","prompt":"How easily do you let yourself be looked after?","domain":"care","options":[{"label":"I do not, and I do not expect to","value":"I do not, and I do not expect to","weights":{"saint":0}},{"label":"Only from a very small number of people","value":"Only from a very small number of people","weights":{"saint":0.25}},{"label":"With some effort, and only when it is offered","value":"With some effort, and only when it is offered","weights":{"saint":0.5}},{"label":"Quite easily, once someone offers","value":"Quite easily, once someone offers","weights":{"saint":0.75}},{"label":"Completely, including from people who barely know me","value":"Completely, including from people who barely know me","weights":{"saint":1}}]},{"id":"archetype-understanding","type":"choice","prompt":"How easily do you accept a decision once you understand the reasoning behind it?","domain":"understanding","options":[{"label":"I still disagree once I understand why","value":"I still disagree once I understand why","weights":{"sage":0}},{"label":"I understand it and then argue anyway","value":"I understand it and then argue anyway","weights":{"sage":0.25}},{"label":"I accept it if the reasoning is sound","value":"I accept it if the reasoning is sound","weights":{"sage":0.5}},{"label":"I accept it, and usually find the reasoning was right","value":"I accept it, and usually find the reasoning was right","weights":{"sage":0.75}},{"label":"I accept it, and I am glad to have been shown","value":"I accept it, and I am glad to have been shown","weights":{"sage":1}}]},{"id":"archetype-authority","type":"choice","prompt":"How much of what goes well do you actually hand to somebody else?","domain":"authority","options":[{"label":"I take most of it, and I am comfortable doing so","value":"I take most of it, and I am comfortable doing so","weights":{"king":0}},{"label":"I take more than is mine","value":"I take more than is mine","weights":{"king":0.25}},{"label":"I hand over what is clearly other people’s","value":"I hand over what is clearly other people’s","weights":{"king":0.5}},{"label":"I hand over most of it without difficulty","value":"I hand over most of it without difficulty","weights":{"king":0.75}},{"label":"It goes to whoever was actually responsible, including people I could have claimed","value":"It goes to whoever was actually responsible, including people I could have claimed","weights":{"king":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["innocent","saint","sage","rebel","king"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"innocent","label":"The Innocent","short":"Kept open on purpose","description":"You run on the possibility that things can still turn out well, and you have not trained that out. Its shadow is small and specific: expectations that were never checked against anything, which can take a long time to correct.","shadow":"Optimism used in place of checking.","color":"amber","masters":["bhakti","observation"],"calibration":{"dimensions":{"spirit":0.25,"emotion":0.25,"thought":0.15},"practiceLevels":{"bhakti":1,"observation":1},"tags":["innocent","unclosed"]}},{"id":"saint","label":"The Saint","short":"Caring that runs on fuel","description":"You orient around other people’s wellbeing, genuinely, and the capacity is considerable. Its cost is that the arrangement has no off switch, and your own state tends to get last in the queue.","shadow":"Goodness that has started to be a strategy.","color":"rose","masters":["bhakti","emotional-healing"],"calibration":{"dimensions":{"connection":0.35,"emotion":0.25,"spirit":0.15},"practiceLevels":{"bhakti":1,"emotional-healing":1},"domainStress":{"caretaking":"emotional-healing"},"tags":["saint","care-giver"]}},{"id":"sage","label":"The Sage","short":"Understanding as authority","description":"You think in terms of how things fit together, and you are good at it. The shadow arrives when the understanding becomes a claim on other people’s thinking, which is generally not what you intend.","shadow":"Certainty that has quietly become a claim.","color":"sky","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"thought":0.4,"spirit":0.2,"connection":0.15},"practiceLevels":{"jnana":2,"self-inquiry":1},"tags":["sage","discerning"]}},{"id":"rebel","label":"The Rebel","short":"The no that is real","description":"You refuse things, and the refusal is often correct. The difficulty is that opposition is a stance rather than a decision, and it keeps standing when the thing being resisted has already changed.","shadow":"Reaction kept dressed as principle.","color":"orange","masters":["raja","kriya"],"calibration":{"dimensions":{"action":0.3,"emotion":0.3,"connection":0.15},"practiceLevels":{"raja":1,"kriya":1},"domainStress":{"conflict":"relationship"},"tags":["rebel","oppositional"]}},{"id":"king","label":"The King","short":"Authority, and what it costs","description":"You take charge, and usually correctly. This figure carries the most shadow of the five because authority is the hardest thing to hold without it hardening into control — and because being the one in charge is the most seductive seat there is.","shadow":"Stewardship that has quietly become rule.","color":"indigo","masters":["raja","witnessing"],"calibration":{"dimensions":{"action":0.35,"connection":0.25,"thought":0.2},"practiceLevels":{"raja":2,"witnessing":1},"domainStress":{"authority":"work-career"},"tags":["king","authority-bearing"]}}]'::jsonb, '{"loops_to_check":["persona","approval-seeking"],"practice_affinity":["witnessing","jnana"],"deepens_with":["shadow-inventory","inner-council","spiritual-bypass"]}'::jsonb, 1, true, false, 100, now())
