-- Karmic patterns (Loops)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('karmic-patterns', 'Karmic patterns', 'The shape of what repeats', 'vedic', 'shadow', E'The word karma here means sequence, not judgement. Whatever the metaphysics, the observable part is plain: certain situations recur, certain patterns recur, and both are legible in hindsight with a precision that is worth sitting with.\n\nThis is treated as a record rather than a verdict. Nothing in it assigns blame, and nothing in it predicts what happens next.', '♻️', 6, 7, '[{"id":"karma-shape","type":"choice","prompt":"How clearly can you see the shape of your own past?","domain":"trace","options":[{"label":"Not at all — it is a list of unrelated events","value":"Not at all — it is a list of unrelated events","weights":{"unnoticed":0}},{"label":"Occasionally something clicks into place","value":"Occasionally something clicks into place","weights":{"unnoticed":0.25}},{"label":"Broadly I can see the shape of it","value":"Broadly I can see the shape of it","weights":{"unnoticed":0.5}},{"label":"Clearly, and I could describe it to someone","value":"Clearly, and I could describe it to someone","weights":{"unnoticed":0.75}},{"label":"So clearly that I have had to work inside it deliberately","value":"So clearly that I have had to work inside it deliberately","weights":{"unnoticed":1}}]},{"id":"karma-frequency","type":"choice","prompt":"How often do similar situations find you?","domain":"frequency","options":[{"label":"Hardly ever","value":"Hardly ever","weights":{"repeated":0}},{"label":"Every few years, at most","value":"Every few years, at most","weights":{"repeated":0.25}},{"label":"Every year or two","value":"Every year or two","weights":{"repeated":0.5}},{"label":"Several times a year, in recognisable situations","value":"Several times a year, in recognisable situations","weights":{"repeated":0.75}},{"label":"Often enough that people around me have started to comment","value":"Often enough that people around me have started to comment","weights":{"repeated":1}}]},{"id":"karma-naming","type":"choice","prompt":"How many of those recurring situations can you put a name to?","domain":"naming","options":[{"label":"None of them","value":"None of them","weights":{"recognised":0}},{"label":"One, loosely","value":"One, loosely","weights":{"recognised":0.25}},{"label":"Two or three","value":"Two or three","weights":{"recognised":0.5}},{"label":"Most of them","value":"Most of them","weights":{"recognised":0.75}},{"label":"All of them, and in words other people recognise","value":"All of them, and in words other people recognise","weights":{"recognised":1}}]},{"id":"karma-reading","type":"choice","prompt":"How early do you notice a situation beginning to repeat itself?","domain":"reading","options":[{"label":"Not until it has finished","value":"Not until it has finished","weights":{"repeated":0}},{"label":"Near the end","value":"Near the end","weights":{"repeated":0.25}},{"label":"Somewhere in the middle","value":"Somewhere in the middle","weights":{"repeated":0.5}},{"label":"Early, if I am paying attention","value":"Early, if I am paying attention","weights":{"repeated":0.75}},{"label":"In the first conversation, usually from a phrase someone uses","value":"In the first conversation, usually from a phrase someone uses","weights":{"repeated":1}}]},{"id":"karma-interrupt","type":"choice","prompt":"In the moment a pattern is about to run, what actually stops it?","domain":"interruption","options":[{"label":"Nothing does","value":"Nothing does","weights":{"released":0}},{"label":"Very little, and usually too late","value":"Very little, and usually too late","weights":{"released":0.25}},{"label":"Sometimes, with effort","value":"Sometimes, with effort","weights":{"released":0.5}},{"label":"Most of the time","value":"Most of the time","weights":{"released":0.75}},{"label":"It holds, and something in me has clearly stopped running it","value":"It holds, and something in me has clearly stopped running it","weights":{"released":1}}]},{"id":"karma-cost","type":"choice","prompt":"How much of what you have learned from difficulty is actually available to you now?","domain":"toll","options":[{"label":"Very little — it mostly went on surviving it","value":"Very little — it mostly went on surviving it","weights":{"released":0}},{"label":"Some of it","value":"Some of it","weights":{"released":0.25}},{"label":"A fair amount, though I could not have told you when","value":"A fair amount, though I could not have told you when","weights":{"released":0.5}},{"label":"Most of it","value":"Most of it","weights":{"released":0.75}},{"label":"Nearly all of it, and I use it deliberately","value":"Nearly all of it, and I use it deliberately","weights":{"released":1}}]},{"id":"karma-account","type":"choice","prompt":"How do you account for the way things have gone?","domain":"accounting","options":[{"label":"I take the blame, or the credit, without looking further","value":"I take the blame, or the credit, without looking further","weights":{"unnoticed":1,"repeated":0,"recognised":0,"released":0}},{"label":"There is a shape to it that I can feel and cannot describe","value":"There is a shape to it that I can feel and cannot describe","weights":{"unnoticed":0.25,"repeated":0.75,"recognised":0,"released":0}},{"label":"I can see the pattern and I do not know what to do with it","value":"I can see the pattern and I do not know what to do with it","weights":{"unnoticed":0,"repeated":0.5,"recognised":0.5,"released":0}},{"label":"I can see it, and I have changed how I meet it","value":"I can see it, and I have changed how I meet it","weights":{"unnoticed":0,"repeated":0,"recognised":0.75,"released":0.25}},{"label":"I can see it, and it no longer needs a meaning to keep going","value":"I can see it, and it no longer needs a meaning to keep going","weights":{"unnoticed":0,"repeated":0,"recognised":0,"released":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["unnoticed","repeated","recognised","released"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"unnoticed","label":"Unnoticed","short":"It is there, and it has no shape yet","description":"Repetition is happening without being counted, which means nothing can currently be worked with. The only available move is the count itself, and it is duller and more useful than it sounds.","shadow":"Assuming that repetition without a pattern is just bad luck.","color":"slate","masters":["witnessing","observation"],"calibration":{"dimensions":{"thought":0.2,"emotion":0.2,"spirit":0.15},"practiceLevels":{"witnessing":1,"observation":1},"tags":["unnoticed","uncounted"]}},{"id":"repeated","label":"Repeated","short":"The count is getting uncomfortable","description":"You can see it recurring and not yet see what it is. This stage has the most friction in it, because the evidence is accumulating faster than the explanation is, and the explanation is what would make it bearable.","shadow":"Sensing the loop and blaming yourself for being inside it.","color":"amber","masters":["witnessing","loop-dissolution"],"calibration":{"dimensions":{"emotion":0.3,"thought":0.25,"connection":0.15},"practiceLevels":{"witnessing":1,"loop-dissolution":1},"tags":["repeated","accumulating"]}},{"id":"recognised","label":"Recognised","short":"It has a name and a shape","description":"The sequence can be described accurately enough that someone else would recognise it. That is the point at which a pattern becomes workable material rather than a mood, and the first moment it can be approached deliberately.","shadow":"The name becoming a place to stop.","color":"rose","masters":["jnana","loop-dissolution"],"calibration":{"dimensions":{"thought":0.3,"spirit":0.25,"emotion":0.15},"practiceLevels":{"jnana":1,"loop-dissolution":1},"tags":["recognised","named"]}},{"id":"released","label":"Released","short":"It runs, and it is not running you","description":"The pattern has been watched operating, understood, and observed no longer operating. Not suppressed and not defeated — simply no longer in charge, with the material itself left over and available.","shadow":"Freedom from the pattern taken as freedom from the past.","color":"indigo","masters":["jnana","loop-dissolution"],"calibration":{"dimensions":{"spirit":0.4,"thought":0.2,"emotion":0.15},"practiceLevels":{"jnana":2,"loop-dissolution":1},"tags":["released","no-longer-driving"]}}]'::jsonb, '{"loops_to_check":["repetition","inherited-pattern","reactivity"],"practice_affinity":["loop-dissolution","witnessing"],"deepens_with":["shadow-inventory","witchcraft-karma-memory"]}'::jsonb, 1, true, false, 100, now())
