) VALUES
    ('klesha-map', 'Kleśa map', 'The five afflictions', 'vedic', 'shadow', E'Patañjali lists five afflictions that are not faults but structures: avidyā, the not-knowing at the root; asmita, the I-making that turns everything into a performance; rāga, the pulling toward what is pleasant; dveṣa, the pushing away from what is not; and abhiniveśa, the clinging to life that is really clinging to the known.\n\nThis is an inventory, not a diagnosis. Nothing here assigns blame, and nothing here predicts what happens next. The useful version of this is a list you could actually read aloud.', '🕸️', 7, 6, '[{"id":"klesha-not-knowing","type":"choice","prompt":"How much of what you believe have you actually tested?","domain":"not knowing","options":[{"label":"Almost none of it — I hold it because it feels true","value":"Almost none of it — I hold it because it feels true","weights":{"avidya":1,"asmita":0,"raga":0,"dvesha":0,"abhinivesha":0}},{"label":"Some of it, in the areas I have questioned","value":"Some of it, in the areas I have questioned","weights":{"avidya":0,"asmita":1,"raga":0,"dvesha":0,"abhinivesha":0}},{"label":"Most of it, and I have revised a good deal","value":"Most of it, and I have revised a good deal","weights":{"avidya":0,"asmita":0,"raga":1,"dvesha":0,"abhinivesha":0}},{"label":"I question what I believe as a matter of course","value":"I question what I believe as a matter of course","weights":{"avidya":0,"asmita":0,"raga":0,"dvesha":1,"abhinivesha":0}},{"label":"I hold very little as certain, and I am comfortable there","value":"I hold very little as certain, and I am comfortable there","weights":{"avidya":0,"asmita":0,"raga":0,"dvesha":0,"abhinivesha":1}}]},{"id":"klesha-identity","type":"choice","prompt":"How much of what you do is about maintaining an image?","domain":"identity","options":[{"label":"Almost none — I am not performing","value":"Almost none — I am not performing","weights":{"asmita":0}},{"label":"Some of it, in situations that matter","value":"Some of it, in situations that matter","weights":{"asmita":0.25}},{"label":"A fair amount, and I notice afterwards","value":"A fair amount, and I notice afterwards","weights":{"asmita":0.5}},{"label":"Most of it, and I usually do not notice","value":"Most of it, and I usually do not notice","weights":{"asmita":0.75}},{"label":"All of it — I cannot stop performing even when I want to","value":"All of it — I cannot stop performing even when I want to","weights":{"asmita":1}}]},{"id":"klesha-clinging","type":"choice","prompt":"What do you reach for when you feel empty?","domain":"clinging","options":[{"label":"I reach for comfort — food, screens, company","value":"I reach for comfort — food, screens, company","weights":{"avidya":1,"asmita":0,"raga":0,"dvesha":0,"abhinivesha":0}},{"label":"I reach for something to occupy me","value":"I reach for something to occupy me","weights":{"avidya":0,"asmita":1,"raga":0,"dvesha":0,"abhinivesha":0}},{"label":"I reach for a practice or a routine","value":"I reach for a practice or a routine","weights":{"avidya":0,"asmita":0,"raga":1,"dvesha":0,"abhinivesha":0}},{"label":"I sit with the emptiness and watch it","value":"I sit with the emptiness and watch it","weights":{"avidya":0,"asmita":0,"raga":0,"dvesha":1,"abhinivesha":0}},{"label":"I do not reach — I let it arrive and leave","value":"I do not reach — I let it arrive and leave","weights":{"avidya":0,"asmita":0,"raga":0,"dvesha":0,"abhinivesha":1}}]},{"id":"klesha-aversion","type":"choice","prompt":"What do you push away when it gets uncomfortable?","domain":"aversion","options":[{"label":"I leave, and I do not go back","value":"I leave, and I do not go back","weights":{"avidya":1,"asmita":0,"raga":0,"dvesha":0,"abhinivesha":0}},{"label":"I think about it constantly, but I do not face it","value":"I think about it constantly, but I do not face it","weights":{"avidya":0,"asmita":1,"raga":0,"dvesha":0,"abhinivesha":0}},{"label":"I face it when I have to, but I avoid it otherwise","value":"I face it when I have to, but I avoid it otherwise","weights":{"avidya":0,"asmita":0,"raga":1,"dvesha":0,"abhinivesha":0}},{"label":"I face it, and I stay until it shifts","value":"I face it, and I stay until it shifts","weights":{"avidya":0,"asmita":0,"raga":0,"dvesha":1,"abhinivesha":0}},{"label":"I can be with it, and it does not control me","value":"I can be with it, and it does not control me","weights":{"avidya":0,"asmita":0,"raga":0,"dvesha":0,"abhinivesha":1}}]},{"id":"klesha-clinging-life","type":"choice","prompt":"How afraid are you of ending?","domain":"clinging to life","options":[{"label":"I do not think about it","value":"I do not think about it","weights":{"abhinivesha":0}},{"label":"It crosses my mind sometimes, and I push it away","value":"It crosses my mind sometimes, and I push it away","weights":{"abhinivesha":0.25}},{"label":"I think about it, and I am uneasy","value":"I think about it, and I am uneasy","weights":{"abhinivesha":0.5}},{"label":"I have looked at it, and it still costs me","value":"I have looked at it, and it still costs me","weights":{"abhinivesha":0.75}},{"label":"I am familiar with it, and it does not control me","value":"I am familiar with it, and it does not control me","weights":{"abhinivesha":1}}]},{"id":"klesha-pattern","type":"choice","prompt":"Which of these five do you recognise most clearly in yourself?","domain":"pattern","options":[{"label":"I do not know what is true, and I am sure of it","value":"I do not know what is true, and I am sure of it","weights":{"avidya":1}},{"label":"I am performing, and I cannot stop","value":"I am performing, and I cannot stop","weights":{"asmita":1}},{"label":"I want things, and I suffer when I cannot have them","value":"I want things, and I suffer when I cannot have them","weights":{"raga":1}},{"label":"I push things away, and I am tired of the pushing","value":"I push things away, and I am tired of the pushing","weights":{"dvesha":1}},{"label":"I cling to what I know, and I am afraid of what I do not","value":"I cling to what I know, and I am afraid of what I do not","weights":{"abhinivesha":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["avidya","asmita","raga","dvesha","abhinivesha"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"avidya","label":"Avidyā","short":"The not-knowing at the root","description":"Not-knowing is the root of everything else. It is not a lack of information; it is certainty that has never been tested, a structure of belief that runs life without being noticed. The work here is not to become clever but to become curious about what has never been questioned.","shadow":"Treating not-knowing as knowledge.","color":"slate","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"thought":0.4,"spirit":0.2,"emotion":0.15},"practiceLevels":{"jnana":2,"self-inquiry":1},"domainStress":{"knowing":"jnana"},"tags":["not-knowing","unquestioned"]}},{"id":"asmita","label":"Asmitā","short":"The I-making that runs everything","description":"I-making turns every event into a performance and every relationship into a transaction of regard. It is not vanity; it is the structure of identity, which is built from other people''s responses. The work is not to destroy the identity but to see it operating.","shadow":"The watcher becoming another performer.","color":"orange","masters":["witnessing","loop-dissolution"],"calibration":{"dimensions":{"connection":0.3,"thought":0.25,"emotion":0.2},"practiceLevels":{"witnessing":2,"loop-dissolution":1},"domainStress":{"identity":"witnessing"},"tags":["identity-making","performing"]}},{"id":"raga","label":"Rāga","short":"The pulling toward what is pleasant","description":"Pulling is not desire; it is the structure of wanting, which turns every pleasant thing into a necessity and every absence into a suffering. The work is not to stop wanting but to see the structure of the wanting, because the structure is where the suffering lives.","shadow":"Wanting becoming a way of not being present.","color":"rose","masters":["emotional-healing","witnessing"],"calibration":{"dimensions":{"emotion":0.4,"connection":0.2,"body":0.15},"practiceLevels":{"emotional-healing":1,"witnessing":1},"domainStress":{"wanting":"emotional-healing"},"tags":["wanting","clinging"]}},{"id":"dvesha","label":"Dveṣa","short":"The pushing away from what is not","description":"Pushing is the other half of pulling, and it is more expensive because it runs constantly. Every unpleasant thing is refused, every difficult person is avoided, every uncomfortable feeling is pushed down — and the energy of the pushing is larger than the energy of the thing being pushed.","shadow":"Pushing away what is actually needed.","color":"amber","masters":["loop-dissolution","witnessing"],"calibration":{"dimensions":{"emotion":0.35,"action":0.2,"body":0.15},"practiceLevels":{"loop-dissolution":2,"witnessing":1},"domainStress":{"aversion":"loop-dissolution"},"tags":["aversive","pushing"]}},{"id":"abhinivesha","label":"Abhiniveśa","short":"The clinging to the known","description":"Clinging is not fear of death; it is fear of the unknown, which is what makes every change feel like a threat. It runs underneath everything else, and it is the hardest to see because it feels like common sense. The work is not to become brave but to see how much of the resistance is actually this.","shadow":"Safety read as wisdom.","color":"teal","masters":["self-inquiry","jnana"],"calibration":{"dimensions":{"spirit":0.3,"thought":0.25,"emotion":0.2},"practiceLevels":{"self-inquiry":1,"jnana":1},"domainStress":{"clinging":"self-inquiry"},"tags":["clinging","fear-of-unknown"]}}]'::jsonb, '{"loops_to_check":["projection","self-criticism","reactivity"],"practice_affinity":["loop-dissolution","witnessing","self-inquiry"],"deepens_with":["shadow-inventory","vasana-map"]}'::jsonb, 1, true, false, 100, now())
