-- Legacy question (Launch)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('legacy-question', 'Legacy question', 'What remains when you are gone', 'vedic', 'action', E'The word legacy makes people reach for being remembered, which is one of two possible readings and usually the less interesting one.\n\nThe other reading is: what is still working after you stop being the one working on it.', '🕰️', 6, 6, '[{"id":"legacy-thought","type":"choice","prompt":"Have you ever thought about what would be left behind?","domain":"consideration","options":[{"label":"Never, and I avoid it","value":"Never, and I avoid it","weights":{"intended":1}},{"label":"Occasionally","value":"Occasionally","weights":{"intended":1}},{"label":"Sometimes, briefly","value":"Sometimes, briefly","weights":{"intended":1}},{"label":"I have thought about it properly","value":"I have thought about it properly","weights":{"intended":1}},{"label":"It runs in the background constantly","value":"It runs in the background constantly","weights":{"intended":1}}]},{"id":"legacy-frame","type":"choice","prompt":"Is this about being remembered, or about being useful?","domain":"framing","options":[{"label":"Being remembered","value":"Being remembered","weights":{"performative":1}},{"label":"Being useful to people after me","value":"Being useful to people after me","weights":{"performative":1}},{"label":"Both, and they are the same to me","value":"Both, and they are the same to me","weights":{"performative":1}},{"label":"Neither — I have not thought in those terms","value":"Neither — I have not thought in those terms","weights":{"performative":1}},{"label":"Something else entirely","value":"Something else entirely","weights":{"performative":1}}]},{"id":"legacy-building","type":"choice","prompt":"Is anything you are building going to work without you?","domain":"practice","options":[{"label":"Everything stops when I stop","value":"Everything stops when I stop","weights":{"unconsidered":1,"performative":0,"intended":0,"embodied":0}},{"label":"Almost everything","value":"Almost everything","weights":{"unconsidered":0.25,"performative":0.75,"intended":0,"embodied":0}},{"label":"Some of it, in time","value":"Some of it, in time","weights":{"unconsidered":0,"performative":0.5,"intended":0.5,"embodied":0}},{"label":"Most of it runs","value":"Most of it runs","weights":{"unconsidered":0,"performative":0,"intended":0.75,"embodied":0.25}},{"label":"I have built things specifically to outlast me","value":"I have built things specifically to outlast me","weights":{"unconsidered":0,"performative":0,"intended":0,"embodied":1}}]},{"id":"legacy-obligation","type":"choice","prompt":"Does the question carry guilt?","domain":"weight","options":[{"label":"It is not something I carry","value":"It is not something I carry","weights":{"unconsidered":1,"performative":0,"intended":0,"embodied":0}},{"label":"It sits there quietly","value":"It sits there quietly","weights":{"unconsidered":0.25,"performative":0.75,"intended":0,"embodied":0}},{"label":"It is a background pressure","value":"It is a background pressure","weights":{"unconsidered":0,"performative":0.5,"intended":0.5,"embodied":0}},{"label":"It has become a responsibility","value":"It has become a responsibility","weights":{"unconsidered":0,"performative":0,"intended":0.75,"embodied":0.25}},{"label":"It is the main thing driving me","value":"It is the main thing driving me","weights":{"unconsidered":0,"performative":0,"intended":0,"embodied":1}}]},{"id":"legacy-burden","type":"choice","prompt":"Would you be comfortable with someone else carrying this on?","domain":"handover","options":[{"label":"No — and I would not want them to","value":"No — and I would not want them to","weights":{"unconsidered":1,"performative":0,"intended":0,"embodied":0}},{"label":"No — I have not let anyone near it","value":"No — I have not let anyone near it","weights":{"unconsidered":0.25,"performative":0.75,"intended":0,"embodied":0}},{"label":"Possibly, to one person","value":"Possibly, to one person","weights":{"unconsidered":0,"performative":0.5,"intended":0.5,"embodied":0}},{"label":"Yes, and the thought relieves me","value":"Yes, and the thought relieves me","weights":{"unconsidered":0,"performative":0,"intended":0.75,"embodied":0.25}},{"label":"I have actively handed it on","value":"I have actively handed it on","weights":{"unconsidered":0,"performative":0,"intended":0,"embodied":1}}]},{"id":"legacy-scale","type":"choice","prompt":"How much of your effort goes toward things that will outlast you?","domain":"proportion","options":[{"label":"Almost none of it","value":"Almost none of it","weights":{"embodied":1}},{"label":"A small amount","value":"A small amount","weights":{"embodied":1}},{"label":"About a quarter","value":"About a quarter","weights":{"embodied":1}},{"label":"A substantial part","value":"A substantial part","weights":{"embodied":1}},{"label":"Most of it","value":"Most of it","weights":{"embodied":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["unconsidered","performative","intended","embodied"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"unconsidered","label":"Unconsidered","short":"The question has not been asked","description":"You have not seriously considered what remains, and you actively avoid the topic. This is the most common state and it carries no guilt — it is simply unexamined, and the avoidance is itself information about the relationship with mortality.","shadow":"Equating not having thought about it with not caring.","color":"slate","masters":["jnana","witnessing"],"calibration":{"dimensions":{"thought":0.2,"spirit":0.2},"practiceLevels":{"jnana":1,"witnessing":1},"tags":["legacy","unconsidered"]}},{"id":"performative","label":"Performative","short":"It is about being remembered","description":"The question is framed around visibility after death, and it is doing something for how you see yourself now. That is human and normal. It is also worth noticing how little of it is actually about anyone else.","shadow":"Legacy as reassurance about your own standing.","color":"violet","masters":["jnana","karma"],"calibration":{"dimensions":{"connection":0.25,"thought":0.2,"action":0.15},"practiceLevels":{"jnana":1,"karma":1},"tags":["legacy","memory"]}},{"id":"intended","label":"Intended","short":"You are building something on purpose","description":"There is a real intention behind what you leave, and you are making choices with the outlasting in mind. The useful next step is the harder one: letting go of it well enough that it can actually function.","shadow":"Building something you are not willing to hand on.","color":"teal","masters":["karma","work-career"],"calibration":{"dimensions":{"action":0.35,"connection":0.25,"spirit":0.2},"practiceLevels":{"karma":1,"work-career":1},"domainStress":{"work":"work-career"},"tags":["legacy","intentional"]}},{"id":"embodied","label":"Embodied","short":"It already runs without you","description":"What you are building works independently of you, and the thought of that is settling rather than heavy. This is the mature form of the question, and it usually arrives with a genuine engagement with your own mortality.","shadow":"Equating the work outlasting you with you outlasting.","color":"emerald","masters":["karma","witnessing"],"calibration":{"dimensions":{"spirit":0.35,"action":0.3,"connection":0.2},"practiceLevels":{"karma":2,"witnessing":1},"tags":["legacy","released"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["karma","jnana"],"deepens_with":["work-dharma","liberation-aim"]}'::jsonb, 1, true, false, 100, now())
