  updated_at
) VALUES
    ('liberation-aim', 'Liberation aim', 'Mokṣa — your orientation to freedom', 'vedic', 'spirit', E'Mokṣa means release. The tradition is precise that liberation is not a better life, a better body, or a better set of circumstances — it is release from the assumption that you are any of those things.\n\nWhich is exactly why the last question is what freedom means to you, specifically.', '🕉️', 6, 6, E'[{"id":"liberation-meaning","type":"choice","prompt":"When you hear \\"freedom\\", what do you picture?","domain":"definition","options":[{"label":"Not having to worry about money or obligations","value":"Not having to worry about money or obligations","weights":{"comfort":1,"improvement":0,"release-from-samsara":0,"moksha-as-inquiry":0}},{"label":"Being well and unimpeded","value":"Being well and unimpeded","weights":{"comfort":0.25,"improvement":0.75,"release-from-samsara":0,"moksha-as-inquiry":0}},{"label":"Free of this cycle of wanting and being disappointed","value":"Free of this cycle of wanting and being disappointed","weights":{"comfort":0,"improvement":0.5,"release-from-samsara":0.5,"moksha-as-inquiry":0}},{"label":"Free of the sense of being a separate self at all","value":"Free of the sense of being a separate self at all","weights":{"comfort":0,"improvement":0,"release-from-samsara":0.75,"moksha-as-inquiry":0.25}},{"label":"I do not have a picture, and I am not sure I want one","value":"I do not have a picture, and I am not sure I want one","weights":{"comfort":0,"improvement":0,"release-from-samsara":0,"moksha-as-inquiry":1}}]},{"id":"liberation-fear","type":"choice","prompt":"What would you have to give up to get it?","domain":"cost","options":[{"label":"Nothing — it is a gain","value":"Nothing — it is a gain","weights":{"release-from-samsara":1}},{"label":"Certain attachments","value":"Certain attachments","weights":{"release-from-samsara":1}},{"label":"Certain relationships","value":"Certain relationships","weights":{"release-from-samsara":1}},{"label":"The whole identity built around it","value":"The whole identity built around it","weights":{"release-from-samsara":1}},{"label":"I have not thought that far","value":"I have not thought that far","weights":{"release-from-samsara":1}}]},{"id":"liberation-escape","type":"choice","prompt":"Is this freedom from something, or freedom to do something?","domain":"distinction","options":[{"label":"Freedom from — getting out of something","value":"Freedom from — getting out of something","weights":{"release-from-samsara":1}},{"label":"Freedom to — being able to do or have something","value":"Freedom to — being able to do or have something","weights":{"release-from-samsara":1}},{"label":"Both, roughly equally","value":"Both, roughly equally","weights":{"release-from-samsara":1}},{"label":"Neither framing quite fits","value":"Neither framing quite fits","weights":{"release-from-samsara":1}},{"label":"I have never separated the two","value":"I have never separated the two","weights":{"release-from-samsara":1}}]},{"id":"liberation-life","type":"choice","prompt":"How much of your actual life is aimed at this?","domain":"priority","options":[{"label":"None of it","value":"None of it","weights":{"comfort":1,"improvement":0,"release-from-samsara":0,"moksha-as-inquiry":0}},{"label":"Occasionally, in principle","value":"Occasionally, in principle","weights":{"comfort":0.25,"improvement":0.75,"release-from-samsara":0,"moksha-as-inquiry":0}},{"label":"As a background intention","value":"As a background intention","weights":{"comfort":0,"improvement":0.5,"release-from-samsara":0.5,"moksha-as-inquiry":0}},{"label":"It shapes most of my decisions","value":"It shapes most of my decisions","weights":{"comfort":0,"improvement":0,"release-from-samsara":0.75,"moksha-as-inquiry":0.25}},{"label":"It is essentially the only thing I am doing","value":"It is essentially the only thing I am doing","weights":{"comfort":0,"improvement":0,"release-from-samsara":0,"moksha-as-inquiry":1}}]},{"id":"liberation-body","type":"choice","prompt":"What do you think you would be, without the body and history?","domain":"identity","options":[{"label":"Nothing — I would not be anything","value":"Nothing — I would not be anything","weights":{"moksha-as-inquiry":1}},{"label":"The same person, without the body","value":"The same person, without the body","weights":{"moksha-as-inquiry":1}},{"label":"Some kind of awareness, but not a person","value":"Some kind of awareness, but not a person","weights":{"moksha-as-inquiry":1}},{"label":"I cannot even pose it without flinching","value":"I cannot even pose it without flinching","weights":{"moksha-as-inquiry":1}},{"label":"I do not know, and I have stopped needing to","value":"I do not know, and I have stopped needing to","weights":{"moksha-as-inquiry":1}}]},{"id":"liberation-competing","type":"choice","prompt":"Do you actually want it, or do you want to be the kind of person who has it?","domain":"comparison","options":[{"label":"I want it","value":"I want it","weights":{"comfort":1,"improvement":0,"release-from-samsara":0,"moksha-as-inquiry":0}},{"label":"I want it, and I also want to be seen wanting it","value":"I want it, and I also want to be seen wanting it","weights":{"comfort":0.25,"improvement":0.75,"release-from-samsara":0,"moksha-as-inquiry":0}},{"label":"Honestly, the second is stronger","value":"Honestly, the second is stronger","weights":{"comfort":0,"improvement":0.5,"release-from-samsara":0.5,"moksha-as-inquiry":0}},{"label":"I do not know any more","value":"I do not know any more","weights":{"comfort":0,"improvement":0,"release-from-samsara":0.75,"moksha-as-inquiry":0.25}},{"label":"I am fairly sure the second has been running it","value":"I am fairly sure the second has been running it","weights":{"comfort":0,"improvement":0,"release-from-samsara":0,"moksha-as-inquiry":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["comfort","improvement","release-from-samsara","moksha-as-inquiry"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"comfort","label":"Comfort","short":"Freedom as the absence of difficulty","description":"Freedom here means life being easier. That is a real and legitimate aim and it is worth noticing that it is a different project from mokṣa, which is why relief practices help and liberation practices may not land.","shadow":"Reading relief as release.","color":"slate","masters":["body","breath"],"calibration":{"dimensions":{"body":0.3,"emotion":0.2,"spirit":0.1},"practiceLevels":{"body":1,"breath":1},"domainStress":{"health":"health"},"tags":["moksha","comfort"]}},{"id":"improvement","label":"Improvement","short":"Freedom as a better version of this","description":"You want a life that is better rather than a self that is released. The tradition treats this as an entirely natural stage and warns only against mistaking progress for arrival.","shadow":"Mistaking the better life for the freed one.","color":"amber","masters":["raja","karma"],"calibration":{"dimensions":{"action":0.3,"emotion":0.2,"thought":0.2},"practiceLevels":{"raja":1,"karma":1},"domainStress":{"work":"work-career"},"tags":["moksha","improvement"]}},{"id":"release-from-samsara","label":"Release","short":"Free of the wanting-and-being-disappointed cycle","description":"You have identified the actual loop, which is the wanting followed by the disappointment followed by the wanting. That identification is most of what any path asks for, and it is not a small thing.","shadow":"Confusing the end of wanting with the absence of everything.","color":"teal","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.35,"emotion":0.25,"thought":0.15},"practiceLevels":{"witnessing":1},"tags":["moksha","release"]}},{"id":"moksha-as-inquiry","label":"The inquiry itself","short":"Not a destination — the question, kept open","description":"The aim has stopped being a state to reach and become the question being held. The tradition treats this as the most honest available position, and as the one least likely to produce either satisfaction or despair.","shadow":"An inquiry that has become an identity of its own.","color":"emerald","masters":["jnana","witnessing"],"calibration":{"dimensions":{"spirit":0.45,"thought":0.25},"practiceLevels":{"jnana":2,"witnessing":1},"tags":["moksha","inquiry"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["jnana","witnessing"],"deepens_with":["non-dual-glimpses","vairagya"]}'::jsonb, 1, true, false, 100, now())
