    ('life-season', 'Life season', 'Where you are in the arc', 'vedic', 'stage', E'Traditions describe life less as a straight road than as a set of seasons, each with its own weather and its own work.\n\nThis is not about predicting how long a season lasts. It is about noticing which one you are standing in, so the practices that fit this season stop feeling like the wrong shape.', '🍂', 7, 8, '[{"id":"season-shape","type":"choice","prompt":"If your last few years were a season, which description fits best?","domain":"arc","options":[{"label":"Ending something and not yet knowing what comes next","value":"Ending something and not yet knowing what comes next","weights":{"threshold":1}},{"label":"Something new is starting to take shape","value":"Something new is starting to take shape","weights":{"emergence":1}},{"label":"Something I built is being asked to hold up under its own weight","value":"Something I built is being asked to hold up under its own weight","weights":{"consolidation":1}},{"label":"I have less and less interest in what I used to chase","value":"I have less and less interest in what I used to chase","weights":{"dissolution":1}}]},{"id":"season-effort","type":"choice","prompt":"How much of your energy goes into getting through the week, versus building something?","domain":"arc","options":[{"label":"Almost all of it goes on keeping things running","value":"Almost all of it goes on keeping things running","weights":{"emergence":1}},{"label":"Most of it goes on keeping things running","value":"Most of it goes on keeping things running","weights":{"emergence":1}},{"label":"It splits fairly evenly","value":"It splits fairly evenly","weights":{"emergence":1}},{"label":"More goes into building than maintaining","value":"More goes into building than maintaining","weights":{"emergence":1}},{"label":"Nearly all of it goes into something being built","value":"Nearly all of it goes into something being built","weights":{"emergence":1}}]},{"id":"season-obstacle","type":"choice","prompt":"What slows you down most right now — outside circumstances, or something in you?","domain":"arc","options":[{"label":"The conditions I did not choose","value":"The conditions I did not choose","weights":{"dissolution":1}},{"label":"The shape of my own attention","value":"The shape of my own attention","weights":{"dissolution":1}},{"label":"Both, about equally","value":"Both, about equally","weights":{"dissolution":1}},{"label":"Neither, honestly — it is moving","value":"Neither, honestly — it is moving","weights":{"dissolution":1}}]},{"id":"season-finished","type":"choice","prompt":"How much of what you set out to do have you actually finished?","domain":"arc","options":[{"label":"I stopped looking at it","value":"I stopped looking at it","weights":{"threshold":1,"emergence":0,"consolidation":0,"dissolution":0}},{"label":"Very little","value":"Very little","weights":{"threshold":0.25,"emergence":0.75,"consolidation":0,"dissolution":0}},{"label":"A third, maybe","value":"A third, maybe","weights":{"threshold":0,"emergence":0.5,"consolidation":0.5,"dissolution":0}},{"label":"Most of it","value":"Most of it","weights":{"threshold":0,"emergence":0,"consolidation":0.75,"dissolution":0.25}},{"label":"I am still carrying it","value":"I am still carrying it","weights":{"threshold":0,"emergence":0,"consolidation":0,"dissolution":1}}]},{"id":"season-urgency","type":"choice","prompt":"How urgent does it feel to sort your life out?","domain":"arc","options":[{"label":"It has been urgent for a long time","value":"It has been urgent for a long time","weights":{"threshold":1,"emergence":0,"consolidation":0,"dissolution":0}},{"label":"A lot","value":"A lot","weights":{"threshold":0.25,"emergence":0.75,"consolidation":0,"dissolution":0}},{"label":"A fair amount","value":"A fair amount","weights":{"threshold":0,"emergence":0.5,"consolidation":0.5,"dissolution":0}},{"label":"A little","value":"A little","weights":{"threshold":0,"emergence":0,"consolidation":0.75,"dissolution":0.25}},{"label":"No urgency at all","value":"No urgency at all","weights":{"threshold":0,"emergence":0,"consolidation":0,"dissolution":1}}]},{"id":"season-belonging","type":"choice","prompt":"Do you feel like you are where you are supposed to be right now?","domain":"arc","options":[{"label":"Very far from it","value":"Very far from it","weights":{"threshold":1,"emergence":0,"consolidation":0,"dissolution":0}},{"label":"Fairly far","value":"Fairly far","weights":{"threshold":0.25,"emergence":0.75,"consolidation":0,"dissolution":0}},{"label":"Not too far","value":"Not too far","weights":{"threshold":0,"emergence":0.5,"consolidation":0.5,"dissolution":0}},{"label":"Mostly I do","value":"Mostly I do","weights":{"threshold":0,"emergence":0,"consolidation":0.75,"dissolution":0.25}},{"label":"This is exactly it","value":"This is exactly it","weights":{"threshold":0,"emergence":0,"consolidation":0,"dissolution":1}}]},{"id":"season-first","type":"choice","prompt":"What would you say you are here to do?","domain":"arc","options":[{"label":"I genuinely do not know","value":"I genuinely do not know","weights":{"threshold":1,"emergence":0,"consolidation":0,"dissolution":0}},{"label":"Something vague","value":"Something vague","weights":{"threshold":0.25,"emergence":0.75,"consolidation":0,"dissolution":0}},{"label":"Something I have said before","value":"Something I have said before","weights":{"threshold":0,"emergence":0.5,"consolidation":0.5,"dissolution":0}},{"label":"Something I can state clearly","value":"Something I can state clearly","weights":{"threshold":0,"emergence":0,"consolidation":0.75,"dissolution":0.25}},{"label":"Something I would die having done","value":"Something I would die having done","weights":{"threshold":0,"emergence":0,"consolidation":0,"dissolution":1}}]},{"id":"season-timed","type":"choice","prompt":"Does anything in your life have a deadline you are not meeting?","domain":"arc","options":[{"label":"Yes, and it is close","value":"Yes, and it is close","weights":{"threshold":1}},{"label":"Yes, but there is room","value":"Yes, but there is room","weights":{"threshold":1}},{"label":"No real deadline","value":"No real deadline","weights":{"threshold":1}},{"label":"I am the one rushing it","value":"I am the one rushing it","weights":{"threshold":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["threshold","emergence","consolidation","dissolution"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"threshold","label":"Threshold","short":"Between one life and the next","description":"Something has ended and the next thing has not arrived. The ground feels uncertain, and part of you is waiting to be told what comes next. This is a demanding season to practise in, because the old methods belonged to the life that just closed.","shadow":"Waiting for permission to begin. Reading other people’s timing as your own.","color":"slate","masters":["self-inquiry","witnessing"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.2,"emotion":0.15},"practiceLevels":{"self-inquiry":1,"witnessing":1},"domainStress":{"direction":"self-inquiry"},"tags":["unsettled","in-transition"]}},{"id":"emergence","label":"Emergence","short":"Something is starting to take shape","description":"There is energy available and something in you is reaching. This is the season where practice compounds fastest, because effort lands on ground that is already prepared.","shadow":"Starting more than you finish.","color":"emerald","masters":["raja","karma"],"calibration":{"dimensions":{"action":0.3,"body":0.2,"thought":0.15},"practiceLevels":{"raja":1,"karma":1},"domainStress":{"work":"work-career"},"tags":["rising","building"]}},{"id":"consolidation","label":"Consolidation","short":"What you built is being tested","description":"There is something real in your life now, and it is asking to hold up under its own weight. Attention turns to maintenance, integrity, and the question of whether the structure matches the intention.","shadow":"Confusing the structure with the thing itself.","color":"amber","masters":["karma","jnana"],"calibration":{"dimensions":{"action":0.35,"connection":0.2,"emotion":0.15},"practiceLevels":{"karma":1,"jnana":1},"domainStress":{"work":"work-career","relation":"relationship"},"tags":["under-load","responsible"]}},{"id":"dissolution","label":"Dissolution","short":"Less pull from what you used to want","description":"The craving that used to organise your days has loosened. This is often mistaken for emptiness. It is more likely that something that ran your life has stopped running it, and you have not decided what to do with the free time.","shadow":"Mistaking peace for meaninglessness.","color":"indigo","masters":["jnana","witnessing"],"calibration":{"dimensions":{"spirit":0.35,"thought":0.2,"action":0.1},"practiceLevels":{"jnana":1,"witnessing":1},"tags":["disenchanted","opening"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["self-inquiry","witnessing"],"deepens_with":["ground-state","inner-compass"]}'::jsonb, 1, true, false, 100, now())
