-- Loop map (Welcome)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('loop-map', 'Loop map', 'The patterns that actually run you', 'vedic', 'shadow', E'A loop is a sequence that has been walked often enough to be easy — easy to enter, hard to see while you are in it. Most of what runs a life was never chosen; it was installed by repetition, one ordinary repetition at a time.\n\nThis does not ask you to name anything. It asks how much of your own pattern is legible to you right now, because that is the variable that decides what can be worked with and what cannot yet be reached.', '🔁', 6, 6, '[{"id":"loop-notice","type":"choice","prompt":"While you are in it, how clearly do you see what you are doing?","domain":"in the moment","options":[{"label":"I do not notice it until it has finished","value":"I do not notice it until it has finished","weights":{"none":1,"hinted":0,"named":0,"mapped":0}},{"label":"I notice something is happening but not what","value":"I notice something is happening but not what","weights":{"none":0,"hinted":1,"named":0,"mapped":0}},{"label":"I can name what is happening as it happens","value":"I can name what is happening as it happens","weights":{"none":0,"hinted":0,"named":1,"mapped":0}},{"label":"I can see the whole sequence while I am in it","value":"I can see the whole sequence while I am in it","weights":{"none":0,"hinted":0,"named":0,"mapped":1}}]},{"id":"loop-words","type":"choice","prompt":"If someone asked you what your worst habit is, what could you say?","domain":"language","options":[{"label":"I would not know where to start","value":"I would not know where to start","weights":{"named":0}},{"label":"Something vague, if pressed","value":"Something vague, if pressed","weights":{"named":0.25}},{"label":"I could name it roughly","value":"I could name it roughly","weights":{"named":0.5}},{"label":"I can describe it accurately","value":"I can describe it accurately","weights":{"named":0.75}},{"label":"I can say it in a single sentence, and someone would recognise it","value":"I can say it in a single sentence, and someone would recognise it","weights":{"named":1}}]},{"id":"loop-start","type":"choice","prompt":"Can you tell where a pattern begins, or only how it ends?","domain":"onset","options":[{"label":"I only ever see it afterwards","value":"I only ever see it afterwards","weights":{"none":1,"hinted":0,"named":0,"mapped":0}},{"label":"I can tell it has started, but not what it is","value":"I can tell it has started, but not what it is","weights":{"none":0.25,"hinted":0.75,"named":0,"mapped":0}},{"label":"I can see it starting and know roughly what follows","value":"I can see it starting and know roughly what follows","weights":{"none":0,"hinted":0.5,"named":0.5,"mapped":0}},{"label":"I can see the start and most of what comes after","value":"I can see the start and most of what comes after","weights":{"none":0,"hinted":0,"named":0.75,"mapped":0.25}},{"label":"I can see the start, the turn, and the place where it stops being able to stop","value":"I can see the start, the turn, and the place where it stops being able to stop","weights":{"none":0,"hinted":0,"named":0,"mapped":1}}]},{"id":"loop-others","type":"choice","prompt":"Do you recognise the same pattern in people around you?","domain":"in others","options":[{"label":"Not at all — that only happens to me","value":"Not at all — that only happens to me","weights":{"none":1,"hinted":0,"named":0,"mapped":0}},{"label":"Occasionally, once it is under way","value":"Occasionally, once it is under way","weights":{"none":0,"hinted":1,"named":0,"mapped":0}},{"label":"I recognise it early, most times","value":"I recognise it early, most times","weights":{"none":0,"hinted":0,"named":1,"mapped":0}},{"label":"I see it in people I have only just met","value":"I see it in people I have only just met","weights":{"none":0,"hinted":0,"named":0,"mapped":1}}]},{"id":"loop-interrupt","type":"choice","prompt":"When a pattern is running, what can actually interrupt it?","domain":"interruption","options":[{"label":"Nothing does, and I have stopped expecting anything to","value":"Nothing does, and I have stopped expecting anything to","weights":{"none":1,"hinted":0,"named":0,"mapped":0}},{"label":"Things mostly carry me past it","value":"Things mostly carry me past it","weights":{"none":0,"hinted":1,"named":0,"mapped":0}},{"label":"I can find something that works if I get there first","value":"I can find something that works if I get there first","weights":{"none":0,"hinted":0,"named":1,"mapped":0}},{"label":"I can see the exact moment it turns, and I am usually there in time","value":"I can see the exact moment it turns, and I am usually there in time","weights":{"none":0,"hinted":0,"named":0,"mapped":1}}]},{"id":"loop-say","type":"choice","prompt":"Would you say it out loud, if it came up?","domain":"out loud","options":[{"label":"I would rather it stayed unsaid","value":"I would rather it stayed unsaid","weights":{"none":1,"hinted":0,"named":0,"mapped":0}},{"label":"I would only say it to one person, carefully","value":"I would only say it to one person, carefully","weights":{"none":0,"hinted":1,"named":0,"mapped":0}},{"label":"I would say it if it came up naturally","value":"I would say it if it came up naturally","weights":{"none":0,"hinted":0,"named":1,"mapped":0}},{"label":"I can say it plainly to almost anyone","value":"I can say it plainly to almost anyone","weights":{"none":0,"hinted":0,"named":0,"mapped":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["none","hinted","named","mapped"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"none","label":"Unmapped","short":"It runs, and it is not visible","description":"Nothing is being read as a pattern yet. What happens arrives as mood, as a difficult month, as a difficulty with one particular person, and it is answered with whatever the moment offers. This is not a position arrived at by choice — a sequence that has never been seen cannot be reported on, so there is nothing here to report.","shadow":"Reading the absence of a map as the absence of a pattern.","color":"slate","masters":["observation","loop-dissolution"],"calibration":{"dimensions":{"thought":0.25,"emotion":0.2,"spirit":0.1},"practiceLevels":{"observation":1,"loop-dissolution":1},"tags":["unmapped","unstructured"]}},{"id":"hinted","label":"Felt, not named","short":"There is a shape, and no word for it","description":"Something is recognisable but not yet referable. The pattern shows up as a texture — the same kind of week, the same kind of person, the same feeling on the way out of something — and it returns without being accounted for. Recognition without a name is where most of the cost sits, because there is nothing to work on yet.","shadow":"Naming it early, and stopping there.","color":"orange","masters":["witnessing","loop-dissolution"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.25,"body":0.15},"practiceLevels":{"witnessing":1,"loop-dissolution":1},"domainStress":{"pattern":"observation"},"tags":["hinted","unreferenced"]}},{"id":"named","label":"Named","short":"It can be said in a sentence","description":"The pattern can be referred to precisely enough to be discussed: where it starts, what it wants, what it costs by the end of it. This is the point at which it stops being a mood and becomes material — the first moment it can be worked with rather than only endured.","shadow":"The name becoming a place to live.","color":"amber","masters":["loop-dissolution","self-inquiry"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.25,"action":0.15},"practiceLevels":{"loop-dissolution":2,"self-inquiry":1},"tags":["named","articulated"]}},{"id":"mapped","label":"Mapped","short":"You can see it from the outside","description":"The pattern is legible enough to be watched while it runs — the onset, the turn, the point where it becomes its own momentum, and the fact that it is recognisable in other people too. From here it is less a thing that happens to you than a sequence with a known shape and known handovers.","shadow":"Mapping the pattern and leaving the map there.","color":"emerald","masters":["self-inquiry","loop-dissolution"],"calibration":{"dimensions":{"spirit":0.35,"thought":0.2,"action":0.15},"practiceLevels":{"loop-dissolution":2,"witnessing":1},"domainStress":{"pattern":"loop-dissolution"},"tags":["mapped","sequenced"]}}]'::jsonb, '{"loops_to_check":["reactivity","avoidance","approval-seeking"],"practice_affinity":["loop-dissolution","witnessing"],"deepens_with":["reactivity-score","inherited-loops"]}'::jsonb, 1, true, false, 100, now())
