  updated_at
) VALUES
    ('love-language', 'Love language', 'How you give and receive love', 'yogic', 'connection', E'Most friction inside a close relationship is two people offering different things, each one quite certain the other is offering nothing at all.\n\nThis asks which of the five forms come most easily to you, which are hardest to take, what is actually being handed to you, and whether love is being offered at all. It is a map of wiring, not a scorecard to be graded on.', '❤️', 6, 8, '[{"id":"love-give","type":"choice","prompt":"Of the five ways people show love, which comes most easily to you?","domain":"giving","options":[{"label":"Being told it matters","value":"Being told it matters","weights":{"words":1}},{"label":"Physical closeness","value":"Physical closeness","weights":{"touch":1}},{"label":"Undistracted time","value":"Undistracted time","weights":{"time":1}},{"label":"Doing something practical for them","value":"Doing something practical for them","weights":{"acts":1}},{"label":"Being understood","value":"Being understood","weights":{"understanding":1}}]},{"id":"love-receive","type":"choice","prompt":"Which of the five is hardest for you to take?","domain":"receiving","options":[{"label":"Physical closeness","value":"Physical closeness","weights":{"touch":1}},{"label":"Being told it matters","value":"Being told it matters","weights":{"words":1}},{"label":"Doing something practical for them","value":"Doing something practical for them","weights":{"acts":1}},{"label":"Being understood","value":"Being understood","weights":{"understanding":1}},{"label":"Undistracted time","value":"Undistracted time","weights":{"time":1}}]},{"id":"love-asked","type":"choice","prompt":"When someone close to you loves you, what are they mostly giving?","domain":"offering","options":[{"label":"Mostly reassurance and words","value":"Mostly reassurance and words","weights":{"words":1}},{"label":"Mostly closeness and touch","value":"Mostly closeness and touch","weights":{"touch":1}},{"label":"Mostly time and presence","value":"Mostly time and presence","weights":{"time":1}},{"label":"Mostly practical things being done","value":"Mostly practical things being done","weights":{"acts":1}},{"label":"Mostly being taken seriously","value":"Mostly being taken seriously","weights":{"understanding":1}}]},{"id":"love-variable","type":"choice","prompt":"Does the way you show love change from one relationship to another?","domain":"variation","options":[{"label":"One fixed way, with everyone","value":"One fixed way, with everyone","weights":{"understanding":1}},{"label":"It changes a little with closeness","value":"It changes a little with closeness","weights":{"understanding":1}},{"label":"It changes with what the other person needs","value":"It changes with what the other person needs","weights":{"understanding":1}},{"label":"It changes a lot, relationship to relationship","value":"It changes a lot, relationship to relationship","weights":{"understanding":1}},{"label":"I have no consistent way of showing it at all","value":"I have no consistent way of showing it at all","weights":{"understanding":1}}]},{"id":"love-offered","type":"choice","prompt":"Is love actually being offered to you, at the rate you need?","domain":"supply","options":[{"label":"Rarely, from anyone","value":"Rarely, from anyone","weights":{"words":1,"touch":0,"time":0,"acts":0,"understanding":0}},{"label":"Occasionally","value":"Occasionally","weights":{"words":0,"touch":1,"time":0,"acts":0,"understanding":0}},{"label":"Sometimes","value":"Sometimes","weights":{"words":0,"touch":0,"time":1,"acts":0,"understanding":0}},{"label":"Usually","value":"Usually","weights":{"words":0,"touch":0,"time":0,"acts":1,"understanding":0}},{"label":"It is there most of the time","value":"It is there most of the time","weights":{"words":0,"touch":0,"time":0,"acts":0,"understanding":1}}]},{"id":"love-land","type":"choice","prompt":"When love is offered to you, do you let it in?","domain":"reception","options":[{"label":"I deflect it","value":"I deflect it","weights":{"understanding":1}},{"label":"I take it politely and move on","value":"I take it politely and move on","weights":{"understanding":1}},{"label":"I take it and stay at arm’s length","value":"I take it and stay at arm’s length","weights":{"understanding":1}},{"label":"I let it land","value":"I let it land","weights":{"understanding":1}},{"label":"I let it land, and I ask for more","value":"I let it land, and I ask for more","weights":{"understanding":1}}]},{"id":"love-ask","type":"choice","prompt":"Have you ever plainly asked someone for what you need?","domain":"asking","options":[{"label":"Never","value":"Never","weights":{"understanding":1}},{"label":"Once or twice","value":"Once or twice","weights":{"understanding":1}},{"label":"With a great deal of difficulty","value":"With a great deal of difficulty","weights":{"understanding":1}},{"label":"Rarely, but I can","value":"Rarely, but I can","weights":{"understanding":1}},{"label":"Regularly, and easily","value":"Regularly, and easily","weights":{"understanding":1}}]},{"id":"love-beyond","type":"choice","prompt":"Does the way you love reach beyond romantic relationships?","domain":"scope","options":[{"label":"It is tied to romantic love","value":"It is tied to romantic love","weights":{"words":1,"touch":0,"time":0,"acts":0,"understanding":0}},{"label":"Mostly that","value":"Mostly that","weights":{"words":0,"touch":1,"time":0,"acts":0,"understanding":0}},{"label":"Family too, with some effort","value":"Family too, with some effort","weights":{"words":0,"touch":0,"time":1,"acts":0,"understanding":0}},{"label":"Close friends as well as family","value":"Close friends as well as family","weights":{"words":0,"touch":0,"time":0,"acts":1,"understanding":0}},{"label":"Almost everyone I am close to","value":"Almost everyone I am close to","weights":{"words":0,"touch":0,"time":0,"acts":0,"understanding":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["words","touch","time","acts","understanding"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"words","label":"Words","short":"It is said, and it has to be said","description":"Language is the channel that carries everything else. Naming is easy here, and being unnamed is hard — a silence in this wiring is not neutral, it registers as absence. The work is usually asking for the sentence out loud rather than waiting to be given it.","shadow":"Saying the thing instead of letting it be felt.","color":"rose","masters":["bhakti","relationship"],"calibration":{"dimensions":{"connection":0.3,"emotion":0.25,"thought":0.15},"practiceLevels":{"relationship":1,"bhakti":1},"domainStress":{"relation":"relationship"},"tags":["love-words","needs-naming"]}},{"id":"touch","label":"Touch","short":"Contact is the language","description":"Presence is registered through the body rather than through what is said about it. This is the channel that cannot be faked convincingly, and its absence is felt before it is noticed. The work is usually in saying that something is missing, out loud.","shadow":"Touch used in place of being known.","color":"orange","masters":["bhakti","body"],"calibration":{"dimensions":{"connection":0.3,"body":0.3,"emotion":0.2},"practiceLevels":{"bhakti":1,"body":1},"domainStress":{"relation":"relationship"},"tags":["love-touch","somatic-bond"]}},{"id":"time","label":"Time","short":"Attention is the thing being given","description":"What registers as love is undivided presence, and it is a genuinely scarce resource rather than a polite gesture. The signal is not the quantity of hours but whether the hours were actually yours. Notice that this is the channel most often supplied in quantity and refused in substance.","shadow":"Quantity of time offered in place of quality of attention.","color":"teal","masters":["bhakti","witnessing"],"calibration":{"dimensions":{"connection":0.3,"spirit":0.2,"emotion":0.2},"practiceLevels":{"bhakti":1,"witnessing":1},"domainStress":{"relation":"relationship"},"tags":["love-time","attention-led"]}},{"id":"acts","label":"Acts","short":"It is done, not said","description":"Care arrives as something completed rather than something discussed. This is reliable and it is hard to read from the outside, because the person receiving it is busy and the person giving it is not looking for thanks. The work is in making it visible.","shadow":"Doing the work instead of saying what it is for.","color":"amber","masters":["karma","relationship"],"calibration":{"dimensions":{"action":0.3,"connection":0.25,"body":0.15},"practiceLevels":{"karma":1,"relationship":1},"domainStress":{"relation":"relationship"},"tags":["love-acts","service-led"]}},{"id":"understanding","label":"Understanding","short":"It has to be understood before it counts","description":"Being known is the requirement, and partial knowledge does not register as care. This is the most demanding of the five to give and the easiest to withhold by accident, because people are usually doing both at once without noticing the half that is missing.","shadow":"Being right about them instead of with them.","color":"violet","masters":["jnana","relationship"],"calibration":{"dimensions":{"connection":0.25,"thought":0.25,"emotion":0.2},"practiceLevels":{"relationship":1,"jnana":1},"domainStress":{"relation":"relationship"},"tags":["love-understanding","known-first"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["relationship","bhakti"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
