-- Meditation depth (12 Skills)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('meditation-depth', 'Meditation depth', 'How far Raja takes you', 'yogic', 'witness', E'Depth is not duration. Twenty minutes where the body disappears and the sense of time goes is deeper than an hour of holding a thought in place.\n\nThis looks at what actually happens when you sit — where the attention rests, what the body does, what is at the bottom, and how the session ends.', '👑', 8, 8, '[{"id":"meditation-resting","type":"choice","prompt":"Where does your attention actually rest when you meditate?","domain":"posture","options":[{"label":"Mostly on the breath, and only reluctantly","value":"Mostly on the breath, and only reluctantly","weights":{"resting":1}},{"label":"On the breath, without much argument","value":"On the breath, without much argument","weights":{"settled":1}},{"label":"On whatever the practice was actually set on","value":"On whatever the practice was actually set on","weights":{"absorbed":1}},{"label":"I cannot locate where it rests at all","value":"I cannot locate where it rests at all","weights":{"merged":1}}]},{"id":"meditation-body","type":"choice","prompt":"During a good sit, does your body disappear?","domain":"body","options":[{"label":"I am more aware of my body than ever","value":"I am more aware of my body than ever","weights":{"merged":0}},{"label":"I notice it more than usual","value":"I notice it more than usual","weights":{"merged":0.25}},{"label":"It is there, but quiet","value":"It is there, but quiet","weights":{"merged":0.5}},{"label":"Only sometimes does it drop away","value":"Only sometimes does it drop away","weights":{"merged":0.75}},{"label":"It is usually not there at all","value":"It is usually not there at all","weights":{"merged":1}}]},{"id":"meditation-thoughts","type":"choice","prompt":"What happens to your thoughts while you sit?","domain":"thoughts","options":[{"label":"They are ignored, loudly, for the whole sitting","value":"They are ignored, loudly, for the whole sitting","weights":{"resting":1}},{"label":"They thin out and come back","value":"They thin out and come back","weights":{"settled":1}},{"label":"They come and go and the attention does not follow","value":"They come and go and the attention does not follow","weights":{"absorbed":1}},{"label":"They stop","value":"They stop","weights":{"merged":1}}]},{"id":"meditation-deepest","type":"choice","prompt":"How deep does your sitting actually get?","domain":"depth","options":[{"label":"I get restless and stop","value":"I get restless and stop","weights":{"resting":0,"settled":0,"absorbed":0,"merged":0}},{"label":"I settle, but stay aware of myself settling","value":"I settle, but stay aware of myself settling","weights":{"resting":1,"settled":0,"absorbed":0,"merged":0}},{"label":"I lose the sense of time","value":"I lose the sense of time","weights":{"resting":0,"settled":1,"absorbed":0,"merged":0}},{"label":"The observer and the observed get hard to tell apart","value":"The observer and the observed get hard to tell apart","weights":{"resting":0,"settled":0,"absorbed":1,"merged":0}},{"label":"There is nothing left to tell them apart","value":"There is nothing left to tell them apart","weights":{"resting":0,"settled":0,"absorbed":0,"merged":1}}]},{"id":"meditation-bottom","type":"choice","prompt":"When you go as deep as you can reach, what is there?","domain":"depth","options":[{"label":"Not much, honestly","value":"Not much, honestly","weights":{"merged":0}},{"label":"A kind of quiet","value":"A kind of quiet","weights":{"merged":0.25}},{"label":"Something I cannot put into words","value":"Something I cannot put into words","weights":{"merged":0.5}},{"label":"Something obviously alive and aware","value":"Something obviously alive and aware","weights":{"merged":0.75}},{"label":"Something clearly aware, and not me","value":"Something clearly aware, and not me","weights":{"merged":1}}]},{"id":"meditation-ending","type":"choice","prompt":"How does a sitting usually end?","domain":"exit","options":[{"label":"I get up as soon as it gets difficult","value":"I get up as soon as it gets difficult","weights":{"resting":1}},{"label":"I come back slowly and start the day","value":"I come back slowly and start the day","weights":{"settled":1}},{"label":"I sit until something moves me","value":"I sit until something moves me","weights":{"absorbed":1}},{"label":"I do not really come back","value":"I do not really come back","weights":{"merged":1}}]},{"id":"meditation-change","type":"choice","prompt":"Has the depth of your sitting changed over the past year?","domain":"trajectory","options":[{"label":"It has not changed","value":"It has not changed","weights":{"absorbed":0}},{"label":"Very slightly","value":"Very slightly","weights":{"absorbed":0.25}},{"label":"Somewhat","value":"Somewhat","weights":{"absorbed":0.5}},{"label":"Noticeably","value":"Noticeably","weights":{"absorbed":0.75}},{"label":"It has changed completely","value":"It has changed completely","weights":{"absorbed":1}}]},{"id":"meditation-effort","type":"choice","prompt":"How much of your sitting is effort?","domain":"effort","options":[{"label":"I force it every single time","value":"I force it every single time","weights":{"resting":0,"settled":0,"absorbed":0,"merged":0}},{"label":"I hold myself to it","value":"I hold myself to it","weights":{"resting":1,"settled":0,"absorbed":0,"merged":0}},{"label":"It takes some settling in","value":"It takes some settling in","weights":{"resting":0,"settled":1,"absorbed":0,"merged":0}},{"label":"It comes fairly naturally now","value":"It comes fairly naturally now","weights":{"resting":0,"settled":0,"absorbed":1,"merged":0}},{"label":"I do not have to start it","value":"I do not have to start it","weights":{"resting":0,"settled":0,"absorbed":0,"merged":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["resting","settled","absorbed","merged"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"resting","label":"Resting","short":"Attention sits on the breath","description":"Sitting means going somewhere rather than being somewhere, and the breath is the place you keep returning to. This is the base of the practice, not a preliminary to it — everything else in Raja is built on being able to stay here.","shadow":"Mistaking the position of the attention for the attention itself.","color":"sky","masters":["breath","raja"],"calibration":{"dimensions":{"body":0.25,"thought":0.2,"spirit":0.15},"practiceLevels":{"breath":1,"raja":1},"domainStress":{"attention":"observation"},"tags":["on-the-breath","effortful"]}},{"id":"settled","label":"Settled","short":"The mind stops arguing","description":"The noise drops and the attention stops being managed. Most of what remains is not the depth but the body, which tends to hold the last of the tension — and which is usually what stops the session going further.","shadow":"Comfortable enough to sit, not yet settled enough to be still.","color":"teal","masters":["raja","body"],"calibration":{"dimensions":{"body":0.2,"spirit":0.3,"thought":0.15},"practiceLevels":{"raja":1,"body":1},"tags":["settled","tension-held"]}},{"id":"absorbed","label":"Absorbed","short":"The chosen object holds you","description":"The object of meditation carries the attention by itself, which is a genuine stage rather than a trick. What often comes next is not more effort but less attachment to what the absorption is for.","shadow":"Confusing the depth with what you are getting from it.","color":"violet","masters":["raja","witnessing"],"calibration":{"dimensions":{"spirit":0.35,"body":0.2,"emotion":0.1},"practiceLevels":{"raja":2,"witnessing":2},"tags":["absorbed","flowing"]}},{"id":"merged","label":"Merged","short":"The distinction thins","description":"The boundary between the one observing and what is observed becomes difficult to locate. It is worth holding with care: a state this complete can be a real opening, and it can also be a place where practice stops being done and starts being lived in.","shadow":"Staying in a state that cannot be carried into the day.","color":"indigo","masters":["witnessing","raja"],"calibration":{"dimensions":{"spirit":0.45,"body":0.15,"connection":0.1},"practiceLevels":{"witnessing":2,"raja":2},"domainStress":{"contact":"relationship"},"tags":["merged","boundary-thin"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["raja","witnessing"],"deepens_with":["dhyana","samadhi"]}'::jsonb, 1, true, false, 100, now())
