-- Meta-cognition (Observation)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('meta-cognition', 'Meta-cognition', 'Your ability to think about thinking', 'vedic', 'thought', E'Most thinking happens without anyone present for it. The thought arrives, runs, and finishes, and the whole event goes unrecorded.\n\nMeta-cognition is the second attention — the one that notices the first. It is not intelligence and it is not insight; it is simply the capacity to see a thought as a thought rather than as what is happening. What this measures is how often that second attention is switched on.', '🪞', 7, 8, '[{"id":"meta-thinking","type":"choice","prompt":"Do you ever notice that you are thinking, rather than just thinking?","domain":"noticing","options":[{"label":"Hardly ever — thinking is just what is happening","value":"Hardly ever — thinking is just what is happening","weights":{"unreflective":1}},{"label":"Occasionally, and I usually miss it at first","value":"Occasionally, and I usually miss it at first","weights":{"occasional":1}},{"label":"Often enough to catch myself in the act","value":"Often enough to catch myself in the act","weights":{"active":1}},{"label":"It is almost continuous background awareness","value":"It is almost continuous background awareness","weights":{"constant":1}}]},{"id":"meta-catch","type":"choice","prompt":"When you notice you have drifted off, how far in have you already gone?","domain":"timing","options":[{"label":"I find out hours later","value":"I find out hours later","weights":{"unreflective":1}},{"label":"I find out well into it","value":"I find out well into it","weights":{"unreflective":0.75,"occasional":0.25}},{"label":"I catch it fairly early on","value":"I catch it fairly early on","weights":{"occasional":1}},{"label":"I catch it as it starts","value":"I catch it as it starts","weights":{"occasional":0.25,"active":0.75}},{"label":"I am there before it begins","value":"I am there before it begins","weights":{"active":0.5,"constant":0.5}}]},{"id":"meta-mood","type":"choice","prompt":"Do you know you are in a particular mood before it starts running?","domain":"affect","options":[{"label":"I only know once it has passed","value":"I only know once it has passed","weights":{"unreflective":1}},{"label":"Partway through, when it is already well advanced","value":"Partway through, when it is already well advanced","weights":{"occasional":1}},{"label":"Usually just as it begins","value":"Usually just as it begins","weights":{"active":1}},{"label":"Almost immediately, before anything happens","value":"Almost immediately, before anything happens","weights":{"constant":1}}]},{"id":"meta-belief","type":"choice","prompt":"Has your mind ever changed about something it was certain of?","domain":"revision","options":[{"label":"I have changed my mind over small things only","value":"I have changed my mind over small things only","weights":{"unreflective":1}},{"label":"Rarely, and it felt destabilising rather than clarifying","value":"Rarely, and it felt destabilising rather than clarifying","weights":{"occasional":1}},{"label":"Yes, on things that mattered to me","value":"Yes, on things that mattered to me","weights":{"active":1}},{"label":"I revise beliefs as a matter of course","value":"I revise beliefs as a matter of course","weights":{"constant":1}}]},{"id":"meta-attention","type":"choice","prompt":"How well do you know where your attention is right now?","domain":"tracking","options":[{"label":"I have no idea where it is","value":"I have no idea where it is","weights":{"unreflective":1}},{"label":"Roughly — I know the general area","value":"Roughly — I know the general area","weights":{"occasional":1}},{"label":"Fairly precisely, most of the time","value":"Fairly precisely, most of the time","weights":{"active":1}},{"label":"I know exactly where it is, second to second","value":"I know exactly where it is, second to second","weights":{"constant":1}}]},{"id":"meta-describe","type":"choice","prompt":"If you had to explain how your own mind works, how accurate could you be?","domain":"accuracy","options":[{"label":"Not at all — I would be guessing","value":"Not at all — I would be guessing","weights":{"unreflective":1}},{"label":"Broadly right, but I would generalise","value":"Broadly right, but I would generalise","weights":{"unreflective":0.75,"occasional":0.25}},{"label":"Reasonably accurate","value":"Reasonably accurate","weights":{"occasional":1}},{"label":"Accurate in detail","value":"Accurate in detail","weights":{"occasional":0.25,"active":0.75}},{"label":"I could describe it closely and get it right","value":"I could describe it closely and get it right","weights":{"active":0.5,"constant":0.5}}]},{"id":"meta-observer","type":"choice","prompt":"When you notice a thought, is there a sense of someone doing the noticing?","domain":"position","options":[{"label":"No — the noticing is just another thought","value":"No — the noticing is just another thought","weights":{"unreflective":1}},{"label":"Sometimes, and it is hard to hold on to","value":"Sometimes, and it is hard to hold on to","weights":{"occasional":1}},{"label":"Usually, there is someone noticing","value":"Usually, there is someone noticing","weights":{"active":1}},{"label":"Clearly and continuously, whoever is doing it","value":"Clearly and continuously, whoever is doing it","weights":{"constant":1}}]},{"id":"meta-interrupt","type":"choice","prompt":"How often do you notice that you have been somewhere else for the past while?","domain":"frequency","options":[{"label":"It can be hours","value":"It can be hours","weights":{"unreflective":1}},{"label":"It can be a good while","value":"It can be a good while","weights":{"unreflective":0.75,"occasional":0.25}},{"label":"Usually within a few minutes","value":"Usually within a few minutes","weights":{"occasional":1}},{"label":"Within a minute or so","value":"Within a minute or so","weights":{"occasional":0.25,"active":0.75}},{"label":"Before I have gone anywhere","value":"Before I have gone anywhere","weights":{"active":0.5,"constant":0.5}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["unreflective","occasional","active","constant"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"unreflective","label":"Unreflective","short":"The thinking runs, and nothing sees it","description":"Thoughts arrive, run and finish without an audience. This is not an absence of intelligence — it is simply that the second attention is off when the first one is working, which means there is currently no vantage point from which to watch the pattern.","shadow":"Believing the thoughts are all there is to you.","color":"slate","masters":["observation","breath"],"calibration":{"dimensions":{"thought":0.4,"spirit":0.15},"practiceLevels":{"observation":1,"breath":1},"tags":["unwatched","automatic"]}},{"id":"occasional","label":"Occasional","short":"The noticing comes and goes","description":"The second attention switches on at intervals, usually in the middle of something that has already gone wrong. What you notice is accurate once it arrives; the outstanding question is the moment of arrival, which is currently not yours to choose.","shadow":"Noticing only after the fact and calling it attention.","color":"amber","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.3,"body":0.2,"spirit":0.15},"practiceLevels":{"observation":1,"witnessing":1},"tags":["intermittent","reactive-noticing"]}},{"id":"active","label":"Active","short":"The second attention is usually on","description":"You can see a thought forming, and you can see a mood arriving before it takes hold. This is a working capacity, and it opens questions that are considerably less comfortable than the ones it usually gets asked.","shadow":"Turning the second attention into a second ego.","color":"teal","masters":["self-inquiry","witnessing"],"calibration":{"dimensions":{"thought":0.3,"spirit":0.3,"emotion":0.15},"practiceLevels":{"witnessing":2,"self-inquiry":1},"tags":["watching","available"]}},{"id":"constant","label":"Constant","short":"Something is there almost throughout","description":"There is a continuous sense of things being noticed, and the noticing rarely switches off. The available work here is not to increase the seeing but to find out what is left over when the seeing is quiet — because the observer is usually the last thing examined.","shadow":"Mistaking the observer for a self that needs defending.","color":"indigo","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.4,"thought":0.25},"practiceLevels":{"witnessing":2,"jnana":1},"tags":["sustained","watcher"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["self-inquiry","witnessing"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
