  updated_at
) VALUES
    ('mind-body-type', 'Mind–body type', 'How thought and body relate for you', 'yogic', 'engines', E'Traditional practice is built on an assumption the modern world mostly dropped: that the body is not a container for the mind but a second site of knowing. Yogic practice in particular works by joining them — a posture that makes a thought harder to sustain, a breath that makes a feeling visible.\n\nThis asks which of the two you consult first. There is no correct answer and no fixed type; the order shifts with fatigue, fear and pressure, and the interesting material is in where it breaks down rather than where it usually sits.', '🧩', 6, 6, '[{"id":"mindbody-decide","type":"choice","prompt":"How does a decision actually get made in you?","domain":"decisions","options":[{"label":"I think it through until the reasoning holds","value":"I think it through until the reasoning holds","weights":{"head-first":1}},{"label":"I weigh it up and then simply do it","value":"I weigh it up and then simply do it","weights":{"balanced":1}},{"label":"I wait, and I see what the body says","value":"I wait, and I see what the body says","weights":{"body-first":1}}]},{"id":"mindbody-speed","type":"choice","prompt":"How quickly does the head answer, before the body has been asked?","domain":"speed","options":[{"label":"The body is nearly always first","value":"The body is nearly always first","weights":{"head-first":0}},{"label":"The body usually gets there first","value":"The body usually gets there first","weights":{"head-first":0.25}},{"label":"It varies, and it depends on the day","value":"It varies, and it depends on the day","weights":{"head-first":0.5}},{"label":"The head is usually ahead","value":"The head is usually ahead","weights":{"head-first":0.75}},{"label":"The head has always answered first","value":"The head has always answered first","weights":{"head-first":1}}]},{"id":"mindbody-truth","type":"choice","prompt":"What is your first response to something you are told is true?","domain":"certainty","options":[{"label":"I want to feel whether it is true","value":"I want to feel whether it is true","weights":{"body-first":1,"balanced":0,"head-first":0}},{"label":"I want to see whether it fits how things are","value":"I want to see whether it fits how things are","weights":{"body-first":0,"balanced":1,"head-first":0}},{"label":"I want to check it against what I already know","value":"I want to check it against what I already know","weights":{"body-first":0,"balanced":0,"head-first":1}}]},{"id":"mindbody-late","type":"choice","prompt":"You are running late and slightly lost. What happens next?","domain":"hurry","options":[{"label":"I stop, breathe, and let the tension go before I move","value":"I stop, breathe, and let the tension go before I move","weights":{"body-first":1,"balanced":0,"head-first":0}},{"label":"I do both at once — ask someone while I walk","value":"I do both at once — ask someone while I walk","weights":{"body-first":0,"balanced":1,"head-first":0}},{"label":"I plan the route in my head and talk myself through it","value":"I plan the route in my head and talk myself through it","weights":{"body-first":0,"balanced":0,"head-first":1}}]},{"id":"mindbody-signal","type":"choice","prompt":"How does your body tell you that something is wrong?","domain":"signal","options":[{"label":"It changes before I have any idea why","value":"It changes before I have any idea why","weights":{"body-first":1,"balanced":0,"head-first":0}},{"label":"It tells me clearly, and I listen","value":"It tells me clearly, and I listen","weights":{"body-first":0,"balanced":1,"head-first":0}},{"label":"I find out later, as a thought I have already finished","value":"I find out later, as a thought I have already finished","weights":{"body-first":0,"balanced":0,"head-first":1}}]},{"id":"mindbody-dispute","type":"choice","prompt":"When your head and your body disagree, how is it settled?","domain":"dispute","options":[{"label":"The body wins, whatever the argument","value":"The body wins, whatever the argument","weights":{"body-first":1,"balanced":0,"head-first":0}},{"label":"They negotiate, and something in the middle usually appears","value":"They negotiate, and something in the middle usually appears","weights":{"body-first":0,"balanced":1,"head-first":0}},{"label":"The head wins, and the body is told afterwards","value":"The head wins, and the body is told afterwards","weights":{"body-first":0,"balanced":0,"head-first":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["head-first","balanced","body-first"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"head-first","label":"Head-first","short":"The thinking comes first","description":"Reasoning leads and the body is a source of information consulted late, if at all. That ordering produces clarity and reliability in most situations that can be thought about, and quietly removes the body from decisions that cannot. The work here is not to stop thinking first — it is to give the body a vote.","shadow":"Believing the body has nothing to add to an argument it was not consulted on.","color":"sky","masters":["jnana","observation"],"calibration":{"dimensions":{"thought":0.4,"body":0.15,"spirit":0.15},"practiceLevels":{"jnana":1,"observation":1},"domainStress":{"attention":"observation"},"tags":["head-dominant","analytical"]}},{"id":"balanced","label":"Balanced","short":"Both arrive, roughly together","description":"Thought and body are consulted in the same breath, which is what most practice is built to develop and what the least practised people manage by accident. The strength is genuine: you can be accurate and still be in contact with what is happening. The risk is integration being taken for granted rather than maintained.","shadow":"Assuming the balance will hold without being fed.","color":"teal","masters":["body","raja"],"calibration":{"dimensions":{"body":0.25,"thought":0.2,"action":0.2},"practiceLevels":{"body":1,"raja":1},"tags":["integrated","two-way"]}},{"id":"body-first","label":"Body-first","short":"The knowing arrives in the body","description":"The body answers first and the reasoning arrives afterwards to organise what has already happened. This is a fast and accurate channel when it is trusted, and it is easy to misread as instinct or as a mood. The work is learning the difference between what the body says and what it has learned to say on your behalf.","shadow":"Taking every signal from the body as a message.","color":"violet","masters":["body","breath"],"calibration":{"dimensions":{"body":0.35,"spirit":0.2,"emotion":0.15},"practiceLevels":{"body":2,"breath":1},"tags":["somatic","intuitive"]}}]'::jsonb, '{"loops_to_check":["over-thinking","avoidance-map"],"practice_affinity":["body","observation","breath"],"deepens_with":["three-brains","sensory-awareness"]}'::jsonb, 1, true, false, 100, now())
