-- Mind wandering (Observation)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('mind-wandering', 'Mind wandering', 'How far the mind drifts before you notice', 'vedic', 'thought', E'The mind leaving is not a failure of discipline. A mind that cannot wander is a mind that has been told what to think, which is a different thing entirely and not obviously better.\n\nWhat matters is what the wandering is made of, whether it is chosen or automatic, and what it costs. All three of those change completely when the drift is looked at rather than fought.', '🌀', 6, 8, '[{"id":"wander-notice","type":"choice","prompt":"How long does your attention go off somewhere before you notice?","domain":"timing","options":[{"label":"I find out hours later","value":"I find out hours later","weights":{"lost":1}},{"label":"It can be a good while","value":"It can be a good while","weights":{"lost":0.75,"drifting":0.25}},{"label":"Usually within the hour","value":"Usually within the hour","weights":{"drifting":1}},{"label":"Within a few minutes","value":"Within a few minutes","weights":{"drifting":0.25,"ranging":0.75}},{"label":"Almost as soon as it starts","value":"Almost as soon as it starts","weights":{"ranging":0.5,"deliberate":0.5}}]},{"id":"wander-content","type":"choice","prompt":"When your mind goes off, where does it usually go?","domain":"content","options":[{"label":"Somewhere of its own that I did not choose","value":"Somewhere of its own that I did not choose","weights":{"lost":1}},{"label":"Back through things that have already happened","value":"Back through things that have already happened","weights":{"drifting":1}},{"label":"Forward into plans and rehearsals","value":"Forward into plans and rehearsals","weights":{"ranging":1}},{"label":"Deliberately, into an idea I want to follow","value":"Deliberately, into an idea I want to follow","weights":{"deliberate":1}}]},{"id":"wander-pleasure","type":"choice","prompt":"Is the drift pleasant?","domain":"texture","options":[{"label":"Unpleasant, and I want out of it","value":"Unpleasant, and I want out of it","weights":{"lost":1}},{"label":"Mostly neutral — it goes on in the background","value":"Mostly neutral — it goes on in the background","weights":{"drifting":1}},{"label":"Pleasant, and part of why I do it","value":"Pleasant, and part of why I do it","weights":{"ranging":1}},{"label":"Chosen, and worth the time it takes","value":"Chosen, and worth the time it takes","weights":{"deliberate":1}}]},{"id":"wander-return","type":"choice","prompt":"Once you notice you have gone, how easily do you come back?","domain":"return","options":[{"label":"It takes me a long time to be back","value":"It takes me a long time to be back","weights":{"lost":1}},{"label":"I get back, but I am pulled again soon","value":"I get back, but I am pulled again soon","weights":{"lost":0.75,"drifting":0.25}},{"label":"It takes a deliberate effort","value":"It takes a deliberate effort","weights":{"drifting":1}},{"label":"I come back fairly readily","value":"I come back fairly readily","weights":{"drifting":0.25,"ranging":0.75}},{"label":"Immediately, and it holds","value":"Immediately, and it holds","weights":{"ranging":0.5,"deliberate":0.5}}]},{"id":"wander-deliberate","type":"choice","prompt":"Can you deliberately let your mind wander?","domain":"agency","options":[{"label":"No — it only ever happens to me","value":"No — it only ever happens to me","weights":{"lost":1}},{"label":"I can let it drift, but I stay half alert","value":"I can let it drift, but I stay half alert","weights":{"drifting":1}},{"label":"I can take it anywhere on purpose","value":"I can take it anywhere on purpose","weights":{"ranging":1}},{"label":"I go there deliberately, and stay as long as I want","value":"I go there deliberately, and stay as long as I want","weights":{"deliberate":1}}]},{"id":"wander-gaps","type":"choice","prompt":"What happens in the gaps between thoughts?","domain":"gaps","options":[{"label":"I am not there at all","value":"I am not there at all","weights":{"lost":1}},{"label":"Something small passes through, too quick to name","value":"Something small passes through, too quick to name","weights":{"drifting":1}},{"label":"A clear sense of space, though I am not sure of it","value":"A clear sense of space, though I am not sure of it","weights":{"ranging":1}},{"label":"Something is there, and I can be in it","value":"Something is there, and I can be in it","weights":{"deliberate":1}}]},{"id":"wander-frequency","type":"choice","prompt":"How often does this happen in a day?","domain":"frequency","options":[{"label":"It is most of the day","value":"It is most of the day","weights":{"lost":1}},{"label":"Very often, in long stretches","value":"Very often, in long stretches","weights":{"lost":0.75,"drifting":0.25}},{"label":"A good few times","value":"A good few times","weights":{"drifting":1}},{"label":"Occasionally","value":"Occasionally","weights":{"drifting":0.25,"ranging":0.75}},{"label":"Rarely, and usually on purpose","value":"Rarely, and usually on purpose","weights":{"ranging":0.5,"deliberate":0.5}}]},{"id":"wander-cost","type":"choice","prompt":"Does the wandering cost you anything?","domain":"consequence","options":[{"label":"Whole hours, and usually the day with them","value":"Whole hours, and usually the day with them","weights":{"lost":1}},{"label":"Small tasks that never get finished","value":"Small tasks that never get finished","weights":{"drifting":1}},{"label":"Mostly it clears itself and nothing is lost","value":"Mostly it clears itself and nothing is lost","weights":{"ranging":1}},{"label":"I treat it as part of the day and plan for it","value":"I treat it as part of the day and plan for it","weights":{"deliberate":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["lost","drifting","ranging","deliberate"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"lost","label":"Lost","short":"Away, and not sure how long for","description":"The mind goes and does not report back, and the return is slow enough that the interval is rarely noticed from inside. Because it is invisible from within, it is usually discovered by other people or by the state of the evening.","shadow":"Reading the disorientation as a bad day rather than a pattern.","color":"rose","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.4,"body":0.2,"action":0.15},"practiceLevels":{"observation":2,"witnessing":1},"domainStress":{"attention":"observation"},"tags":["lost-time","unaware"]}},{"id":"drifting","label":"Drifting","short":"Away, and found again reasonably often","description":"The mind leaves and comes back, and the return is available. What is unresolved is what the drift is for — it is usually the mind going to whichever place it would rather not be.","shadow":"Mistaking a comfortable drift for freedom.","color":"amber","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.25,"body":0.15},"practiceLevels":{"observation":1,"witnessing":1},"tags":["background-drift","returning"]}},{"id":"ranging","label":"Ranging","short":"It goes out, and it comes back with something","description":"The mind travels and returns, and the travel produces material — a thought, a plan, a question that was not there before. This is the mind working, at a scale the conscious attention would never have permitted.","shadow":"Letting the range substitute for the decision that was avoided.","color":"teal","masters":["observation","jnana"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.3,"action":0.2},"practiceLevels":{"observation":1,"jnana":1},"tags":["productive-drift","wide"]}},{"id":"deliberate","label":"Deliberate","short":"The wandering is chosen, and it is on purpose","description":"The mind can be sent somewhere and taken back, deliberately. What is worth examining now is the difference between a chosen wandering and an escape that has learned to describe itself as chosen.","shadow":"Choosing the escape and naming it freedom.","color":"indigo","masters":["raja","witnessing"],"calibration":{"dimensions":{"spirit":0.35,"thought":0.3},"practiceLevels":{"raja":1,"witnessing":2},"tags":["chosen","trained"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["observation","witnessing"],"deepens_with":["fantasy-loops","rumination-index"]}'::jsonb, 1, true, false, 100, now())
