-- Money psyche (Heart)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('money-psyche', 'Money psyche', 'Your relationship with money', 'yogic', 'attachment', E'Money is the one thing in a life that arrives as a scoreboard for every other thing — safety, freedom, worth, comparison, generosity. Most people have had it longer than they have had time to notice the arrangement.\n\nThis describes the shape of that relationship as it actually runs, with no opinion about how much of it there is or what it should be. Having little and having much are both facts about a situation. What tends to be inherited is the conclusion drawn from it.', '💰', 6, 6, '[{"id":"money-first-thought","type":"choice","prompt":"What is the first thought that arrives when money comes up?","domain":"first reaction","options":[{"label":"Whether there is enough, and whether it will last","value":"Whether there is enough, and whether it will last","weights":{"scarcity":1,"abundance-neutral":0,"stewardship":0,"generosity":0}},{"label":"Where things stand — the figures, plainly","value":"Where things stand — the figures, plainly","weights":{"scarcity":0.25,"abundance-neutral":0.75,"stewardship":0,"generosity":0}},{"label":"Whether it is being looked after","value":"Whether it is being looked after","weights":{"scarcity":0,"abundance-neutral":0.5,"stewardship":0.5,"generosity":0}},{"label":"What I am doing with it, and how well","value":"What I am doing with it, and how well","weights":{"scarcity":0,"abundance-neutral":0,"stewardship":0.75,"generosity":0.25}},{"label":"Where it goes, and who it reaches","value":"Where it goes, and who it reaches","weights":{"scarcity":0,"abundance-neutral":0,"stewardship":0,"generosity":1}}]},{"id":"money-checking","type":"choice","prompt":"How often do you look at what you have?","domain":"checking","options":[{"label":"I genuinely do not look","value":"I genuinely do not look","weights":{"scarcity":0}},{"label":"Rarely, and usually only when I have to","value":"Rarely, and usually only when I have to","weights":{"scarcity":0.25}},{"label":"Now and then, before something specific","value":"Now and then, before something specific","weights":{"scarcity":0.5}},{"label":"Often, without a particular reason","value":"Often, without a particular reason","weights":{"scarcity":0.75}},{"label":"Most days — and not until I have, the day has not properly started","value":"Most days — and not until I have, the day has not properly started","weights":{"scarcity":1}}]},{"id":"money-enough","type":"choice","prompt":"Do you know what enough would look like for you?","domain":"enough","options":[{"label":"No idea, and I would not want one","value":"No idea, and I would not want one","weights":{"abundance-neutral":0}},{"label":"Vaguely — I would know if I was near it","value":"Vaguely — I would know if I was near it","weights":{"abundance-neutral":0.25}},{"label":"Roughly, though the number keeps changing","value":"Roughly, though the number keeps changing","weights":{"abundance-neutral":0.5}},{"label":"Yes, and I am usually in that region","value":"Yes, and I am usually in that region","weights":{"abundance-neutral":0.75}},{"label":"Yes, precisely, and it has not moved in years","value":"Yes, precisely, and it has not moved in years","weights":{"abundance-neutral":1}}]},{"id":"money-care","type":"choice","prompt":"How well is the money you are responsible for looked after?","domain":"the resource","options":[{"label":"It leaks, and I let it","value":"It leaks, and I let it","weights":{"stewardship":0}},{"label":"Some leaks that I do not notice","value":"Some leaks that I do not notice","weights":{"stewardship":0.25}},{"label":"I keep it roughly straight","value":"I keep it roughly straight","weights":{"stewardship":0.5}},{"label":"I know exactly where it is and where it is going","value":"I know exactly where it is and where it is going","weights":{"stewardship":0.75}},{"label":"It is looked after deliberately, and I can see the whole picture","value":"It is looked after deliberately, and I can see the whole picture","weights":{"stewardship":1}}]},{"id":"money-giving","type":"choice","prompt":"How does money move out of your hands?","domain":"movement out","options":[{"label":"It does not","value":"It does not","weights":{"generosity":0}},{"label":"Rarely, and reluctantly","value":"Rarely, and reluctantly","weights":{"generosity":0.25}},{"label":"When something obliges me to","value":"When something obliges me to","weights":{"generosity":0.5}},{"label":"Regularly, to people who ask","value":"Regularly, to people who ask","weights":{"generosity":0.75}},{"label":"Regularly, to people and purposes I have chosen","value":"Regularly, to people and purposes I have chosen","weights":{"generosity":1}}]},{"id":"money-learned","type":"choice","prompt":"What did you grow up hearing about money?","domain":"where it came from","options":[{"label":"That there might not be enough","value":"That there might not be enough","weights":{"scarcity":1,"abundance-neutral":0,"stewardship":0,"generosity":0}},{"label":"That it comes and goes, and you cannot lean on it","value":"That it comes and goes, and you cannot lean on it","weights":{"scarcity":0.25,"abundance-neutral":0.75,"stewardship":0,"generosity":0}},{"label":"That it is a matter of fact — neither good nor bad","value":"That it is a matter of fact — neither good nor bad","weights":{"scarcity":0,"abundance-neutral":0.5,"stewardship":0.5,"generosity":0}},{"label":"That it is a tool, and tools are looked after","value":"That it is a tool, and tools are looked after","weights":{"scarcity":0,"abundance-neutral":0,"stewardship":0.75,"generosity":0.25}},{"label":"That it is meant to move, and to reach other people","value":"That it is meant to move, and to reach other people","weights":{"scarcity":0,"abundance-neutral":0,"stewardship":0,"generosity":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["scarcity","abundance-neutral","stewardship","generosity"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"scarcity","label":"Scarcity","short":"Organised around not running short","description":"Your relationship to money is built on a working assumption that it will run out, so most of your attention goes on prevention — checking, keeping, holding on. That arithmetic is not a character flaw and rarely a personal invention: it is usually something learned accurately at a time when it was accurate. What is harder to see from inside is how much of the day the guard occupies, and how much attention is therefore available for anything that does not involve counting.","shadow":"Reading the constant arithmetic as evidence about you.","color":"amber","masters":["finance","observation"],"calibration":{"dimensions":{"action":0.3,"emotion":0.25,"thought":0.15},"practiceLevels":{"finance":2,"observation":1},"domainStress":{"security":"finance"},"tags":["scarcity","guarded"]}},{"id":"abundance-neutral","label":"Even","short":"A matter of fact, not a verdict","description":"Money has no particular charge in your system. It is a thing that exists with a shape and a size, and you can read the shape without it telling you anything about your worth. This is the middle of the range, not a lukewarm version of either end of it — it is a genuinely easier place to stand, and the number is only rarely where the attention is.","shadow":"Neutrality mistaken for indifference to what it does.","color":"slate","masters":["observation","jnana"],"calibration":{"dimensions":{"thought":0.25,"action":0.2,"emotion":0.1},"practiceLevels":{"observation":1,"finance":1},"tags":["even","uncharged"]}},{"id":"stewardship","label":"Stewardship","short":"A resource with a job, being looked after","description":"Money is treated as a resource rather than as a score. It is held, counted, directed, and kept in a shape you chose, and the shape was chosen on purpose. The part that is easy to miss is that this is a practice rather than a possession — it has to be done again deliberately, and what makes it durable is the doing.","shadow":"The care taken over the resource replacing the resource itself.","color":"teal","masters":["finance","raja"],"calibration":{"dimensions":{"action":0.35,"thought":0.2,"connection":0.1},"practiceLevels":{"finance":2,"raja":1},"domainStress":{"resource":"finance"},"tags":["stewardship","managed"]}},{"id":"generosity","label":"Generosity","short":"Money that is meant to move","description":"Money leaves your hands by design, and where it goes is largely yours to have chosen. This is a description of the function money is serving for you — not a claim about how much, and not a claim about virtue, which is a separate question and a less interesting one. The question this opens is what the giving is for, and what would happen to it if no one knew.","shadow":"The movement of money beginning to substitute for your own.","color":"emerald","masters":["karma","finance"],"calibration":{"dimensions":{"connection":0.35,"action":0.2,"spirit":0.1},"practiceLevels":{"finance":1,"karma":1},"domainStress":{"giving":"finance"},"tags":["generosity","circulating"]}}]'::jsonb, '{"loops_to_check":["scarcity-drift","comparison"],"practice_affinity":["finance","observation"],"deepens_with":["work-dharma"]}'::jsonb, 1, true, false, 100, now())
