-- Nervous system tone (Engines)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('nervous-system-tone', 'Nervous system tone', 'Fight, flight, freeze, or rest', 'yogic', 'vitality', E'A nervous system is not a personality. It is a set of preparations, older than language, that decides what happens next before you have voted on it.\n\nThe first three moves — fight, flight, freeze — are not flaws. They are a body solving an emergency as fast as it can. There is a fourth, less discussed, and it is the one that is hardest to reach without a real opening. This looks at which one your system reaches for, how long it stays, and what actually brings it back down.', '🫀', 7, 8, '[{"id":"nervous-first","type":"choice","prompt":"When something suddenly demands a response, what happens in your body first?","domain":"activation","options":[{"label":"Jaw sets, shoulders come up, I meet it head-on","value":"Jaw sets, shoulders come up, I meet it head-on","weights":{"fight":1}},{"label":"A rush of heat and an urge to be somewhere else","value":"A rush of heat and an urge to be somewhere else","weights":{"flight":1}},{"label":"Everything goes still and my mind goes blank","value":"Everything goes still and my mind goes blank","weights":{"freeze":1}},{"label":"I open towards whoever or whatever is there","value":"I open towards whoever or whatever is there","weights":{"tend-befriend":1}}]},{"id":"nervous-breath","type":"choice","prompt":"When you are under pressure, what does your breathing do?","domain":"breath","options":[{"label":"It goes fast and high in the chest","value":"It goes fast and high in the chest","weights":{"flight":1}},{"label":"It gets noticeably shallower","value":"It gets noticeably shallower","weights":{"flight":0.75,"freeze":0.25}},{"label":"It catches in my throat, or stops for a moment","value":"It catches in my throat, or stops for a moment","weights":{"freeze":1}},{"label":"It drops low and slows on its own","value":"It drops low and slows on its own","weights":{"tend-befriend":0.75,"freeze":0.25}},{"label":"It stays the same whatever is happening","value":"It stays the same whatever is happening","weights":{"tend-befriend":1}}]},{"id":"nervous-downshift","type":"choice","prompt":"How easily does the day let go of you in the evening?","domain":"recovery","options":[{"label":"It will not come down at all","value":"It will not come down at all","weights":{"flight":1}},{"label":"It takes hours to unwind","value":"It takes hours to unwind","weights":{"flight":0.75,"freeze":0.25}},{"label":"It settles eventually","value":"It settles eventually","weights":{"freeze":0.75,"fight":0.25}},{"label":"It comes down fairly easily","value":"It comes down fairly easily","weights":{"freeze":0.25,"tend-befriend":0.75}},{"label":"It is down almost as soon as I stop","value":"It is down almost as soon as I stop","weights":{"tend-befriend":1}}]},{"id":"nervous-company","type":"choice","prompt":"When something has gone badly, who do you go to?","domain":"contact","options":[{"label":"Straight to someone, because I settle when I am held","value":"Straight to someone, because I settle when I am held","weights":{"tend-befriend":1}},{"label":"Away from everyone, alone until it passes","value":"Away from everyone, alone until it passes","weights":{"flight":1}},{"label":"Very still, waiting for it to move over me","value":"Very still, waiting for it to move over me","weights":{"freeze":1}},{"label":"Through it — I stay in the room and keep going","value":"Through it — I stay in the room and keep going","weights":{"fight":1}}]},{"id":"nervous-appetite","type":"choice","prompt":"When you are stressed, does your appetite change?","domain":"regulation","options":[{"label":"I eat far more than usual","value":"I eat far more than usual","weights":{"fight":1}},{"label":"I want very little at all","value":"I want very little at all","weights":{"flight":1}},{"label":"I eat without noticing that I am eating","value":"I eat without noticing that I am eating","weights":{"freeze":1}},{"label":"It is almost unchanged","value":"It is almost unchanged","weights":{"tend-befriend":1}}]},{"id":"nervous-length","type":"choice","prompt":"After a stressful morning, how long does it stay with you?","domain":"recovery","options":[{"label":"The rest of the day","value":"The rest of the day","weights":{"fight":0}},{"label":"Most of the day","value":"Most of the day","weights":{"fight":0.25}},{"label":"A few hours","value":"A few hours","weights":{"fight":0.5}},{"label":"An hour or two","value":"An hour or two","weights":{"fight":0.75}},{"label":"It clears within minutes","value":"It clears within minutes","weights":{"fight":1}}]},{"id":"nervous-turndown","type":"choice","prompt":"What actually brings you down when you are wound up?","domain":"regulation","options":[{"label":"Walking, lifting, moving the body hard","value":"Walking, lifting, moving the body hard","weights":{"fight":1}},{"label":"A long breath, or feeling my feet on the ground","value":"A long breath, or feeling my feet on the ground","weights":{"freeze":1}},{"label":"Music, a shower, being in water","value":"Music, a shower, being in water","weights":{"flight":1}},{"label":"Someone to talk it through with","value":"Someone to talk it through with","weights":{"tend-befriend":1}}]},{"id":"nervous-now","type":"choice","prompt":"Compared to a year ago, is your body more or less switched on?","domain":"history","options":[{"label":"I am switched on much more of the time","value":"I am switched on much more of the time","weights":{"flight":1}},{"label":"I react more sharply than I used to","value":"I react more sharply than I used to","weights":{"fight":1}},{"label":"I have gone quieter and further shut down","value":"I have gone quieter and further shut down","weights":{"freeze":1}},{"label":"I am steadier, and easier in my own company","value":"I am steadier, and easier in my own company","weights":{"tend-befriend":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["fight","flight","freeze","tend-befriend"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"fight","label":"Fight-forward","short":"The system meets it head-on","description":"Pressure brings engagement rather than retreat — jaw set, shoulders up, still in the room. There is real energy here, and it is energy that was built for something difficult. The cost is that the body stays braced long after the situation has finished.","shadow":"Mistaking the tension for commitment.","color":"orange","masters":["raja","body"],"calibration":{"dimensions":{"action":0.3,"body":0.3,"emotion":0.2},"practiceLevels":{"body":1,"raja":1},"domainStress":{"pressure":"work-career"},"tags":["braced","over-committed"]}},{"id":"flight","label":"Flight-forward","short":"It leaves early, and it stays left","description":"The system is oriented to distance itself, and it does so quickly and early. Breath rises, sleep lightens, attention starts scanning for the exit. This is an efficient system for genuine danger, and an expensive one for a life with no danger in it.","shadow":"Calling constant readiness a reasonable caution.","color":"rose","masters":["breath","kriya"],"calibration":{"dimensions":{"body":0.3,"thought":0.25,"spirit":0.15},"practiceLevels":{"breath":2},"domainStress":{"safety":"health"},"tags":["hypervigilant","restless"]}},{"id":"freeze","label":"Freeze-dominant","short":"The system goes still rather than moves","description":"When the pressure arrives, movement stops. Attention goes flat, the body waits, and the moment passes over without being met. Freeze is often mistaken for calm from the outside; from the inside it is usually a wide stillness with a great deal held in it.","shadow":"Reading stillness as peace because nothing is moving.","color":"sky","masters":["witnessing","observation"],"calibration":{"dimensions":{"body":0.3,"emotion":0.3,"connection":0.15},"practiceLevels":{"witnessing":1,"observation":1},"domainStress":{"contact":"relationship"},"tags":["dissociating","held-still"]}},{"id":"tend-befriend","label":"Tending-forward","short":"The system reaches for connection and holds it","description":"Under pressure, the first move is towards rather than away. This is the least defended of the four, and also the one that costs the most to hold consistently, because staying open needs a body that is not still braced from the morning before.","shadow":"Staying open as a way of never being alone with the hard part.","color":"emerald","masters":["bhakti","relationship"],"calibration":{"dimensions":{"connection":0.35,"emotion":0.25,"body":0.2},"practiceLevels":{"bhakti":1},"domainStress":{"relation":"relationship"},"tags":["open","held"]}}]'::jsonb, '{"loops_to_check":["hypervigilance","numbness"],"practice_affinity":["breath","body"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
