-- Niyamas (Patanjali)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('niyamas', 'Niyamas', 'The five self-disciplines', 'yogic', 'ethics', E'The second limb turns the same five-part shape inward. If the yamas are what you owe other people, the niyamas are what you owe yourself.\n\nThe second one — contentment — is the one that quietly undoes the first five if it is missing.', '🪷', 7, 6, '[{"id":"niyama-alive","type":"choice","prompt":"Of the five — cleanliness, contentment, heat, study, and surrender — which is actually alive in your life?","domain":"priority","options":[{"label":"Cleanliness — of body, surroundings, or thought","value":"Cleanliness — of body, surroundings, or thought","weights":{"sauca":1}},{"label":"Contentment — being enough as you are","value":"Contentment — being enough as you are","weights":{"samtosha":1}},{"label":"Tapas — sustained effort toward something","value":"Tapas — sustained effort toward something","weights":{"tapas":1}},{"label":"Study — keeping yourself in contact with yourself","value":"Study — keeping yourself in contact with yourself","weights":{"svadhyaya":1}},{"label":"Surrender — orienting toward something larger","value":"Surrender — orienting toward something larger","weights":{"ishvarapranidhana":1}}]},{"id":"niyama-neglected","type":"choice","prompt":"And which one have you quietly not done at all?","domain":"neglect","options":[{"label":"Cleanliness — of body, surroundings, or thought","value":"Cleanliness — of body, surroundings, or thought","weights":{"sauca":1}},{"label":"Contentment — being enough as you are","value":"Contentment — being enough as you are","weights":{"samtosha":1}},{"label":"Tapas — sustained effort toward something","value":"Tapas — sustained effort toward something","weights":{"tapas":1}},{"label":"Study — keeping yourself in contact with yourself","value":"Study — keeping yourself in contact with yourself","weights":{"svadhyaya":1}},{"label":"Surrender — orienting toward something larger","value":"Surrender — orienting toward something larger","weights":{"ishvarapranidhana":1}}]},{"id":"niyama-content","type":"choice","prompt":"How often are you actually satisfied with what you have?","domain":"samtosha","options":[{"label":"I am almost never satisfied with where I am","value":"I am almost never satisfied with where I am","weights":{"samtosha":0}},{"label":"Briefly, and rarely","value":"Briefly, and rarely","weights":{"samtosha":0.25}},{"label":"In short stretches, after things settle","value":"In short stretches, after things settle","weights":{"samtosha":0.5}},{"label":"Most of the time, with some effort","value":"Most of the time, with some effort","weights":{"samtosha":0.75}},{"label":"It is simply my default state","value":"It is simply my default state","weights":{"samtosha":1}}]},{"id":"niyama-effort","type":"choice","prompt":"How much sustained effort is your life actually asking of you?","domain":"tapas","options":[{"label":"Almost none, by design","value":"Almost none, by design","weights":{"tapas":1}},{"label":"Not much, and no plan to change it","value":"Not much, and no plan to change it","weights":{"tapas":1}},{"label":"Some, in bursts","value":"Some, in bursts","weights":{"tapas":1}},{"label":"A steady amount, most days","value":"A steady amount, most days","weights":{"tapas":1}},{"label":"More than is sustainable","value":"More than is sustainable","weights":{"tapas":1}}]},{"id":"niyama-study","type":"choice","prompt":"When did you last learn something about yourself deliberately?","domain":"svadhyaya","options":[{"label":"I never do","value":"I never do","weights":{"svadhyaya":1}},{"label":"Rarely, and only if something forces it","value":"Rarely, and only if something forces it","weights":{"svadhyaya":1}},{"label":"Now and then","value":"Now and then","weights":{"svadhyaya":1}},{"label":"Regularly, and it helps","value":"Regularly, and it helps","weights":{"svadhyaya":1}},{"label":"It is a fixed part of how I work","value":"It is a fixed part of how I work","weights":{"svadhyaya":1}}]},{"id":"niyama-surrender","type":"choice","prompt":"Can you hand something over that you cannot manage?","domain":"ishvarapranidhana","options":[{"label":"I cannot, under any circumstances","value":"I cannot, under any circumstances","weights":{"ishvarapranidhana":1}},{"label":"Rarely, and it costs me","value":"Rarely, and it costs me","weights":{"ishvarapranidhana":1}},{"label":"With a lot of difficulty","value":"With a lot of difficulty","weights":{"ishvarapranidhana":1}},{"label":"Fairly readily, in most things","value":"Fairly readily, in most things","weights":{"ishvarapranidhana":1}},{"label":"It is easy — I do not have to hold everything","value":"It is easy — I do not have to hold everything","weights":{"ishvarapranidhana":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["sauca","samtosha","tapas","svadhyaya","ishvarapranidhana"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"sauca","label":"Śauca is the live one","short":"Clarity of body, surroundings, or thought","description":"Purity and clarity are where your practice is. This usually shows up as an appetite for order — in your environment, your inputs, or the way you think — and it is more demanding on you than it is on anyone else.","shadow":"Cleaning the room instead of sitting in it.","color":"sky","masters":["body","observation"],"calibration":{"dimensions":{"body":0.3,"thought":0.25},"practiceLevels":{"body":1,"observation":1},"tags":["niyama","clarity"]}},{"id":"samtosha","label":"Sāntosha is the live one","short":"Enough is the question you keep deferring","description":"Contentment is your live niyama. Not because you lack ambition, but because contentment is the precondition for everything else in the set — without it, the yamas become a performance and the rest becomes strain.","shadow":"Using contentment to avoid the next thing.","color":"emerald","masters":["witnessing","raja"],"calibration":{"dimensions":{"emotion":0.3,"spirit":0.25,"body":0.15},"practiceLevels":{"witnessing":1},"tags":["niyama","contentment"]}},{"id":"tapas","label":"Tāpas is the live one","short":"The heat is on","description":"Sustained effort is your centre. You are running hot, and the question is not whether to push harder but whether the vessel holds. Tapas without the other four becomes suffering.","shadow":"Confusing endurance with progress.","color":"orange","masters":["raja","karma"],"calibration":{"dimensions":{"action":0.35,"body":0.25},"practiceLevels":{"raja":1,"karma":1},"domainStress":{"work":"work-career"},"tags":["niyama","high-effort"]}},{"id":"svadhyaya","label":"Svādhyāya is the live one","short":"Keeping yourself in contact","description":"Deliberate self-study is your live discipline. You are the kind of person who benefits from returning to the same material — your own notes, your own recordings, your own patterns.","shadow":"Gathering material instead of revisiting it.","color":"violet","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"thought":0.35,"spirit":0.2},"practiceLevels":{"jnana":1,"self-inquiry":1},"tags":["niyama","self-study"]}},{"id":"ishvarapranidhana","label":"Īśvarapraṇidhāna is the live one","short":"Something larger is available","description":"Surrender and dedication are where your practice lives. There is an orientation toward something beyond your own making, and your work is learning what it asks for without shrinking.","shadow":"Surrendering to something you have not looked at.","color":"indigo","masters":["bhakti","raja"],"calibration":{"dimensions":{"spirit":0.4,"emotion":0.2,"connection":0.15},"practiceLevels":{"bhakti":1,"raja":1},"tags":["niyama","devotion"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["raja","jnana"],"deepens_with":["yamas","svadhyaya"]}'::jsonb, 1, true, false, 100, now())
