-- Non-dual glimpses (Launch)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('non-dual-glimpses', 'Non-dual glimpses', 'Flashes of unity', 'vedic', 'spirit', E'A glimpse is a brief, unarguable experience of unity that cannot be sustained and is not always welcome afterwards.\n\nThe important distinction is between having had one, having heard about one, and being able to recognise one in the moment.', '∞', 6, 6, '[{"id":"nondual-experience","type":"choice","prompt":"Have you ever directly experienced unity — not thought about it, had it?","domain":"history","options":[{"label":"No, and I have not thought much about it","value":"No, and I have not thought much about it","weights":{"never":1}},{"label":"I know the idea well","value":"I know the idea well","weights":{"never":0}},{"label":"I have had something close, but I would not call it that","value":"I have had something close, but I would not call it that","weights":{"never":0}},{"label":"Yes, unmistakably","value":"Yes, unmistakably","weights":{"never":0}},{"label":"Yes, and I have never entirely come back","value":"Yes, and I have never entirely come back","weights":{"never":0}}]},{"id":"nondual-duration","type":"choice","prompt":"How long did it last?","domain":"duration","options":[{"label":"Not applicable","value":"Not applicable","weights":{"never":1,"concept-only":0,"brief-glimpses":0,"recurring":0}},{"label":"An instant","value":"An instant","weights":{"never":0.25,"concept-only":0.75,"brief-glimpses":0,"recurring":0}},{"label":"A few seconds","value":"A few seconds","weights":{"never":0,"concept-only":0.5,"brief-glimpses":0.5,"recurring":0}},{"label":"A minute or so","value":"A minute or so","weights":{"never":0,"concept-only":0,"brief-glimpses":0.75,"recurring":0.25}},{"label":"Long enough to lose the sense of a body and a self","value":"Long enough to lose the sense of a body and a self","weights":{"never":0,"concept-only":0,"brief-glimpses":0,"recurring":1}}]},{"id":"nondual-after","type":"choice","prompt":"What happened in the hours and days after?","domain":"aftermath","options":[{"label":"Not applicable","value":"Not applicable","weights":{"brief-glimpses":1}},{"label":"A strange elevation for a day","value":"A strange elevation for a day","weights":{"brief-glimpses":1}},{"label":"A long depression","value":"A long depression","weights":{"brief-glimpses":1}},{"label":"Clarity that stayed","value":"Clarity that stayed","weights":{"brief-glimpses":1}},{"label":"The world looked wrong for weeks and I could not explain why","value":"The world looked wrong for weeks and I could not explain why","weights":{"brief-glimpses":1}}]},{"id":"nondual-invite","type":"choice","prompt":"Can you invite it deliberately?","domain":"invitation","options":[{"label":"Not applicable","value":"Not applicable","weights":{"never":1,"concept-only":0,"brief-glimpses":0,"recurring":0}},{"label":"I have not tried","value":"I have not tried","weights":{"never":0.25,"concept-only":0.75,"brief-glimpses":0,"recurring":0}},{"label":"Rarely, and I cannot tell if I caused it","value":"Rarely, and I cannot tell if I caused it","weights":{"never":0,"concept-only":0.5,"brief-glimpses":0.5,"recurring":0}},{"label":"Sometimes, with the right conditions","value":"Sometimes, with the right conditions","weights":{"never":0,"concept-only":0,"brief-glimpses":0.75,"recurring":0.25}},{"label":"I can get close to the threshold fairly reliably","value":"I can get close to the threshold fairly reliably","weights":{"never":0,"concept-only":0,"brief-glimpses":0,"recurring":1}}]},{"id":"nondual-language","type":"choice","prompt":"When you talk about it, is it an experience or a concept?","domain":"framing","options":[{"label":"I do not really talk about it","value":"I do not really talk about it","weights":{"brief-glimpses":1}},{"label":"As a philosophy, and I value it","value":"As a philosophy, and I value it","weights":{"brief-glimpses":1}},{"label":"As something I have read about","value":"As something I have read about","weights":{"brief-glimpses":1}},{"label":"As something I have had","value":"As something I have had","weights":{"brief-glimpses":1}},{"label":"As the most real thing available, and everything else is the abstraction","value":"As the most real thing available, and everything else is the abstraction","weights":{"brief-glimpses":1}}]},{"id":"nondual-fear","type":"choice","prompt":"Does the idea frighten you at all?","domain":"relation","options":[{"label":"I avoid the whole subject and prefer not to think about why","value":"I avoid the whole subject and prefer not to think about why","weights":{"never":1,"concept-only":0,"brief-glimpses":0,"recurring":0}},{"label":"It frightens me","value":"It frightens me","weights":{"never":0.25,"concept-only":0.75,"brief-glimpses":0,"recurring":0}},{"label":"It makes me uneasy","value":"It makes me uneasy","weights":{"never":0,"concept-only":0.5,"brief-glimpses":0.5,"recurring":0}},{"label":"Slight unease","value":"Slight unease","weights":{"never":0,"concept-only":0,"brief-glimpses":0.75,"recurring":0.25}},{"label":"No resistance at all","value":"No resistance at all","weights":{"never":0,"concept-only":0,"brief-glimpses":0,"recurring":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["never","concept-only","brief-glimpses","recurring"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"never","label":"Never","short":"The idea, and not yet the event","description":"You have no direct experience of unity, which is entirely ordinary and is not a spiritual deficiency — it is a description of a life. Most traditions treat the concept before the event, and the concept is not wasted.","shadow":"Reading a description as though it were the thing.","color":"slate","masters":["jnana","witnessing"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.2},"practiceLevels":{"jnana":1,"witnessing":1},"tags":["non-dual","not-yet"]}},{"id":"concept-only","label":"Concept only","short":"You know it well and have not met it","description":"The philosophy is familiar and the event has not arrived. This is a normal and slightly uncomfortable position, because the concept creates an expectation that the experience then fails to meet.","shadow":"Anticipating an event rather than living toward it.","color":"sky","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"thought":0.3,"spirit":0.25},"practiceLevels":{"jnana":1,"self-inquiry":1},"tags":["non-dual","conceptual"]}},{"id":"brief-glimpses","label":"Brief glimpses","short":"You have met it, briefly","description":"There have been real, unarguable flashes and they were short. The aftermath is the live question — what follows one determines whether there will be another.","shadow":"Wanting the next one before the last one has been understood.","color":"teal","masters":["witnessing","raja"],"calibration":{"dimensions":{"spirit":0.4,"emotion":0.2},"practiceLevels":{"witnessing":2},"tags":["non-dual","glimpsed"]}},{"id":"recurring","label":"Recurring","short":"It keeps coming back, and it takes something with it","description":"The glimpses recur and something is different afterwards each time. The difficulty has shifted from whether this is real to what a life organised around it actually looks like.","shadow":"Building a life around an experience rather than in it.","color":"indigo","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.45,"thought":0.2,"body":0.15},"practiceLevels":{"witnessing":2,"jnana":1},"tags":["non-dual","recurring"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["witnessing","jnana"],"deepens_with":["liberation-aim","meditation-depth"]}'::jsonb, 1, true, false, 100, now())
