  updated_at
) VALUES
    ('pancha-kosha', 'Pañca kośa', 'The five layers of self', 'yogic', 'witness', E'The Taittirīya Upaniṣad describes the self as five layers, each one wider than the last: the body, the breath, the mind, the knowing, and the bliss. They are not separate things — they are places where attention lands, and each one has its own texture and its own way of being noticed.\n\nThis asks which layer is most available to you right now, and which one is least. There is no prize at the far end of this one; the top layer is not better than the bottom, it is simply wider.', '🧅', 7, 6, '[{"id":"kosha-body","type":"choice","prompt":"How present is your body right now?","domain":"body","options":[{"label":"I am barely aware of it","value":"I am barely aware of it","weights":{"annamaya":0}},{"label":"I notice it when something draws my attention","value":"I notice it when something draws my attention","weights":{"annamaya":0.25}},{"label":"I am in it most of the time","value":"I am in it most of the time","weights":{"annamaya":0.5}},{"label":"I am present in it, and it is not a problem","value":"I am present in it, and it is not a problem","weights":{"annamaya":0.75}},{"label":"I am at home here, and it stays that way","value":"I am at home here, and it stays that way","weights":{"annamaya":1}}]},{"id":"kosha-breath","type":"choice","prompt":"How available is your breath?","domain":"breath","options":[{"label":"I cannot feel it without thinking about it","value":"I cannot feel it without thinking about it","weights":{"annamaya":1,"pranamaya":0,"manomaya":0,"vijnanamaya":0,"anandamaya":0}},{"label":"I can feel it, and it is shallow","value":"I can feel it, and it is shallow","weights":{"annamaya":0,"pranamaya":1,"manomaya":0,"vijnanamaya":0,"anandamaya":0}},{"label":"I can feel it, and follow it for a while","value":"I can feel it, and follow it for a while","weights":{"annamaya":0,"pranamaya":0,"manomaya":1,"vijnanamaya":0,"anandamaya":0}},{"label":"It is easy to find and easy to follow","value":"It is easy to find and easy to follow","weights":{"annamaya":0,"pranamaya":0,"manomaya":0,"vijnanamaya":1,"anandamaya":0}},{"label":"It is always there, and I do not have to look","value":"It is always there, and I do not have to look","weights":{"annamaya":0,"pranamaya":0,"manomaya":0,"vijnanamaya":0,"anandamaya":1}}]},{"id":"kosha-mind","type":"choice","prompt":"How loud is your mind right now?","domain":"mind","options":[{"label":"Quiet, and I can hear underneath","value":"Quiet, and I can hear underneath","weights":{"pranamaya":1,"manomaya":0,"vijnanamaya":0,"anandamaya":0}},{"label":"Mostly quiet, with the odd noise","value":"Mostly quiet, with the odd noise","weights":{"pranamaya":0.25,"manomaya":0.75,"vijnanamaya":0,"anandamaya":0}},{"label":"Busy, but I can step back from it","value":"Busy, but I can step back from it","weights":{"pranamaya":0,"manomaya":0.5,"vijnanamaya":0.5,"anandamaya":0}},{"label":"Loud, and I am caught in it","value":"Loud, and I am caught in it","weights":{"pranamaya":0,"manomaya":0,"vijnanamaya":0.75,"anandamaya":0.25}},{"label":"I cannot hear anything else","value":"I cannot hear anything else","weights":{"pranamaya":0,"manomaya":0,"vijnanamaya":0,"anandamaya":1}}]},{"id":"kosha-witness","type":"choice","prompt":"How easily can you step back from your own thinking?","domain":"witnessing","options":[{"label":"I cannot find a vantage point","value":"I cannot find a vantage point","weights":{"vijnanamaya":0}},{"label":"I can sometimes, when I remember","value":"I can sometimes, when I remember","weights":{"vijnanamaya":0.25}},{"label":"I can usually step back","value":"I can usually step back","weights":{"vijnanamaya":0.5}},{"label":"I can watch without effort","value":"I can watch without effort","weights":{"vijnanamaya":0.75}},{"label":"The watching is the larger part","value":"The watching is the larger part","weights":{"vijnanamaya":1}}]},{"id":"kosha-bliss","type":"choice","prompt":"How often do you feel part of something larger?","domain":"bliss","options":[{"label":"I rarely feel anything beyond myself","value":"I rarely feel anything beyond myself","weights":{"manomaya":1,"vijnanamaya":0,"anandamaya":0}},{"label":"Sometimes, without arranging it","value":"Sometimes, without arranging it","weights":{"manomaya":0.5,"vijnanamaya":0.5,"anandamaya":0}},{"label":"Often, and I can find it again","value":"Often, and I can find it again","weights":{"manomaya":0,"vijnanamaya":1,"anandamaya":0}},{"label":"It is ordinary, and I do not have to look","value":"It is ordinary, and I do not have to look","weights":{"manomaya":0,"vijnanamaya":0.5,"anandamaya":0.5}},{"label":"It is always here, underneath the noise","value":"It is always here, underneath the noise","weights":{"manomaya":0,"vijnanamaya":0,"anandamaya":1}}]},{"id":"kosha-shelter","type":"choice","prompt":"Which layer do you retreat to when things get hard?","domain":"shelter","options":[{"label":"I withdraw into my body — sleep, food, comfort","value":"I withdraw into my body — sleep, food, comfort","weights":{"annamaya":1}},{"label":"I hold my breath and narrow my focus","value":"I hold my breath and narrow my focus","weights":{"pranamaya":1}},{"label":"I go into my mind — planning, analysing, rehearsing","value":"I go into my mind — planning, analysing, rehearsing","weights":{"manomaya":1}},{"label":"I step back and watch, and something settles","value":"I step back and watch, and something settles","weights":{"vijnanamaya":1}},{"label":"I let go, and something wider holds me","value":"I let go, and something wider holds me","weights":{"anandamaya":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["annamaya","pranamaya","manomaya","vijnanamaya","anandamaya"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"annamaya","label":"Annamaya","short":"The body is the first word","description":"The outermost layer, the body, is where attention lives most of the time. This is not a failing — the body is the only honest layer, because it does not pretend to be anything else. What it means is that the mind is running mostly on physical input, and the layers above are not yet being consulted.","shadow":"Treating the body as the whole of what is available.","color":"slate","masters":["body","breath"],"calibration":{"dimensions":{"body":0.4,"emotion":0.2,"thought":0.1},"practiceLevels":{"body":2,"breath":1},"domainStress":{"physical":"body"},"tags":["body-anchored","sensory"]}},{"id":"pranamaya","label":"Prāṇamaya","short":"The breath is the bridge","description":"The breath layer is the hinge between body and mind, and it is the one most people can find without instruction. It is also the one most people manipulate without noticing — they breathe to calm down rather than to find out what is actually there.","shadow":"Using the breath to control rather than to feel.","color":"sky","masters":["breath","body"],"calibration":{"dimensions":{"body":0.3,"emotion":0.2,"spirit":0.2},"practiceLevels":{"breath":2,"body":1},"domainStress":{"breath":"breath"},"tags":["breath-anchored","transitional"]}},{"id":"manomaya","label":"Manomaya","short":"The mind is the talker","description":"The mind layer is where most people live, and it is a noisy place to live. The thinking is continuous, the self-narration never stops, and most decisions are made by the voice that is loudest rather than the one that is wisest.","shadow":"Identifying with the thinking and not knowing it is happening.","color":"orange","masters":["witnessing","self-inquiry"],"calibration":{"dimensions":{"thought":0.4,"emotion":0.25,"body":0.1},"practiceLevels":{"witnessing":1,"self-inquiry":1},"domainStress":{"mind":"witnessing"},"tags":["mind-anchored","noisy"]}},{"id":"vijnanamaya","label":"Vijñānamaya","short":"The knowing is the watcher","description":"The knowing layer is the one that can stand back and watch the mind think. It is not the thoughts themselves — it is the part of you that knows there are thoughts, and can choose whether to follow them.","shadow":"The watcher becoming another performer.","color":"indigo","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.3,"thought":0.25,"emotion":0.15},"practiceLevels":{"witnessing":2,"jnana":1},"domainStress":{"knowing":"jnana"},"tags":["witnessing","discriminating"]}},{"id":"anandamaya","label":"Ānandamaya","short":"The bliss is the absence of edges","description":"The top layer is not a feeling of happiness; it is the state of having no edges. It arrives when the other four have stopped running their separate shows, and it cannot be pursued — it can only be met when the noise has died down enough.","shadow":"Chasing a feeling that only arrives when it is not being chased.","color":"violet","masters":["witnessing","bhakti"],"calibration":{"dimensions":{"spirit":0.45,"connection":0.2,"emotion":0.1},"practiceLevels":{"witnessing":2,"bhakti":1},"domainStress":{"bliss":"bhakti"},"tags":["bliss-anchored","edgeless"]}}]'::jsonb, '{"loops_to_check":["over-thinking","avoidance-map"],"practice_affinity":["body","breath","witnessing"],"deepens_with":["witness-capacity","sensory-awareness"]}'::jsonb, 1, true, false, 100, now())
