) VALUES
    ('path-affinity', 'Path affinity', 'Which approach fits you', 'yogic', 'path', E'Four broad approaches have been carried forward because they work, not because they are the only ones. Bhakti is the path of care; jñāna is the path of understanding; karma is the path of action; rāja is the path of attention.\n\nNobody is only one of these, and nobody is wrong for being more of one than another. The question is which one is already doing the most work in your life, because that is the one most likely to respond to being named.', '🛤️', 6, 6, '[{"id":"path-draw","type":"choice","prompt":"When you read about practice, what draws you in?","domain":"attraction","options":[{"label":"Stories and figures that move me","value":"Stories and figures that move me","weights":{"bhakti":1}},{"label":"Ideas that make something click","value":"Ideas that make something click","weights":{"jnana":1}},{"label":"Things I can actually do","value":"Things I can actually do","weights":{"karma":1}},{"label":"States of attention I can taste","value":"States of attention I can taste","weights":{"raja":1}}]},{"id":"path-effort","type":"choice","prompt":"Which of these feels most like work?","domain":"effort","options":[{"label":"Opening myself to something larger","value":"Opening myself to something larger","weights":{"bhakti":1}},{"label":"Holding a question without reaching for an answer","value":"Holding a question without reaching for an answer","weights":{"jnana":1}},{"label":"Doing something for no reason other than it needs doing","value":"Doing something for no reason other than it needs doing","weights":{"karma":1}},{"label":"Sitting with attention without pulling it anywhere","value":"Sitting with attention without pulling it anywhere","weights":{"raja":1}}]},{"id":"path-sustain","type":"choice","prompt":"What keeps you going when practice gets hard?","domain":"sustaining","options":[{"label":"The feeling that something cares about this","value":"The feeling that something cares about this","weights":{"bhakti":1,"jnana":0,"karma":0,"raja":0}},{"label":"The sense that there is something to understand","value":"The sense that there is something to understand","weights":{"bhakti":0,"jnana":1,"karma":0,"raja":0}},{"label":"The knowledge that showing up is itself the practice","value":"The knowledge that showing up is itself the practice","weights":{"bhakti":0,"jnana":0,"karma":1,"raja":0}},{"label":"The memory of what it is like when attention lands","value":"The memory of what it is like when attention lands","weights":{"bhakti":0,"jnana":0,"karma":0,"raja":1}}]},{"id":"path-language","type":"choice","prompt":"Which language do you naturally reach for?","domain":"language","options":[{"label":"I surrender, I trust, I let go","value":"I surrender, I trust, I let go","weights":{"bhakti":1}},{"label":"I see, I understand, I question","value":"I see, I understand, I question","weights":{"jnana":1}},{"label":"I serve, I act, I offer","value":"I serve, I act, I offer","weights":{"karma":1}},{"label":"I witness, I return, I rest in attention","value":"I witness, I return, I rest in attention","weights":{"raja":1}}]},{"id":"path-resonance","type":"choice","prompt":"Which of these feels most like coming home?","domain":"resonance","options":[{"label":"A widening, a softening, a warmth","value":"A widening, a softening, a warmth","weights":{"bhakti":1,"jnana":0,"karma":0,"raja":0}},{"label":"A clarity, a distinction, a seeing-through","value":"A clarity, a distinction, a seeing-through","weights":{"bhakti":0,"jnana":1,"karma":0,"raja":0}},{"label":"A rightness, a fitness, a thing in its place","value":"A rightness, a fitness, a thing in its place","weights":{"bhakti":0,"jnana":0,"karma":1,"raja":0}},{"label":"A silence, a rest, a stopping","value":"A silence, a rest, a stopping","weights":{"bhakti":0,"jnana":0,"karma":0,"raja":1}}]},{"id":"path-natural","type":"choice","prompt":"What do you do without being asked?","domain":"natural","options":[{"label":"I reach for connection, or for something to believe in","value":"I reach for connection, or for something to believe in","weights":{"bhakti":1}},{"label":"I want to know, and I keep asking","value":"I want to know, and I keep asking","weights":{"jnana":1}},{"label":"I do the thing, and I feel better for having done it","value":"I do the thing, and I feel better for having done it","weights":{"karma":1}},{"label":"I sit, I watch, I come back","value":"I sit, I watch, I come back","weights":{"raja":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["bhakti","jnana","karma","raja"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"bhakti","label":"Bhakti","short":"The path of care","description":"Your natural orientation is toward something you can care about, and practice is sustained by the quality of that care. The strength is real: devotion produces a steadiness that no amount of effort can manufacture. The risk is that the object of care becomes more important than the caring.","shadow":"The object of devotion replacing the act of devoting.","color":"rose","masters":["bhakti","relationship"],"calibration":{"dimensions":{"connection":0.35,"emotion":0.3,"spirit":0.2},"practiceLevels":{"bhakti":2,"relationship":1},"domainStress":{"devotion":"bhakti"},"tags":["devotional","heart-centred"]}},{"id":"jnana","label":"Jñāna","short":"The path of understanding","description":"Your natural orientation is toward knowing, and practice is sustained by the pleasure of a thing becoming clear. The strength is discernment: you can tell a real insight from a persuasive story. The risk is that understanding becomes a substitute for doing.","shadow":"Knowing becoming a substitute for living.","color":"sky","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"thought":0.4,"spirit":0.25,"connection":0.15},"practiceLevels":{"jnana":2,"self-inquiry":1},"domainStress":{"knowing":"jnana"},"tags":["discriminating","seeing-through"]}},{"id":"karma","label":"Karma","short":"The path of action","description":"Your natural orientation is toward doing, and practice is sustained by the sense that action itself is the matter. The strength is reliability: you show up, you do the work, you do not wait for inspiration. The risk is that doing replaces being.","shadow":"Activity that has forgotten what it is acting for.","color":"amber","masters":["karma","raja"],"calibration":{"dimensions":{"action":0.4,"body":0.2,"thought":0.15},"practiceLevels":{"karma":2,"raja":1},"domainStress":{"doing":"karma"},"tags":["active","service-oriented"]}},{"id":"raja","label":"Rāja","short":"The path of attention","description":"Your natural orientation is toward the state of attention itself, and practice is sustained by the memory of what it is like when attention lands. The strength is depth: once attention is trained, nothing else needs to change. The risk is that the inward turn becomes a withdrawal.","shadow":"Attention turning into avoidance of what is being looked at.","color":"indigo","masters":["raja","witnessing"],"calibration":{"dimensions":{"spirit":0.35,"thought":0.25,"body":0.15},"practiceLevels":{"raja":2,"witnessing":1},"domainStress":{"attention":"raja"},"tags":["attentional","inward"]}}]'::jsonb, '{"loops_to_check":["drift","approval-seeking"],"practice_affinity":["bhakti","jnana","karma","raja"],"deepens_with":["inner-compass","work-dharma"]}'::jsonb, 1, true, false, 100, now())
