  updated_at
) VALUES
    ('persona-mask', 'Persona mask', 'The social self you wear', 'jungian', 'shadow', E'Jung used the word persona for the face presented to the world, and thought of it as a necessary adaptation rather than a deceit. A face is what allows a person to work, to belong, and to be spoken to without friction.\n\nThis is not about whether the face is a lie. It is about where the seam sits — between what is shown and what is underneath, whether the putting on is noticed, and what is left when the room empties.', '🎭', 6, 8, '[{"id":"mask-assembly","type":"choice","prompt":"With a new group of people, how soon do you start managing how you come across?","domain":"presentation","options":[{"label":"There is no performance — what people meet is what arrives","value":"There is no performance — what people meet is what arrives","weights":{"performative":0}},{"label":"Very little, and it is not something I think about","value":"Very little, and it is not something I think about","weights":{"performative":0.25}},{"label":"Some, in certain situations","value":"Some, in certain situations","weights":{"performative":0.5}},{"label":"More often than not, in most situations","value":"More often than not, in most situations","weights":{"performative":0.75}},{"label":"Continuously, and I am managing the impression most of the time","value":"Continuously, and I am managing the impression most of the time","weights":{"performative":1}}]},{"id":"mask-audience","type":"choice","prompt":"Do you behave differently depending on which people are in the room?","domain":"variation","options":[{"label":"The same with everybody","value":"The same with everybody","weights":{"merged":1,"performative":0,"conscious-mask":0,"porous":0}},{"label":"Nearly the same, with small differences","value":"Nearly the same, with small differences","weights":{"merged":0.25,"performative":0.75,"conscious-mask":0,"porous":0}},{"label":"Noticeably different from group to group","value":"Noticeably different from group to group","weights":{"merged":0,"performative":0.5,"conscious-mask":0.5,"porous":0}},{"label":"Markedly different, and I switch between them","value":"Markedly different, and I switch between them","weights":{"merged":0,"performative":0,"conscious-mask":0.75,"porous":0.25}},{"label":"I am effectively a different person in each group","value":"I am effectively a different person in each group","weights":{"merged":0,"performative":0,"conscious-mask":0,"porous":1}}]},{"id":"mask-noticed","type":"choice","prompt":"How often are you aware that you are playing a role while you are playing it?","domain":"awareness","options":[{"label":"I do not think about it at all","value":"I do not think about it at all","weights":{"conscious-mask":0}},{"label":"Only when someone points it out","value":"Only when someone points it out","weights":{"conscious-mask":0.25}},{"label":"Occasionally, usually afterwards","value":"Occasionally, usually afterwards","weights":{"conscious-mask":0.5}},{"label":"Most of the time, while it is happening","value":"Most of the time, while it is happening","weights":{"conscious-mask":0.75}},{"label":"It is one of the first things I notice","value":"It is one of the first things I notice","weights":{"conscious-mask":1}}]},{"id":"mask-mistaken","type":"choice","prompt":"Has anyone ever taken the version of you they met for the whole of you?","domain":"effect","options":[{"label":"People have taken the presentation for the whole person, and it stuck","value":"People have taken the presentation for the whole person, and it stuck","weights":{"merged":1}},{"label":"People have read more into me than was actually there","value":"People have read more into me than was actually there","weights":{"performative":1}},{"label":"People mostly meet the person underneath, once they look","value":"People mostly meet the person underneath, once they look","weights":{"conscious-mask":1}},{"label":"The two have never been confused","value":"The two have never been confused","weights":{"porous":1}}]},{"id":"mask-without","type":"choice","prompt":"Take the performance away. What is there?","domain":"alone","options":[{"label":"I genuinely do not know, and it unsettles me","value":"I genuinely do not know, and it unsettles me","weights":{"porous":0}},{"label":"Dropping it takes real effort, and often does not happen","value":"Dropping it takes real effort, and often does not happen","weights":{"porous":0.25}},{"label":"It takes a deliberate decision I rarely make","value":"It takes a deliberate decision I rarely make","weights":{"porous":0.5}},{"label":"I can set it down fairly easily","value":"I can set it down fairly easily","weights":{"porous":0.75}},{"label":"It comes off by itself, and the person underneath is unharmed","value":"It comes off by itself, and the person underneath is unharmed","weights":{"porous":1}}]},{"id":"mask-leak","type":"choice","prompt":"Has there ever been a moment when the person appeared unexpectedly?","domain":"porosity","options":[{"label":"It has never happened","value":"It has never happened","weights":{"porous":0}},{"label":"Rarely","value":"Rarely","weights":{"porous":0.25}},{"label":"Occasionally","value":"Occasionally","weights":{"porous":0.5}},{"label":"Often enough to be uncomfortable","value":"Often enough to be uncomfortable","weights":{"porous":0.75}},{"label":"Regularly, and I cannot predict when","value":"Regularly, and I cannot predict when","weights":{"porous":1}}]},{"id":"mask-deliberate","type":"choice","prompt":"Do you choose when to put the face on?","domain":"agency","options":[{"label":"It goes on and off by itself, without consulting me","value":"It goes on and off by itself, without consulting me","weights":{"performative":1,"conscious-mask":0,"porous":0}},{"label":"It responds to the situation almost immediately","value":"It responds to the situation almost immediately","weights":{"performative":0.25,"conscious-mask":0,"porous":0}},{"label":"With a little warning, I can influence it","value":"With a little warning, I can influence it","weights":{"performative":0,"conscious-mask":0.5,"porous":0}},{"label":"I can usually choose whether to use it","value":"I can usually choose whether to use it","weights":{"performative":0,"conscious-mask":0.75,"porous":0.25}},{"label":"I put it on deliberately, and take it off deliberately","value":"I put it on deliberately, and take it off deliberately","weights":{"performative":0,"conscious-mask":0,"porous":1}}]},{"id":"mask-rest","type":"choice","prompt":"How much does managing the impression take out of an ordinary day?","domain":"cost","options":[{"label":"Nothing I can detect","value":"Nothing I can detect","weights":{"performative":0}},{"label":"A little background effort","value":"A little background effort","weights":{"performative":0.25}},{"label":"A noticeable amount, most days","value":"A noticeable amount, most days","weights":{"performative":0.5}},{"label":"A great deal, and it is the largest thing I do","value":"A great deal, and it is the largest thing I do","weights":{"performative":0.75}},{"label":"So much that I arrive at the end of a day with almost nothing left","value":"So much that I arrive at the end of a day with almost nothing left","weights":{"performative":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["merged","performative","conscious-mask","porous"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"merged","label":"Merged","short":"No seam between the face and the person","description":"The presentation and the person have not come apart. Whatever a situation calls for, the response arrives from somewhere below choice, and there is no reliable way to tell which is which from the inside. This is the hardest position to examine, because the instrument being pointed at the face is itself part of the face.","shadow":"Reading spontaneity as freedom.","color":"slate","masters":["witnessing","self-inquiry"],"calibration":{"dimensions":{"connection":0.25,"thought":0.2,"spirit":0.15},"practiceLevels":{"witnessing":1,"self-inquiry":1},"domainStress":{"contact":"relationship"},"tags":["merged","unseparated"]}},{"id":"performative","label":"Performative","short":"The face is being managed all the time","description":"The impression is being produced most of the time, largely on autopilot, and the production takes a real share of the day. It works, which is why it persists — and the cost is paid in attention that never arrives anywhere else.","shadow":"Mistaking the room for the truth.","color":"rose","masters":["witnessing","self-inquiry"],"calibration":{"dimensions":{"connection":0.3,"thought":0.2,"emotion":0.15},"practiceLevels":{"witnessing":2},"domainStress":{"contact":"relationship"},"tags":["performative","image-maintained"]}},{"id":"conscious-mask","label":"Wearing it consciously","short":"The face is a tool, and the holding of it is visible","description":"The performance is noticed while it runs, and can be adjusted or set down. This is a workable relationship with the persona: the face is still there, but something is holding it, and what is holding it can be looked at.","shadow":"Watching the face become a second habit.","color":"amber","masters":["witnessing","self-inquiry"],"calibration":{"dimensions":{"connection":0.2,"thought":0.25,"spirit":0.15},"practiceLevels":{"witnessing":1,"self-inquiry":1},"tags":["conscious","awareness-of-mask"]}},{"id":"porous","label":"Porous","short":"The face comes off and the person survives it","description":"The mask can be put on and taken off deliberately, and the person underneath is not damaged by the taking off. The risk here is a different one: the face becomes optional, and optional faces are sometimes dropped at the moment they were needed.","shadow":"Authenticity used as a reason to stop adapting.","color":"teal","masters":["self-inquiry","witnessing"],"calibration":{"dimensions":{"connection":0.2,"spirit":0.3,"thought":0.15},"practiceLevels":{"self-inquiry":1,"witnessing":1},"tags":["porous","self-governed"]}}]'::jsonb, '{"loops_to_check":["people-pleasing","identity-diffusion"],"practice_affinity":["witnessing","self-inquiry"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
