  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('practice-level-calibration', 'Practice level', 'How far along the path you are', 'yogic', 'practice', E'Practice has a shape that is not the same as effort. Someone can be trying hard for a short time and be at the beginning, and someone can be doing very little for a long time and be much further along.\n\nFour positions are described here. They are not grades and they are not permanent: the reading is a description of today, and most people have been in at least two of them already.', '📈', 6, 6, '[{"id":"practice-duration","type":"choice","prompt":"How long have you been practising in some form?","domain":"time on the mat","options":[{"label":"A few weeks, if that","value":"A few weeks, if that","weights":{"beginner":1,"developing":0,"established":0,"deepening":0}},{"label":"A few months, with gaps","value":"A few months, with gaps","weights":{"beginner":0,"developing":1,"established":0,"deepening":0}},{"label":"A year or more, reasonably consistent","value":"A year or more, reasonably consistent","weights":{"beginner":0,"developing":0,"established":1,"deepening":0}},{"label":"Several years, and it has changed me","value":"Several years, and it has changed me","weights":{"beginner":0,"developing":0,"established":0,"deepening":1}}]},{"id":"practice-frequency","type":"choice","prompt":"How often does practice actually happen?","domain":"regularity","options":[{"label":"Rarely — it comes and goes","value":"Rarely — it comes and goes","weights":{"developing":0}},{"label":"Sometimes, when I feel like it","value":"Sometimes, when I feel like it","weights":{"developing":0.25}},{"label":"Most days, but not always","value":"Most days, but not always","weights":{"developing":0.5}},{"label":"Regularly, and I notice when it stops","value":"Regularly, and I notice when it stops","weights":{"developing":0.75}},{"label":"It is part of the day, like eating","value":"It is part of the day, like eating","weights":{"developing":1}}]},{"id":"practice-depth","type":"choice","prompt":"When you practise, how far in do you go?","domain":"depth","options":[{"label":"I am mostly going through the motions","value":"I am mostly going through the motions","weights":{"beginner":1,"developing":0,"established":0,"deepening":0}},{"label":"I settle a little, but it is shallow","value":"I settle a little, but it is shallow","weights":{"beginner":0.25,"developing":0.75,"established":0,"deepening":0}},{"label":"I can stay present for most of it","value":"I can stay present for most of it","weights":{"beginner":0,"developing":0.5,"established":0.5,"deepening":0}},{"label":"I lose track of time sometimes","value":"I lose track of time sometimes","weights":{"beginner":0,"developing":0,"established":0.75,"deepening":0.25}},{"label":"There are moments where I am not there at all","value":"There are moments where I am not there at all","weights":{"beginner":0,"developing":0,"established":0,"deepening":1}}]},{"id":"practice-integration","type":"choice","prompt":"How much of practice shows up outside the session?","domain":"off the mat","options":[{"label":"Almost none","value":"Almost none","weights":{"established":0}},{"label":"A little, sometimes","value":"A little, sometimes","weights":{"established":0.25}},{"label":"Some of it, most days","value":"Some of it, most days","weights":{"established":0.5}},{"label":"Most of it, without trying","value":"Most of it, without trying","weights":{"established":0.75}},{"label":"It is just how the day is organised","value":"It is just how the day is organised","weights":{"established":1}}]},{"id":"practice-resistance","type":"choice","prompt":"What happens when practice gets hard?","domain":"avoidance","options":[{"label":"I stop, and do not go back for a while","value":"I stop, and do not go back for a while","weights":{"beginner":1}},{"label":"I shorten it, and avoid the hard part","value":"I shorten it, and avoid the hard part","weights":{"developing":1}},{"label":"I stay, but I am not fully there","value":"I stay, but I am not fully there","weights":{"established":1}},{"label":"I go through it, and something shifts afterwards","value":"I go through it, and something shifts afterwards","weights":{"deepening":1}}]},{"id":"practice-witness","type":"choice","prompt":"How much of the practice is you watching yourself?","domain":"witnessing","options":[{"label":"I am doing it, and that is all","value":"I am doing it, and that is all","weights":{"beginner":1,"developing":0,"established":0,"deepening":0}},{"label":"I notice I am doing it","value":"I notice I am doing it","weights":{"beginner":0.25,"developing":0.75,"established":0,"deepening":0}},{"label":"I can watch while it is happening","value":"I can watch while it is happening","weights":{"beginner":0,"developing":0.5,"established":0.5,"deepening":0}},{"label":"The watching is the larger part","value":"The watching is the larger part","weights":{"beginner":0,"developing":0,"established":0.75,"deepening":0.25}},{"label":"There is no difference between the two","value":"There is no difference between the two","weights":{"beginner":0,"developing":0,"established":0,"deepening":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["beginner","developing","established","deepening"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"beginner","label":"Beginning","short":"The first genuine contact","description":"Practice has started, and the first thing noticed is how much is happening that was not seen before. This is not a weak position — it is the most honest one, because everything in it is new and unedited.","shadow":"Treating the first discoveries as the whole of what is available.","color":"slate","masters":["observation","body"],"calibration":{"dimensions":{"body":0.3,"thought":0.25,"emotion":0.15},"practiceLevels":{"observation":1,"body":1},"tags":["beginner","contact"]}},{"id":"developing","label":"Developing","short":"Building the habit of returning","description":"Practice is happening often enough to be a presence rather than an event. The work here is not depth but consistency — showing up when nothing interesting is happening, which is most of the time.","shadow":"Confusing regularity for understanding.","color":"amber","masters":["raja","witnessing"],"calibration":{"dimensions":{"action":0.3,"thought":0.2,"body":0.2},"practiceLevels":{"raja":1,"witnessing":1},"tags":["developing","consistent"]}},{"id":"established","label":"Established","short":"It is part of the architecture","description":"Practice has become a structure rather than an activity. It carries over into the day without being summoned, and the sessions have a depth that is not dependent on feeling inspired.","shadow":"Letting the structure replace the inquiry.","color":"sky","masters":["raja","kriya"],"calibration":{"dimensions":{"spirit":0.3,"body":0.25,"thought":0.2},"practiceLevels":{"raja":1,"kriya":1},"tags":["established","structural"]}},{"id":"deepening","label":"Deepening","short":"The surface has become transparent","description":"Practice is no longer something done; it is something lived. The sessions are quiet and uneventful from the outside, and from the inside they are the most direct thing that happens in a day.","shadow":"Treating depth as a permanent state rather than a recurring visit.","color":"violet","masters":["witnessing","self-inquiry"],"calibration":{"dimensions":{"spirit":0.35,"thought":0.25,"emotion":0.2},"practiceLevels":{"witnessing":2,"self-inquiry":1},"tags":["deepening","embodied"]}}]'::jsonb, '{"loops_to_check":["drift","avoidance-map"],"practice_affinity":["observation","self-inquiry","witnessing"],"deepens_with":["discipline-style","sankalpa-shakti"]}'::jsonb, 1, true, false, 100, now())
