-- Prāṇāyāma capacity (Patanjali)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('pranayama-capacity', 'Prāṇāyāma capacity', 'How you meet the breath', 'yogic', 'vitality', E'Prāṇāyāma is the fourth limb and, for most people, the first real obstacle. The difficulty is rarely breathwork itself — it is what happens when you try to control the one thing that has never stopped moving on its own.\n\nThis measures what actually happens when you intervene.', '🌬️', 6, 6, '[{"id":"prana-hold","type":"choice","prompt":"What happens when you try to hold your breath for ten seconds?","domain":"capacity","options":[{"label":"It is impossible, and uncomfortable quickly","value":"It is impossible, and uncomfortable quickly","weights":{"breath-only":1,"retention":0,"sama":0,"sushumna-aware":0}},{"label":"I can do it, but it fights me","value":"I can do it, but it fights me","weights":{"breath-only":0.25,"retention":0.75,"sama":0,"sushumna-aware":0}},{"label":"I can hold it comfortably","value":"I can hold it comfortably","weights":{"breath-only":0,"retention":0.5,"sama":0.5,"sushumna-aware":0}},{"label":"I can hold it and something interesting happens","value":"I can hold it and something interesting happens","weights":{"breath-only":0,"retention":0,"sama":0.75,"sushumna-aware":0.25}},{"label":"The breath holds itself","value":"The breath holds itself","weights":{"breath-only":0,"retention":0,"sama":0,"sushumna-aware":1}}]},{"id":"prana-lengthen","type":"choice","prompt":"Can you make your exhale longer than your inhale?","domain":"exhale","options":[{"label":"Not without a lot of strain","value":"Not without a lot of strain","weights":{"retention":0}},{"label":"For a short time, with effort","value":"For a short time, with effort","weights":{"retention":0.25}},{"label":"Yes, fairly comfortably","value":"Yes, fairly comfortably","weights":{"retention":0.5}},{"label":"Yes, and it settles me noticeably","value":"Yes, and it settles me noticeably","weights":{"retention":0.75}},{"label":"Yes, and the breath starts to move itself","value":"Yes, and the breath starts to move itself","weights":{"retention":1}}]},{"id":"prana-spine","type":"choice","prompt":"Do you feel anything along your spine when you work with the breath?","domain":"sushumna","options":[{"label":"No, nothing at all","value":"No, nothing at all","weights":{"breath-only":1,"retention":0,"sama":0,"sushumna-aware":0}},{"label":"Something, but I cannot place it","value":"Something, but I cannot place it","weights":{"breath-only":0.25,"retention":0.75,"sama":0,"sushumna-aware":0}},{"label":"A sensation, low down","value":"A sensation, low down","weights":{"breath-only":0,"retention":0.5,"sama":0.5,"sushumna-aware":0}},{"label":"A clear line, sometimes","value":"A clear line, sometimes","weights":{"breath-only":0,"retention":0,"sama":0.75,"sushumna-aware":0.25}},{"label":"A distinct current I can follow","value":"A distinct current I can follow","weights":{"breath-only":0,"retention":0,"sama":0,"sushumna-aware":1}}]},{"id":"prana-dizzy","type":"choice","prompt":"Does breathwork ever make you lightheaded or anxious?","domain":"response","options":[{"label":"I have never tried","value":"I have never tried","weights":{"breath-only":1}},{"label":"Only slightly, and briefly","value":"Only slightly, and briefly","weights":{"breath-only":1}},{"label":"Yes, fairly reliably","value":"Yes, fairly reliably","weights":{"breath-only":1}},{"label":"Yes, and it is uncomfortable","value":"Yes, and it is uncomfortable","weights":{"breath-only":1}},{"label":"I avoid it for that reason","value":"I avoid it for that reason","weights":{"breath-only":1}}]},{"id":"prana-after","type":"choice","prompt":"How do you feel in the twenty minutes after real breathwork?","domain":"settling","options":[{"label":"Wired, or worse than before","value":"Wired, or worse than before","weights":{"sama":0}},{"label":"About the same","value":"About the same","weights":{"sama":0.25}},{"label":"A little steadier","value":"A little steadier","weights":{"sama":0.5}},{"label":"Clearly calmer for a while","value":"Clearly calmer for a while","weights":{"sama":0.75}},{"label":"Calmer for the rest of the day","value":"Calmer for the rest of the day","weights":{"sama":1}}]},{"id":"prana-effort","type":"choice","prompt":"How does the practice feel — is it something you do to your breath, or with it?","domain":"relationship","options":[{"label":"I force it, and it resists","value":"I force it, and it resists","weights":{"sama":1}},{"label":"I control it more than it moves me","value":"I control it more than it moves me","weights":{"sama":1}},{"label":"It is somewhere in between","value":"It is somewhere in between","weights":{"sama":1}},{"label":"We move together","value":"We move together","weights":{"sama":1}},{"label":"I am watching something that happens","value":"I am watching something that happens","weights":{"sama":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["breath-only","retention","sama","sushumna-aware"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"breath-only","label":"Breath only","short":"You are working with the breath as breath","description":"The breath is still just air, and intervening in it is effortful. This is the completely ordinary starting point and there is nothing wrong with it — prāṇāyāma becomes useful long after the sensation changes.","shadow":"Reading effort as a sign you are doing it wrong.","color":"slate","masters":["breath","body"],"calibration":{"dimensions":{"body":0.35,"thought":0.15},"practiceLevels":{"breath":1,"body":1},"tags":["prana","beginning"]}},{"id":"retention","label":"Retention is available","short":"You can hold and lengthen","description":"You have real capacity with retention and the longer exhale. The breath is still something you do, rather than something that happens — but the mechanism is working.","shadow":"Pushing the retention further than it needs to go.","color":"amber","masters":["breath","raja"],"calibration":{"dimensions":{"body":0.3,"spirit":0.2},"practiceLevels":{"breath":2},"tags":["prana","retention-works"]}},{"id":"sama","label":"Sāma — the steadiness","short":"It works, and you can feel it working","description":"The practice does what it is supposed to do: it settles the system and the settling lasts. This is the fourth limb doing its actual job.","shadow":"Using the calm to keep going rather than to rest.","color":"teal","masters":["breath","raja"],"calibration":{"dimensions":{"body":0.3,"spirit":0.3,"emotion":0.2},"practiceLevels":{"breath":2,"raja":1},"tags":["prana","steadying"]}},{"id":"sushumna-aware","label":"The central channel is available","short":"There is something there, and you can follow it","description":"You have direct experience of a central current and can work with it. The tradition calls this the sushumnā. Practically, it means the breath is giving you somewhere to go, not just something to regulate.","shadow":"Chasing the sensation once it has become familiar.","color":"indigo","masters":["kriya","raja"],"calibration":{"dimensions":{"spirit":0.4,"body":0.25},"practiceLevels":{"kriya":1,"raja":1},"tags":["prana","subtle"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["breath","kriya"],"deepens_with":["breath-pattern","meditation-depth"]}'::jsonb, 1, true, false, 100, now())
