-- Presence quality (Observation)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('presence-quality', 'Presence quality', 'How much of you is here', 'vedic', 'witness', E'Presence is usually described as a single state, present or absent, and it is easier to use as a way of being dissatisfied with yourself than as a description of anything. Most people are in a third place: enough of them is here to function and not enough to be satisfied.\n\nThe four positions here are about quantity and continuity rather than quality. The one that matters most is not the amount of presence available but how easily the missing part comes back once it has gone.', '⏳', 6, 6, '[{"id":"presence-location","type":"choice","prompt":"While you are doing the thing you are doing, where is most of you?","domain":"location","options":[{"label":"Wherever the loudest thing is","value":"Wherever the loudest thing is","weights":{"scattered":1,"fragmented":0,"mostly-here":0,"fully-here":0}},{"label":"In the task, with a piece of me somewhere else","value":"In the task, with a piece of me somewhere else","weights":{"scattered":0,"fragmented":1,"mostly-here":0,"fully-here":0}},{"label":"In the task, properly","value":"In the task, properly","weights":{"scattered":0,"fragmented":0,"mostly-here":1,"fully-here":0}},{"label":"In the task and in the body doing it","value":"In the task and in the body doing it","weights":{"scattered":0,"fragmented":0,"mostly-here":0,"fully-here":1}}]},{"id":"presence-return","type":"choice","prompt":"Something pulls you away. How long before you are back?","domain":"return","options":[{"label":"I do not come back that day","value":"I do not come back that day","weights":{"scattered":1,"fragmented":0,"mostly-here":0,"fully-here":0}},{"label":"An hour or two, if I notice at all","value":"An hour or two, if I notice at all","weights":{"scattered":0,"fragmented":1,"mostly-here":0,"fully-here":0}},{"label":"A few minutes","value":"A few minutes","weights":{"scattered":0,"fragmented":0,"mostly-here":1,"fully-here":0}},{"label":"Almost at once","value":"Almost at once","weights":{"scattered":0,"fragmented":0,"mostly-here":0,"fully-here":1}}]},{"id":"presence-others","type":"choice","prompt":"In the middle of a conversation, how much of you is actually there?","domain":"others","options":[{"label":"All of it, including the parts I would rather keep back","value":"All of it, including the parts I would rather keep back","weights":{"fragmented":0}},{"label":"Most of me","value":"Most of me","weights":{"fragmented":0.25}},{"label":"About half","value":"About half","weights":{"fragmented":0.5}},{"label":"A little of it","value":"A little of it","weights":{"fragmented":0.75}},{"label":"None of it — I am elsewhere for most of it","value":"None of it — I am elsewhere for most of it","weights":{"fragmented":1}}]},{"id":"presence-wait","type":"choice","prompt":"You are waiting for something. What happens?","domain":"waiting","options":[{"label":"It is uncomfortable and I fill it","value":"It is uncomfortable and I fill it","weights":{"scattered":1}},{"label":"I check my phone and stay half in the moment","value":"I check my phone and stay half in the moment","weights":{"fragmented":1}},{"label":"I let the wait be a wait","value":"I let the wait be a wait","weights":{"mostly-here":1}},{"label":"The wait becomes interesting in itself","value":"The wait becomes interesting in itself","weights":{"fully-here":1}}]},{"id":"presence-night","type":"choice","prompt":"In the moment before sleep, where is most of you?","domain":"night","options":[{"label":"Racing through the day, unfinished","value":"Racing through the day, unfinished","weights":{"scattered":1,"fragmented":0,"mostly-here":0,"fully-here":0}},{"label":"Still in the last conversation","value":"Still in the last conversation","weights":{"scattered":0,"fragmented":1,"mostly-here":0,"fully-here":0}},{"label":"In the body at last, and quiet","value":"In the body at last, and quiet","weights":{"scattered":0,"fragmented":0,"mostly-here":1,"fully-here":0}},{"label":"Wide open, and not going anywhere","value":"Wide open, and not going anywhere","weights":{"scattered":0,"fragmented":0,"mostly-here":0,"fully-here":1}}]},{"id":"presence-gap","type":"choice","prompt":"How often do you suddenly realise you were somewhere else?","domain":"gap","options":[{"label":"Several times an hour","value":"Several times an hour","weights":{"scattered":1,"fragmented":0,"mostly-here":0,"fully-here":0}},{"label":"A few times a day","value":"A few times a day","weights":{"scattered":0,"fragmented":1,"mostly-here":0,"fully-here":0}},{"label":"A few times a week","value":"A few times a week","weights":{"scattered":0,"fragmented":0,"mostly-here":1,"fully-here":0}},{"label":"Almost never","value":"Almost never","weights":{"scattered":0,"fragmented":0,"mostly-here":0,"fully-here":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["scattered","fragmented","mostly-here","fully-here"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"scattered","label":"Scattered","short":"Most of you is somewhere else","description":"Attention is being taken more than given, and the loudest input in the room is the one that gets the hours. This is a description of an overloaded nervous system rather than of a character, and it responds quickly to any change in what comes in. Almost nothing else moves as fast.","shadow":"Reading the overload as evidence that there is not enough of you to go around.","color":"rose","masters":["observation","breath"],"calibration":{"dimensions":{"thought":0.3,"body":0.15,"emotion":0.15},"practiceLevels":{"observation":1,"breath":1},"domainStress":{"attention":"observation"},"tags":["scattered","dispersed"]}},{"id":"fragmented","label":"Fragmented","short":"Here and there, in pieces","description":"A workable amount of you is present and a working amount is not, and the split is invisible from the inside. This is a very common shape and it is mostly a load problem — the fragmentation points at how many things are being held, not at any failure of attention. It resolves when the load does, and it does not resolve by trying harder to concentrate.","shadow":"Treating a load problem as a discipline problem.","color":"amber","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.25,"emotion":0.2,"body":0.15},"practiceLevels":{"observation":1,"witnessing":1},"tags":["partial","split"]}},{"id":"mostly-here","label":"Mostly here","short":"Present, with a residue elsewhere","description":"Most of you is in the room and a background part is still running something else — usually the day that has not been dealt with yet. This is the most workable position in the set, and the residue is usually identifiable if you look for it. It shrinks with attention and grows with an unclosed day.","shadow":"Calling the residue part of your personality.","color":"teal","masters":["witnessing","breath"],"calibration":{"dimensions":{"spirit":0.3,"body":0.2,"emotion":0.15},"practiceLevels":{"witnessing":1,"breath":1},"tags":["mostly-present","residual"]}},{"id":"fully-here","label":"Fully here","short":"The whole of you is in the moment","description":"The whole of you arrives, including the parts that would rather stay folded away. This is a genuine attainment and it is not comfortable to live in permanently — full presence in one place means the other places go unfilled, and the people who are not in front of you are the ones paying for it.","shadow":"Absence in the room mistaken for depth elsewhere.","color":"indigo","masters":["witnessing","raja"],"calibration":{"dimensions":{"spirit":0.45,"body":0.15},"practiceLevels":{"witnessing":2,"raja":1},"domainStress":{"contact":"relationship"},"tags":["fully-present","whole"]}}]'::jsonb, '{"loops_to_check":["rumination","attention-drift"],"practice_affinity":["observation","breath","witnessing"],"deepens_with":["witness-capacity","attention-diet"]}'::jsonb, 1, true, false, 100, now())
