-- Purpose mirror (Launch)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('purpose-mirror', 'Purpose mirror', 'Why you are here, in your own words', 'vedic', 'action', E'Four things drive most lives: keeping a floor under things, belonging to something, getting good at something, and mattering in some way. They are not opposites, and nearly everyone runs all four at once.\n\nThis asks which one is actually in charge — not the one that sounds best in an interview, and not the one that appears on a list of values.', '🕯️', 6, 7, E'[{"id":"purpose-driver","type":"choice","prompt":"Finish the sentence \\"I am here to\\" — with the first honest answer.","domain":"driver","options":[{"label":"Stay above water","value":"Stay above water","weights":{"survival":1}},{"label":"Belong to something","value":"Belong to something","weights":{"belonging":1}},{"label":"Get genuinely good at something","value":"Get genuinely good at something","weights":{"mastery":1}},{"label":"Matter in some way","value":"Matter in some way","weights":{"meaning":1}}]},{"id":"purpose-complaint","type":"choice","prompt":"What do you complain about most?","domain":"friction","options":[{"label":"That there is never quite enough","value":"That there is never quite enough","weights":{"survival":1}},{"label":"That I am doing this mostly on my own","value":"That I am doing this mostly on my own","weights":{"belonging":1}},{"label":"That I am not actually getting anywhere","value":"That I am not actually getting anywhere","weights":{"mastery":1}},{"label":"That none of it is leading anywhere I would count","value":"That none of it is leading anywhere I would count","weights":{"meaning":1}}]},{"id":"purpose-money","type":"choice","prompt":"If money stopped mattering, would you still be doing this?","domain":"test","options":[{"label":"No — none of it","value":"No — none of it","weights":{"meaning":0}},{"label":"Only the parts I happen to enjoy","value":"Only the parts I happen to enjoy","weights":{"meaning":0.25}},{"label":"Some of it, honestly","value":"Some of it, honestly","weights":{"meaning":0.5}},{"label":"Most of it","value":"Most of it","weights":{"meaning":0.75}},{"label":"Yes, entirely","value":"Yes, entirely","weights":{"meaning":1}}]},{"id":"purpose-duty","type":"choice","prompt":"How much of what you do is for the people in your life?","domain":"obligation","options":[{"label":"Very little — it is mine","value":"Very little — it is mine","weights":{"belonging":0}},{"label":"Some of it","value":"Some of it","weights":{"belonging":0.25}},{"label":"A fair amount","value":"A fair amount","weights":{"belonging":0.5}},{"label":"Most of it","value":"Most of it","weights":{"belonging":0.75}},{"label":"They are the reason; I would not be doing this otherwise","value":"They are the reason; I would not be doing this otherwise","weights":{"belonging":1}}]},{"id":"purpose-craft","type":"choice","prompt":"How much time do you put into getting genuinely better at something?","domain":"craft","options":[{"label":"Almost none","value":"Almost none","weights":{"mastery":0}},{"label":"A little, when I feel like it","value":"A little, when I feel like it","weights":{"mastery":0.25}},{"label":"A fair amount","value":"A fair amount","weights":{"mastery":0.5}},{"label":"Most of my free time","value":"Most of my free time","weights":{"mastery":0.75}},{"label":"It is most of what I do","value":"It is most of what I do","weights":{"mastery":1}}]},{"id":"purpose-surplus","type":"choice","prompt":"If you had more money than you needed, what would you do with it?","domain":"sufficiency","options":[{"label":"I genuinely have no idea","value":"I genuinely have no idea","weights":{"meaning":0}},{"label":"Something ordinary, for security","value":"Something ordinary, for security","weights":{"meaning":0.25}},{"label":"The people I am responsible for","value":"The people I am responsible for","weights":{"meaning":0.5}},{"label":"The work, because that is what I do with anything spare","value":"The work, because that is what I do with anything spare","weights":{"meaning":0.75}},{"label":"Something that would outlast me — and I already know what","value":"Something that would outlast me — and I already know what","weights":{"meaning":1}}]},{"id":"purpose-horizon","type":"choice","prompt":"How far ahead does what you are building actually reach?","domain":"horizon","options":[{"label":"To the end of this month","value":"To the end of this month","weights":{"survival":1,"belonging":0,"mastery":0,"meaning":0}},{"label":"To the end of this year","value":"To the end of this year","weights":{"survival":0,"belonging":1,"mastery":0,"meaning":0}},{"label":"To whatever I can build in the time I have","value":"To whatever I can build in the time I have","weights":{"survival":0,"belonging":0,"mastery":1,"meaning":0}},{"label":"To something that will still be standing when I am not","value":"To something that will still be standing when I am not","weights":{"survival":0,"belonging":0,"mastery":0,"meaning":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["survival","belonging","mastery","meaning"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"survival","label":"Keeping the floor","short":"Security is doing most of the work","description":"Most of your energy goes into keeping things where they are. That is not a small achievement and it is frequently the ground other people stand on — but a life run entirely from the floor does not have much in it to climb towards.","shadow":"Mistaking the fact that it is stable for evidence that it is right.","color":"slate","masters":["karma","raja"],"calibration":{"dimensions":{"action":0.3,"body":0.2,"thought":0.15},"practiceLevels":{"karma":1,"raja":1},"domainStress":{"security":"finance"},"tags":["survival","security-led"]}},{"id":"belonging","label":"Belonging","short":"The people are the point","description":"Your direction is organised around other people — their needs, their opinion, their presence. This is a real source of meaning and a real source of drag, because the centre of the plan is not yours and moves around.","shadow":"Losing your own line inside the one you are holding for everyone.","color":"sky","masters":["relationship","bhakti"],"calibration":{"dimensions":{"connection":0.35,"action":0.2,"emotion":0.2},"practiceLevels":{"relationship":1,"bhakti":1},"domainStress":{"belonging":"relationship"},"tags":["belonging","other-referenced"]}},{"id":"mastery","label":"Mastery","short":"Getting good is the engine","description":"You are running toward competence. The engine is real and reliable, and the interesting question at this stage is whether the skill is being built toward something or simply accumulated.","shadow":"Mistaking the improvement for the point of it.","color":"amber","masters":["karma","raja"],"calibration":{"dimensions":{"action":0.35,"thought":0.2,"body":0.15},"practiceLevels":{"karma":1,"raja":1},"domainStress":{"craft":"work-career"},"tags":["mastery","craft-led"]}},{"id":"meaning","label":"Meaning","short":"It has to go somewhere","description":"You are working toward something that is meant to outlast the working. This orientation sustains effort over years and can also make ordinary maintenance very hard to prioritise, since maintenance does not obviously contribute.","shadow":"Meaning as a reason to keep postponing the practical part.","color":"violet","masters":["jnana","bhakti"],"calibration":{"dimensions":{"spirit":0.35,"action":0.2,"connection":0.15},"practiceLevels":{"jnana":1,"bhakti":1},"domainStress":{"calling":"work-career"},"tags":["meaning","long-horizon"]}}]'::jsonb, '{"loops_to_check":["drift","approval-seeking"],"practice_affinity":["karma","self-inquiry"],"deepens_with":["inner-compass","work-dharma","legacy-question"]}'::jsonb, 1, true, false, 100, now())
