-- Raja access (4 Yogas)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('raja-access', 'Raja access', 'Your inner control room', 'yogic', 'path', E'Rāja yoga is the discipline of the mind itself — of governing the machinery rather than being carried by it.\n\nThe question is not whether you are in control. It is whether you are in control of the thing you think you are controlling.', '👑', 6, 6, '[{"id":"raja-decider","type":"choice","prompt":"In a moment of real pressure, who decides?","domain":"authority","options":[{"label":"I do not know until after","value":"I do not know until after","weights":{"free-running":1}},{"label":"Something in me reacts first, and I follow it","value":"Something in me reacts first, and I follow it","weights":{"free-running":1}},{"label":"I catch myself, but not always","value":"I catch myself, but not always","weights":{"free-running":1}},{"label":"I catch myself, and I choose","value":"I catch myself, and I choose","weights":{"free-running":1}},{"label":"I choose without having to catch myself","value":"I choose without having to catch myself","weights":{"free-running":1}}]},{"id":"raja-disrupt","type":"choice","prompt":"What most reliably takes the controls off you?","domain":"disruption","options":[{"label":"Hunger or poor sleep","value":"Hunger or poor sleep","weights":{"unregulated":1}},{"label":"A specific person","value":"A specific person","weights":{"unregulated":1}},{"label":"Being rushed or judged","value":"Being rushed or judged","weights":{"unregulated":1}},{"label":"Unexpected news","value":"Unexpected news","weights":{"unregulated":1}},{"label":"Nothing — it is genuinely stable","value":"Nothing — it is genuinely stable","weights":{"unregulated":1}}]},{"id":"raja-effort","type":"choice","prompt":"Does steering feel like effort, or like driving?","domain":"effort","options":[{"label":"Constantly effortful","value":"Constantly effortful","weights":{"unregulated":1,"partly-governed":0,"mostly-governed":0,"free-running":0}},{"label":"Usually effortful","value":"Usually effortful","weights":{"unregulated":0.25,"partly-governed":0.75,"mostly-governed":0,"free-running":0}},{"label":"Effortful, then it settles","value":"Effortful, then it settles","weights":{"unregulated":0,"partly-governed":0.5,"mostly-governed":0.5,"free-running":0}},{"label":"Fairly easy","value":"Fairly easy","weights":{"unregulated":0,"partly-governed":0,"mostly-governed":0.75,"free-running":0.25}},{"label":"It is simply how I operate","value":"It is simply how I operate","weights":{"unregulated":0,"partly-governed":0,"mostly-governed":0,"free-running":1}}]},{"id":"raja-release","type":"choice","prompt":"What happens if you deliberately let go of control for an hour?","domain":"surrender","options":[{"label":"It is frightening, and I do not do it","value":"It is frightening, and I do not do it","weights":{"unregulated":1,"partly-governed":0,"mostly-governed":0,"free-running":0}},{"label":"It is uncomfortable, so I avoid it","value":"It is uncomfortable, so I avoid it","weights":{"unregulated":0.25,"partly-governed":0.75,"mostly-governed":0,"free-running":0}},{"label":"It is neutral, and mildly interesting","value":"It is neutral, and mildly interesting","weights":{"unregulated":0,"partly-governed":0.5,"mostly-governed":0.5,"free-running":0}},{"label":"It is genuinely restful","value":"It is genuinely restful","weights":{"unregulated":0,"partly-governed":0,"mostly-governed":0.75,"free-running":0.25}},{"label":"I do it regularly and it is where I am most myself","value":"I do it regularly and it is where I am most myself","weights":{"unregulated":0,"partly-governed":0,"mostly-governed":0,"free-running":1}}]},{"id":"raja-return","type":"choice","prompt":"After the controls have been off, how long to get them back?","domain":"recovery","options":[{"label":"I do not always get them back","value":"I do not always get them back","weights":{"unregulated":1,"partly-governed":0,"mostly-governed":0,"free-running":0}},{"label":"It takes most of the day","value":"It takes most of the day","weights":{"unregulated":0.25,"partly-governed":0.75,"mostly-governed":0,"free-running":0}},{"label":"Within an hour","value":"Within an hour","weights":{"unregulated":0,"partly-governed":0.5,"mostly-governed":0.5,"free-running":0}},{"label":"Within a few minutes","value":"Within a few minutes","weights":{"unregulated":0,"partly-governed":0,"mostly-governed":0.75,"free-running":0.25}},{"label":"Immediately, automatically","value":"Immediately, automatically","weights":{"unregulated":0,"partly-governed":0,"mostly-governed":0,"free-running":1}}]},{"id":"raja-trust","type":"choice","prompt":"How much do you trust your own judgement under pressure?","domain":"reliance","options":[{"label":"I do not trust it at all","value":"I do not trust it at all","weights":{"unregulated":1,"partly-governed":0,"mostly-governed":0,"free-running":0}},{"label":"Not very much","value":"Not very much","weights":{"unregulated":0.25,"partly-governed":0.75,"mostly-governed":0,"free-running":0}},{"label":"Generally","value":"Generally","weights":{"unregulated":0,"partly-governed":0.5,"mostly-governed":0.5,"free-running":0}},{"label":"Quite a lot","value":"Quite a lot","weights":{"unregulated":0,"partly-governed":0,"mostly-governed":0.75,"free-running":0.25}},{"label":"Completely, which is its own risk","value":"Completely, which is its own risk","weights":{"unregulated":0,"partly-governed":0,"mostly-governed":0,"free-running":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["unregulated","partly-governed","mostly-governed","free-running"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"unregulated","label":"Unregulated","short":"The mind drives, and you are along for it","description":"There is more steering happening than actual steering. This is worth naming without judgement: the system you are hoping to control is the same one doing the hoping.","shadow":"Believing the intention to govern is the governing.","color":"rose","masters":["breath","observation"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.25,"spirit":0.15},"practiceLevels":{"breath":1,"observation":1},"tags":["raja","reactive"]}},{"id":"partly-governed","label":"Partly governed","short":"You catch it, more often than not","description":"You intervene. It works often enough to be encouraging and unreliably enough to be frustrating, and the catching is effortful rather than automatic.","shadow":"Catching the reaction instead of the condition that produces it.","color":"amber","masters":["raja","witnessing"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.2,"body":0.15},"practiceLevels":{"raja":1,"witnessing":1},"tags":["raja","governing"]}},{"id":"mostly-governed","label":"Mostly governed","short":"You steer, and the steering holds","description":"Real governance, and it is reliable enough that you trust it. The remaining question is the harder one: what is the point of steering this particular vehicle?","shadow":"Governing without ever having asked what for.","color":"teal","masters":["raja","karma"],"calibration":{"dimensions":{"thought":0.2,"action":0.3,"spirit":0.25},"practiceLevels":{"raja":2,"karma":1},"tags":["raja","steady"]}},{"id":"free-running","label":"Free-running","short":"Governing without gripping","description":"The controls are there when needed and not in your hands the rest of the time. This is the mature form — the risk here is not loss of control but subtle pride in holding it.","shadow":"Identifiying with the one who steers.","color":"emerald","masters":["raja","witnessing"],"calibration":{"dimensions":{"spirit":0.4,"thought":0.2,"action":0.15},"practiceLevels":{"raja":2,"witnessing":1},"tags":["raja","free"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["raja","breath"],"deepens_with":["reactivity-score","meditation-depth"]}'::jsonb, 1, true, false, 100, now())
