-- Reactivity score (Loops)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('reactivity-score', 'Reactivity score', 'The gap between trigger and act', 'yogic', 'shadow', E'Almost all of the practice in this app lives in the interval between feeling something and doing something about it. That interval can be measured, and it can be lengthened.\n\nThis is a measurement of that gap, together with what occupies it, what interrupts it, and whether the same reaction can be slowed.', '⏱️', 6, 8, '[{"id":"react-gap","type":"choice","prompt":"How much time passes between feeling something and acting on it?","domain":"interval","options":[{"label":"None at all — feeling and acting are one event","value":"None at all — feeling and acting are one event","weights":{"instant":0,"delayed":0,"considered":0,"chosen":0}},{"label":"A fraction of a second","value":"A fraction of a second","weights":{"instant":1,"delayed":0,"considered":0,"chosen":0}},{"label":"A second or two","value":"A second or two","weights":{"instant":0,"delayed":1,"considered":0,"chosen":0}},{"label":"A few seconds","value":"A few seconds","weights":{"instant":0,"delayed":0,"considered":1,"chosen":0}},{"label":"I can hold it for as long as it takes","value":"I can hold it for as long as it takes","weights":{"instant":0,"delayed":0,"considered":0,"chosen":1}}]},{"id":"react-memory","type":"choice","prompt":"Do you remember the reaction afterwards?","domain":"memory","options":[{"label":"I remember it clearly and in detail","value":"I remember it clearly and in detail","weights":{"instant":0}},{"label":"I remember the general shape of it","value":"I remember the general shape of it","weights":{"instant":0.25}},{"label":"I remember that something happened","value":"I remember that something happened","weights":{"instant":0.5}},{"label":"Only when somebody mentions it","value":"Only when somebody mentions it","weights":{"instant":0.75}},{"label":"I genuinely do not remember most of it","value":"I genuinely do not remember most of it","weights":{"instant":1}}]},{"id":"react-body","type":"choice","prompt":"What happens in the body before the mind has decided anything?","domain":"somatic","options":[{"label":"Nothing physical at all","value":"Nothing physical at all","weights":{"instant":0}},{"label":"A little tension, easy to miss","value":"A little tension, easy to miss","weights":{"instant":0.25}},{"label":"The chest, jaw or gut, quite fast","value":"The chest, jaw or gut, quite fast","weights":{"instant":0.5}},{"label":"A strong, unmistakable surge before I have thought anything","value":"A strong, unmistakable surge before I have thought anything","weights":{"instant":0.75}},{"label":"A full change in the body that arrives ahead of the feeling itself","value":"A full change in the body that arrives ahead of the feeling itself","weights":{"instant":1}}]},{"id":"react-shape","type":"choice","prompt":"How consistently does it take the same form?","domain":"form","options":[{"label":"I react and only look at it afterwards","value":"I react and only look at it afterwards","weights":{"considered":0}},{"label":"I react, and then start checking myself part way through","value":"I react, and then start checking myself part way through","weights":{"considered":0.25}},{"label":"I catch myself and still do it","value":"I catch myself and still do it","weights":{"considered":0.5}},{"label":"I pause and choose the response, though the choice is often automatic","value":"I pause and choose the response, though the choice is often automatic","weights":{"considered":0.75}},{"label":"I hold long enough to choose properly","value":"I hold long enough to choose properly","weights":{"considered":1}}]},{"id":"react-interrupt","type":"choice","prompt":"Does anything interrupt it?","domain":"brake","options":[{"label":"Nothing gets in the way","value":"Nothing gets in the way","weights":{"delayed":0,"considered":0,"chosen":0}},{"label":"Only real pain, or real fear","value":"Only real pain, or real fear","weights":{"delayed":1,"considered":0,"chosen":0}},{"label":"A habit of counting or breathing, if I remember it","value":"A habit of counting or breathing, if I remember it","weights":{"delayed":0,"considered":1,"chosen":0}},{"label":"Usually something — a question, a look, a rule I set myself","value":"Usually something — a question, a look, a rule I set myself","weights":{"delayed":0,"considered":0,"chosen":0}},{"label":"Most of the time, and quickly","value":"Most of the time, and quickly","weights":{"delayed":0,"considered":0,"chosen":1}}]},{"id":"react-regret","type":"choice","prompt":"How often do you regret the reaction afterwards?","domain":"after","options":[{"label":"Never","value":"Never","weights":{"instant":0}},{"label":"Rarely","value":"Rarely","weights":{"instant":0.25}},{"label":"Sometimes","value":"Sometimes","weights":{"instant":0.5}},{"label":"Most times","value":"Most times","weights":{"instant":0.75}},{"label":"Almost every time, and I know it is coming before it arrives","value":"Almost every time, and I know it is coming before it arrives","weights":{"instant":1}}]},{"id":"react-slow","type":"choice","prompt":"Can the same reaction be slowed?","domain":"trainable","options":[{"label":"No, it has never slowed down for me","value":"No, it has never slowed down for me","weights":{"chosen":0}},{"label":"Rarely, and only by luck","value":"Rarely, and only by luck","weights":{"chosen":0.25}},{"label":"Once or twice, with real effort","value":"Once or twice, with real effort","weights":{"chosen":0.5}},{"label":"Regularly, when I remember to set it up in advance","value":"Regularly, when I remember to set it up in advance","weights":{"chosen":0.75}},{"label":"Almost every time now","value":"Almost every time now","weights":{"chosen":1}}]},{"id":"react-rate","type":"choice","prompt":"How often is there any reaction at all in a day?","domain":"baseline","options":[{"label":"Constantly — there is no gap anywhere in the day","value":"Constantly — there is no gap anywhere in the day","weights":{"instant":0,"delayed":0,"considered":0,"chosen":0}},{"label":"Most of the day","value":"Most of the day","weights":{"instant":1,"delayed":0,"considered":0,"chosen":0}},{"label":"Several times a day","value":"Several times a day","weights":{"instant":0,"delayed":1,"considered":0,"chosen":0}},{"label":"A few times a week","value":"A few times a week","weights":{"instant":0,"delayed":0,"considered":1,"chosen":0}},{"label":"Rarely enough that I would call it under control","value":"Rarely enough that I would call it under control","weights":{"instant":0,"delayed":0,"considered":0,"chosen":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["instant","delayed","considered","chosen"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"instant","label":"Instant","short":"No interval at all","description":"Trigger, feeling and act arrive as a single event, and the body is committed before the mind is consulted. Nothing here is broken — this is the fastest possible setting. It is also the setting in which the body work does the most good, because the interval that reasoning would use does not exist yet.","shadow":"Reading the absence of a pause as an absence of a choice.","color":"rose","masters":["body","breath"],"calibration":{"dimensions":{"body":0.35,"emotion":0.3,"thought":0.1},"practiceLevels":{"body":1,"breath":1},"domainStress":{"state":"emotional-healing"},"tags":["instant","fast-reacting"]}},{"id":"delayed","label":"Delayed","short":"A fraction of a second, sometimes","description":"Some interval exists, though it is short and inconsistent. This is a workable place to begin, because the gap can be felt from the inside while it is being widened, and a felt gap is a gap that can be practised with.","shadow":"Widening the gap without noticing what is inside it.","color":"orange","masters":["breath","witnessing"],"calibration":{"dimensions":{"body":0.25,"thought":0.25,"emotion":0.2},"practiceLevels":{"breath":1,"witnessing":1},"tags":["delayed","short-gap"]}},{"id":"considered","label":"Considered","short":"A real pause before the act","description":"The interval is dependable, and something is being considered in it. Most of the time this is enough to keep a reaction from becoming an event, and the remaining material is in the reactions that are unusually fast under unusually specific conditions.","shadow":"The pause becoming a habit of talking yourself out of feeling.","color":"teal","masters":["witnessing","loop-dissolution"],"calibration":{"dimensions":{"thought":0.25,"emotion":0.2,"body":0.2},"practiceLevels":{"witnessing":1,"loop-dissolution":1},"tags":["considered","pausing"]}},{"id":"chosen","label":"Chosen","short":"The response is picked, not taken","description":"There is a real interval and it is used deliberately, which means the reaction has become a selection rather than an event. The shadow side of this is worth naming: a well-trained pause can also be used to keep a life carefully unchanged.","shadow":"A pause used to avoid the situation rather than the reaction.","color":"emerald","masters":["loop-dissolution","jnana"],"calibration":{"dimensions":{"thought":0.2,"spirit":0.3,"emotion":0.2},"practiceLevels":{"loop-dissolution":1,"jnana":1},"tags":["chosen","self-directed"]}}]'::jsonb, '{"loops_to_check":["reactive","impulsive"],"practice_affinity":["loop-dissolution","witnessing"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
