  updated_at
) VALUES
    ('relationship-roles', 'Relationship roles', 'The role you play in others’ lives', 'vedic', 'connection', E'Almost everyone runs a role in close relationships, and the role does a lot of the work of knowing what to do. Four of the common ones are the rescuer, the persecutor, the pleaser and the withdrawn one — the last of them is usually a rest from the other three rather than a position in its own right.\n\nThis asks which one is running, and then asks what it has cost. It is written on the assumption that the answer is a role, not a character.', '💞', 6, 7, '[{"id":"roles-which","type":"choice","prompt":"Which of these is closest to the part you take in a close relationship?","domain":"role","options":[{"label":"I go in and sort it out","value":"I go in and sort it out","weights":{"rescuer":1}},{"label":"I get hard on people, and call it honesty","value":"I get hard on people, and call it honesty","weights":{"persecutor":1}},{"label":"I agree with whatever keeps things smooth","value":"I agree with whatever keeps things smooth","weights":{"pleaser":1}},{"label":"I stop speaking and wait for it to pass","value":"I stop speaking and wait for it to pass","weights":{"withdrawn":1}},{"label":"I say what I actually think, including the awkward parts","value":"I say what I actually think, including the awkward parts","weights":{"equal":1}}]},{"id":"roles-switch","type":"choice","prompt":"Which role do you fall into when the other person is the one in trouble?","domain":"switch","options":[{"label":"I go in and fix it","value":"I go in and fix it","weights":{"rescuer":1}},{"label":"I get hard on them, because it is the fastest thing available","value":"I get hard on them, because it is the fastest thing available","weights":{"persecutor":1}},{"label":"I agree with whatever they want and help them carry it","value":"I agree with whatever they want and help them carry it","weights":{"pleaser":1}},{"label":"I stop speaking to them","value":"I stop speaking to them","weights":{"withdrawn":1}},{"label":"I stay with them and tell them what I see","value":"I stay with them and tell them what I see","weights":{"equal":1}}]},{"id":"roles-rescue","type":"choice","prompt":"How often do you end up holding up a situation that was never actually yours to hold?","domain":"rescue","options":[{"label":"Rarely — I know what is mine","value":"Rarely — I know what is mine","weights":{"rescuer":0}},{"label":"Sometimes, and I let it slide","value":"Sometimes, and I let it slide","weights":{"rescuer":0.25}},{"label":"Often","value":"Often","weights":{"rescuer":0.5}},{"label":"Most of the time","value":"Most of the time","weights":{"rescuer":0.75}},{"label":"Almost always, and I have stopped counting who is actually struggling","value":"Almost always, and I have stopped counting who is actually struggling","weights":{"rescuer":1}}]},{"id":"roles-strictness","type":"choice","prompt":"How easily can you hold someone to a standard without them feeling punished?","domain":"authority","options":[{"label":"I do not hold people to anything","value":"I do not hold people to anything","weights":{"persecutor":0}},{"label":"I do it and then feel guilty","value":"I do it and then feel guilty","weights":{"persecutor":0.25}},{"label":"I do it, and I would rather they did not notice","value":"I do it, and I would rather they did not notice","weights":{"persecutor":0.5}},{"label":"I can do it and still be warm about it","value":"I can do it and still be warm about it","weights":{"persecutor":0.75}},{"label":"I can be completely clear and completely fair at the same time","value":"I can be completely clear and completely fair at the same time","weights":{"persecutor":1}}]},{"id":"roles-yes","type":"choice","prompt":"How much do you say yes when you would rather not?","domain":"cost","options":[{"label":"I say what I mean, including no","value":"I say what I mean, including no","weights":{"pleaser":0}},{"label":"I say yes and manage the consequences","value":"I say yes and manage the consequences","weights":{"pleaser":0.25}},{"label":"I say yes, and complain about it afterwards","value":"I say yes, and complain about it afterwards","weights":{"pleaser":0.5}},{"label":"I say yes, and resent it for days","value":"I say yes, and resent it for days","weights":{"pleaser":0.75}},{"label":"I say yes to almost everything, and I am not sure why","value":"I say yes to almost everything, and I am not sure why","weights":{"pleaser":1}}]},{"id":"roles-distance","type":"choice","prompt":"When it gets difficult with someone close, how far away do you go?","domain":"distance","options":[{"label":"I stay in it","value":"I stay in it","weights":{"withdrawn":0}},{"label":"I shorten my answers","value":"I shorten my answers","weights":{"withdrawn":0.25}},{"label":"I get busy","value":"I get busy","weights":{"withdrawn":0.5}},{"label":"I go quiet for days","value":"I go quiet for days","weights":{"withdrawn":0.75}},{"label":"I leave, and stay left, and everyone has learned to manage around it","value":"I leave, and stay left, and everyone has learned to manage around it","weights":{"withdrawn":1}}]},{"id":"roles-agreement","type":"choice","prompt":"How often do you reach an agreement with someone and both of you actually mean it?","domain":"negotiating","options":[{"label":"We rarely reach one at all","value":"We rarely reach one at all","weights":{"equal":0}},{"label":"We reach one and it feels provisional","value":"We reach one and it feels provisional","weights":{"equal":0.25}},{"label":"We reach one, and it holds","value":"We reach one, and it holds","weights":{"equal":0.5}},{"label":"We reach one, and both of us are glad about it","value":"We reach one, and both of us are glad about it","weights":{"equal":0.75}},{"label":"We negotiate openly, including the parts neither of us wants to say","value":"We negotiate openly, including the parts neither of us wants to say","weights":{"equal":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["rescuer","persecutor","pleaser","withdrawn","equal"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"rescuer","label":"The rescuer","short":"You arrive with the answer","description":"You take responsibility for how things go, and you are usually competent at it. The role is genuinely useful and genuinely consuming — nobody in it is being helped as much as it looks, and the relief on offer does not reach the person who needs it.","shadow":"Rescue that was never asked for, given anyway.","color":"rose","masters":["relationship","emotional-healing"],"calibration":{"dimensions":{"connection":0.3,"action":0.25,"emotion":0.2},"practiceLevels":{"relationship":1,"emotional-healing":1},"domainStress":{"caretaking":"emotional-healing"},"tags":["rescuer","over-responsible"]}},{"id":"persecutor","label":"The persecutor","short":"You set the terms","description":"You hold the standard and enforce it, and you have usually earned the right to. The shadow shows up in the enforcement rather than the standard — it is a narrow strip, and most people cross it without noticing they have.","shadow":"Enforcement mistaken for honesty.","color":"orange","masters":["relationship","raja"],"calibration":{"dimensions":{"action":0.3,"connection":0.25,"emotion":0.2},"practiceLevels":{"relationship":1,"raja":1},"domainStress":{"conflict":"relationship"},"tags":["persecutor","hard-edged"]}},{"id":"pleaser","label":"The pleaser","short":"You keep it smooth","description":"You manage the emotional temperature of a relationship, mostly by agreeing. This is a real skill and it keeps things workable, at a running cost that arrives later and is always larger than expected.","shadow":"Smoothness purchased with something you wanted.","color":"amber","masters":["relationship","emotional-healing"],"calibration":{"dimensions":{"connection":0.3,"emotion":0.25,"body":0.15},"practiceLevels":{"relationship":1,"emotional-healing":1},"domainStress":{"agreement":"relationship"},"tags":["pleaser","conflict-avoiding"]}},{"id":"withdrawn","label":"Withdrawn","short":"You leave the room","description":"You exit rather than compete, which often removes the fight and occasionally removes the relationship. Distance is doing the work that conversation is meant to do, and it is cheaper in the short run and more expensive over years.","shadow":"Absence described as needing space.","color":"sky","masters":["witnessing","relationship"],"calibration":{"dimensions":{"connection":0.3,"emotion":0.25,"body":0.2},"practiceLevels":{"witnessing":1,"relationship":1},"domainStress":{"withdrawal":"emotional-healing"},"tags":["withdrawn","disengaged"]}},{"id":"equal","label":"Equal","short":"Two people, both saying what they mean","description":"You are in the relationship rather than performing a part in it, and you can hold a difficult conversation without withdrawing from it or managing it. The work is real and it is mostly invisible from outside.","shadow":"Equality held so carefully it becomes negotiation on every point.","color":"emerald","masters":["relationship","jnana"],"calibration":{"dimensions":{"connection":0.3,"spirit":0.2,"thought":0.2},"practiceLevels":{"relationship":2,"jnana":1},"tags":["equal","mutual"]}}]'::jsonb, '{"loops_to_check":["codependency","conflict-avoidance","approval-seeking"],"practice_affinity":["relationship","emotional-healing"],"deepens_with":["attachment-style","inner-council","inner-child"]}'::jsonb, 1, true, false, 100, now())
