    ('ritual-life', 'Ritual life', 'The sacred rhythms you keep', 'vedic', 'spirit', E'Ritual is the one practice that requires no belief to work. You do not have to think a lamp means anything for it to change the room.\n\nWhat is worth looking at is which of your rhythms are actually sacred, as opposed to merely repeated.', '🪔', 5, 6, '[{"id":"ritual-what","type":"choice","prompt":"Is there anything you do regularly that has meaning to you?","domain":"inventory","options":[{"label":"Nothing I would call ritual","value":"Nothing I would call ritual","weights":{"inherited":1}},{"label":"One or two, occasionally","value":"One or two, occasionally","weights":{"inherited":1}},{"label":"A few, from my family or culture","value":"A few, from my family or culture","weights":{"inherited":1}},{"label":"Several, and I keep them","value":"Several, and I keep them","weights":{"inherited":1}},{"label":"A daily rhythm with clear anchors","value":"A daily rhythm with clear anchors","weights":{"inherited":1}}]},{"id":"ritual-origin","type":"choice","prompt":"Where did it come from — you, or someone before you?","domain":"source","options":[{"label":"Entirely inherited","value":"Entirely inherited","weights":{"none":1,"occasional":0,"inherited":0,"chosen-and-kept":0}},{"label":"Mostly inherited","value":"Mostly inherited","weights":{"none":0.25,"occasional":0.75,"inherited":0,"chosen-and-kept":0}},{"label":"A mix of both","value":"A mix of both","weights":{"none":0,"occasional":0.5,"inherited":0.5,"chosen-and-kept":0}},{"label":"Mostly chosen by me","value":"Mostly chosen by me","weights":{"none":0,"occasional":0,"inherited":0.75,"chosen-and-kept":0.25}},{"label":"Chosen, and I would defend it","value":"Chosen, and I would defend it","weights":{"none":0,"occasional":0,"inherited":0,"chosen-and-kept":1}}]},{"id":"ritual-effect","type":"choice","prompt":"Does it change anything, or is it a form?","domain":"effect","options":[{"label":"No effect that I can detect","value":"No effect that I can detect","weights":{"none":1}},{"label":"A slight shift in mood","value":"A slight shift in mood","weights":{"none":0}},{"label":"It does settle me","value":"It does settle me","weights":{"none":0}},{"label":"It changes how the rest of the day goes","value":"It changes how the rest of the day goes","weights":{"none":0}},{"label":"I would not know how to start the day without it","value":"I would not know how to start the day without it","weights":{"none":0}}]},{"id":"ritual-kept","type":"choice","prompt":"Do you keep it when it is inconvenient?","domain":"continuity","options":[{"label":"I drop it without a thought","value":"I drop it without a thought","weights":{"none":1,"occasional":0,"inherited":0,"chosen-and-kept":0}},{"label":"It slips whenever it clashes","value":"It slips whenever it clashes","weights":{"none":0.25,"occasional":0.75,"inherited":0,"chosen-and-kept":0}},{"label":"I keep it most of the time","value":"I keep it most of the time","weights":{"none":0,"occasional":0.5,"inherited":0.5,"chosen-and-kept":0}},{"label":"I keep it, and it costs me something","value":"I keep it, and it costs me something","weights":{"none":0,"occasional":0,"inherited":0.75,"chosen-and-kept":0.25}},{"label":"I would rearrange other things around it","value":"I would rearrange other things around it","weights":{"none":0,"occasional":0,"inherited":0,"chosen-and-kept":1}}]},{"id":"ritual-alone","type":"choice","prompt":"Do you do any of it alone?","domain":"solitary","options":[{"label":"All of it is with other people","value":"All of it is with other people","weights":{"chosen-and-kept":1}},{"label":"Mostly with others","value":"Mostly with others","weights":{"chosen-and-kept":1}},{"label":"Some alone, some together","value":"Some alone, some together","weights":{"chosen-and-kept":1}},{"label":"Most of it alone","value":"Most of it alone","weights":{"chosen-and-kept":1}},{"label":"Entirely alone, by choice","value":"Entirely alone, by choice","weights":{"chosen-and-kept":1}}]},{"id":"ritual-gap","type":"choice","prompt":"What happens to you when the rhythm breaks?","domain":"break","options":[{"label":"Nothing noticeable","value":"Nothing noticeable","weights":{"none":1}},{"label":"Minor irritation","value":"Minor irritation","weights":{"none":0}},{"label":"I miss it clearly","value":"I miss it clearly","weights":{"none":0}},{"label":"It disrupts me more than I would expect","value":"It disrupts me more than I would expect","weights":{"none":0}},{"label":"The break is genuinely disorienting","value":"The break is genuinely disorienting","weights":{"none":0}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["none","occasional","inherited","chosen-and-kept"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"none","label":"None","short":"No deliberate rhythm","description":"There is no ritual structure in your life. Nothing is wrong and there is no requirement for one. It is worth noticing, though, that this reading tends to pair with a life that is quite continuous — and that continuity is its own kind of unconscious ritual.","shadow":"Mistaking consistency for intentionality.","color":"slate","masters":["observation","raja"],"calibration":{"dimensions":{"spirit":0.2,"thought":0.2},"practiceLevels":{"observation":1,"raja":1},"tags":["ritual","none"]}},{"id":"occasional","label":"Occasional","short":"Something, at intervals","description":"There is something — a few times a year, perhaps — that has meaning and is not repeated. The inconsistency is the interesting part: what stops it from being regular is usually a decision, not an obstacle.","shadow":"Keeping something sacred only when it is convenient.","color":"amber","masters":["raja","witnessing"],"calibration":{"dimensions":{"spirit":0.25,"emotion":0.15},"practiceLevels":{"raja":1,"witnessing":1},"tags":["ritual","intermittent"]}},{"id":"inherited","label":"Inherited","short":"It came from someone before you","description":"You have a real rhythm and it came from your family or your culture. This is a genuine practice, and the only question is whether you have ever made it yours rather than simply continuing it.","shadow":"Keeping something because stopping would mean something.","color":"sky","masters":["bhakti","raja"],"calibration":{"dimensions":{"spirit":0.3,"connection":0.25,"emotion":0.2},"practiceLevels":{"bhakti":1,"raja":1},"tags":["ritual","inherited"]}},{"id":"chosen-and-kept","label":"Chosen and kept","short":"Yours, and you keep it when it costs you","description":"The rhythm is yours, you chose it, and you keep it when it is inconvenient. That last part is what separates ritual from a preference, and it is the reason the effect tends to be real.","shadow":"The rhythm becoming the thing the life is organised around.","color":"emerald","masters":["raja","tantra"],"calibration":{"dimensions":{"spirit":0.4,"body":0.25,"thought":0.15},"practiceLevels":{"raja":2,"tantra":1},"tags":["ritual","kept"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["raja","tantra"],"deepens_with":["awe-frequency","svadhyaya"]}'::jsonb, 1, true, false, 100, now())
