-- Rumination index (Loops)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('rumination-index', 'Rumination index', 'How often the mind rewinds', 'yogic', 'thought', E'Rumination is what thinking becomes when it is pointed at something it cannot change. It is nearly indistinguishable from analysis from the inside, and the difference is entirely in whether it terminates.\n\nThis looks at the rate, the direction, and what the rewinding is for.', '🔁', 6, 8, '[{"id":"rumination-rate","type":"choice","prompt":"How often does your mind go back over the same material?","domain":"rate","options":[{"label":"It barely happens","value":"It barely happens","weights":{"rare":1,"occasional":0,"frequent":0,"constant":0}},{"label":"Occasionally, and it passes","value":"Occasionally, and it passes","weights":{"rare":0.25,"occasional":0.75,"frequent":0,"constant":0}},{"label":"Most days","value":"Most days","weights":{"rare":0,"occasional":0.5,"frequent":0.5,"constant":0}},{"label":"Several times a day","value":"Several times a day","weights":{"rare":0,"occasional":0,"frequent":0.75,"constant":0.25}},{"label":"It is the background of most of my waking life","value":"It is the background of most of my waking life","weights":{"rare":0,"occasional":0,"frequent":0,"constant":1}}]},{"id":"rumination-direction","type":"choice","prompt":"Is it mostly about what happened, or about what might?","domain":"direction","options":[{"label":"Almost all of it is about what happened","value":"Almost all of it is about what happened","weights":{"occasional":0,"frequent":0,"constant":0}},{"label":"Mostly the past, with some of the future","value":"Mostly the past, with some of the future","weights":{"occasional":1,"frequent":0,"constant":0}},{"label":"About half and half","value":"About half and half","weights":{"occasional":0,"frequent":1,"constant":0}},{"label":"Mostly what might happen","value":"Mostly what might happen","weights":{"occasional":0,"frequent":0,"constant":0}},{"label":"Almost all of it is about what might happen","value":"Almost all of it is about what might happen","weights":{"occasional":0,"frequent":0,"constant":1}}]},{"id":"rumination-useful","type":"choice","prompt":"Is it analysis, or is it going round?","domain":"analysis","options":[{"label":"It is analysis, and it produces answers","value":"It is analysis, and it produces answers","weights":{"rare":1,"occasional":0,"frequent":0,"constant":0}},{"label":"It is analysis most of the time","value":"It is analysis most of the time","weights":{"rare":0,"occasional":1,"frequent":0,"constant":0}},{"label":"It starts as analysis and turns into replay","value":"It starts as analysis and turns into replay","weights":{"rare":0,"occasional":0,"frequent":0,"constant":0}},{"label":"It is mostly replay — the same material, over and over","value":"It is mostly replay — the same material, over and over","weights":{"rare":0,"occasional":0,"frequent":1,"constant":0}},{"label":"It produces nothing at all, only more of itself","value":"It produces nothing at all, only more of itself","weights":{"rare":0,"occasional":0,"frequent":0,"constant":1}}]},{"id":"rumination-produces","type":"choice","prompt":"What does it produce?","domain":"output","options":[{"label":"Something I can use","value":"Something I can use","weights":{"frequent":0}},{"label":"A plan, sometimes","value":"A plan, sometimes","weights":{"frequent":0.25}},{"label":"A better understanding of a person, or of a problem","value":"A better understanding of a person, or of a problem","weights":{"frequent":0.5}},{"label":"A settled low mood","value":"A settled low mood","weights":{"frequent":0.75}},{"label":"Nothing, and less energy than before","value":"Nothing, and less energy than before","weights":{"frequent":1}}]},{"id":"rumination-purpose","type":"choice","prompt":"What is it for?","domain":"function","options":[{"label":"I have no idea, and that is uncomfortable","value":"I have no idea, and that is uncomfortable","weights":{"constant":0}},{"label":"Trying to solve a problem I have not solved","value":"Trying to solve a problem I have not solved","weights":{"constant":0.25}},{"label":"Trying to feel a feeling I have not allowed myself to feel","value":"Trying to feel a feeling I have not allowed myself to feel","weights":{"constant":0.5}},{"label":"Protecting me from having to feel it again","value":"Protecting me from having to feel it again","weights":{"constant":0.75}},{"label":"Keeping the whole thing running","value":"Keeping the whole thing running","weights":{"constant":1}}]},{"id":"rumination-stop","type":"choice","prompt":"Can you stop it?","domain":"termination","options":[{"label":"I can stop it whenever I want","value":"I can stop it whenever I want","weights":{"rare":1,"occasional":0,"frequent":0,"constant":0}},{"label":"With some effort","value":"With some effort","weights":{"rare":0,"occasional":1,"frequent":0,"constant":0}},{"label":"If I get genuinely absorbed in something else","value":"If I get genuinely absorbed in something else","weights":{"rare":0,"occasional":0,"frequent":0,"constant":0}},{"label":"It fades eventually, on its own","value":"It fades eventually, on its own","weights":{"rare":0,"occasional":0,"frequent":1,"constant":0}},{"label":"I have never found a way to stop it","value":"I have never found a way to stop it","weights":{"rare":0,"occasional":0,"frequent":0,"constant":1}}]},{"id":"rumination-substitute","type":"choice","prompt":"What is it standing in for?","domain":"substitution","options":[{"label":"Nothing in particular","value":"Nothing in particular","weights":{"frequent":0}},{"label":"Rest, mostly","value":"Rest, mostly","weights":{"frequent":0.25}},{"label":"A decision I have not made","value":"A decision I have not made","weights":{"frequent":0.5}},{"label":"Grief, or anger, or fear","value":"Grief, or anger, or fear","weights":{"frequent":0.75}},{"label":"The parts of my life I am not actually living","value":"The parts of my life I am not actually living","weights":{"frequent":1}}]},{"id":"rumination-body","type":"choice","prompt":"Where does it live?","domain":"somatic","options":[{"label":"It is entirely in the head","value":"It is entirely in the head","weights":{"frequent":0}},{"label":"Mostly thoughts, with some tension","value":"Mostly thoughts, with some tension","weights":{"frequent":0.25}},{"label":"A tight loop, with the body involved","value":"A tight loop, with the body involved","weights":{"frequent":0.5}},{"label":"Chest and stomach, most of the time","value":"Chest and stomach, most of the time","weights":{"frequent":0.75}},{"label":"A physical weight, with the thoughts arriving around it","value":"A physical weight, with the thoughts arriving around it","weights":{"frequent":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["rare","occasional","frequent","constant"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"rare","label":"Rare","short":"The mind finishes what it starts","description":"Rumination is rare, which means thinking generally terminates. This is worth protecting: the ability to finish a thought is a precondition for a great deal of what people come here to find, and it disappears quietly when a life gets crowded.","shadow":"Assuming it will always be this easy.","color":"slate","masters":["observation","jnana"],"calibration":{"dimensions":{"thought":0.2,"spirit":0.2,"emotion":0.15},"practiceLevels":{"observation":1,"jnana":1},"tags":["rare","terminating"]}},{"id":"occasional","label":"Occasional","short":"It comes, and it passes","description":"The loop arrives under certain conditions and leaves on its own. The conditions are the useful part, because they are the places where a small interruption would change the shape of the day.","shadow":"Noticing the conditions without changing anything about them.","color":"teal","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.2,"body":0.15},"practiceLevels":{"observation":1,"witnessing":1},"tags":["occasional","episodic"]}},{"id":"frequent","label":"Frequent","short":"Several passes a day, mostly unnoticed","description":"The rewinding is a regular part of the day and has become easy not to notice, which is precisely what makes it cheap to maintain. What it produces is usually the most telling thing about it.","shadow":"Calling it thinking because it uses words.","color":"amber","masters":["loop-dissolution","witnessing"],"calibration":{"dimensions":{"thought":0.35,"emotion":0.3,"body":0.15},"practiceLevels":{"loop-dissolution":1,"witnessing":1},"domainStress":{"mind":"observation"},"tags":["frequent","routinised"]}},{"id":"constant","label":"Constant","short":"The background process of the day","description":"The loop has become the background condition rather than an event within it, which narrows the field considerably: there is less attention available for anything that is actually arriving. What it is for is the question worth sitting with, because a loop that serves a function will keep returning to serve it.","shadow":"Mistaking the intensity of the loop for the depth of the feeling underneath it.","color":"rose","masters":["loop-dissolution","emotional-healing"],"calibration":{"dimensions":{"emotion":0.4,"thought":0.3,"body":0.2},"practiceLevels":{"loop-dissolution":1,"emotional-healing":1},"domainStress":{"state":"emotional-healing"},"tags":["constant","narrowed-field"]}}]'::jsonb, '{"loops_to_check":["rumination","worry"],"practice_affinity":["observation","witnessing"],"deepens_with":["mind-wandering"]}'::jsonb, 1, true, false, 100, now())
