) VALUES
    ('sankalpa-shakti', 'Saṃkalpa śakti', 'The power of resolve', 'yogic', 'action', E'A saṃkalpa is not a wish. It is a resolve that has been tested against enough noise to know it is still there when the noise has passed. Most people have had many wishes and very few saṃkalpas, because a resolve has to survive contact with reality — and most wishes do not.\n\nFour positions are described here. The reading is not a verdict on your willpower; it is a description of how clearly the thing you want has been separated from the things you think you want.', '🎯', 6, 6, '[{"id":"sankalpa-clarity","type":"choice","prompt":"How clear is the thing you want?","domain":"clarity","options":[{"label":"I have a general sense, but not a specific one","value":"I have a general sense, but not a specific one","weights":{"diffuse":1,"forming":0,"clear":0,"held":0}},{"label":"I know the area, but not the thing itself","value":"I know the area, but not the thing itself","weights":{"diffuse":0,"forming":1,"clear":0,"held":0}},{"label":"I can name it, but I keep changing the wording","value":"I can name it, but I keep changing the wording","weights":{"diffuse":0,"forming":0,"clear":1,"held":0}},{"label":"I know it, and the wording does not change","value":"I know it, and the wording does not change","weights":{"diffuse":0,"forming":0,"clear":0,"held":1}}]},{"id":"sankalpa-noise","type":"choice","prompt":"How much of what you want is actually yours?","domain":"noise","options":[{"label":"Almost none of it is mine","value":"Almost none of it is mine","weights":{"forming":0}},{"label":"Some of it, in places","value":"Some of it, in places","weights":{"forming":0.25}},{"label":"Most of it, with a few borrowed parts","value":"Most of it, with a few borrowed parts","weights":{"forming":0.5}},{"label":"Nearly all of it, and I have checked","value":"Nearly all of it, and I have checked","weights":{"forming":0.75}},{"label":"All of it — I have signed for every part","value":"All of it — I have signed for every part","weights":{"forming":1}}]},{"id":"sankalpa-endurance","type":"choice","prompt":"How long has the thing you want lasted?","domain":"endurance","options":[{"label":"It comes and goes with the day","value":"It comes and goes with the day","weights":{"diffuse":1,"forming":0,"clear":0,"held":0}},{"label":"It has lasted a few weeks, at most","value":"It has lasted a few weeks, at most","weights":{"diffuse":0.25,"forming":0.75,"clear":0,"held":0}},{"label":"It has lasted months, and survived some scrutiny","value":"It has lasted months, and survived some scrutiny","weights":{"diffuse":0,"forming":0.5,"clear":0.5,"held":0}},{"label":"It has lasted, and I have defended it against noise","value":"It has lasted, and I have defended it against noise","weights":{"diffuse":0,"forming":0,"clear":0.75,"held":0.25}},{"label":"It has lasted, and it has become part of how I decide","value":"It has lasted, and it has become part of how I decide","weights":{"diffuse":0,"forming":0,"clear":0,"held":1}}]},{"id":"sankalpa-conflict","type":"choice","prompt":"What happens when the resolve costs you something?","domain":"conflict","options":[{"label":"I let it go, and decide it was not that important","value":"I let it go, and decide it was not that important","weights":{"diffuse":1}},{"label":"I hesitate, and then come back to it","value":"I hesitate, and then come back to it","weights":{"forming":1}},{"label":"I hold it, but I bargain around the edges","value":"I hold it, but I bargain around the edges","weights":{"clear":1}},{"label":"I pay the price, and the resolve gets stronger","value":"I pay the price, and the resolve gets stronger","weights":{"held":1}}]},{"id":"sankalpa-source","type":"choice","prompt":"Where does the wanting come from?","domain":"source","options":[{"label":"I do not know — it just arrives","value":"I do not know — it just arrives","weights":{"diffuse":1,"forming":0,"clear":0,"held":0}},{"label":"It comes from a part of me I am still getting to know","value":"It comes from a part of me I am still getting to know","weights":{"diffuse":0,"forming":1,"clear":0,"held":0}},{"label":"It comes from the part of me that has been consistent","value":"It comes from the part of me that has been consistent","weights":{"diffuse":0,"forming":0,"clear":1,"held":0}},{"label":"It comes from the part of me that knows what matters","value":"It comes from the part of me that knows what matters","weights":{"diffuse":0,"forming":0,"clear":0,"held":1}}]},{"id":"sankalpa-action","type":"choice","prompt":"How much of your life is organised around this resolve?","domain":"action","options":[{"label":"None — it is something I think about sometimes","value":"None — it is something I think about sometimes","weights":{"diffuse":1,"forming":0,"clear":0,"held":0}},{"label":"Some of it — it shows up in small decisions","value":"Some of it — it shows up in small decisions","weights":{"diffuse":0,"forming":1,"clear":0,"held":0}},{"label":"Most of it — the days bend toward it","value":"Most of it — the days bend toward it","weights":{"diffuse":0,"forming":0,"clear":1,"held":0}},{"label":"All of it — the days are built around it","value":"All of it — the days are built around it","weights":{"diffuse":0,"forming":0,"clear":0,"held":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["diffuse","forming","clear","held"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"diffuse","label":"Diffuse","short":"There is wanting, and no shape to it","description":"Wanting is present but has no specific form. This is not a problem — most people start here, and the first move is simply noticing that there is something to be shaped. What makes it hard to work with is that a diffuse want behaves like a mood: it arrives, it fades, and it returns without ever being named.","shadow":"Treating the return of the want as evidence of its importance.","color":"slate","masters":["self-inquiry","jnana"],"calibration":{"dimensions":{"thought":0.25,"emotion":0.25,"spirit":0.15},"practiceLevels":{"self-inquiry":1,"jnana":1},"tags":["diffuse","unnamed"]}},{"id":"forming","label":"Forming","short":"The shape is becoming visible","description":"The resolve is becoming legible. It has survived a few contacts with reality and is starting to hold its shape. The work here is not more wishing but more checking — each time it is looked at honestly, it becomes clearer.","shadow":"Naming it early and stopping there.","color":"amber","masters":["jnana","raja"],"calibration":{"dimensions":{"thought":0.3,"action":0.2,"spirit":0.2},"practiceLevels":{"jnana":1,"raja":1},"domainStress":{"formation":"jnana"},"tags":["forming","clarifying"]}},{"id":"clear","label":"Clear","short":"It can be said plainly","description":"The resolve is specific enough to be stated, defended, and acted on. It is no longer a mood or a wish — it is a direction. The test of clarity is not whether it feels good; it is whether it survives the first real cost.","shadow":"Clarity becoming rigidity.","color":"sky","masters":["raja","jnana"],"calibration":{"dimensions":{"thought":0.35,"action":0.25,"spirit":0.15},"practiceLevels":{"raja":1,"jnana":1},"domainStress":{"clarity":"raja"},"tags":["clear","directed"]}},{"id":"held","label":"Held","short":"It has become part of the architecture","description":"The resolve is no longer something maintained; it is something lived. It shows up in decisions without being announced, and it survives difficulty without needing to be defended. This is the point at which wanting becomes being.","shadow":"The resolve hardening into an identity that cannot be questioned.","color":"emerald","masters":["karma","raja"],"calibration":{"dimensions":{"action":0.35,"spirit":0.25,"thought":0.15},"practiceLevels":{"karma":1,"raja":1},"domainStress":{"holding":"karma"},"tags":["held","embodied"]}}]'::jsonb, '{"loops_to_check":["drift","approval-seeking"],"practice_affinity":["raja","jnana","karma"],"deepens_with":["inner-compass","work-dharma"]}'::jsonb, 1, true, false, 100, now())
