  sort_order,
  updated_at
) VALUES
    ('self-image', 'Self-image', 'The story you tell about you', 'jungian', 'shadow', E'Everyone carries a short account of who they are, and most people deliver it without noticing they are delivering it. It is a useful account — it is just usually older than the person telling it.\n\nThis looks at where that account came from, whether it has ever been tested, and how much of it was chosen rather than simply received.', '📖', 6, 8, '[{"id":"image-describe","type":"choice","prompt":"How would you describe yourself to a stranger?","domain":"account","options":[{"label":"A few flat facts, and not much else","value":"A few flat facts, and not much else","weights":{"fixed":1}},{"label":"A story with a few chapters that explains where I came from","value":"A story with a few chapters that explains where I came from","weights":{"shaped":1}},{"label":"Something I am still rewriting as I go","value":"Something I am still rewriting as I go","weights":{"shifting":1}},{"label":"Something I keep taking apart and putting back together","value":"Something I keep taking apart and putting back together","weights":{"under-examination":1}}]},{"id":"image-source","type":"choice","prompt":"Where did that description come from?","domain":"origin","options":[{"label":"It was given to me before I was old enough to question it","value":"It was given to me before I was old enough to question it","weights":{"fixed":1}},{"label":"It was mostly assembled from family and early life","value":"It was mostly assembled from family and early life","weights":{"shaped":1}},{"label":"It has been rebuilt several times since","value":"It has been rebuilt several times since","weights":{"shifting":1}},{"label":"I can trace where each part of it came from","value":"I can trace where each part of it came from","weights":{"under-examination":1}}]},{"id":"image-changed","type":"choice","prompt":"When did it last change?","domain":"revision","options":[{"label":"It has not changed since I was young","value":"It has not changed since I was young","weights":{"shifting":0}},{"label":"It has changed only when something forced it","value":"It has changed only when something forced it","weights":{"shifting":0.25}},{"label":"It has moved a few times in my adult life","value":"It has moved a few times in my adult life","weights":{"shifting":0.5}},{"label":"It has changed considerably in the last decade","value":"It has changed considerably in the last decade","weights":{"shifting":0.75}},{"label":"It is in constant revision, and never finished","value":"It is in constant revision, and never finished","weights":{"shifting":1}}]},{"id":"image-chosen","type":"choice","prompt":"How much of it did you choose?","domain":"agency","options":[{"label":"Almost entirely inherited — I did not pick any of it","value":"Almost entirely inherited — I did not pick any of it","weights":{"fixed":0,"shaped":0,"shifting":0,"under-examination":0}},{"label":"Mostly inherited, with a few things I chose","value":"Mostly inherited, with a few things I chose","weights":{"fixed":1,"shaped":0,"shifting":0,"under-examination":0}},{"label":"About half each way","value":"About half each way","weights":{"fixed":0,"shaped":1,"shifting":0,"under-examination":0}},{"label":"Largely chosen, though some of it is still handed down","value":"Largely chosen, though some of it is still handed down","weights":{"fixed":0,"shaped":0,"shifting":1,"under-examination":0}},{"label":"Chosen deliberately, and I can show the working","value":"Chosen deliberately, and I can show the working","weights":{"fixed":0,"shaped":0,"shifting":0,"under-examination":1}}]},{"id":"image-tested","type":"choice","prompt":"Has any of it been put to the test?","domain":"evidence","options":[{"label":"It has never been put to anything","value":"It has never been put to anything","weights":{"under-examination":0}},{"label":"I assumed it and did not check","value":"I assumed it and did not check","weights":{"under-examination":0.25}},{"label":"A few things have tested it and I adjusted","value":"A few things have tested it and I adjusted","weights":{"under-examination":0.5}},{"label":"It has been tested repeatedly and still holds","value":"It has been tested repeatedly and still holds","weights":{"under-examination":0.75}},{"label":"I hold it lightly, knowing it may not survive the next test","value":"I hold it lightly, knowing it may not survive the next test","weights":{"under-examination":1}}]},{"id":"image-accuracy","type":"choice","prompt":"How well does it actually fit?","domain":"fit","options":[{"label":"I have no real idea whether it is true","value":"I have no real idea whether it is true","weights":{"fixed":1}},{"label":"It is probably close, but nobody has checked it","value":"It is probably close, but nobody has checked it","weights":{"shaped":1}},{"label":"It is mostly accurate for the situation I am in now","value":"It is mostly accurate for the situation I am in now","weights":{"shifting":1}},{"label":"I have found the gaps in it myself","value":"I have found the gaps in it myself","weights":{"under-examination":1}}]},{"id":"image-defended","type":"choice","prompt":"What happens when someone questions it?","domain":"attachment","options":[{"label":"I drop it the moment it is questioned","value":"I drop it the moment it is questioned","weights":{"fixed":0}},{"label":"I get uncomfortable and start explaining it","value":"I get uncomfortable and start explaining it","weights":{"fixed":0.25}},{"label":"I hold it, but I listen to the objection","value":"I hold it, but I listen to the objection","weights":{"fixed":0.5}},{"label":"I can put it down and pick it up again later","value":"I can put it down and pick it up again later","weights":{"fixed":0.75}},{"label":"It is a working theory, not a possession","value":"It is a working theory, not a possession","weights":{"fixed":1}}]},{"id":"image-inherited","type":"choice","prompt":"How much of it is the family’s account rather than yours?","domain":"proportion","options":[{"label":"Almost all of it","value":"Almost all of it","weights":{"fixed":0}},{"label":"Most of it","value":"Most of it","weights":{"fixed":0.25}},{"label":"A substantial part","value":"A substantial part","weights":{"fixed":0.5}},{"label":"Some of it","value":"Some of it","weights":{"fixed":0.75}},{"label":"Very little of it","value":"Very little of it","weights":{"fixed":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["fixed","shaped","shifting","under-examination"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"fixed","label":"Fixed","short":"The account has not been revisited in years","description":"The self-description has been in place a long time and is defended rather than examined. Stability of this kind is genuinely useful, and it also means the description is now making decisions on your behalf without being asked.","shadow":"Mistaking consistency for accuracy.","color":"slate","masters":["self-inquiry","witnessing"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.2,"emotion":0.15},"practiceLevels":{"self-inquiry":1,"witnessing":1},"tags":["fixed","unrevised"]}},{"id":"shaped","label":"Shaped","short":"Assembled by life, and largely accepted","description":"The account has real material in it — experience, family, events — but the shape was largely given. It fits, which is why it is rarely questioned, and it will hold until something does not fit.","shadow":"Assuming a story that fits must be true.","color":"rose","masters":["self-inquiry","witnessing"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.2,"connection":0.15},"practiceLevels":{"self-inquiry":1},"tags":["shaped","largely-received"]}},{"id":"shifting","label":"Shifting","short":"The account is being rewritten","description":"The description moves, sometimes deliberately and sometimes because life moved it. There is real self-authoring happening here. The risk is drift — a story that keeps changing without ever being looked at directly.","shadow":"Change mistaken for progress.","color":"amber","masters":["self-inquiry","jnana"],"calibration":{"dimensions":{"thought":0.25,"action":0.2,"spirit":0.15},"practiceLevels":{"self-inquiry":1,"jnana":1},"tags":["shifting","in-revision"]}},{"id":"under-examination","label":"Under examination","short":"The story is being taken apart while it is told","description":"The self-account is treated as a working description rather than a fact, and it is checked against experience as it goes. This costs something — a held story is a stable one — and it buys a different kind of accuracy.","shadow":"An account examined until nothing is left standing.","color":"teal","masters":["self-inquiry","jnana"],"calibration":{"dimensions":{"spirit":0.3,"thought":0.25,"emotion":0.15},"practiceLevels":{"self-inquiry":2,"jnana":1},"tags":["under-examination","self-authored"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["self-inquiry","witnessing"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
