  sort_order,
  updated_at
) VALUES
    ('self-talk-tone', 'Self-talk tone', 'The pitch of your inner critic', 'vedic', 'emotion', E'There is a voice that runs most of the day, and it is rarely the one anyone chose. The question here is not whether it exists — it does, for nearly everyone — but what pitch it runs at, and what happens when it is addressed.\n\nA voice that is harsh has never once improved the thing it criticises. It has only made the same ground harder to work on.', '🗣️', 6, 8, '[{"id":"voice-content","type":"choice","prompt":"When the inner voice speaks, what is it usually saying?","domain":"content","options":[{"label":"What is wrong with me","value":"What is wrong with me","weights":{"harsh":1}},{"label":"What I should have done differently","value":"What I should have done differently","weights":{"fault-finding":1}},{"label":"The facts about what is happening","value":"The facts about what is happening","weights":{"neutral":1}},{"label":"What is going right, and what is possible","value":"What is going right, and what is possible","weights":{"encouraging":1}}]},{"id":"voice-compare","type":"choice","prompt":"Is the inner voice harsher with you than it is with other people?","domain":"comparison","options":[{"label":"Far harsher with myself","value":"Far harsher with myself","weights":{"harsh":1}},{"label":"Noticeably harsher","value":"Noticeably harsher","weights":{"harsh":0.75,"fault-finding":0.25}},{"label":"About the same either way","value":"About the same either way","weights":{"fault-finding":1}},{"label":"Slightly kinder than I am with others","value":"Slightly kinder than I am with others","weights":{"fault-finding":0.25,"neutral":0.75}},{"label":"I speak to myself as I would to a friend","value":"I speak to myself as I would to a friend","weights":{"neutral":0.5,"encouraging":0.5}}]},{"id":"voice-role","type":"choice","prompt":"Is the inner voice more like a coach or a prosecutor?","domain":"posture","options":[{"label":"A prosecutor — always building a case against me","value":"A prosecutor — always building a case against me","weights":{"harsh":1}},{"label":"A critic — never done finding the flaw","value":"A critic — never done finding the flaw","weights":{"fault-finding":1}},{"label":"A reporter — stating what is, without comment","value":"A reporter — stating what is, without comment","weights":{"neutral":1}},{"label":"A coach — pointing at what is possible","value":"A coach — pointing at what is possible","weights":{"encouraging":1}}]},{"id":"voice-volume","type":"choice","prompt":"How loud is it?","domain":"pitch","options":[{"label":"Constant, at full volume","value":"Constant, at full volume","weights":{"harsh":1}},{"label":"Loud for most of the day","value":"Loud for most of the day","weights":{"fault-finding":1}},{"label":"It comes and goes","value":"It comes and goes","weights":{"neutral":1}},{"label":"Present, and mostly worth hearing","value":"Present, and mostly worth hearing","weights":{"encouraging":1}}]},{"id":"voice-switch","type":"choice","prompt":"Can you turn it down when you want to?","domain":"control","options":[{"label":"No, I cannot turn it down at all","value":"No, I cannot turn it down at all","weights":{"harsh":1}},{"label":"Barely, and not for long","value":"Barely, and not for long","weights":{"harsh":0.75,"fault-finding":0.25}},{"label":"With effort","value":"With effort","weights":{"fault-finding":1}},{"label":"Usually, if I remember to","value":"Usually, if I remember to","weights":{"fault-finding":0.25,"neutral":0.75}},{"label":"Quickly, and it goes","value":"Quickly, and it goes","weights":{"neutral":0.5,"encouraging":0.5}}]},{"id":"voice-quiet","type":"choice","prompt":"What has ever quietened it?","domain":"relief","options":[{"label":"Nothing I have tried","value":"Nothing I have tried","weights":{"harsh":1}},{"label":"Distraction, and it comes straight back","value":"Distraction, and it comes straight back","weights":{"fault-finding":1}},{"label":"A quiet walk, or a bath","value":"A quiet walk, or a bath","weights":{"neutral":1}},{"label":"Someone being gentle with me","value":"Someone being gentle with me","weights":{"encouraging":1}}]},{"id":"voice-peak","type":"choice","prompt":"When is it loudest?","domain":"timing","options":[{"label":"After I have got something wrong","value":"After I have got something wrong","weights":{"harsh":1}},{"label":"When I am tired or depleted","value":"When I am tired or depleted","weights":{"fault-finding":1}},{"label":"When I am on my own","value":"When I am on my own","weights":{"neutral":1}},{"label":"When I am being asked to be seen","value":"When I am being asked to be seen","weights":{"encouraging":1}}]},{"id":"voice-others","type":"choice","prompt":"Does the inner voice comment on other people as well?","domain":"direction","options":[{"label":"It is almost entirely about me","value":"It is almost entirely about me","weights":{"harsh":1}},{"label":"Mostly about me, with a running commentary on others","value":"Mostly about me, with a running commentary on others","weights":{"fault-finding":1}},{"label":"It comments on both, and fairly","value":"It comments on both, and fairly","weights":{"neutral":1}},{"label":"It is kinder about other people than they are about themselves","value":"It is kinder about other people than they are about themselves","weights":{"encouraging":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["harsh","fault-finding","neutral","encouraging"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"harsh","label":"Harsh voice","short":"The pitch never drops","description":"The inner commentary runs at a volume and a pitch that most people would not put up with from a stranger. It is constant, it is not addressed, and it has been running long enough to be indistinguishable from the truth.","shadow":"Mistaking a voice that never stops for a self that cannot be questioned.","color":"rose","masters":["loop-dissolution","witnessing"],"calibration":{"dimensions":{"emotion":0.4,"thought":0.25,"body":0.15},"practiceLevels":{"witnessing":1,"loop-dissolution":1},"domainStress":{"self":"emotional-healing"},"tags":["self-critical","high-volume"]}},{"id":"fault-finding","label":"Fault-finding voice","short":"It is always pointing at something","description":"The voice is not cruel so much as permanently unresolved — it finds the flaw in whatever it is handed and moves on to the next thing. Because it is useful in small ways, it is rarely questioned as a whole.","shadow":"Confusing the accuracy of a criticism with the fairness of the tone.","color":"orange","masters":["witnessing","jnana"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.3,"action":0.15},"practiceLevels":{"witnessing":1,"jnana":1},"tags":["fault-finding","never-satisfied"]}},{"id":"neutral","label":"Neutral voice","short":"It reports, and stops there","description":"The inner voice is reasonably even and mostly descriptive. There is little of the criticism and not much encouragement either, which has its own consequence: it is difficult to find out what the voice is for, if it is not defending or encouraging.","shadow":"Flatness that is mistaken for the absence of an inner life.","color":"slate","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.25,"emotion":0.25,"spirit":0.15},"practiceLevels":{"observation":1,"witnessing":1},"tags":["even","unresolved"]}},{"id":"encouraging","label":"Encouraging voice","short":"It says the thing that is actually useful","description":"The inner voice is on your side and says so in specifics. Worth watching for one thing: a voice that never says anything difficult becomes a second thing to maintain, and the things it does not say go on being unsaid.","shadow":"Encouragement that has stopped being honest.","color":"emerald","masters":["bhakti","witnessing"],"calibration":{"dimensions":{"emotion":0.3,"connection":0.2,"spirit":0.25},"practiceLevels":{"bhakti":1,"witnessing":1},"tags":["kind","useful"]}}]'::jsonb, '{"loops_to_check":["self-criticism","approval-seeking"],"practice_affinity":["witnessing","self-inquiry"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
