  updated_at
) VALUES
    ('sensory-awareness', 'Sensory awareness', 'How often you notice the body noticing', 'yogic', 'body', E'The body is reporting continuously and most of the report is never read. Sensation is the first language, and the one that never stopped speaking.\n\nThis looks at the receiving end of that report: how much arrives, how precisely it is described, and whether the body is background or foreground during an ordinary day.', '👁️', 6, 8, '[{"id":"sense-breath","type":"choice","prompt":"How often do you notice your breathing without deciding to?","domain":"breath","options":[{"label":"Only when something has gone wrong with it","value":"Only when something has gone wrong with it","weights":{"dull":1}},{"label":"Rarely, and usually late","value":"Rarely, and usually late","weights":{"dull":0.75,"occasional":0.25}},{"label":"Sometimes, when I remember","value":"Sometimes, when I remember","weights":{"occasional":1}},{"label":"Quite often","value":"Quite often","weights":{"occasional":0.25,"attentive":0.75}},{"label":"Without deciding to, most of the time","value":"Without deciding to, most of the time","weights":{"attentive":0.5,"continuous":0.5}}]},{"id":"sense-tension","type":"choice","prompt":"Do you feel a tension before it starts to hurt?","domain":"early","options":[{"label":"Only once it actually hurts","value":"Only once it actually hurts","weights":{"dull":1}},{"label":"Sometimes, if I think to look","value":"Sometimes, if I think to look","weights":{"occasional":1}},{"label":"Usually, before it hurts","value":"Usually, before it hurts","weights":{"attentive":1}},{"label":"Long before it hurts","value":"Long before it hurts","weights":{"continuous":1}}]},{"id":"sense-emotion","type":"choice","prompt":"Where in your body do you feel an emotion as it happens?","domain":"affect","options":[{"label":"I feel it, but I could not place it","value":"I feel it, but I could not place it","weights":{"dull":1}},{"label":"I place it once it has passed","value":"I place it once it has passed","weights":{"occasional":1}},{"label":"I place it as it is happening","value":"I place it as it is happening","weights":{"attentive":1}},{"label":"I feel it move through the body as it happens","value":"I feel it move through the body as it happens","weights":{"continuous":1}}]},{"id":"sense-walk-eat","type":"choice","prompt":"While you are walking or eating, how much of your attention is on what you are doing?","domain":"activity","options":[{"label":"I am already in the next thing","value":"I am already in the next thing","weights":{"dull":1}},{"label":"Mostly in the next thing","value":"Mostly in the next thing","weights":{"dull":0.75,"occasional":0.25}},{"label":"Half and half","value":"Half and half","weights":{"occasional":1}},{"label":"Mostly on what I am doing","value":"Mostly on what I am doing","weights":{"occasional":0.25,"attentive":0.75}},{"label":"Completely on it, including how it feels","value":"Completely on it, including how it feels","weights":{"attentive":0.5,"continuous":0.5}}]},{"id":"sense-background","type":"choice","prompt":"Is the body background or foreground for most of the day?","domain":"foreground","options":[{"label":"Entirely background — I would not know it was there","value":"Entirely background — I would not know it was there","weights":{"dull":1}},{"label":"Background, unless something hurts","value":"Background, unless something hurts","weights":{"occasional":1}},{"label":"Foreground much of the time","value":"Foreground much of the time","weights":{"attentive":1}},{"label":"Foreground nearly all the time","value":"Foreground nearly all the time","weights":{"continuous":1}}]},{"id":"sense-describe","type":"choice","prompt":"If you felt a strange sensation, could you describe exactly what it was?","domain":"precision","options":[{"label":"No, not at all — I would not know where to start","value":"No, not at all — I would not know where to start","weights":{"dull":1}},{"label":"Roughly, and in general words","value":"Roughly, and in general words","weights":{"occasional":1}},{"label":"Quite precisely, if I take the time","value":"Quite precisely, if I take the time","weights":{"attentive":1}},{"label":"Exactly, in detail, if I look","value":"Exactly, in detail, if I look","weights":{"continuous":1}}]},{"id":"sense-memory","type":"choice","prompt":"How much do you remember of how your body felt during a day?","domain":"record","options":[{"label":"Almost nothing","value":"Almost nothing","weights":{"dull":1}},{"label":"Only when something unusual happened","value":"Only when something unusual happened","weights":{"occasional":1}},{"label":"A fair amount of the day","value":"A fair amount of the day","weights":{"attentive":1}},{"label":"A detailed account, in order","value":"A detailed account, in order","weights":{"continuous":1}}]},{"id":"sense-interference","type":"choice","prompt":"Does noticing the body ever get in the way of what you are doing?","domain":"cost","options":[{"label":"It does not come up at all","value":"It does not come up at all","weights":{"dull":1}},{"label":"Only when something is wrong","value":"Only when something is wrong","weights":{"occasional":1}},{"label":"It interrupts me fairly often","value":"It interrupts me fairly often","weights":{"attentive":1}},{"label":"It is almost continuously there","value":"It is almost continuously there","weights":{"continuous":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["dull","occasional","attentive","continuous"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"dull","label":"Low registration","short":"The report is there, unread","description":"The body is signalling and the signal is not being read. This is worth taking seriously as a capacity rather than a symptom, because the sensing equipment is intact — it is the reading of it that has gone quiet.","shadow":"Calling a dull day calm when nothing is actually being felt.","color":"slate","masters":["body","observation"],"calibration":{"dimensions":{"body":0.35,"thought":0.2,"emotion":0.2},"practiceLevels":{"body":1,"observation":1},"tags":["under-felt","unread"]}},{"id":"occasional","label":"Occasional sensing","short":"It comes and goes, usually with discomfort","description":"The body is registered in episodes, most often when something hurts. Because the noticing arrives with the discomfort, the association between sensing and suffering gets formed — which is the association worth undoing first.","shadow":"Only noticing the body when the body is making a complaint.","color":"amber","masters":["body","breath"],"calibration":{"dimensions":{"body":0.3,"thought":0.15,"emotion":0.2},"practiceLevels":{"body":1,"breath":1},"tags":["intermittent","pain-led"]}},{"id":"attentive","label":"Attentive to the body","short":"The sensing is a working habit","description":"Sensation is read reliably, and descriptions of it are accurate. This is the level at which body practice becomes informative rather than merely calming, because there is finally something specific to work with.","shadow":"Accuracy about sensation mistaken for distance from it.","color":"teal","masters":["body","observation"],"calibration":{"dimensions":{"body":0.3,"spirit":0.2,"thought":0.2},"practiceLevels":{"body":2,"observation":1},"tags":["precise","inhabited"]}},{"id":"continuous","label":"Continuous sensing","short":"The body is foreground, all day","description":"The body is being lived in rather than carried around, and the noticing does not switch off. The remaining question is what happens at the edges — whether a constant signal can still be heard when it matters, or has simply become a hum.","shadow":"A constant signal that has stopped being information.","color":"indigo","masters":["body","witnessing"],"calibration":{"dimensions":{"body":0.3,"spirit":0.35,"emotion":0.15},"practiceLevels":{"body":2,"witnessing":1},"tags":["continuous","foreground"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["body","observation"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
