-- Sensory sensitivity (Engines)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('sensory-sensitivity', 'Sensory sensitivity', 'How much the world reaches you', 'yogic', 'attention', E'The world is constantly putting things in. Most of the time it is not noticed, and the noticing is what turns a life into an experience rather than a sequence of tasks.\n\nSensitivity runs on a scale that is easy to get wrong from the inside. Both the numb end and the overwhelmed end are positions on the same dial, and the useful work is finding out where the dial actually sits and what is doing the turning.', '🎚️', 6, 8, '[{"id":"sensory-noise","type":"choice","prompt":"How does noise affect you?","domain":"sound","options":[{"label":"I avoid places with people in them","value":"I avoid places with people in them","weights":{"overloaded":1}},{"label":"I find busy places genuinely hard to be in","value":"I find busy places genuinely hard to be in","weights":{"sensitive":0.75,"overloaded":0.25}},{"label":"I am aware of background noise most of the time","value":"I am aware of background noise most of the time","weights":{"selective":1}},{"label":"Only when it is really loud","value":"Only when it is really loud","weights":{"selective":0.75,"numb":0.25}},{"label":"Noise does not bother me at all","value":"Noise does not bother me at all","weights":{"numb":1}}]},{"id":"sensory-light","type":"choice","prompt":"How do bright light, flickering screens and glare land on you?","domain":"light","options":[{"label":"I barely register it","value":"I barely register it","weights":{"numb":1}},{"label":"It tires me after a while","value":"It tires me after a while","weights":{"selective":1}},{"label":"I notice it at once and it grates","value":"I notice it at once and it grates","weights":{"sensitive":1}},{"label":"It can be genuinely painful","value":"It can be genuinely painful","weights":{"overloaded":1}}]},{"id":"sensory-texture","type":"choice","prompt":"How much do fabrics, textures and materials register on you?","domain":"touch","options":[{"label":"Some textures I genuinely cannot stand","value":"Some textures I genuinely cannot stand","weights":{"overloaded":1}},{"label":"I notice textures constantly","value":"I notice textures constantly","weights":{"sensitive":0.75,"overloaded":0.25}},{"label":"I notice them a fair amount","value":"I notice them a fair amount","weights":{"selective":1}},{"label":"Only if it is extreme","value":"Only if it is extreme","weights":{"selective":0.75,"numb":0.25}},{"label":"I barely feel what things are made of","value":"I barely feel what things are made of","weights":{"numb":1}}]},{"id":"sensory-crowds","type":"choice","prompt":"How do crowded spaces affect you?","domain":"space","options":[{"label":"I get out as soon as I can","value":"I get out as soon as I can","weights":{"overloaded":1}},{"label":"I find somewhere to stand, at the edge","value":"I find somewhere to stand, at the edge","weights":{"sensitive":1}},{"label":"It takes a moment to settle into","value":"It takes a moment to settle into","weights":{"selective":1}},{"label":"I am comfortable in them","value":"I am comfortable in them","weights":{"numb":1}}]},{"id":"sensory-enjoyment","type":"choice","prompt":"How much of what comes at you in a normal day do you enjoy, as against simply tolerate?","domain":"dose","options":[{"label":"Almost none of it — it all registers as a tax","value":"Almost none of it — it all registers as a tax","weights":{"overloaded":1}},{"label":"Very little of it","value":"Very little of it","weights":{"sensitive":0.75,"overloaded":0.25}},{"label":"A fair amount","value":"A fair amount","weights":{"sensitive":0.5,"selective":0.5}},{"label":"A good amount, and I go looking for more of it","value":"A good amount, and I go looking for more of it","weights":{"selective":1}}]},{"id":"sensory-change","type":"choice","prompt":"Compared to a few years ago, has any of this changed?","domain":"history","options":[{"label":"It has become far more intense","value":"It has become far more intense","weights":{"overloaded":1}},{"label":"I have become more reactive to things","value":"I have become more reactive to things","weights":{"sensitive":0.75,"overloaded":0.25}},{"label":"About the same as it was","value":"About the same as it was","weights":{"selective":0.5,"sensitive":0.5}},{"label":"I have become less reactive","value":"I have become less reactive","weights":{"selective":1}},{"label":"A good deal of it has gone numb","value":"A good deal of it has gone numb","weights":{"numb":1}}]},{"id":"sensory-overload","type":"choice","prompt":"What most often takes you over the edge?","domain":"cause","options":[{"label":"Many small things at once","value":"Many small things at once","weights":{"sensitive":1}},{"label":"One thing that will not stop — a sound, a light, an ache","value":"One thing that will not stop — a sound, a light, an ache","weights":{"overloaded":1}},{"label":"Being tired or unwell beforehand","value":"Being tired or unwell beforehand","weights":{"selective":1}},{"label":"Rarely anything specific","value":"Rarely anything specific","weights":{"numb":1}}]},{"id":"sensory-downshift","type":"choice","prompt":"When there is too much coming in, how well can you turn it down?","domain":"control","options":[{"label":"I cannot — once it is up, it stays up","value":"I cannot — once it is up, it stays up","weights":{"overloaded":1}},{"label":"Only by leaving the situation","value":"Only by leaving the situation","weights":{"sensitive":0.75,"overloaded":0.25}},{"label":"By narrowing it deliberately, one thing at a time","value":"By narrowing it deliberately, one thing at a time","weights":{"selective":1}},{"label":"I can bring it down in the moment, fairly reliably","value":"I can bring it down in the moment, fairly reliably","weights":{"selective":0.5,"numb":0.5}},{"label":"I can turn it down and it actually goes down","value":"I can turn it down and it actually goes down","weights":{"numb":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["numb","selective","sensitive","overloaded"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"numb","label":"Low registration","short":"The world is arriving, unheard","description":"Input is arriving and not being received. Read from the outside this looks like steadiness; from the inside there is a great deal of not-knowing. Numbness is a real capacity to be turned back on, and the dial underneath it usually reads more sensitive than it currently does.","shadow":"Mistaking not registering for not happening.","color":"slate","masters":["observation","body"],"calibration":{"dimensions":{"body":0.3,"thought":0.2,"emotion":0.2},"practiceLevels":{"observation":1,"body":1},"tags":["dulled","under-received"]}},{"id":"selective","label":"Selective registration","short":"Some things land, most do not","description":"The filtering works, and it works well — most of the day passes without registering, and what does register was chosen by something. This is the most workable position of the four, and also the easiest to be complacent about.","shadow":"A filter that is never asked what it is filtering.","color":"teal","masters":["observation","raja"],"calibration":{"dimensions":{"thought":0.25,"body":0.2,"spirit":0.2},"practiceLevels":{"observation":1},"tags":["filtered","partly-aware"]}},{"id":"sensitive","label":"High registration","short":"Everything arrives, in detail","description":"The channels are wide open and detail is coming in continuously. There is a great deal of life in this, and a real cost to it, because there is no background level that lets a small thing stay small.","shadow":"Calling the sensitivity a difficulty rather than a dial setting.","color":"sky","masters":["body","breath"],"calibration":{"dimensions":{"body":0.3,"emotion":0.25,"spirit":0.2},"practiceLevels":{"body":1,"breath":1},"domainStress":{"senses":"health"},"tags":["sensitive","wide-open"]}},{"id":"overloaded","label":"Overload-prone","short":"The input outruns the processing","description":"There is capacity here, but not enough of it for what is coming in, and the overflow is felt in the body before it is noticed at all. The work here is not to feel less — it is to find the downstream valve that is currently missing.","shadow":"Pushing through a full system and calling the cost a personality.","color":"rose","masters":["breath","witnessing"],"calibration":{"dimensions":{"body":0.35,"emotion":0.3,"thought":0.15},"practiceLevels":{"breath":1,"witnessing":1},"domainStress":{"senses":"health"},"tags":["overloaded","flooded"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["body","observation"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
