-- Service instinct (12 Skills)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('service-instinct', 'Service instinct', 'Your natural Karma flavor', 'vedic', 'path', E'Service is usually presented as a decision. For some people it arrives long before the decision — the need is seen, the hand moves, and the reasoning catches up afterwards.\n\nThis looks at that reflex: whether it runs on exchange, whether it is chosen or reactive, and what happens to it when it is refused.', '🤲', 5, 8, '[{"id":"service-notice","type":"choice","prompt":"How often do you notice that someone needs something before they say so?","domain":"awareness","options":[{"label":"Almost never — I wait to be asked","value":"Almost never — I wait to be asked","weights":{"responsive":0}},{"label":"Rarely","value":"Rarely","weights":{"responsive":0.25}},{"label":"Sometimes","value":"Sometimes","weights":{"responsive":0.5}},{"label":"Often","value":"Often","weights":{"responsive":0.75}},{"label":"I usually see it before it is said","value":"I usually see it before it is said","weights":{"responsive":1}}]},{"id":"service-useful","type":"choice","prompt":"How easy is it for you to be useful to other people?","domain":"ease","options":[{"label":"I would rather not be asked","value":"I would rather not be asked","weights":{"self-directed":0,"responsive":0,"proactive":0,"spontaneous-service":0}},{"label":"I help when it is clear what is wanted","value":"I help when it is clear what is wanted","weights":{"self-directed":1,"responsive":0,"proactive":0,"spontaneous-service":0}},{"label":"It depends entirely on who is asking","value":"It depends entirely on who is asking","weights":{"self-directed":0,"responsive":1,"proactive":0,"spontaneous-service":0}},{"label":"I am genuinely useful to the people around me","value":"I am genuinely useful to the people around me","weights":{"self-directed":0,"responsive":0,"proactive":1,"spontaneous-service":0}},{"label":"Being useful is the easiest thing I do","value":"Being useful is the easiest thing I do","weights":{"self-directed":0,"responsive":0,"proactive":0,"spontaneous-service":1}}]},{"id":"service-exchange","type":"choice","prompt":"When you help someone, is there something coming back to you?","domain":"exchange","options":[{"label":"Help usually comes back to me somehow","value":"Help usually comes back to me somehow","weights":{"self-directed":1}},{"label":"I keep an honest mental tally of it","value":"I keep an honest mental tally of it","weights":{"responsive":1}},{"label":"I help because it is the right thing, whatever it returns","value":"I help because it is the right thing, whatever it returns","weights":{"proactive":1}},{"label":"I help before I have decided to help","value":"I help before I have decided to help","weights":{"spontaneous-service":1}}]},{"id":"service-avoided","type":"choice","prompt":"What is being avoided in your service?","domain":"shadow","options":[{"label":"Being needed","value":"Being needed","weights":{"self-directed":1}},{"label":"Being thanked, or not being thanked","value":"Being thanked, or not being thanked","weights":{"responsive":1}},{"label":"The limits of what I can actually do for someone","value":"The limits of what I can actually do for someone","weights":{"proactive":1}},{"label":"Nothing — I have not found the edge of it","value":"Nothing — I have not found the edge of it","weights":{"spontaneous-service":1}}]},{"id":"service-chosen","type":"choice","prompt":"Do you choose your helping, or does it arrive as a reaction to the moment?","domain":"choice","options":[{"label":"Pure reaction — it happens and then I am in it","value":"Pure reaction — it happens and then I am in it","weights":{"proactive":0}},{"label":"Mostly reaction","value":"Mostly reaction","weights":{"proactive":0.25}},{"label":"Half chosen, half reaction","value":"Half chosen, half reaction","weights":{"proactive":0.5}},{"label":"Mostly chosen before the moment arrives","value":"Mostly chosen before the moment arrives","weights":{"proactive":0.75}},{"label":"I choose it long before anyone has asked","value":"I choose it long before anyone has asked","weights":{"proactive":1}}]},{"id":"service-refused","type":"choice","prompt":"What happens inside you when someone refuses your help?","domain":"shadow","options":[{"label":"I feel rejected","value":"I feel rejected","weights":{"self-directed":1}},{"label":"I take it as a sign they did not really need me","value":"I take it as a sign they did not really need me","weights":{"responsive":1}},{"label":"I accept it and let it go","value":"I accept it and let it go","weights":{"proactive":1}},{"label":"I keep offering until I understand why","value":"I keep offering until I understand why","weights":{"spontaneous-service":1}}]},{"id":"service-after","type":"choice","prompt":"After a day of helping people, how do you feel?","domain":"ease","options":[{"label":"Completely drained","value":"Completely drained","weights":{"spontaneous-service":0}},{"label":"Tired, but glad it was useful","value":"Tired, but glad it was useful","weights":{"spontaneous-service":0.25}},{"label":"About the same as any other day","value":"About the same as any other day","weights":{"spontaneous-service":0.5}},{"label":"Lighter than I was before","value":"Lighter than I was before","weights":{"spontaneous-service":0.75}},{"label":"Genuinely restored by it","value":"Genuinely restored by it","weights":{"spontaneous-service":1}}]},{"id":"service-impulse","type":"choice","prompt":"How much do you act on an impulse to help, rather than waiting to be sure?","domain":"choice","options":[{"label":"I almost never act on the first impulse","value":"I almost never act on the first impulse","weights":{"spontaneous-service":0}},{"label":"Rarely","value":"Rarely","weights":{"spontaneous-service":0.25}},{"label":"About half the time","value":"About half the time","weights":{"spontaneous-service":0.5}},{"label":"Often","value":"Often","weights":{"spontaneous-service":0.75}},{"label":"The impulse and the act are the same thing","value":"The impulse and the act are the same thing","weights":{"spontaneous-service":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["self-directed","responsive","proactive","spontaneous-service"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"self-directed","label":"Help with a return expected","short":"Service that runs in both directions","description":"The helping is real and it is also largely managed. There is usually an account running underneath — proof of goodness, a place kept warm, a role to occupy. None of that makes the help less useful to the person receiving it.","shadow":"Needing to be needed in order to keep giving.","color":"amber","masters":["karma","relationship"],"calibration":{"dimensions":{"connection":0.3,"action":0.25,"emotion":0.2},"practiceLevels":{"karma":1,"relationship":1},"domainStress":{"relation":"relationship"},"tags":["accounted","role-bound"]}},{"id":"responsive","label":"Responsive","short":"You see the need and you meet it","description":"You notice what is missing and act on it. What tends to go untested here is the source of the noticing — how much of the seeing comes from genuinely attending, and how much from scanning for a role you can take.","shadow":"Attending to others as a way of avoiding your own.","color":"teal","masters":["karma","observation"],"calibration":{"dimensions":{"connection":0.3,"action":0.2,"thought":0.1},"practiceLevels":{"karma":1,"observation":1},"tags":["attentive","useful"]}},{"id":"proactive","label":"Proactive","short":"You move before being asked","description":"The help arrives ahead of the request, and you generally know when it is real. The remaining question is a quiet one — whether the initiative is yours, or a need of your own being met in someone else’s situation.","shadow":"Moving first to be the one who arrived.","color":"sky","masters":["karma","witnessing"],"calibration":{"dimensions":{"action":0.35,"connection":0.25,"spirit":0.1},"practiceLevels":{"karma":2,"witnessing":1},"tags":["initiative","chosen"]}},{"id":"spontaneous-service","label":"Spontaneous service","short":"It moves in you before it is a decision","description":"The impulse to help arrives whole and does not wait for consultation. It is the rarest of the four and the one most easily mistaken for a strength of character — it is better understood as a capacity that can be spent, or exhausted.","shadow":"Service that cannot be set down when it is not wanted.","color":"indigo","masters":["karma","witnessing"],"calibration":{"dimensions":{"connection":0.25,"spirit":0.35,"action":0.2},"practiceLevels":{"karma":2,"witnessing":2},"domainStress":{"contact":"relationship"},"tags":["immediate","non-negotiable"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["karma","relationship"],"deepens_with":["service-radius","karma-signature"]}'::jsonb, 1, true, false, 100, now())
