-- Service radius (4 Yogas)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('service-radius', 'Service radius', 'Who your circle of care includes', 'vedic', 'connection', E'Karma yoga has a scope question attached to it, and it is a harder one than it looks. Care that reliably stops at a familiar radius is real care, but it is not the same thing as the tradition is pointing at.\n\nThis asks where your radius is, and what sets it.', '🫂', 6, 6, '[{"id":"service-radius","type":"choice","prompt":"How far does your care naturally reach?","domain":"scope","options":[{"label":"Mostly myself","value":"Mostly myself","weights":{"household":1}},{"label":"Myself and the people closest to me","value":"Myself and the people closest to me","weights":{"household":1}},{"label":"Wider — a network, a community, work colleagues","value":"Wider — a network, a community, work colleagues","weights":{"household":1}},{"label":"A great many people, and I still know their names","value":"A great many people, and I still know their names","weights":{"household":1}},{"label":"Whoever is in front of me, without a boundary","value":"Whoever is in front of me, without a boundary","weights":{"household":1}}]},{"id":"service-widen","type":"choice","prompt":"Has that ever widened, and what happened?","domain":"growth","options":[{"label":"It has never changed","value":"It has never changed","weights":{"self":1,"household":0,"community":0,"all-sentient":0}},{"label":"It has narrowed, mostly by circumstance","value":"It has narrowed, mostly by circumstance","weights":{"self":0.25,"household":0.75,"community":0,"all-sentient":0}},{"label":"It has stayed about the same","value":"It has stayed about the same","weights":{"self":0,"household":0.5,"community":0.5,"all-sentient":0}},{"label":"It has widened a little","value":"It has widened a little","weights":{"self":0,"household":0,"community":0.75,"all-sentient":0.25}},{"label":"It has widened substantially and I know why","value":"It has widened substantially and I know why","weights":{"self":0,"household":0,"community":0,"all-sentient":1}}]},{"id":"service-difficulty","type":"choice","prompt":"Does difficulty of any kind widen your care or narrow it?","domain":"boundary","options":[{"label":"It narrows sharply","value":"It narrows sharply","weights":{"all-sentient":1}},{"label":"It narrows a little","value":"It narrows a little","weights":{"all-sentient":1}},{"label":"It makes no difference","value":"It makes no difference","weights":{"all-sentient":1}},{"label":"It widens — they need more","value":"It widens — they need more","weights":{"all-sentient":1}},{"label":"It is when I find out what I actually feel","value":"It is when I find out what I actually feel","weights":{"all-sentient":1}}]},{"id":"service-cost","type":"choice","prompt":"What does your care cost you, honestly?","domain":"cost","options":[{"label":"More than I can sustain","value":"More than I can sustain","weights":{"self":1,"household":0,"community":0,"all-sentient":0}},{"label":"Real energy, and I am running low","value":"Real energy, and I am running low","weights":{"self":0.25,"household":0.75,"community":0,"all-sentient":0}},{"label":"Real time I do not have","value":"Real time I do not have","weights":{"self":0,"household":0.5,"community":0.5,"all-sentient":0}},{"label":"A little, and it is fine","value":"A little, and it is fine","weights":{"self":0,"household":0,"community":0.75,"all-sentient":0.25}},{"label":"Nothing — it costs me nothing","value":"Nothing — it costs me nothing","weights":{"self":0,"household":0,"community":0,"all-sentient":1}}]},{"id":"service-reciprocity","type":"choice","prompt":"Does it need to be mutual?","domain":"direction","options":[{"label":"It has to be mutual, or it is not worth it","value":"It has to be mutual, or it is not worth it","weights":{"community":1}},{"label":"Some reciprocity is expected","value":"Some reciprocity is expected","weights":{"community":1}},{"label":"I do not track it","value":"I do not track it","weights":{"community":1}},{"label":"I do not need it back","value":"I do not need it back","weights":{"community":1}},{"label":"I actively prefer it not to be returned","value":"I actively prefer it not to be returned","weights":{"community":1}}]},{"id":"service-visibility","type":"choice","prompt":"Do you need anyone to know that you are doing it?","domain":"recognition","options":[{"label":"It would be hard to keep doing it unseen","value":"It would be hard to keep doing it unseen","weights":{"self":1,"household":0,"community":0,"all-sentient":0}},{"label":"Quite a lot","value":"Quite a lot","weights":{"self":0.25,"household":0.75,"community":0,"all-sentient":0}},{"label":"Some is nice","value":"Some is nice","weights":{"self":0,"household":0.5,"community":0.5,"all-sentient":0}},{"label":"No, not really","value":"No, not really","weights":{"self":0,"household":0,"community":0.75,"all-sentient":0.25}},{"label":"No — it would be worse if they did","value":"No — it would be worse if they did","weights":{"self":0,"household":0,"community":0,"all-sentient":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["self","household","community","all-sentient"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"self","label":"Self","short":"The circle has not widened yet","description":"Care is essentially self-directed. This is the honest starting point and it is where most people are, whatever the stated intentions. It requires no apology — it requires contact, which is a different kind of work entirely.","shadow":"Service that has not left the house being read as service.","color":"slate","masters":["karma","body"],"calibration":{"dimensions":{"action":0.2,"connection":0.25,"body":0.15},"practiceLevels":{"karma":1,"body":1},"tags":["service","self"]}},{"id":"household","label":"Household","short":"A real circle, and a fixed one","description":"Your care reaches the people you are already close to, which is where most people live. The radius is not unnaturally small — it is simply unstretched, and the question is what would widen it.","shadow":"Depth mistaken for breadth.","color":"amber","masters":["karma","relationship"],"calibration":{"dimensions":{"connection":0.3,"action":0.2},"practiceLevels":{"karma":1,"relationship":1},"domainStress":{"relation":"relationship"},"tags":["service","household"]}},{"id":"community","label":"Community","short":"A network, and reciprocity","description":"Your circle extends beyond the household and there is a normal expectation that it runs both ways. This is the shape of most long friendships and communities, and it works — until the reciprocity becomes the point.","shadow":"Keeping score inside the circle of care.","color":"teal","masters":["karma","relationship"],"calibration":{"dimensions":{"connection":0.35,"action":0.25},"practiceLevels":{"karma":1,"relationship":1},"domainStress":{"relation":"relationship"},"tags":["service","community"]}},{"id":"all-sentient","label":"Open","short":"No boundary, and not much visibility needed","description":"The circle is not organised by closeness. What is unusual about this reading is not the size of the radius but the absence of a need for it to be seen — which is the part most people get wrong.","shadow":"Diffuse care, which can also mean no actual care.","color":"emerald","masters":["karma","bhakti"],"calibration":{"dimensions":{"connection":0.4,"spirit":0.3,"action":0.2},"practiceLevels":{"karma":2,"bhakti":1},"tags":["service","open"]}}]'::jsonb, '{"loops_to_check":["isolation","over-giving"],"practice_affinity":["karma","relationship"],"deepens_with":["service-instinct","community-rooting"]}'::jsonb, 1, true, false, 100, now())
