  is_featured,
  sort_order,
  updated_at
) VALUES
    ('sexuality-eros', 'Sexuality & eros', 'Kāma — met honestly', 'vedic', 'attachment', E'Kāma is the tradition’s word for desire in the widest sense — attraction, wanting, and the pull that something has on you. It is not a moral category. It is what a body does when it reaches for something, and it does not stop because it has been told to.\n\nThis asks how that is handled in your life: whether it is shameful or ordinary, whether it is said or swallowed, and whether it is bound up with love or kept somewhere separate. It is not asking how much of it you have. It is asking what you do with it.', '🕯️', 7, 8, '[{"id":"eros-place","type":"choice","prompt":"Where does wanting sit in your daily life?","domain":"desire","options":[{"label":"It is not something I look at","value":"It is not something I look at","weights":{"suppressed":0,"obligated":0,"expressive":0,"integrated":0}},{"label":"I keep it out of sight","value":"I keep it out of sight","weights":{"suppressed":1,"obligated":0,"expressive":0,"integrated":0}},{"label":"I allow it in the forms I am allowed to allow it","value":"I allow it in the forms I am allowed to allow it","weights":{"suppressed":0,"obligated":1,"expressive":0,"integrated":0}},{"label":"I say what I want, plainly","value":"I say what I want, plainly","weights":{"suppressed":0,"obligated":0,"expressive":1,"integrated":0}},{"label":"I want what I want, and it needs no separate category","value":"I want what I want, and it needs no separate category","weights":{"suppressed":0,"obligated":0,"expressive":0,"integrated":1}}]},{"id":"eros-shame","type":"choice","prompt":"Growing up, was desire treated as something to be embarrassed about?","domain":"shame","options":[{"label":"Heavily","value":"Heavily","weights":{"suppressed":1,"obligated":0,"expressive":0,"integrated":0}},{"label":"Fairly","value":"Fairly","weights":{"suppressed":0.25,"obligated":0.75,"expressive":0,"integrated":0}},{"label":"Some of it","value":"Some of it","weights":{"suppressed":0,"obligated":0.5,"expressive":0.5,"integrated":0}},{"label":"Mostly not","value":"Mostly not","weights":{"suppressed":0,"obligated":0,"expressive":0.75,"integrated":0.25}},{"label":"Not at all, and it was spoken of plainly","value":"Not at all, and it was spoken of plainly","weights":{"suppressed":0,"obligated":0,"expressive":0,"integrated":1}}]},{"id":"eros-said","type":"choice","prompt":"How much of what you actually want do you say out loud?","domain":"expression","options":[{"label":"Almost none of it","value":"Almost none of it","weights":{"suppressed":1,"obligated":0,"expressive":0,"integrated":0}},{"label":"Very little of it","value":"Very little of it","weights":{"suppressed":0.25,"obligated":0.75,"expressive":0,"integrated":0}},{"label":"Some of it","value":"Some of it","weights":{"suppressed":0,"obligated":0.5,"expressive":0.5,"integrated":0}},{"label":"Most of it","value":"Most of it","weights":{"suppressed":0,"obligated":0,"expressive":0.75,"integrated":0.25}},{"label":"All of it, and early","value":"All of it, and early","weights":{"suppressed":0,"obligated":0,"expressive":0,"integrated":1}}]},{"id":"eros-for","type":"choice","prompt":"What is desire mostly for, as far as you can tell?","domain":"function","options":[{"label":"Pleasure, mostly","value":"Pleasure, mostly","weights":{"integrated":1}},{"label":"Connection, mostly","value":"Connection, mostly","weights":{"integrated":1}},{"label":"Something to want while I get on with the rest of it","value":"Something to want while I get on with the rest of it","weights":{"integrated":1}},{"label":"A sense of being desirable, or worth something","value":"A sense of being desirable, or worth something","weights":{"integrated":1}},{"label":"I have not honestly worked this out","value":"I have not honestly worked this out","weights":{"integrated":1}}]},{"id":"eros-split","type":"choice","prompt":"Can you be in love with someone and want them at the same time?","domain":"love","options":[{"label":"They have nothing to do with each other for me","value":"They have nothing to do with each other for me","weights":{"integrated":1}},{"label":"They are separate, and I keep them separate","value":"They are separate, and I keep them separate","weights":{"integrated":1}},{"label":"They are joined, but awkward","value":"They are joined, but awkward","weights":{"integrated":1}},{"label":"They are joined and mostly easy","value":"They are joined and mostly easy","weights":{"integrated":1}},{"label":"I have never had to separate them","value":"I have never had to separate them","weights":{"integrated":1}}]},{"id":"eros-body","type":"choice","prompt":"How do you treat your own body in relation to all this?","domain":"body","options":[{"label":"Something to manage and cover","value":"Something to manage and cover","weights":{"suppressed":1,"obligated":0,"expressive":0,"integrated":0}},{"label":"Something to manage","value":"Something to manage","weights":{"suppressed":0.25,"obligated":0.75,"expressive":0,"integrated":0}},{"label":"Mine, without much thought either way","value":"Mine, without much thought either way","weights":{"suppressed":0,"obligated":0.5,"expressive":0.5,"integrated":0}},{"label":"A place I enjoy being in","value":"A place I enjoy being in","weights":{"suppressed":0,"obligated":0,"expressive":0.75,"integrated":0.25}},{"label":"The place I actually live","value":"The place I actually live","weights":{"suppressed":0,"obligated":0,"expressive":0,"integrated":1}}]},{"id":"eros-integration","type":"choice","prompt":"If this part of your life were properly sorted, what would change?","domain":"integration","options":[{"label":"I genuinely cannot name it","value":"I genuinely cannot name it","weights":{"suppressed":1,"obligated":0,"expressive":0,"integrated":0}},{"label":"A little less tension","value":"A little less tension","weights":{"suppressed":0.25,"obligated":0.75,"expressive":0,"integrated":0}},{"label":"I would be less hard on myself","value":"I would be less hard on myself","weights":{"suppressed":0,"obligated":0.5,"expressive":0.5,"integrated":0}},{"label":"I would be more available to the people close to me","value":"I would be more available to the people close to me","weights":{"suppressed":0,"obligated":0,"expressive":0.75,"integrated":0.25}},{"label":"The whole area would stop being a subject","value":"The whole area would stop being a subject","weights":{"suppressed":0,"obligated":0,"expressive":0,"integrated":1}}]},{"id":"eros-restraint","type":"choice","prompt":"Is there restraint around any of this, and where does that restraint come from?","domain":"boundary","options":[{"label":"Not much of it","value":"Not much of it","weights":{"obligated":1}},{"label":"A fair amount, and I set it myself","value":"A fair amount, and I set it myself","weights":{"obligated":1}},{"label":"It comes from my family","value":"It comes from my family","weights":{"obligated":1}},{"label":"It comes from religion, or from my values","value":"It comes from religion, or from my values","weights":{"obligated":1}},{"label":"It comes from somewhere I have never examined","value":"It comes from somewhere I have never examined","weights":{"obligated":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["suppressed","obligated","expressive","integrated"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"suppressed","label":"Suppressed","short":"Desire is not being looked at","description":"The wanting is there and the looking is not. What has been shut down is not the capacity — it is the relationship to it, and that relationship was set by someone else a long time ago. This resolves with contact, not with decisions.","shadow":"Reading the absence of desire as the absence of a life.","color":"rose","masters":["bhakti","emotional-healing"],"calibration":{"dimensions":{"emotion":0.35,"connection":0.25,"body":0.15},"practiceLevels":{"bhakti":1,"emotional-healing":1},"domainStress":{"relation":"relationship"},"tags":["desire-disowned","shame-carrying"]}},{"id":"obligated","label":"Obligated","short":"Only permitted in certain forms","description":"Wanting has been given a narrow channel and a set of conditions. Inside those conditions it is expressed; outside them it goes quiet. The result is a life where intimacy has a job description attached to it.","shadow":"Confusing the role with the person in it.","color":"amber","masters":["relationship","karma"],"calibration":{"dimensions":{"connection":0.3,"emotion":0.25,"action":0.15},"practiceLevels":{"relationship":1,"karma":1},"domainStress":{"relation":"relationship"},"tags":["duty-shaped","role-bound"]}},{"id":"expressive","label":"Expressive","short":"Wanting is alive and said plainly","description":"Desire is available to you and it is named when it appears. That makes it workable — the costs of this shape are honesty and some exposure, and both are cheaper than the alternative.","shadow":"Offering what is wanted instead of what is wanted by you.","color":"teal","masters":["bhakti","relationship"],"calibration":{"dimensions":{"emotion":0.25,"connection":0.3,"body":0.2},"practiceLevels":{"bhakti":1,"relationship":1},"tags":["desire-alive","direct"]}},{"id":"integrated","label":"Integrated","short":"Wanting and loving are one movement","description":"Desire no longer has to be exiled for love to be serious, and it no longer has to be exaggerated for it to be felt. This is the shape where the eros stops being a separate department of the life.","shadow":"Integration used as a reason to stop looking.","color":"violet","masters":["bhakti","tantra"],"calibration":{"dimensions":{"spirit":0.3,"connection":0.25,"emotion":0.2},"practiceLevels":{"bhakti":2,"tantra":1},"tags":["desire-integrated","no-split"]}}]'::jsonb, '{"loops_to_check":["shame","avoidance"],"practice_affinity":["bhakti","relationship"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
