-- Shadow inventory (Loops)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('shadow-inventory', 'Shadow inventory', 'What you do not recognise as yours', 'jungian', 'shadow', E'What we cannot tolerate in ourselves tends to turn up in other people with remarkable frequency. That is not proof of anything — it is just what attention does when it cannot find the thing at home.\n\nThis is an inventory, not an accusation. Nothing here is a finding about you, and nothing here is a verdict on anybody else. The useful version of this is a list you could actually read aloud.', '🌑', 7, 7, '[{"id":"shadow-list","type":"choice","prompt":"How much of your own difficult material could you actually list right now?","domain":"inventory","options":[{"label":"I could not begin","value":"I could not begin","weights":{"unseen":0}},{"label":"A general sense that something is off, with no details","value":"A general sense that something is off, with no details","weights":{"unseen":0.25}},{"label":"A handful of things I could probably name","value":"A handful of things I could probably name","weights":{"unseen":0.5}},{"label":"A list I could read out","value":"A list I could read out","weights":{"unseen":0.75}},{"label":"A list I have worked through, item by item","value":"A list I have worked through, item by item","weights":{"unseen":1}}]},{"id":"shadow-glimpse","type":"choice","prompt":"How often does something in you surface for a second and then get explained away?","domain":"glimpses","options":[{"label":"It has never happened to me","value":"It has never happened to me","weights":{"suspected":0}},{"label":"Rarely — I would notice if it did","value":"Rarely — I would notice if it did","weights":{"suspected":0.25}},{"label":"Often enough that I have a word for it","value":"Often enough that I have a word for it","weights":{"suspected":0.5}},{"label":"Constantly, and I have a name for the explaining","value":"Constantly, and I have a name for the explaining","weights":{"suspected":0.75}},{"label":"I can usually feel it happening, and watch myself reach for the explanation","value":"I can usually feel it happening, and watch myself reach for the explanation","weights":{"suspected":1}}]},{"id":"shadow-other","type":"choice","prompt":"How quickly do you notice a trait in someone else that you find hard to stand?","domain":"recognition","options":[{"label":"I do not think this happens to me","value":"I do not think this happens to me","weights":{"projected":0}},{"label":"Occasionally, usually after a while","value":"Occasionally, usually after a while","weights":{"projected":0.25}},{"label":"Quite quickly, and I usually form a view","value":"Quite quickly, and I usually form a view","weights":{"projected":0.5}},{"label":"Almost immediately, and the view is formed","value":"Almost immediately, and the view is formed","weights":{"projected":0.75}},{"label":"Immediately — and I have learned that the irritation is usually about me","value":"Immediately — and I have learned that the irritation is usually about me","weights":{"projected":1}}]},{"id":"shadow-timing","type":"choice","prompt":"How long does it take you to notice that the thing that annoyed you was yours?","domain":"delay","options":[{"label":"I do not think it ever does","value":"I do not think it ever does","weights":{"suspected":0}},{"label":"Months, if ever","value":"Months, if ever","weights":{"suspected":0.25}},{"label":"Weeks","value":"Weeks","weights":{"suspected":0.5}},{"label":"Days — usually after I have said something I regret","value":"Days — usually after I have said something I regret","weights":{"suspected":0.75}},{"label":"Hours, and I still talk myself out of it the first time","value":"Hours, and I still talk myself out of it the first time","weights":{"suspected":1}}]},{"id":"shadow-where","type":"choice","prompt":"Someone you know does the thing that annoys you most. Where does it land?","domain":"friction","options":[{"label":"It stays with them. I have my own reasons","value":"It stays with them. I have my own reasons","weights":{"unseen":1,"suspected":0,"projected":0,"owned":0}},{"label":"It stays with them, and something in me recognises the shape of it","value":"It stays with them, and something in me recognises the shape of it","weights":{"unseen":0.25,"suspected":0.75,"projected":0,"owned":0}},{"label":"It takes me two days to notice it is about me","value":"It takes me two days to notice it is about me","weights":{"unseen":0,"suspected":0.5,"projected":0.5,"owned":0}},{"label":"I notice mid-sentence and say so","value":"I notice mid-sentence and say so","weights":{"unseen":0,"suspected":0,"projected":0.75,"owned":0.25}},{"label":"I bring it up afterwards, plainly, without making them carry it","value":"I bring it up afterwards, plainly, without making them carry it","weights":{"unseen":0,"suspected":0,"projected":0,"owned":1}}]},{"id":"shadow-say","type":"choice","prompt":"How easily could you say out loud the thing about yourself you like least?","domain":"admission","options":[{"label":"Not at all — I would rather not","value":"Not at all — I would rather not","weights":{"owned":0}},{"label":"To one person, and long ago","value":"To one person, and long ago","weights":{"owned":0.25}},{"label":"In the past, to people who were safe","value":"In the past, to people who were safe","weights":{"owned":0.5}},{"label":"Fairly easily, in the right company","value":"Fairly easily, in the right company","weights":{"owned":0.75}},{"label":"I can say it plainly without it becoming a performance","value":"I can say it plainly without it becoming a performance","weights":{"owned":1}}]},{"id":"shadow-chosen","type":"choice","prompt":"How much of what you call your character is something you chose?","domain":"integration","options":[{"label":"Very little — it is what I am","value":"Very little — it is what I am","weights":{"owned":0}},{"label":"A bit, in places I have worked at","value":"A bit, in places I have worked at","weights":{"owned":0.25}},{"label":"A fair amount, mostly in the last few years","value":"A fair amount, mostly in the last few years","weights":{"owned":0.5}},{"label":"Most of what I count as mine, deliberately","value":"Most of what I count as mine, deliberately","weights":{"owned":0.75}},{"label":"I take what is mine and hand back the rest as material I am still carrying","value":"I take what is mine and hand back the rest as material I am still carrying","weights":{"owned":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["unseen","suspected","projected","owned"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"unseen","label":"Not yet on the list","short":"A general sense, no items","description":"Something is not right and it has no name. There is very little to work with here, and that is the honest position: the noticing is the first item, and it is smaller than it sounds.","shadow":"Reading the unnamed thing as a character defect.","color":"slate","masters":["witnessing","self-inquiry"],"calibration":{"dimensions":{"thought":0.25,"emotion":0.2,"spirit":0.15},"practiceLevels":{"witnessing":1,"self-inquiry":1},"tags":["unseen","unnamed"]}},{"id":"suspected","label":"Suspected","short":"You have noticed and moved on","description":"The material is close to being visible and gets accounted for each time it surfaces. Suspicion without confirmation is an uncomfortable place to sit, because the hypothesis keeps re-running without ever being tested.","shadow":"Collecting suspicions and never checking one.","color":"amber","masters":["witnessing","jnana"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.25,"spirit":0.15},"practiceLevels":{"witnessing":1,"jnana":1},"tags":["suspected","deferred"]}},{"id":"projected","label":"Out there first","short":"You see it in other people clearly","description":"The trait is unmistakable in other people and almost invisible in yourself. This is the most common shape of the whole thing, and it is genuinely useful once you know it is happening, because the material is already in view — it is just attached to the wrong person.","shadow":"Being very clear about them, and only at a distance.","color":"violet","masters":["witnessing","loop-dissolution"],"calibration":{"dimensions":{"connection":0.3,"thought":0.25,"emotion":0.25},"practiceLevels":{"witnessing":2,"loop-dissolution":1},"domainStress":{"friction":"relationship"},"tags":["projected","externalised"]}},{"id":"owned","label":"Owned","short":"You have signed for it","description":"The material has been looked at, said out loud, and taken on without requiring anyone else to confirm it. Ownership is not a feeling — it is a decision you have already made, and it can be revisited.","shadow":"Using the inventory as a reason to withdraw from people.","color":"teal","masters":["jnana","loop-dissolution"],"calibration":{"dimensions":{"spirit":0.3,"thought":0.25,"connection":0.2},"practiceLevels":{"jnana":1,"loop-dissolution":1},"domainStress":{"contact":"relationship"},"tags":["owned","taken-on"]}}]'::jsonb, '{"loops_to_check":["projection","self-criticism"],"practice_affinity":["jnana","witnessing"],"deepens_with":["jungian-archetypes","karmic-patterns","inner-council"]}'::jsonb, 1, true, false, 100, now())
