  updated_at
) VALUES
    ('silence-tolerance', 'Silence tolerance', 'How long you can sit alone with yourself', 'vedic', 'witness', E'Silence is not the absence of input. It is the absence of a reason to be somewhere else.\n\nMost people believe they cannot tolerate silence. What is usually true is that the mind cannot tolerate being unattended. This measures how long it can be left alone.', '🤫', 5, 8, '[{"id":"silence-unattended","type":"choice","prompt":"When you are alone with nothing to do, how soon do you reach for something?","domain":"tolerance","options":[{"label":"Almost immediately","value":"Almost immediately","weights":{"restless":0,"tolerant":0,"settled":0,"profound":0}},{"label":"Within a minute or two","value":"Within a minute or two","weights":{"restless":1,"tolerant":0,"settled":0,"profound":0}},{"label":"After five minutes or so","value":"After five minutes or so","weights":{"restless":0,"tolerant":1,"settled":0,"profound":0}},{"label":"I can sit a while","value":"I can sit a while","weights":{"restless":0,"tolerant":0,"settled":1,"profound":0}},{"label":"I can sit with it indefinitely","value":"I can sit with it indefinitely","weights":{"restless":0,"tolerant":0,"settled":0,"profound":1}}]},{"id":"silence-pain","type":"choice","prompt":"Is stillness uncomfortable for you, or just uninteresting?","domain":"tolerance","options":[{"label":"It is genuinely uncomfortable","value":"It is genuinely uncomfortable","weights":{"restless":1,"tolerant":0,"settled":0,"profound":0}},{"label":"It makes me restless","value":"It makes me restless","weights":{"restless":0.25,"tolerant":0.75,"settled":0,"profound":0}},{"label":"It is just boring","value":"It is just boring","weights":{"restless":0,"tolerant":0.5,"settled":0.5,"profound":0}},{"label":"It is restful","value":"It is restful","weights":{"restless":0,"tolerant":0,"settled":0.75,"profound":0.25}},{"label":"I want more of it","value":"I want more of it","weights":{"restless":0,"tolerant":0,"settled":0,"profound":1}}]},{"id":"silence-thoughts","type":"choice","prompt":"What happens in your mind when there is nothing else to think about?","domain":"tolerance","options":[{"label":"It gets loud and unpleasant","value":"It gets loud and unpleasant","weights":{"restless":1,"tolerant":0,"settled":0,"profound":0}},{"label":"It runs through problems","value":"It runs through problems","weights":{"restless":0.25,"tolerant":0.75,"settled":0,"profound":0}},{"label":"It reviews my life","value":"It reviews my life","weights":{"restless":0,"tolerant":0.5,"settled":0.5,"profound":0}},{"label":"It goes fairly quiet","value":"It goes fairly quiet","weights":{"restless":0,"tolerant":0,"settled":0.75,"profound":0.25}},{"label":"It opens up","value":"It opens up","weights":{"restless":0,"tolerant":0,"settled":0,"profound":1}}]},{"id":"silence-alone","type":"choice","prompt":"How comfortable are you alone with no one to talk to?","domain":"tolerance","options":[{"label":"I avoid it entirely","value":"I avoid it entirely","weights":{"restless":1,"tolerant":0,"settled":0,"profound":0}},{"label":"I find it difficult","value":"I find it difficult","weights":{"restless":0.25,"tolerant":0.75,"settled":0,"profound":0}},{"label":"I can manage","value":"I can manage","weights":{"restless":0,"tolerant":0.5,"settled":0.5,"profound":0}},{"label":"I enjoy it","value":"I enjoy it","weights":{"restless":0,"tolerant":0,"settled":0.75,"profound":0.25}},{"label":"It is one of my favourite states","value":"It is one of my favourite states","weights":{"restless":0,"tolerant":0,"settled":0,"profound":1}}]},{"id":"silence-noticing","type":"choice","prompt":"When you sit still, what do you notice first?","domain":"tolerance","options":[{"label":"My thoughts","value":"My thoughts","weights":{"restless":1,"tolerant":0,"settled":0,"profound":0}},{"label":"My body","value":"My body","weights":{"restless":0.25,"tolerant":0.75,"settled":0,"profound":0}},{"label":"My breathing","value":"My breathing","weights":{"restless":0,"tolerant":0.5,"settled":0.5,"profound":0}},{"label":"The room around me","value":"The room around me","weights":{"restless":0,"tolerant":0,"settled":0.75,"profound":0.25}},{"label":"Something I cannot put into words","value":"Something I cannot put into words","weights":{"restless":0,"tolerant":0,"settled":0,"profound":1}}]},{"id":"silence-practice","type":"choice","prompt":"How much time do you deliberately spend being still?","domain":"tolerance","options":[{"label":"None","value":"None","weights":{"restless":1,"tolerant":0,"settled":0,"profound":0}},{"label":"Occasionally","value":"Occasionally","weights":{"restless":0.25,"tolerant":0.75,"settled":0,"profound":0}},{"label":"A few times a month","value":"A few times a month","weights":{"restless":0,"tolerant":0.5,"settled":0.5,"profound":0}},{"label":"Most days","value":"Most days","weights":{"restless":0,"tolerant":0,"settled":0.75,"profound":0.25}},{"label":"It structures my day","value":"It structures my day","weights":{"restless":0,"tolerant":0,"settled":0,"profound":1}}]},{"id":"silence-others","type":"choice","prompt":"How do you feel when someone else needs silence from you?","domain":"tolerance","options":[{"label":"I find it hard","value":"I find it hard","weights":{"restless":1,"tolerant":0,"settled":0,"profound":0}},{"label":"I fill it quickly","value":"I fill it quickly","weights":{"restless":0.25,"tolerant":0.75,"settled":0,"profound":0}},{"label":"I manage","value":"I manage","weights":{"restless":0,"tolerant":0.5,"settled":0.5,"profound":0}},{"label":"I am comfortable","value":"I am comfortable","weights":{"restless":0,"tolerant":0,"settled":0.75,"profound":0.25}},{"label":"I protect it for them","value":"I protect it for them","weights":{"restless":0,"tolerant":0,"settled":0,"profound":1}}]},{"id":"silence-want","type":"choice","prompt":"If you could have unlimited silence, would you take it?","domain":"tolerance","options":[{"label":"I would not — it is not for me","value":"I would not — it is not for me","weights":{"restless":1,"tolerant":0,"settled":0,"profound":0}},{"label":"I would, occasionally","value":"I would, occasionally","weights":{"restless":0.25,"tolerant":0.75,"settled":0,"profound":0}},{"label":"I would, regularly","value":"I would, regularly","weights":{"restless":0,"tolerant":0.5,"settled":0.5,"profound":0}},{"label":"I would, most of the time","value":"I would, most of the time","weights":{"restless":0,"tolerant":0,"settled":0.75,"profound":0.25}},{"label":"I am already asking for it","value":"I am already asking for it","weights":{"restless":0,"tolerant":0,"settled":0,"profound":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["restless","tolerant","settled","profound"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"restless","label":"Restless","short":"Unattended, the mind objects","description":"Silence gets interpreted as something to be escaped. The discomfort is real and it is also the single most useful thing about your practice right now — it shows exactly where the escape reflex lives.","shadow":"Believing you have no inner life to find.","color":"rose","masters":["witnessing","breath"],"calibration":{"dimensions":{"spirit":0.3,"thought":0.2,"emotion":0.15},"practiceLevels":{"witnessing":1,"breath":1},"tags":["restless","avoidant"]}},{"id":"tolerant","label":"Tolerant","short":"You can sit, with effort","description":"You can stay with stillness for a while, and the mind makes noise during it. The capacity exists; it is just not yet automatic, and it is being spent on resisting the noise rather than on the silence itself.","shadow":"Mistaking endurance for peace.","color":"amber","masters":["witnessing","breath"],"calibration":{"dimensions":{"spirit":0.25,"thought":0.2,"body":0.1},"practiceLevels":{"witnessing":1,"breath":1},"tags":["tolerating","noisy"]}},{"id":"settled","label":"Settled","short":"Silence is somewhere you can live","description":"Stillness is not threatening to you, and you can return to it deliberately. The mind still speaks, but there is a floor beneath it that stays quiet.","shadow":"Comfortable enough to stop looking.","color":"teal","masters":["witnessing","raja"],"calibration":{"dimensions":{"spirit":0.3,"body":0.15,"emotion":0.15},"practiceLevels":{"witnessing":2},"tags":["settled","grounded"]}},{"id":"profound","label":"Profound","short":"You go there deliberately","description":"Silence is a place you go on purpose, and you know what is on the other side of the noise. This is a capacity worth being careful with — it can become its own escape when it starts to be preferred to the difficult conversations.","shadow":"Silence used to avoid rather than to see.","color":"indigo","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.45,"thought":0.2},"practiceLevels":{"witnessing":2,"jnana":1},"domainStress":{"contact":"relationship"},"tags":["deep","at-home-in-quiet"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["witnessing","breath"],"deepens_with":["inner-silence","meditation-depth"]}'::jsonb, 1, true, false, 100, now())
