-- Sleep signature (Engines)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('sleep-signature', 'Sleep signature', 'The quality and rhythm of your rest', 'yogic', 'vitality', E'Hours in bed and rest restored are two different measurements, and the distance between them is where a lot of a life is spent.\n\nThis reads the shape of the night: the descent, the middle, the waking, and what is actually left on the other side. It is not a request to fix your sleep. It is a reading of what your nights are currently made of.', '🌙', 6, 8, '[{"id":"sleep-falling","type":"choice","prompt":"Once you get into bed, how long before you are asleep?","domain":"onset","options":[{"label":"A long time — I am usually awake well past it","value":"A long time — I am usually awake well past it","weights":{"restless":1}},{"label":"Longer than I would like","value":"Longer than I would like","weights":{"restless":0.75,"shallow":0.25}},{"label":"Eventually","value":"Eventually","weights":{"shallow":1}},{"label":"Fairly quickly","value":"Fairly quickly","weights":{"shallow":0.25,"restorative":0.75}},{"label":"Before I have finished putting the day down","value":"Before I have finished putting the day down","weights":{"restorative":1}}]},{"id":"sleep-staying","type":"choice","prompt":"If you wake in the night, what happens next?","domain":"continuity","options":[{"label":"I am awake for hours and the day is ruined","value":"I am awake for hours and the day is ruined","weights":{"broken":1}},{"label":"I lie there for a while, awake","value":"I lie there for a while, awake","weights":{"restless":1}},{"label":"I wake at close to the same hour most nights","value":"I wake at close to the same hour most nights","weights":{"shallow":1}},{"label":"I am back asleep almost at once","value":"I am back asleep almost at once","weights":{"restorative":1}}]},{"id":"sleep-waking","type":"choice","prompt":"How do you feel in the first few minutes of the day?","domain":"morning","options":[{"label":"Worse than when I went to sleep","value":"Worse than when I went to sleep","weights":{"shallow":1}},{"label":"As tired as I was before","value":"As tired as I was before","weights":{"shallow":0.75,"broken":0.25}},{"label":"About the same, no real change","value":"About the same, no real change","weights":{"broken":1}},{"label":"Noticeably better than when I went down","value":"Noticeably better than when I went down","weights":{"broken":0.25,"restorative":0.75}},{"label":"As if I had been given something","value":"As if I had been given something","weights":{"restorative":1}}]},{"id":"sleep-dreams","type":"choice","prompt":"How often do you remember dreaming?","domain":"content","options":[{"label":"I rarely remember any of it","value":"I rarely remember any of it","weights":{"shallow":1}},{"label":"Only fragments, usually when something is unfinished","value":"Only fragments, usually when something is unfinished","weights":{"restless":1}},{"label":"Vivid, story-like dreams most nights","value":"Vivid, story-like dreams most nights","weights":{"broken":1}},{"label":"I dream, and I wake up rested","value":"I dream, and I wake up rested","weights":{"restorative":1}}]},{"id":"sleep-time","type":"choice","prompt":"What time do you usually end up going to bed?","domain":"rhythm","options":[{"label":"Whenever I finally stop","value":"Whenever I finally stop","weights":{"restless":1}},{"label":"Very late, well past one","value":"Very late, well past one","weights":{"restless":0.75,"broken":0.25}},{"label":"Around midnight","value":"Around midnight","weights":{"broken":1}},{"label":"Around eleven","value":"Around eleven","weights":{"broken":0.25,"restorative":0.75}},{"label":"By ten or earlier","value":"By ten or earlier","weights":{"restorative":1}}]},{"id":"sleep-body","type":"choice","prompt":"What does your body do at night?","domain":"night","options":[{"label":"Still going through the day in my head","value":"Still going through the day in my head","weights":{"shallow":1}},{"label":"Clenching, and I only find the tension in the morning","value":"Clenching, and I only find the tension in the morning","weights":{"broken":1}},{"label":"Restless limbs, a body that will not settle","value":"Restless limbs, a body that will not settle","weights":{"restless":1}},{"label":"Still, and genuinely at rest","value":"Still, and genuinely at rest","weights":{"restorative":1}}]},{"id":"sleep-restores","type":"choice","prompt":"Does a normal night actually restore anything?","domain":"restoration","options":[{"label":"Not at all — I go down as tired as I get up","value":"Not at all — I go down as tired as I get up","weights":{"shallow":1}},{"label":"Barely, if anything","value":"Barely, if anything","weights":{"shallow":0.75,"broken":0.25}},{"label":"Enough to function, nothing more","value":"Enough to function, nothing more","weights":{"shallow":0.5,"restorative":0.5}},{"label":"A real amount","value":"A real amount","weights":{"shallow":0.25,"restorative":0.75}},{"label":"A great deal — I come up with something","value":"A great deal — I come up with something","weights":{"restorative":1}}]},{"id":"sleep-good-night","type":"choice","prompt":"How often do you have a genuinely good night?","domain":"frequency","options":[{"label":"Almost never","value":"Almost never","weights":{"shallow":1}},{"label":"Rarely","value":"Rarely","weights":{"shallow":0.75,"broken":0.25}},{"label":"About half the time","value":"About half the time","weights":{"shallow":0.5,"restorative":0.5}},{"label":"Most nights","value":"Most nights","weights":{"broken":0.25,"restorative":0.75}},{"label":"Nearly every night, and I know why","value":"Nearly every night, and I know why","weights":{"restorative":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["restless","shallow","broken","restorative"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"restless","label":"Restless nights","short":"Down, but not asleep","description":"The body agrees to lie down and the mind does not agree to be left. Time is spent in bed without being spent asleep, and the gap gets read as insomnia rather than as restlessness — which is a different situation with a different answer.","shadow":"Counting hours in bed as the measure of rest.","color":"rose","masters":["witnessing","breath"],"calibration":{"dimensions":{"thought":0.3,"body":0.3,"spirit":0.2},"practiceLevels":{"witnessing":1,"breath":1},"domainStress":{"rest":"observation"},"tags":["restless","mind-not-switching-off"]}},{"id":"shallow","label":"Shallow sleep","short":"Present, but nothing gets finished","description":"The hours are slept and the hours do not do their work. Nothing is properly processed overnight, and the morning arrives without a clear deposit. This is often the reading when the day has not been digested rather than the night itself.","shadow":"Mistaking low quality for a short night.","color":"slate","masters":["observation","body"],"calibration":{"dimensions":{"body":0.3,"thought":0.25,"emotion":0.15},"practiceLevels":{"observation":1,"body":1},"tags":["unrestored","undigested"]}},{"id":"broken","label":"Interrupted sleep","short":"The night keeps being cut short","description":"Sleep is repeatedly cut and restarted, often on a schedule regular enough that the body has begun to expect it. Because the hours still add up, it is often only noticed when something else in the day stops working.","shadow":"Assuming the interruption is identical on every night when it is not.","color":"orange","masters":["health","breath"],"calibration":{"dimensions":{"body":0.35,"emotion":0.25},"practiceLevels":{"health":1,"breath":1},"domainStress":{"rest":"health"},"tags":["fragmented","interrupted"]}},{"id":"restorative","label":"Restorative sleep","short":"The night actually pays something back","description":"Sleep does its work and the morning has something in it. The night is also regular enough that the body can rely on it, which means it is doing more than restoring — it is holding part of the structure of the week together.","shadow":"A night so good it stops being looked at.","color":"emerald","masters":["breath","raja"],"calibration":{"dimensions":{"body":0.25,"spirit":0.25,"emotion":0.2},"practiceLevels":{"breath":1},"tags":["restored","rhythmic"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["breath","body"],"deepens_with":["energy-baseline"]}'::jsonb, 1, true, false, 100, now())
