-- Spiritual bypass (Levels)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('spiritual-bypass', 'Spiritual bypass', 'Using the language of depth to avoid the shallows', 'vedic', 'shadow', E'Every serious tradition eventually produces its own ways of avoiding itself, and they are usually elegant. A developed vocabulary is not the same thing as contact with what is actually happening, and the two can move in opposite directions without anyone noticing.\n\nNobody can reliably spot this in themselves — that is the reason it is worth asking at all. The question is not whether you do it, because everyone does it somewhere and does it often. It is whether it shows up in the people closest to you, who are the only reliable witnesses available.', '🎪', 7, 7, '[{"id":"bypass-vocabulary","type":"choice","prompt":"How often do you describe something difficult in the language of depth rather than saying what is happening?","domain":"language","options":[{"label":"I describe what is actually happening","value":"I describe what is actually happening","weights":{"frequent":0}},{"label":"Occasionally, when nothing simpler occurs to me","value":"Occasionally, when nothing simpler occurs to me","weights":{"frequent":0.25}},{"label":"As often as anything else","value":"As often as anything else","weights":{"frequent":0.5}},{"label":"Most of the time","value":"Most of the time","weights":{"frequent":0.75}},{"label":"It is the only register I have for anything difficult","value":"It is the only register I have for anything difficult","weights":{"frequent":1}}]},{"id":"bypass-substitute","type":"choice","prompt":"When a practice does not give you what you wanted, what happens next?","domain":"substitute","options":[{"label":"I go back to it the next morning, unchanged","value":"I go back to it the next morning, unchanged","weights":{"none":1,"occasional":0,"frequent":0,"dominant":0}},{"label":"I adjust slightly and carry on","value":"I adjust slightly and carry on","weights":{"none":0.25,"occasional":0.75,"frequent":0,"dominant":0}},{"label":"I go looking for the right way of doing it","value":"I go looking for the right way of doing it","weights":{"none":0,"occasional":0.5,"frequent":0.5,"dominant":0}},{"label":"I go looking for a better practice","value":"I go looking for a better practice","weights":{"none":0,"occasional":0,"frequent":0.75,"dominant":0.25}},{"label":"I go looking for a better explanation of why it did not work","value":"I go looking for a better explanation of why it did not work","weights":{"none":0,"occasional":0,"frequent":0,"dominant":1}}]},{"id":"bypass-others","type":"choice","prompt":"When someone close tells you something painful, how often do you answer with a concept?","domain":"relational","options":[{"label":"I stay with them and say nothing clever","value":"I stay with them and say nothing clever","weights":{"occasional":0}},{"label":"Rarely","value":"Rarely","weights":{"occasional":0.25}},{"label":"About half the time","value":"About half the time","weights":{"occasional":0.5}},{"label":"Often, and it is usually something I am pleased with","value":"Often, and it is usually something I am pleased with","weights":{"occasional":0.75}},{"label":"Almost always, and I would be hard to talk to about it","value":"Almost always, and I would be hard to talk to about it","weights":{"occasional":1}}]},{"id":"bypass-body","type":"choice","prompt":"How often does the language arrive while something physical is happening that has not been named?","domain":"body","options":[{"label":"Hardly ever — I check in with what is going on physically","value":"Hardly ever — I check in with what is going on physically","weights":{"frequent":0}},{"label":"Once in a while","value":"Once in a while","weights":{"frequent":0.25}},{"label":"Fairly often","value":"Fairly often","weights":{"frequent":0.5}},{"label":"Most of the time, without noticing","value":"Most of the time, without noticing","weights":{"frequent":0.75}},{"label":"It is my main way of handling anything at all","value":"It is my main way of handling anything at all","weights":{"frequent":1}}]},{"id":"bypass-witness","type":"choice","prompt":"When someone you respect disagrees with how you see something, how often do you reach for the vocabulary to settle it?","domain":"test","options":[{"label":"I let their view stand and keep mine to myself","value":"I let their view stand and keep mine to myself","weights":{"occasional":0}},{"label":"Rarely","value":"Rarely","weights":{"occasional":0.25}},{"label":"About half the time","value":"About half the time","weights":{"occasional":0.5}},{"label":"Often, and I usually sound convincing","value":"Often, and I usually sound convincing","weights":{"occasional":0.75}},{"label":"Almost always, and I have genuinely stopped seeing the problem","value":"Almost always, and I have genuinely stopped seeing the problem","weights":{"occasional":1}}]},{"id":"bypass-effect","type":"choice","prompt":"How much has the practice actually improved your ability to be with people?","domain":"effect","options":[{"label":"Not at all — it has not affected that either way","value":"Not at all — it has not affected that either way","weights":{"dominant":0}},{"label":"Very little","value":"Very little","weights":{"dominant":0.25}},{"label":"Some","value":"Some","weights":{"dominant":0.5}},{"label":"A fair amount, most weeks","value":"A fair amount, most weeks","weights":{"dominant":0.75}},{"label":"It is the main thing practice has given me","value":"It is the main thing practice has given me","weights":{"dominant":1}}]},{"id":"bypass-close","type":"choice","prompt":"If the people closest to you described how your practice has changed them, what would they most likely say?","domain":"close-contact","options":[{"label":"That it has not really changed anything between us","value":"That it has not really changed anything between us","weights":{"none":0}},{"label":"That I am slightly less available than I used to be","value":"That I am slightly less available than I used to be","weights":{"none":0.25}},{"label":"That they have to be careful about how they bring things to me","value":"That they have to be careful about how they bring things to me","weights":{"none":0.5}},{"label":"That I have become noticeably harder to disagree with","value":"That I have become noticeably harder to disagree with","weights":{"none":0.75}},{"label":"That some of it has come between us, and they stopped saying so a while ago","value":"That some of it has come between us, and they stopped saying so a while ago","weights":{"none":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["none","occasional","frequent","dominant"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"none","label":"Not showing up","short":"The language has not closed the door","description":"Depth of vocabulary is being used to look at things rather than to get away from them, which is what makes it worth having. It is worth keeping an eye on, mostly because this is the position people are least able to see themselves from.","shadow":"Assuming the diagnosis is now out of date.","color":"slate","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.25,"thought":0.2,"connection":0.2},"practiceLevels":{"witnessing":1,"jnana":1},"tags":["clean-reading","connected"]}},{"id":"occasional","label":"Occasional","short":"It shows up under pressure","description":"The vocabulary mostly serves, and occasionally gets picked up at exactly the moment it is not wanted — usually when the real thing is uncomfortable to say plainly.","shadow":"Reaching for depth precisely when plainness is available.","color":"amber","masters":["witnessing","relationship"],"calibration":{"dimensions":{"thought":0.2,"spirit":0.2,"connection":0.2},"practiceLevels":{"witnessing":1,"relationship":1},"domainStress":{"contact":"relationship"},"tags":["occasional","occasionally-avoiding"]}},{"id":"frequent","label":"Frequent","short":"It is doing a lot of work","description":"The language is carrying more than it can hold, and it is being chosen at the moments when something simpler would land. This is common among people who are genuinely serious about the practice, which is exactly why it stays invisible.","shadow":"Seriousness mistaken for contact.","color":"rose","masters":["witnessing","loop-dissolution"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.2,"connection":0.2},"practiceLevels":{"witnessing":2,"loop-dissolution":1},"domainStress":{"contact":"relationship"},"tags":["frequent","intellectualising"]}},{"id":"dominant","label":"Dominant","short":"The framework is in place of the thing","description":"The vocabulary has become the primary way of being with experience, including your own, and it is currently standing between you and a great deal of ordinary contact with people. This is a description of a position, not a verdict on the person in it, and it is reversible by the same route that produced it.","shadow":"The framework being mistaken for what it was meant to reach.","color":"violet","masters":["witnessing","relationship"],"calibration":{"dimensions":{"thought":0.3,"connection":0.25,"spirit":0.2},"practiceLevels":{"witnessing":2,"relationship":2},"domainStress":{"contact":"relationship"},"tags":["dominant","framework-bound"]}}]'::jsonb, '{"loops_to_check":["intellectualisation","projection","avoidance"],"practice_affinity":["witnessing","relationship"],"deepens_with":["jungian-archetypes","inner-council","shadow-inventory"]}'::jsonb, 1, true, false, 100, now())
