    ('story-loop', 'Story loop', 'Victim, hero, rescuer — which role you replay', 'jungian', 'shadow', E'A role is a position a story puts you in, and a position has a use. Each of these five gets something done, which is why each of them is so easy to settle into and so hard to notice from inside.\n\nThis looks at the role you are currently playing, what it gets you, what it is holding off, and which one is hardest to own.', '🎭', 6, 8, '[{"id":"story-current","type":"choice","prompt":"Which of these is closest to how you usually end up in a difficult situation?","domain":"role","options":[{"label":"The one it happens to","value":"The one it happens to","weights":{"victim":1}},{"label":"The one who copes and keeps going","value":"The one who copes and keeps going","weights":{"hero":1}},{"label":"The one who steps in and fixes it","value":"The one who steps in and fixes it","weights":{"rescuer":1}},{"label":"The one who lightens the room","value":"The one who lightens the room","weights":{"jester":1}},{"label":"The one who sees what is really going on","value":"The one who sees what is really going on","weights":{"sage":1}}]},{"id":"story-consistency","type":"choice","prompt":"Is it usually the same role?","domain":"frequency","options":[{"label":"It is nearly always the same role","value":"It is nearly always the same role","weights":{"victim":1,"hero":0,"rescuer":0,"jester":0,"sage":0}},{"label":"Usually one role, occasionally another","value":"Usually one role, occasionally another","weights":{"victim":0,"hero":1,"rescuer":0,"jester":0,"sage":0}},{"label":"It varies with the situation","value":"It varies with the situation","weights":{"victim":0,"hero":0,"rescuer":1,"jester":0,"sage":0}},{"label":"Several roles, depending on who is in the room","value":"Several roles, depending on who is in the room","weights":{"victim":0,"hero":0,"rescuer":0,"jester":1,"sage":0}},{"label":"I move between them, and the choice is deliberate","value":"I move between them, and the choice is deliberate","weights":{"victim":0,"hero":0,"rescuer":0,"jester":0,"sage":1}}]},{"id":"story-gets","type":"choice","prompt":"What does the role get you?","domain":"return","options":[{"label":"Survival, of a kind","value":"Survival, of a kind","weights":{"victim":0,"hero":0,"rescuer":0,"sage":0}},{"label":"Sympathy, and attention","value":"Sympathy, and attention","weights":{"victim":1,"hero":0,"rescuer":0,"sage":0}},{"label":"Control over how I am seen","value":"Control over how I am seen","weights":{"victim":0,"hero":1,"rescuer":0,"sage":0}},{"label":"Being useful, and therefore hard to discard","value":"Being useful, and therefore hard to discard","weights":{"victim":0,"hero":0,"rescuer":1,"sage":0}},{"label":"Distance from my own involvement in it","value":"Distance from my own involvement in it","weights":{"victim":0,"hero":0,"rescuer":0,"sage":1}}]},{"id":"story-protects","type":"choice","prompt":"What is the role protecting you from?","domain":"defence","options":[{"label":"From being looked at too closely","value":"From being looked at too closely","weights":{"hero":0,"rescuer":0,"jester":0,"sage":0}},{"label":"From being thought incapable","value":"From being thought incapable","weights":{"hero":1,"rescuer":0,"jester":0,"sage":0}},{"label":"From having to admit I wanted something","value":"From having to admit I wanted something","weights":{"hero":0,"rescuer":1,"jester":0,"sage":0}},{"label":"From being left with my own feelings","value":"From being left with my own feelings","weights":{"hero":0,"rescuer":0,"jester":1,"sage":0}},{"label":"From nothing I have been able to identify","value":"From nothing I have been able to identify","weights":{"hero":0,"rescuer":0,"jester":0,"sage":1}}]},{"id":"story-change","type":"choice","prompt":"Can the role be changed?","domain":"movement","options":[{"label":"I am not sure it is even a role","value":"I am not sure it is even a role","weights":{"victim":1,"hero":0,"rescuer":0,"jester":0,"sage":0}},{"label":"I have seen it change under pressure, without choosing to","value":"I have seen it change under pressure, without choosing to","weights":{"victim":0,"hero":1,"rescuer":0,"jester":0,"sage":0}},{"label":"I can step out of it, with real effort","value":"I can step out of it, with real effort","weights":{"victim":0,"hero":0,"rescuer":1,"jester":0,"sage":0}},{"label":"I can step out of it deliberately, and usually do","value":"I can step out of it deliberately, and usually do","weights":{"victim":0,"hero":0,"rescuer":0,"jester":1,"sage":0}},{"label":"I choose the part each time, out of several","value":"I choose the part each time, out of several","weights":{"victim":0,"hero":0,"rescuer":0,"jester":0,"sage":1}}]},{"id":"story-told","type":"choice","prompt":"How do you tell the story afterwards?","domain":"narration","options":[{"label":"I do not tell it at all","value":"I do not tell it at all","weights":{"victim":1,"hero":0,"rescuer":0,"jester":0,"sage":0}},{"label":"I tell it the way it happened","value":"I tell it the way it happened","weights":{"victim":0,"hero":1,"rescuer":0,"jester":0,"sage":0}},{"label":"I tell it so that I come out of it as well as I can","value":"I tell it so that I come out of it as well as I can","weights":{"victim":0,"hero":0,"rescuer":1,"jester":0,"sage":0}},{"label":"I tell it so that I am the one who learned from it","value":"I tell it so that I am the one who learned from it","weights":{"victim":0,"hero":0,"rescuer":0,"jester":1,"sage":0}},{"label":"I tell it so that it means something","value":"I tell it so that it means something","weights":{"victim":0,"hero":0,"rescuer":0,"jester":0,"sage":1}}]},{"id":"story-hardest","type":"choice","prompt":"Which of these is hardest for you to own?","domain":"ownership","options":[{"label":"To be the one it happens to","value":"To be the one it happens to","weights":{"victim":1}},{"label":"To be the strong one who copes","value":"To be the strong one who copes","weights":{"hero":1}},{"label":"To be the one everybody leans on","value":"To be the one everybody leans on","weights":{"rescuer":1}},{"label":"To be the funny one who deflects","value":"To be the funny one who deflects","weights":{"jester":1}},{"label":"To be the one who is always right about the situation","value":"To be the one who is always right about the situation","weights":{"sage":1}}]},{"id":"story-mirror","type":"choice","prompt":"How do other people respond to the role?","domain":"response","options":[{"label":"It is not noticed","value":"It is not noticed","weights":{"rescuer":0}},{"label":"It is noticed, and used","value":"It is noticed, and used","weights":{"rescuer":0.25}},{"label":"It is noticed, and relied upon","value":"It is noticed, and relied upon","weights":{"rescuer":0.5}},{"label":"It is noticed, and occasionally resented","value":"It is noticed, and occasionally resented","weights":{"rescuer":0.75}},{"label":"It is noticed, named, and refused","value":"It is noticed, named, and refused","weights":{"rescuer":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["victim","hero","rescuer","jester","sage"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"victim","label":"Victim","short":"The story happens to you","description":"The position taken is the one things happen to, and it reliably produces sympathy without responsibility. This is a difficult role to look at directly, because the material inside it is often real suffering, and the role is what has been built around it.","shadow":"Reading the position as the whole of the event.","color":"slate","masters":["self-inquiry","emotional-healing"],"calibration":{"dimensions":{"emotion":0.35,"connection":0.25,"thought":0.15},"practiceLevels":{"self-inquiry":1,"emotional-healing":1},"domainStress":{"relation":"relationship"},"tags":["victim","happened-to"]}},{"id":"hero","label":"Hero","short":"The one who copes and keeps going","description":"The position is competence under load, and it is genuinely useful in a pinch. Its long-term cost is that it is very hard to be helped, and being helped is often the only way through the very situations it is built to survive.","shadow":"Mistaking the ability to hold it for an absence of need.","color":"orange","masters":["self-inquiry","karma"],"calibration":{"dimensions":{"action":0.35,"connection":0.2,"emotion":0.15},"practiceLevels":{"self-inquiry":1,"karma":1},"tags":["hero","coping"]}},{"id":"rescuer","label":"Rescuer","short":"The one who steps in and fixes it","description":"The position is the one who turns up, and it is reliably useful to other people. What it produces, over time, is a specific kind of loneliness: the people most helped are frequently the least able to leave.","shadow":"Mistaking being needed for being known.","color":"amber","masters":["relationship","karma"],"calibration":{"dimensions":{"connection":0.35,"action":0.25,"spirit":0.1},"practiceLevels":{"relationship":1,"karma":1},"domainStress":{"relation":"relationship"},"tags":["rescuer","useful"]}},{"id":"jester","label":"Jester","short":"The one who lightens the room","description":"The position turns everything into material, and it is genuinely skilful. It also determines who gets to set the terms of a conversation, and it makes one particular subject — the one it deflects — permanently unavailable.","shadow":"The deflection mistaken for lightness.","color":"teal","masters":["witnessing","bhakti"],"calibration":{"dimensions":{"connection":0.3,"emotion":0.25,"spirit":0.15},"practiceLevels":{"witnessing":1,"bhakti":1},"tags":["jester","deflecting"]}},{"id":"sage","label":"Sage","short":"The one who sees what is going on","description":"The position is the one who perceives clearly, and the clarity is real. The shadow of it is specific and worth naming: the person who sees everything can be very slow to do anything, and insight is used more easily than it is surrendered.","shadow":"The insight kept, and the action not taken.","color":"indigo","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"thought":0.3,"spirit":0.3,"action":0.15},"practiceLevels":{"jnana":1,"self-inquiry":1},"tags":["sage","observing"]}}]'::jsonb, '{"loops_to_check":["narrative-pattern","role-repetition"],"practice_affinity":["self-inquiry","witnessing"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
