-- Svādhyāya · study habit (4 Yogas)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('svadhyaya', 'Svādhyāya · study habit', 'How you keep learning yourself', 'vedic', 'thought', E'The fourth niyama, and the one most often reduced to reading. The tradition is specific: the study is of yourself, and the same material is meant to be returned to rather than consumed.\n\nThis is about the habit, not the book list.', '📚', 5, 6, '[{"id":"study-what","type":"choice","prompt":"When you learn something, is it about the world or about you?","domain":"subject","options":[{"label":"Entirely about the world","value":"Entirely about the world","weights":{"none":1,"occasional":0,"regular":0,"relentless":0}},{"label":"Mostly about the world","value":"Mostly about the world","weights":{"none":0.25,"occasional":0.75,"regular":0,"relentless":0}},{"label":"Both, and I move between them","value":"Both, and I move between them","weights":{"none":0,"occasional":0.5,"regular":0.5,"relentless":0}},{"label":"Mostly about me","value":"Mostly about me","weights":{"none":0,"occasional":0,"regular":0.75,"relentless":0.25}},{"label":"Almost entirely about me","value":"Almost entirely about me","weights":{"none":0,"occasional":0,"regular":0,"relentless":1}}]},{"id":"study-return","type":"choice","prompt":"Do you go back to things you have already read?","domain":"return","options":[{"label":"I never do — I move on","value":"I never do — I move on","weights":{"occasional":0,"regular":0}},{"label":"Rarely","value":"Rarely","weights":{"occasional":0,"regular":0}},{"label":"Occasionally, on the same things","value":"Occasionally, on the same things","weights":{"occasional":1,"regular":0}},{"label":"Regularly, on a small body of material","value":"Regularly, on a small body of material","weights":{"occasional":0,"regular":1}},{"label":"I am going through the same material for the third time","value":"I am going through the same material for the third time","weights":{"occasional":0,"regular":0}}]},{"id":"study-record","type":"choice","prompt":"Do you keep any record of your own material?","domain":"recording","options":[{"label":"No, and I would not think to","value":"No, and I would not think to","weights":{"regular":1}},{"label":"Only occasionally","value":"Only occasionally","weights":{"regular":1}},{"label":"Some things, but scattered","value":"Some things, but scattered","weights":{"regular":1}},{"label":"Yes, fairly systematically","value":"Yes, fairly systematically","weights":{"regular":1}},{"label":"Yes — it is the main thing I work with","value":"Yes — it is the main thing I work with","weights":{"regular":1}}]},{"id":"study-enjoyment","type":"choice","prompt":"Is learning enjoyable, or is it maintenance?","domain":"quality","options":[{"label":"Purely obligation","value":"Purely obligation","weights":{"none":1,"occasional":0,"regular":0,"relentless":0}},{"label":"Mostly obligation","value":"Mostly obligation","weights":{"none":0.25,"occasional":0.75,"regular":0,"relentless":0}},{"label":"Both, depending on the material","value":"Both, depending on the material","weights":{"none":0,"occasional":0.5,"regular":0.5,"relentless":0}},{"label":"Mostly a pleasure","value":"Mostly a pleasure","weights":{"none":0,"occasional":0,"regular":0.75,"relentless":0.25}},{"label":"The pleasure is most of why I do it","value":"The pleasure is most of why I do it","weights":{"none":0,"occasional":0,"regular":0,"relentless":1}}]},{"id":"study-browse","type":"choice","prompt":"How much of what you take in is chosen, and how much finds you?","domain":"appetite","options":[{"label":"Nearly all of it finds me","value":"Nearly all of it finds me","weights":{"none":1,"occasional":0,"regular":0,"relentless":0}},{"label":"Most of it finds me","value":"Most of it finds me","weights":{"none":0.25,"occasional":0.75,"regular":0,"relentless":0}},{"label":"About half","value":"About half","weights":{"none":0,"occasional":0.5,"regular":0.5,"relentless":0}},{"label":"Mostly chosen","value":"Mostly chosen","weights":{"none":0,"occasional":0,"regular":0.75,"relentless":0.25}},{"label":"Nearly everything I read I chose deliberately","value":"Nearly everything I read I chose deliberately","weights":{"none":0,"occasional":0,"regular":0,"relentless":1}}]},{"id":"study-change","type":"choice","prompt":"Has your study changed how you actually behave?","domain":"effect","options":[{"label":"Not once","value":"Not once","weights":{"occasional":0}},{"label":"Once, a long time ago","value":"Once, a long time ago","weights":{"occasional":0}},{"label":"A few times","value":"A few times","weights":{"occasional":1}},{"label":"Often enough that people can see it","value":"Often enough that people can see it","weights":{"occasional":0}},{"label":"It is the main thing that has shaped how I live","value":"It is the main thing that has shaped how I live","weights":{"occasional":0}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["none","occasional","regular","relentless"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"none","label":"None","short":"No deliberate self-study","description":"There is no self-study habit. This is common and unremarkable. It is also, of the five niyamas, the one with the least self-reinforcement — nothing else here makes it more likely to start.","shadow":"Reading as a substitute for being read.","color":"slate","masters":["jnana","observation"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.15},"practiceLevels":{"jnana":1,"observation":1},"tags":["svadhyaya","none"]}},{"id":"occasional","label":"Occasional","short":"It happens, without a shape","description":"You read things that are relevant to you from time to time, but there is no return to the same material and no record. The subject is usually yourself; the method is consumption rather than study.","shadow":"Collecting material instead of revisiting it.","color":"amber","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"thought":0.3,"spirit":0.15},"practiceLevels":{"jnana":1,"self-inquiry":1},"tags":["svadhyaya","consuming"]}},{"id":"regular","label":"Regular","short":"A practice with a shape","description":"You keep a real habit and you return to the same material. The subject is increasingly yourself. The discipline is holding because the material is small enough to hold.","shadow":"Outgrowing the small library you built the habit with.","color":"teal","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"thought":0.3,"spirit":0.25},"practiceLevels":{"jnana":2,"self-inquiry":1},"tags":["svadhyaya","practised"]}},{"id":"relentless","label":"Relentless","short":"The same material, for years","description":"You return to the same body of material repeatedly and it keeps yielding. The material is small, the returning is deep, and something has usually changed about what you are willing to look at.","shadow":"Knowing the material so well it stops asking anything.","color":"indigo","masters":["jnana","witnessing"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.45},"practiceLevels":{"jnana":2,"witnessing":1},"tags":["svadhyaya","deep"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["jnana","self-inquiry"],"deepens_with":["niyamas","inquiry-sharpness"]}'::jsonb, 1, true, false, 100, now())
