-- Three brains (Engines)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('three-brains', 'Three brains', 'The layered nervous system', 'neuroscience', 'engines', E'Paul MacLean proposed in the 1960s that the nervous system is three systems laid down at different times in evolution, each with its own job: an ancient survival layer, a middle layer for attachment and feeling, and the newest, which handles language and abstraction. It is a working model, not a settled finding — the layers overlap heavily and the neat three-part picture has been revised many times.\n\nIt is still the most useful picture available for one particular question: which layer answered first, and what did that cost the other two? This asks that, without asking you to choose a layer or become one.', '🧠', 7, 6, '[{"id":"brain-first","type":"choice","prompt":"Something happens. What answers first?","domain":"sequence","options":[{"label":"My body moved before I knew what had happened","value":"My body moved before I knew what had happened","weights":{"reactive":1}},{"label":"The feeling arrived, and told me what to do about it","value":"The feeling arrived, and told me what to do about it","weights":{"emotional":1}},{"label":"I worked out what it meant, and then acted","value":"I worked out what it meant, and then acted","weights":{"rational":1}}]},{"id":"brain-speed","type":"choice","prompt":"How much time passes between something happening and you responding?","domain":"reaction","options":[{"label":"A long enough gap to notice what I am doing","value":"A long enough gap to notice what I am doing","weights":{"reactive":0}},{"label":"A second or two","value":"A second or two","weights":{"reactive":0.25}},{"label":"About a second","value":"About a second","weights":{"reactive":0.5}},{"label":"A fraction of a second","value":"A fraction of a second","weights":{"reactive":0.75}},{"label":"There is no gap at all","value":"There is no gap at all","weights":{"reactive":1}}]},{"id":"brain-conflict","type":"choice","prompt":"When what you feel and what you think want different things, which one usually wins?","domain":"disagreement","options":[{"label":"The body, and it is not close","value":"The body, and it is not close","weights":{"reactive":1,"emotional":0,"rational":0}},{"label":"The feeling, nearly every time","value":"The feeling, nearly every time","weights":{"reactive":0,"emotional":1,"rational":0}},{"label":"It is worked out, and the reasoning usually has the last word","value":"It is worked out, and the reasoning usually has the last word","weights":{"reactive":0,"emotional":0,"rational":1}}]},{"id":"brain-trust","type":"choice","prompt":"How much do you trust the first thing you feel?","domain":"instinct","options":[{"label":"I act on it straight away and rarely regret it","value":"I act on it straight away and rarely regret it","weights":{"reactive":1,"emotional":0,"rational":0}},{"label":"Usually, without stopping to check it","value":"Usually, without stopping to check it","weights":{"reactive":0.5,"emotional":0.5,"rational":0}},{"label":"Sometimes, when I am calm","value":"Sometimes, when I am calm","weights":{"reactive":0,"emotional":1,"rational":0}},{"label":"Rarely — I look for the reasoning first","value":"Rarely — I look for the reasoning first","weights":{"reactive":0,"emotional":0.5,"rational":0.5}},{"label":"Almost never; I want the case made before I move","value":"Almost never; I want the case made before I move","weights":{"reactive":0,"emotional":0,"rational":1}}]},{"id":"brain-belt","type":"choice","prompt":"Someone corrects you. Where does that land?","domain":"belly","options":[{"label":"It lands in the stomach and stays there for days","value":"It lands in the stomach and stays there for days","weights":{"reactive":1,"emotional":0,"rational":0}},{"label":"It lands in the chest and I feel it for hours","value":"It lands in the chest and I feel it for hours","weights":{"reactive":0,"emotional":1,"rational":0}},{"label":"I take it apart and check the reasoning","value":"I take it apart and check the reasoning","weights":{"reactive":0,"emotional":0,"rational":1}}]},{"id":"brain-override","type":"choice","prompt":"At what point does a decision stop being yours to make?","domain":"override","options":[{"label":"Inside the first half second, and I never stood a chance","value":"Inside the first half second, and I never stood a chance","weights":{"reactive":1}},{"label":"Within a few seconds, once the feeling has formed","value":"Within a few seconds, once the feeling has formed","weights":{"reactive":0.5,"emotional":0.5}},{"label":"Over a few minutes, while the feeling is still moving","value":"Over a few minutes, while the feeling is still moving","weights":{"emotional":0.75,"rational":0.25}},{"label":"Over hours, once I have looked at it from more than one side","value":"Over hours, once I have looked at it from more than one side","weights":{"rational":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["reactive","emotional","rational"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"reactive","label":"Reactive-led","short":"The first answer is the answer","description":"The oldest layer is doing the deciding, and it does so before thought is available to object. This is not a defect and it is not stupidity — it is a system built for emergencies, still doing its job in a life that mostly does not have them. What it costs is the enormous gap between stimulus and response, which is where every other capacity has to be built.","shadow":"Believing you have no say in what happens next.","color":"rose","masters":["body","breath"],"calibration":{"dimensions":{"body":0.35,"emotion":0.2,"thought":0.1},"practiceLevels":{"body":1,"breath":1},"domainStress":{"activation":"health"},"tags":["reactive","fast-first"]}},{"id":"emotional","label":"Emotional-led","short":"Feeling decides, thinking follows","description":"The middle layer holds the casting vote: something is felt, the feeling has a direction, and the reasoning is brought in afterwards to justify it. This gives your life its colour and its relationships much of their depth, and it means a great deal of your thinking is post-hoc. Not wrong — simply late.","shadow":"Arriving at a conclusion and then arguing for it.","color":"violet","masters":["emotional-healing","observation"],"calibration":{"dimensions":{"emotion":0.4,"connection":0.2,"body":0.15},"practiceLevels":{"emotional-healing":1,"observation":1},"domainStress":{"feeling":"emotional-healing"},"tags":["feeling-led","relational"]}},{"id":"rational","label":"Rational-led","short":"The case is made before the move","description":"The newest layer is given the decision, which produces clarity, consistency and good judgement under pressure. It also produces a life in which the other two layers are downstream — felt afterwards, and often only when there is time. The interesting work is not more reasoning but letting the older two finish speaking.","shadow":"Arriving at the right answer and not arriving at anything.","color":"sky","masters":["jnana","neuroscience"],"calibration":{"dimensions":{"thought":0.4,"spirit":0.2,"body":0.1},"practiceLevels":{"jnana":1,"neuroscience":1},"tags":["analytical","reasoning-first"]}}]'::jsonb, '{"loops_to_check":["reactivity","conflict-avoidance"],"practice_affinity":["neuroscience","breath","observation"],"deepens_with":["nervous-system-tone","mind-body-type"]}'::jsonb, 1, true, false, 100, now())
