-- Time relationship (Observation)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('time-relationship', 'Time relationship', 'Your relationship with time', 'vedic', 'rhythm', E'Vedic thought treats time as something a person has a relationship with, not a container they are put inside — which is why the same life can feel generous to one person and brutal to another, on identical schedules.\n\nWhat follows is about felt time rather than clock time, and the two come apart more often than people expect. None of the five positions is a personality defect; they are five different relationships with the same amount of it.', '⏰', 6, 6, '[{"id":"time-texture","type":"choice","prompt":"What does time feel like from the inside of an ordinary day?","domain":"texture","options":[{"label":"It is always running out","value":"It is always running out","weights":{"rushed":1,"deficient":0,"adequate":0,"spacious":0,"abundant":0}},{"label":"There is never quite enough","value":"There is never quite enough","weights":{"rushed":0,"deficient":1,"adequate":0,"spacious":0,"abundant":0}},{"label":"It is about what I need","value":"It is about what I need","weights":{"rushed":0,"deficient":0,"adequate":1,"spacious":0,"abundant":0}},{"label":"There is real room in it","value":"There is real room in it","weights":{"rushed":0,"deficient":0,"adequate":0,"spacious":1,"abundant":0}},{"label":"There is more of it than I can use","value":"There is more of it than I can use","weights":{"rushed":0,"deficient":0,"adequate":0,"spacious":0,"abundant":1}}]},{"id":"time-speed","type":"choice","prompt":"How often are you behind, late, or running?","domain":"speed","options":[{"label":"Almost never","value":"Almost never","weights":{"rushed":0}},{"label":"Rarely","value":"Rarely","weights":{"rushed":0.25}},{"label":"Often enough to notice","value":"Often enough to notice","weights":{"rushed":0.5}},{"label":"Most days","value":"Most days","weights":{"rushed":0.75}},{"label":"Constantly","value":"Constantly","weights":{"rushed":1}}]},{"id":"time-deadline","type":"choice","prompt":"A deadline is set for something. How does it sit with you?","domain":"deadline","options":[{"label":"I set my own earlier one, and keep to it","value":"I set my own earlier one, and keep to it","weights":{"abundant":1,"spacious":0,"adequate":0,"rushed":0}},{"label":"I plan it properly and finish with room to spare","value":"I plan it properly and finish with room to spare","weights":{"abundant":0,"spacious":1,"adequate":0,"rushed":0}},{"label":"I work steadily and finish just in time","value":"I work steadily and finish just in time","weights":{"abundant":0,"spacious":0,"adequate":1,"rushed":0}},{"label":"Panic, and nothing gets done until the last hour","value":"Panic, and nothing gets done until the last hour","weights":{"abundant":0,"spacious":0,"adequate":0,"rushed":1}}]},{"id":"time-past","type":"choice","prompt":"What happens to yesterday?","domain":"past","options":[{"label":"It is gone, and I was not there for it","value":"It is gone, and I was not there for it","weights":{"rushed":1,"adequate":0,"abundant":0}},{"label":"It is a real day and I was mostly present for it","value":"It is a real day and I was mostly present for it","weights":{"rushed":0,"adequate":1,"abundant":0}},{"label":"It is available — I can go back into it whenever I want","value":"It is available — I can go back into it whenever I want","weights":{"rushed":0,"adequate":0,"abundant":1}}]},{"id":"time-future","type":"choice","prompt":"When you think about later, what arrives?","domain":"future","options":[{"label":"Anxiety about catching up","value":"Anxiety about catching up","weights":{"rushed":1}},{"label":"A vague sense of not having enough","value":"A vague sense of not having enough","weights":{"deficient":1}},{"label":"A plan that would probably work","value":"A plan that would probably work","weights":{"adequate":1}},{"label":"Room to do one of the things I have wanted to","value":"Room to do one of the things I have wanted to","weights":{"spacious":1}},{"label":"Nothing in particular; I am not in a hurry","value":"Nothing in particular; I am not in a hurry","weights":{"abundant":1}}]},{"id":"time-wait","type":"choice","prompt":"How well can you wait?","domain":"wait","options":[{"label":"Badly, and I fill every part of it","value":"Badly, and I fill every part of it","weights":{"rushed":1,"deficient":0,"adequate":0,"spacious":0}},{"label":"Acceptably","value":"Acceptably","weights":{"rushed":0,"deficient":1,"adequate":0,"spacious":0}},{"label":"Without much difficulty","value":"Without much difficulty","weights":{"rushed":0,"deficient":0,"adequate":1,"spacious":0}},{"label":"Comfortably, and I notice what is happening while I do","value":"Comfortably, and I notice what is happening while I do","weights":{"rushed":0,"deficient":0,"adequate":0,"spacious":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["rushed","deficient","adequate","spacious","abundant"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"rushed","label":"Rushed","short":"Time is always behind you","description":"The day is always arriving faster than you can meet it, and the pace is felt in the body as much as in the mind. This is a reliable system for a life with a genuine emergency in it and an expensive one for a life that mostly does not. Behind it there is usually an amount to hold that was never actually chosen.","shadow":"Reading the amount to hold as a personal failing.","color":"rose","masters":["breath","observation"],"calibration":{"dimensions":{"body":0.25,"thought":0.25,"emotion":0.2},"practiceLevels":{"breath":1,"observation":1},"domainStress":{"pace":"health"},"tags":["time-pressured","urgent"]}},{"id":"deficient","label":"Deficient","short":"There is never enough of it","description":"Not panic, but a persistent shortfall — always one thing short of what the week requires. The feeling is accurate in the sense that something real is missing; what is missing is usually capacity or margin rather than hours. Adding more hours to that arrangement has a poor record of fixing it.","shadow":"Working longer inside a structure that was already too small.","color":"orange","masters":["raja","karma"],"calibration":{"dimensions":{"action":0.25,"thought":0.2,"body":0.15},"practiceLevels":{"raja":1,"karma":1},"domainStress":{"load":"work-career"},"tags":["short","over-committed"]}},{"id":"adequate","label":"Adequate","short":"Enough, and enough is genuinely enough","description":"The week matches what you have, without much margin either way. This is a stable and under-rated position: it is the one from which decisions are made without panic and from which a practice can actually be sustained. The question worth sitting with is whether adequate is what you are aiming for.","shadow":"Mistaking a workable amount for the whole ambition.","color":"teal","masters":["raja","observation"],"calibration":{"dimensions":{"action":0.2,"body":0.2,"emotion":0.15},"practiceLevels":{"raja":1},"tags":["manageable","even"]}},{"id":"spacious","label":"Spacious","short":"There is room in the day","description":"The day has margin in it, and the margin is being used rather than defended. This is largely a matter of load and of what has been agreed to, and it is the position from which the most interesting work gets done. The one thing to watch is whether the space stays yours or gets quietly filled.","shadow":"Losing the margin to the first thing that needs it.","color":"sky","masters":["breath","raja"],"calibration":{"dimensions":{"spirit":0.25,"body":0.2,"action":0.15},"practiceLevels":{"breath":1,"raja":1},"tags":["spacious","unhurried"]}},{"id":"abundant","label":"Abundant","short":"Time is material you work with","description":"Time reads as a material rather than a constraint — you set the measure and work inside it, and the past remains available rather than closed. Most people reach this by removing commitments rather than by rearranging them. The particular risk of living in a wide time is that other people’s narrower time starts to feel like an imposition on yours.","shadow":"Experiencing other people’s pace as an interruption to your own.","color":"indigo","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.35,"thought":0.2},"practiceLevels":{"witnessing":2,"jnana":1},"tags":["unbounded","timeless"]}}]'::jsonb, '{"loops_to_check":["over-committed","urgency"],"practice_affinity":["observation","raja","breath"],"deepens_with":["daily-rhythm","energy-baseline"]}'::jsonb, 1, true, false, 100, now())
