-- Trigger map (Welcome)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('trigger-map', 'Trigger map', 'What sets you off, and why', 'vedic', 'shadow', E'A trigger is not the event. The event is weather. The trigger is the specific place where you have already decided what will happen — and then it happens.\n\nThis maps the set points. It does not ask you to forgive anything or change anyone.', '⚡', 7, 8, '[{"id":"trigger-fastest","type":"choice","prompt":"What can set you off fastest?","domain":"pattern","options":[{"label":"Feeling physically unsafe or outnumbered","value":"Feeling physically unsafe or outnumbered","weights":{"threat":1}},{"label":"Being seen as foolish or wrong in front of others","value":"Being seen as foolish or wrong in front of others","weights":{"shame":1}},{"label":"Being left out, ignored, or not chosen","value":"Being left out, ignored, or not chosen","weights":{"rejection":1}},{"label":"Things not going the way I decided","value":"Things not going the way I decided","weights":{"control":1}},{"label":"Being treated unfairly, or as less than I am","value":"Being treated unfairly, or as less than I am","weights":{"injustice":1}}]},{"id":"trigger-body","type":"choice","prompt":"Where in your body do you feel it before you act?","domain":"pattern","options":[{"label":"All over, with no clear location","value":"All over, with no clear location","weights":{"threat":1}},{"label":"Chest and throat","value":"Chest and throat","weights":{"threat":1}},{"label":"Stomach and gut","value":"Stomach and gut","weights":{"threat":1}},{"label":"Face and jaw","value":"Face and jaw","weights":{"threat":1}},{"label":"Hands and arms","value":"Hands and arms","weights":{"threat":1}}]},{"id":"trigger-delay","type":"choice","prompt":"How much time passes between feeling it and reacting?","domain":"pattern","options":[{"label":"None at all — I react instantly","value":"None at all — I react instantly","weights":{"threat":1,"shame":0,"rejection":0,"control":0,"injustice":0}},{"label":"Under a second","value":"Under a second","weights":{"threat":0,"shame":1,"rejection":0,"control":0,"injustice":0}},{"label":"A few seconds","value":"A few seconds","weights":{"threat":0,"shame":0,"rejection":1,"control":0,"injustice":0}},{"label":"A minute or so","value":"A minute or so","weights":{"threat":0,"shame":0,"rejection":0,"control":1,"injustice":0}},{"label":"I can hold it for a long time","value":"I can hold it for a long time","weights":{"threat":0,"shame":0,"rejection":0,"control":0,"injustice":1}}]},{"id":"trigger-same","type":"choice","prompt":"Is the same thing able to set you off repeatedly?","domain":"pattern","options":[{"label":"The same thing, over and over","value":"The same thing, over and over","weights":{"threat":1,"shame":0,"rejection":0,"control":0,"injustice":0}},{"label":"Similar things, different details","value":"Similar things, different details","weights":{"threat":0,"shame":1,"rejection":0,"control":0,"injustice":0}},{"label":"Different things, same feeling","value":"Different things, same feeling","weights":{"threat":0,"shame":0,"rejection":1,"control":0,"injustice":0}},{"label":"It is genuinely random","value":"It is genuinely random","weights":{"threat":0,"shame":0,"rejection":0,"control":1,"injustice":0}},{"label":"Nothing sets me off much","value":"Nothing sets me off much","weights":{"threat":0,"shame":0,"rejection":0,"control":0,"injustice":1}}]},{"id":"trigger-size","type":"choice","prompt":"How much does it matter to you what people think?","domain":"pattern","options":[{"label":"Not at all","value":"Not at all","weights":{"shame":1}},{"label":"A little","value":"A little","weights":{"shame":1}},{"label":"Quite a lot","value":"Quite a lot","weights":{"shame":1}},{"label":"A great deal","value":"A great deal","weights":{"shame":1}},{"label":"It governs most of my choices","value":"It governs most of my choices","weights":{"shame":1}}]},{"id":"trigger-after","type":"choice","prompt":"How do you feel an hour after one of these?","domain":"pattern","options":[{"label":"Shaken for the rest of the day","value":"Shaken for the rest of the day","weights":{"threat":1,"shame":0,"rejection":0,"control":0,"injustice":0}},{"label":"Still irritated","value":"Still irritated","weights":{"threat":0,"shame":1,"rejection":0,"control":0,"injustice":0}},{"label":"About the same as before","value":"About the same as before","weights":{"threat":0,"shame":0,"rejection":1,"control":0,"injustice":0}},{"label":"Slightly better — it cleared something","value":"Slightly better — it cleared something","weights":{"threat":0,"shame":0,"rejection":0,"control":1,"injustice":0}},{"label":"Glad it happened","value":"Glad it happened","weights":{"threat":0,"shame":0,"rejection":0,"control":0,"injustice":1}}]},{"id":"trigger-covered","type":"choice","prompt":"Do you react more strongly to things you expected?","domain":"pattern","options":[{"label":"Almost always","value":"Almost always","weights":{"threat":1,"shame":0,"rejection":0,"control":0,"injustice":0}},{"label":"Often","value":"Often","weights":{"threat":0,"shame":1,"rejection":0,"control":0,"injustice":0}},{"label":"About half the time","value":"About half the time","weights":{"threat":0,"shame":0,"rejection":1,"control":0,"injustice":0}},{"label":"Rarely","value":"Rarely","weights":{"threat":0,"shame":0,"rejection":0,"control":1,"injustice":0}},{"label":"No, I react to what is actually there","value":"No, I react to what is actually there","weights":{"threat":0,"shame":0,"rejection":0,"control":0,"injustice":1}}]},{"id":"trigger-cost","type":"choice","prompt":"How much has this cost you — relationships, chances, or peace?","domain":"pattern","options":[{"label":"Not really anything","value":"Not really anything","weights":{"threat":1}},{"label":"Small things, repeatedly","value":"Small things, repeatedly","weights":{"threat":1}},{"label":"A few important things","value":"A few important things","weights":{"threat":1}},{"label":"Something I still live with","value":"Something I still live with","weights":{"threat":1}},{"label":"More than I can list","value":"More than I can list","weights":{"threat":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["threat","shame","rejection","control","injustice"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"threat","label":"Threat-reactive","short":"Safety comes first","description":"Your reactions are organised around safety. This is the oldest system in the body and the hardest to argue with — which is why reasoning rarely moves it. Regulation does.","shadow":"Reading hypervigilance as paranoia.","color":"rose","masters":["body","breath"],"calibration":{"dimensions":{"body":0.35,"emotion":0.25,"spirit":0.1},"practiceLevels":{"body":1,"breath":1},"domainStress":{"safety":"health"},"tags":["hypervigilant","threat-scan"]}},{"id":"shame","label":"Shame-reactive","short":"Exposure is the sharp edge","description":"Being seen as foolish is the thing your system cannot absorb. Much of your social energy goes toward not being seen in that way, which is expensive and largely invisible to you.","shadow":"Believing the shame is about the specific mistake.","color":"orange","masters":["emotional-healing","witnessing"],"calibration":{"dimensions":{"emotion":0.4,"connection":0.2,"thought":0.15},"practiceLevels":{"witnessing":1,"bhakti":1},"domainStress":{"relation":"relationship"},"tags":["shame-driven","image-protective"]}},{"id":"rejection","label":"Abandonment-reactive","short":"Not being chosen is the wound","description":"Your reactions are organised around the possibility of being left out or set down. This produces a lot of energy spent on reading the room for signs.","shadow":"Confusing attention with safety.","color":"violet","masters":["relationship","bhakti"],"calibration":{"dimensions":{"connection":0.4,"emotion":0.3,"spirit":0.1},"practiceLevels":{"bhakti":1,"witnessing":1},"domainStress":{"relation":"relationship"},"tags":["abandonment-fear","reaching"]}},{"id":"control","label":"Control-reactive","short":"When it does not go your way","description":"The trigger is the loss of authorship — things happening without your agreement. This is common in capable people, because competence has trained them to expect that outcomes are governable.","shadow":"Mistaking control for safety.","color":"amber","masters":["raja","karma"],"calibration":{"dimensions":{"action":0.35,"thought":0.25,"emotion":0.2},"practiceLevels":{"raja":1,"karma":1},"domainStress":{"control":"work-career"},"tags":["control-seeking","rigid"]}},{"id":"injustice","label":"Injustice-reactive","short":"Being misjudged moves you most","description":"Your reactions are organised around fairness being violated. This is a principled response, and it is also the one most easily provoked by anything ambiguous.","shadow":"Noticing the injustice but not your part in it.","color":"sky","masters":["jnana","karma"],"calibration":{"dimensions":{"action":0.3,"connection":0.25,"thought":0.2},"practiceLevels":{"jnana":1,"karma":1},"tags":["principled","comparative"]}}]'::jsonb, '{"loops_to_check":["reactivity","conflict-avoidance","approval-seeking"],"practice_affinity":["loop-dissolution","witnessing"],"deepens_with":["reactivity-score","shadow-inventory"]}'::jsonb, 1, true, false, 100, now())
