-- Triguna analysis (Engines)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('triguna-analysis', 'Triguna analysis', 'The three qualities in you', 'ayurvedic', 'engines', E'Sāṃkhya reads nature as three qualities always in motion: sattva, the force of clarity and light; rajas, the force of movement and heat; and tamas, the force of stability and weight. No one is any single one of them — what changes is which one is driving, and how much of the others is visible underneath.\n\nThis is a working description, not a diagnosis. What it is useful for is noticing which of your own tendencies is currently running hottest, because a great deal of what people call their personality is one guṇa behaving predictably.', '⚖️', 7, 6, '[{"id":"guna-clarity","type":"choice","prompt":"How would you describe your mind on a normal day?","domain":"clarity","options":[{"label":"Mostly cloudy, and I cannot see through it","value":"Mostly cloudy, and I cannot see through it","weights":{"tamas":1,"rajas":0,"sattva":0}},{"label":"Patchy — some things are clear, others are not","value":"Patchy — some things are clear, others are not","weights":{"tamas":0.5,"rajas":0.5,"sattva":0}},{"label":"Mostly clear, with the odd fog","value":"Mostly clear, with the odd fog","weights":{"tamas":0,"rajas":1,"sattva":0}},{"label":"Clear enough that I can see what is underneath","value":"Clear enough that I can see what is underneath","weights":{"tamas":0,"rajas":0.5,"sattva":0.5}},{"label":"Bright, and the seeing is effortless","value":"Bright, and the seeing is effortless","weights":{"tamas":0,"rajas":0,"sattva":1}}]},{"id":"guna-activity","type":"choice","prompt":"How much of your day is driven by movement?","domain":"activity","options":[{"label":"Slow, and I resist picking up","value":"Slow, and I resist picking up","weights":{"tamas":1,"sattva":0,"rajas":0}},{"label":"Steady, and I move when I need to","value":"Steady, and I move when I need to","weights":{"tamas":0.5,"sattva":0.5,"rajas":0}},{"label":"Quite active, and I like it","value":"Quite active, and I like it","weights":{"tamas":0,"sattva":1,"rajas":0}},{"label":"Fast, and I am always doing something","value":"Fast, and I am always doing something","weights":{"tamas":0,"sattva":0.5,"rajas":0.5}},{"label":"Driven, and I find it hard to stop","value":"Driven, and I find it hard to stop","weights":{"tamas":0,"sattva":0,"rajas":1}}]},{"id":"guna-weight","type":"choice","prompt":"How do you handle inertia?","domain":"weight","options":[{"label":"I do not move until something forces me","value":"I do not move until something forces me","weights":{"tamas":1,"sattva":0,"rajas":0}},{"label":"I need a push, and then I go","value":"I need a push, and then I go","weights":{"tamas":0.5,"sattva":0.5,"rajas":0}},{"label":"I move when I decide to, without drama","value":"I move when I decide to, without drama","weights":{"tamas":0,"sattva":1,"rajas":0}},{"label":"I find inertia easy to shift","value":"I find inertia easy to shift","weights":{"tamas":0,"sattva":0.5,"rajas":0.5}},{"label":"I rarely meet it — something is always in motion","value":"I rarely meet it — something is always in motion","weights":{"tamas":0,"sattva":0,"rajas":1}}]},{"id":"guna-dominant","type":"choice","prompt":"Which of these three is doing most of the work in you right now?","domain":"dominant","options":[{"label":"I feel heavy, and it is hard to get going","value":"I feel heavy, and it is hard to get going","weights":{"tamas":1}},{"label":"I am moving, but I do not know where","value":"I am moving, but I do not know where","weights":{"rajas":1}},{"label":"I am clear, and things fall into place","value":"I am clear, and things fall into place","weights":{"sattva":1}}]},{"id":"guna-stability","type":"choice","prompt":"How stable is your inner state from day to day?","domain":"stability","options":[{"label":"I swing a lot, and the days are very different","value":"I swing a lot, and the days are very different","weights":{"sattva":0}},{"label":"I am mostly steady, with the odd dip","value":"I am mostly steady, with the odd dip","weights":{"sattva":0.25}},{"label":"I recover quickly, and the day returns","value":"I recover quickly, and the day returns","weights":{"sattva":0.5}},{"label":"I am rarely thrown far","value":"I am rarely thrown far","weights":{"sattva":0.75}},{"label":"I am mostly the same, whatever happens","value":"I am mostly the same, whatever happens","weights":{"sattva":1}}]},{"id":"guna-shift","type":"choice","prompt":"How easily does your state change?","domain":"shift","options":[{"label":"I do not notice it changing","value":"I do not notice it changing","weights":{"tamas":1,"rajas":0,"sattva":0}},{"label":"I notice it after it has happened","value":"I notice it after it has happened","weights":{"tamas":0.5,"rajas":0.5,"sattva":0}},{"label":"I can feel it turning","value":"I can feel it turning","weights":{"tamas":0,"rajas":1,"sattva":0}},{"label":"I can name what moved it","value":"I can name what moved it","weights":{"tamas":0,"rajas":0.5,"sattva":0.5}},{"label":"I can move it deliberately","value":"I can move it deliberately","weights":{"tamas":0,"rajas":0,"sattva":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["sattva","rajas","tamas"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"sattva","label":"Sattva","short":"Clarity, light, and an easy seeing","description":"Clarity and lightness dominate: the mind is steady, the seeing is easy, and what is underneath a situation tends to arrive without being forced. This is the quality most practice is built to develop, and it is not an achievement — it is a state that arrives when the other two are not running the show.","shadow":"Clarity used as a way of not being affected.","color":"amber","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"spirit":0.35,"thought":0.25,"emotion":0.15},"practiceLevels":{"jnana":1,"self-inquiry":1},"tags":["clear","luminous"]}},{"id":"rajas","label":"Rajas","short":"Movement, heat, and a forward lean","description":"Movement and desire dominate: the mind wants to do, to achieve, to get somewhere. This is the engine of most lives and most careers, and it is not a flaw — it is how things get built. What it costs is the distance between stimulus and response, which gets shorter every time the engine is rewarded for going faster.","shadow":"Movement that has forgotten where it is going.","color":"orange","masters":["karma","raja"],"calibration":{"dimensions":{"action":0.35,"emotion":0.25,"body":0.15},"practiceLevels":{"karma":1,"raja":1},"domainStress":{"activity":"karma"},"tags":["active","driven"]}},{"id":"tamas","label":"Tamas","short":"Weight, inertia, and a slow turning","description":"Stability and weight dominate: the mind resists change, the body resists movement, and the default state is rest. This is not a defect — it is the quality that holds everything else in place, and a life without any of it would have no continuity. What it costs is the distance between deciding and doing, which can become very large.","shadow":"Inertia read as rest, and rest read as enough.","color":"slate","masters":["body","raja"],"calibration":{"dimensions":{"body":0.35,"thought":0.2,"emotion":0.15},"practiceLevels":{"body":1,"raja":1},"domainStress":{"inertia":"body"},"tags":["heavy","slow-moving"]}}]'::jsonb, '{"loops_to_check":["over-committed","avoidance-map"],"practice_affinity":["body","breath","raja"],"deepens_with":["dosha-constitution","nervous-system-tone"]}'::jsonb, 1, true, false, 100, now())
