-- Trust baseline (Heart)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('trust-baseline', 'Trust baseline', 'How open you begin', 'yogic', 'connection', E'Trust has a starting setting. Whatever it is set to, you tend to begin every new person there, before you know anything about them.\n\nThis looks at that setting: how a stranger is treated in the first minutes, what has to be earned, what a betrayal did to it, whether it has been put back up, and how visible the guard is. It is a description of a starting point, not a verdict on the destination.', '🔓', 7, 9, '[{"id":"trust-first","type":"choice","prompt":"In the first ten minutes with someone new, what happens?","domain":"opening","options":[{"label":"I assess, and disclose almost nothing","value":"I assess, and disclose almost nothing","weights":{"guarded":1}},{"label":"I am warm, but I am watching","value":"I am warm, but I am watching","weights":{"guarded":1}},{"label":"I open up fairly quickly","value":"I open up fairly quickly","weights":{"guarded":1}},{"label":"I open up immediately, before I know anything","value":"I open up immediately, before I know anything","weights":{"guarded":1}},{"label":"I decide within a minute how far this is going to go","value":"I decide within a minute how far this is going to go","weights":{"guarded":1}}]},{"id":"trust-earn","type":"choice","prompt":"What has to happen before you relax with someone?","domain":"conditions","options":[{"label":"A long time — years, sometimes","value":"A long time — years, sometimes","weights":{"guarded":1}},{"label":"Sustained consistency","value":"Sustained consistency","weights":{"guarded":1}},{"label":"One good conversation","value":"One good conversation","weights":{"guarded":1}},{"label":"Very little","value":"Very little","weights":{"guarded":1}},{"label":"Nothing. I decide in advance","value":"Nothing. I decide in advance","weights":{"guarded":1}}]},{"id":"trust-betrayal","type":"choice","prompt":"What did a betrayal do to that starting setting?","domain":"wound","options":[{"label":"Nothing I still notice","value":"Nothing I still notice","weights":{"guarded":1}},{"label":"It is in the past and it is still in there","value":"It is in the past and it is still in there","weights":{"guarded":1}},{"label":"It lowered the setting for everyone","value":"It lowered the setting for everyone","weights":{"guarded":1}},{"label":"It shut me down almost completely","value":"It shut me down almost completely","weights":{"guarded":1}},{"label":"I cannot trace it to one event — it is simply how I am","value":"I cannot trace it to one event — it is simply how I am","weights":{"guarded":1}}]},{"id":"trust-rebuilt","type":"choice","prompt":"Has the setting been put back up since?","domain":"repair","options":[{"label":"I have not tried","value":"I have not tried","weights":{"open":1}},{"label":"I have tried, and it did not hold","value":"I have tried, and it did not hold","weights":{"open":1}},{"label":"Partly","value":"Partly","weights":{"open":1}},{"label":"Mostly","value":"Mostly","weights":{"open":1}},{"label":"It is back, and it is better than it was","value":"It is back, and it is better than it was","weights":{"open":1}}]},{"id":"trust-disclosure","type":"choice","prompt":"How much do you put out there at the start?","domain":"disclosure","options":[{"label":"Almost nothing","value":"Almost nothing","weights":{"guarded":1,"conditional":0,"open":0,"naive-closed":0}},{"label":"Only what is needed to function","value":"Only what is needed to function","weights":{"guarded":0.25,"conditional":0.75,"open":0,"naive-closed":0}},{"label":"A fair amount, fairly quickly","value":"A fair amount, fairly quickly","weights":{"guarded":0,"conditional":0.5,"open":0.5,"naive-closed":0}},{"label":"A great deal, early","value":"A great deal, early","weights":{"guarded":0,"conditional":0,"open":0.75,"naive-closed":0.25}},{"label":"More than is wise","value":"More than is wise","weights":{"guarded":0,"conditional":0,"open":0,"naive-closed":1}}]},{"id":"trust-visible","type":"choice","prompt":"Can other people see the guard?","domain":"legibility","options":[{"label":"Completely invisible","value":"Completely invisible","weights":{"naive-closed":1}},{"label":"Only to people very close to me","value":"Only to people very close to me","weights":{"naive-closed":1}},{"label":"It shows sometimes","value":"It shows sometimes","weights":{"naive-closed":1}},{"label":"It is plainly visible to anyone","value":"It is plainly visible to anyone","weights":{"naive-closed":1}},{"label":"I have told people it is there","value":"I have told people it is there","weights":{"naive-closed":1}}]},{"id":"trust-testing","type":"choice","prompt":"Do you test people?","domain":"testing","options":[{"label":"Never","value":"Never","weights":{"guarded":1}},{"label":"Rarely","value":"Rarely","weights":{"guarded":1}},{"label":"Sometimes","value":"Sometimes","weights":{"guarded":1}},{"label":"Often","value":"Often","weights":{"guarded":1}},{"label":"Most of the time","value":"Most of the time","weights":{"guarded":1}}]},{"id":"trust-body","type":"choice","prompt":"How quickly does your body settle around a new person?","domain":"somatic","options":[{"label":"It does not settle at all","value":"It does not settle at all","weights":{"guarded":1,"conditional":0,"open":0,"naive-closed":0}},{"label":"Slowly","value":"Slowly","weights":{"guarded":0.25,"conditional":0.75,"open":0,"naive-closed":0}},{"label":"Within an hour or so","value":"Within an hour or so","weights":{"guarded":0,"conditional":0.5,"open":0.5,"naive-closed":0}},{"label":"Quite quickly","value":"Quite quickly","weights":{"guarded":0,"conditional":0,"open":0.75,"naive-closed":0.25}},{"label":"Immediately, before I know anything","value":"Immediately, before I know anything","weights":{"guarded":0,"conditional":0,"open":0,"naive-closed":1}}]},{"id":"trust-ask","type":"choice","prompt":"Can you ask someone for what you need?","domain":"asking","options":[{"label":"I do not","value":"I do not","weights":{"guarded":1,"conditional":0,"open":0,"naive-closed":0}},{"label":"Only at breaking point","value":"Only at breaking point","weights":{"guarded":0.25,"conditional":0.75,"open":0,"naive-closed":0}},{"label":"With real difficulty","value":"With real difficulty","weights":{"guarded":0,"conditional":0.5,"open":0.5,"naive-closed":0}},{"label":"Fairly easily","value":"Fairly easily","weights":{"guarded":0,"conditional":0,"open":0.75,"naive-closed":0.25}},{"label":"Yes, plainly, and early","value":"Yes, plainly, and early","weights":{"guarded":0,"conditional":0,"open":0,"naive-closed":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["guarded","conditional","open","naive-closed"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"guarded","label":"Guarded","short":"The door is shut before anyone arrives","description":"The starting setting is closed, and the closing was installed by a specific event. It is doing its job and it is also the reason nothing new gets in. The good news is that a setting is a setting — it can be moved, and it is often faster to move than people expect.","shadow":"Reading the guard as the whole of what you are.","color":"rose","masters":["relationship","witnessing"],"calibration":{"dimensions":{"connection":0.4,"emotion":0.3,"thought":0.15},"practiceLevels":{"relationship":2,"witnessing":1},"domainStress":{"relation":"relationship"},"tags":["guarded","closed-by-default"]}},{"id":"conditional","label":"Conditional","short":"It opens, on evidence","description":"Warmth is available and it is earned over time by consistency. This works, and it is slow, and it means the first meeting is not representative of what you would become. The settings being tested are usually about reliability rather than character.","shadow":"Making the evidence impossible to produce.","color":"amber","masters":["relationship","bhakti"],"calibration":{"dimensions":{"connection":0.3,"emotion":0.25,"action":0.15},"practiceLevels":{"relationship":1,"bhakti":1},"domainStress":{"relation":"relationship"},"tags":["trust-conditional","evidence-based"]}},{"id":"open","label":"Open","short":"The door is genuinely open","description":"People get access relatively early, and the experience of most of them is that it holds. This is a real result, not naivety, and it is maintained by the same things that built it: saying what is true, early and often.","shadow":"Openness that has stopped being chosen.","color":"emerald","masters":["relationship","bhakti"],"calibration":{"dimensions":{"connection":0.35,"spirit":0.2,"emotion":0.2},"practiceLevels":{"relationship":1,"bhakti":1},"tags":["open","consistent"]}},{"id":"naive-closed","label":"Naive-closed","short":"Wide open, then shut — with nothing in between","description":"There is no reliable setting here. Some people get the full thing immediately, and the next betrayal closes the door entirely, and the two states alternate without anything being built in between. Neither one is a decision, so neither one can be revised by argument.","shadow":"Deciding after the fact that the person was the problem, rather than the pattern.","color":"violet","masters":["loop-dissolution","witnessing"],"calibration":{"dimensions":{"connection":0.35,"emotion":0.35,"thought":0.2},"practiceLevels":{"loop-dissolution":1,"witnessing":1},"domainStress":{"relation":"relationship"},"tags":["trust-volatile","unbuilt-baseline"]}}]'::jsonb, '{"loops_to_check":["hypervigilance","avoidant-attachment"],"practice_affinity":["relationship","bhakti"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
