  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('vairagya', 'Vairāgya', 'Dispassion without coldness', 'vedic', 'attachment', E'Vairāgya is the last limb and the one most often faked. It is commonly confused with indifference, with having got over something, or with simply not caring any more.\n\nIt is none of those. It is the capacity to be fully present with something without needing it to be different.', '🍂', 6, 6, '[{"id":"vairagya-want","type":"choice","prompt":"How much do you still want, from the things that once mattered?","domain":"wanting","options":[{"label":"I want it as much as ever","value":"I want it as much as ever","weights":{"detached":0}},{"label":"I want it, and I know it","value":"I want it, and I know it","weights":{"detached":0}},{"label":"The wanting is quieter","value":"The wanting is quieter","weights":{"detached":0}},{"label":"I still want it, and it does not drive me","value":"I still want it, and it does not drive me","weights":{"detached":1}},{"label":"I have stopped wanting most of it","value":"I have stopped wanting most of it","weights":{"detached":0}}]},{"id":"vairagya-catch","type":"choice","prompt":"When wanting shows up, do you notice it, or does it just run you?","domain":"catching","options":[{"label":"Zero — it runs me","value":"Zero — it runs me","weights":{"attached":1,"disenchanted":0,"detached":0,"dispassionate":0}},{"label":"Very narrow","value":"Very narrow","weights":{"attached":0.25,"disenchanted":0.75,"detached":0,"dispassionate":0}},{"label":"Narrow, but present","value":"Narrow, but present","weights":{"attached":0,"disenchanted":0.5,"detached":0.5,"dispassionate":0}},{"label":"Wide enough to choose","value":"Wide enough to choose","weights":{"attached":0,"disenchanted":0,"detached":0.75,"dispassionate":0.25}},{"label":"It arrives and I am simply not in it","value":"It arrives and I am simply not in it","weights":{"attached":0,"disenchanted":0,"detached":0,"dispassionate":1}}]},{"id":"vairagya-cold","type":"choice","prompt":"Have you gone cold on people, or is it still warm?","domain":"warmth","options":[{"label":"I have gone cold, and I do not mind","value":"I have gone cold, and I do not mind","weights":{"dispassionate":0}},{"label":"I have gone cold, and I am not sure I like it","value":"I have gone cold, and I am not sure I like it","weights":{"dispassionate":0.25}},{"label":"Somewhat cooler than before","value":"Somewhat cooler than before","weights":{"dispassionate":0.5}},{"label":"Cooler, but the warmth is still there","value":"Cooler, but the warmth is still there","weights":{"dispassionate":0.75}},{"label":"Free of the wanting and just as warm","value":"Free of the wanting and just as warm","weights":{"dispassionate":1}}]},{"id":"vairagya-hard","type":"choice","prompt":"Is there one specific thing you cannot let go of?","domain":"specific","options":[{"label":"A relationship","value":"A relationship","weights":{"attached":1}},{"label":"A possession or a place","value":"A possession or a place","weights":{"attached":1}},{"label":"A role or an identity","value":"A role or an identity","weights":{"attached":1}},{"label":"An outcome I am waiting on","value":"An outcome I am waiting on","weights":{"attached":1}},{"label":"Nothing specific — it has all loosened","value":"Nothing specific — it has all loosened","weights":{"attached":1}}]},{"id":"vairagya-cost","type":"choice","prompt":"Has letting go cost you anything, or only gained?","domain":"cost","options":[{"label":"Nothing — it was pure gain","value":"Nothing — it was pure gain","weights":{"detached":1}},{"label":"A little numbness","value":"A little numbness","weights":{"detached":1}},{"label":"A real loss, and it was worth it","value":"A real loss, and it was worth it","weights":{"detached":1}},{"label":"A real loss, and I still feel it","value":"A real loss, and I still feel it","weights":{"detached":1}},{"label":"I do not know yet","value":"I do not know yet","weights":{"detached":1}}]},{"id":"vairagya-still","type":"choice","prompt":"Are you still fully in your life, or partly out of it?","domain":"engagement","options":[{"label":"Half of me is somewhere else","value":"Half of me is somewhere else","weights":{"attached":1,"disenchanted":0,"detached":0,"dispassionate":0}},{"label":"Present in body, absent in attention","value":"Present in body, absent in attention","weights":{"attached":0.25,"disenchanted":0.75,"detached":0,"dispassionate":0}},{"label":"Here when it matters","value":"Here when it matters","weights":{"attached":0,"disenchanted":0.5,"detached":0.5,"dispassionate":0}},{"label":"Fully here, most of the time","value":"Fully here, most of the time","weights":{"attached":0,"disenchanted":0,"detached":0.75,"dispassionate":0.25}},{"label":"Committed and not detached from the outcome","value":"Committed and not detached from the outcome","weights":{"attached":0,"disenchanted":0,"detached":0,"dispassionate":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["attached","disenchanted","detached","dispassionate"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"attached","label":"Attached","short":"The wanting still runs things","description":"Wanting is still the deciding force in a good number of your decisions, and it is not a flaw — it is where the work is. Notice that the wanting tends to look reasonable from the inside, which is what makes it hard to see.","shadow":"Reading the intensity of the wanting as evidence you should want it.","color":"orange","masters":["witnessing","jnana"],"calibration":{"dimensions":{"emotion":0.3,"action":0.2,"thought":0.2},"practiceLevels":{"witnessing":1,"jnana":1},"tags":["vairagya","attached"]}},{"id":"disenchanted","label":"Disenchanted","short":"The wanting has cooled, and so has everything else","description":"The interest has gone out of things that once held you, and it has gone out of the people involved too. This is frequently mistaken for progress. It is closer to a withdrawal, and it is reversible.","shadow":"Mistaking a low mood for a freed one.","color":"slate","masters":["bhakti","witnessing"],"calibration":{"dimensions":{"emotion":0.3,"connection":0.2,"body":0.15},"practiceLevels":{"bhakti":1,"witnessing":1},"domainStress":{"contact":"relationship"},"tags":["vairagya","disenchanted"]}},{"id":"detached","label":"Detached","short":"You can step back and stay warm","description":"You are no longer driven by the outcome and the warmth is still there. This is a working vairāgya — the thing is still in your life and you are not invested in how it turns out.","shadow":"Letting the detachment become a refusal to care.","color":"teal","masters":["karma","witnessing"],"calibration":{"dimensions":{"action":0.3,"spirit":0.25,"emotion":0.2},"practiceLevels":{"karma":1,"witnessing":1},"tags":["vairagya","detached"]}},{"id":"dispassionate","label":"Dispassionate","short":"Free of the needing, and fully in it","description":"The wanting is no longer the operator, and neither is the absence of wanting. What is left is engagement without a stake in the outcome. The tradition treats this as a stage rather than a destination, because it can still be lost.","shadow":"Confusing the state with having arrived.","color":"emerald","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.4,"emotion":0.25,"action":0.15},"practiceLevels":{"witnessing":2,"jnana":1},"tags":["vairagya","free"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["witnessing","jnana"],"deepens_with":["vairagya-progress","detachment-grade"]}'::jsonb, 1, true, false, 100, now())
