-- Vāsanā map (Loops)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('vasana-map', 'Vāsanā map', 'The habits that run underneath', 'vedic', 'shadow', E'A vāsanā is a groove worn by repetition — not a habit in the ordinary sense, but a channel so worn that the mind falls into it without deciding to. Most of what runs a life is vāsanā: the way the day starts, the way a disagreement ends, the way the mind reacts to a particular tone of voice.\n\nThis asks how much of yours is visible to you. There is no prize at the far end of this one; the reading is a description of how much of your own machinery you can see, and that is the only variable that decides what can be changed.', '🔄', 6, 6, '[{"id":"vasana-visible","type":"choice","prompt":"How many of your own patterns can you actually name?","domain":"visible","options":[{"label":"I cannot name any","value":"I cannot name any","weights":{"active":1,"recurring":0,"recognised":0,"releasing":0}},{"label":"One, if I think about it","value":"One, if I think about it","weights":{"active":0.25,"recurring":0.75,"recognised":0,"releasing":0}},{"label":"A handful, and I know them roughly","value":"A handful, and I know them roughly","weights":{"active":0,"recurring":0.5,"recognised":0.5,"releasing":0}},{"label":"Most of them, and I can describe them","value":"Most of them, and I can describe them","weights":{"active":0,"recurring":0,"recognised":0.75,"releasing":0.25}},{"label":"All of them, and I have worked on several","value":"All of them, and I have worked on several","weights":{"active":0,"recurring":0,"recognised":0,"releasing":1}}]},{"id":"vasana-trigger","type":"choice","prompt":"What triggers your most automatic response?","domain":"trigger","options":[{"label":"I do not notice the trigger until afterwards","value":"I do not notice the trigger until afterwards","weights":{"active":1,"recurring":0,"recognised":0,"releasing":0}},{"label":"I notice something has happened, but not what","value":"I notice something has happened, but not what","weights":{"active":0,"recurring":1,"recognised":0,"releasing":0}},{"label":"I can name the trigger while it is running","value":"I can name the trigger while it is running","weights":{"active":0,"recurring":0,"recognised":1,"releasing":0}},{"label":"I can see it coming, and I can choose","value":"I can see it coming, and I can choose","weights":{"active":0,"recurring":0,"recognised":0,"releasing":1}}]},{"id":"vasana-interrupt","type":"choice","prompt":"What can actually interrupt an automatic pattern?","domain":"interruption","options":[{"label":"Nothing does, and I have stopped expecting it to","value":"Nothing does, and I have stopped expecting it to","weights":{"active":1,"recurring":0,"recognised":0,"releasing":0}},{"label":"Something external sometimes stops it","value":"Something external sometimes stops it","weights":{"active":0.25,"recurring":0.75,"recognised":0,"releasing":0}},{"label":"I can sometimes catch it in time","value":"I can sometimes catch it in time","weights":{"active":0,"recurring":0.5,"recognised":0.5,"releasing":0}},{"label":"I can usually find the off switch","value":"I can usually find the off switch","weights":{"active":0,"recurring":0,"recognised":0.75,"releasing":0.25}},{"label":"I can interrupt it before it starts","value":"I can interrupt it before it starts","weights":{"active":0,"recurring":0,"recognised":0,"releasing":1}}]},{"id":"vasana-recognition","type":"choice","prompt":"How quickly do you recognise a pattern in yourself?","domain":"recognition","options":[{"label":"I never recognise it until afterwards","value":"I never recognise it until afterwards","weights":{"recognised":0}},{"label":"Hours, if ever","value":"Hours, if ever","weights":{"recognised":0.25}},{"label":"Usually within the day","value":"Usually within the day","weights":{"recognised":0.5}},{"label":"Usually while it is happening","value":"Usually while it is happening","weights":{"recognised":0.75}},{"label":"Usually before it starts","value":"Usually before it starts","weights":{"recognised":1}}]},{"id":"vasana-source","type":"choice","prompt":"Where did the pattern come from?","domain":"source","options":[{"label":"I have no idea where it came from","value":"I have no idea where it came from","weights":{"active":1,"recurring":0,"recognised":0,"releasing":0}},{"label":"I suspect it came from somewhere early","value":"I suspect it came from somewhere early","weights":{"active":0.25,"recurring":0.75,"recognised":0,"releasing":0}},{"label":"I can see it was learned from someone","value":"I can see it was learned from someone","weights":{"active":0,"recurring":0.5,"recognised":0.5,"releasing":0}},{"label":"I can see the exact situation where it was installed","value":"I can see the exact situation where it was installed","weights":{"active":0,"recurring":0,"recognised":0.75,"releasing":0.25}},{"label":"I have traced it, and I understand the mechanism","value":"I have traced it, and I understand the mechanism","weights":{"active":0,"recurring":0,"recognised":0,"releasing":1}}]},{"id":"vasana-cost","type":"choice","prompt":"How much does the pattern cost you?","domain":"cost","options":[{"label":"I do not think it costs anything","value":"I do not think it costs anything","weights":{"active":1,"recurring":0,"recognised":0,"releasing":0}},{"label":"A little, but it is not important","value":"A little, but it is not important","weights":{"active":0.25,"recurring":0.75,"recognised":0,"releasing":0}},{"label":"A noticeable amount, and I have felt it","value":"A noticeable amount, and I have felt it","weights":{"active":0,"recurring":0.5,"recognised":0.5,"releasing":0}},{"label":"A great deal, and I have counted it","value":"A great deal, and I have counted it","weights":{"active":0,"recurring":0,"recognised":0.75,"releasing":0.25}},{"label":"I have counted it, and I have started to change it","value":"I have counted it, and I have started to change it","weights":{"active":0,"recurring":0,"recognised":0,"releasing":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["active","recurring","recognised","releasing"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"active","label":"Active","short":"It runs, and you do not see it","description":"The pattern is running and you are inside it. This is the most honest position, because it admits that the machinery is operating without consent — which is the condition of every vāsanā before it is seen.","shadow":"Reading the absence of a map as the absence of a pattern.","color":"slate","masters":["witnessing","observation"],"calibration":{"dimensions":{"thought":0.3,"emotion":0.2,"body":0.15},"practiceLevels":{"witnessing":1,"observation":1},"domainStress":{"unseen":"witnessing"},"tags":["unseen","running"]}},{"id":"recurring","label":"Recurring","short":"You see it afterwards, and it returns","description":"The pattern is visible in hindsight but not in time. It returns without being invited, and the recognition usually arrives after the event has finished. This is the position most people are in for most of their adult lives.","shadow":"Analysing the pattern instead of catching it.","color":"orange","masters":["witnessing","loop-dissolution"],"calibration":{"dimensions":{"thought":0.25,"emotion":0.25,"spirit":0.15},"practiceLevels":{"witnessing":1,"loop-dissolution":1},"domainStress":{"recurrence":"loop-dissolution"},"tags":["recurring","retrospective"]}},{"id":"recognised","label":"Recognised","short":"You can name it while it runs","description":"The pattern is legible while it is happening, which is the point at which it stops being a mood and becomes material. Recognition does not stop the pattern — it makes it available to work with, which is a different thing entirely.","shadow":"Naming the pattern and mistaking the name for the change.","color":"amber","masters":["loop-dissolution","self-inquiry"],"calibration":{"dimensions":{"thought":0.3,"spirit":0.2,"emotion":0.15},"practiceLevels":{"loop-dissolution":2,"self-inquiry":1},"tags":["recognised","named"]}},{"id":"releasing","label":"Releasing","short":"You can choose not to follow it","description":"The pattern is visible, and something in you can choose not to follow it. This is not the same as the pattern being gone — vāsanās do not disappear, they become less compelling. The release is the moment between the trigger and the response, and it gets wider with practice.","shadow":"Treating an occasional release as the pattern being finished.","color":"emerald","masters":["loop-dissolution","witnessing"],"calibration":{"dimensions":{"spirit":0.3,"action":0.2,"thought":0.2},"practiceLevels":{"loop-dissolution":2,"witnessing":1},"domainStress":{"release":"loop-dissolution"},"tags":["releasing","choosing"]}}]'::jsonb, '{"loops_to_check":["reactivity","approval-seeking","inherited-pattern"],"practice_affinity":["loop-dissolution","witnessing"],"deepens_with":["klesha-map","shadow-inventory"]}'::jsonb, 1, true, false, 100, now())
