-- Vitality index (Engines)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('vitality-index', 'Vitality index', 'Your available life-force today', 'yogic', 'vitality', E'Vitality is not the same as strength, and not the same as mood. It is the amount actually available — how much is in the tank, how quickly it comes back, and how much of it is yours rather than borrowed from tomorrow.\n\nThis is a reading of today. Vitality moves daily, and a low reading on a bad week is information about the week rather than a measurement of the person.', '⚡', 6, 8, '[{"id":"vital-strength","type":"choice","prompt":"How strong do you actually feel, physically?","domain":"strength","options":[{"label":"I could barely lift anything","value":"I could barely lift anything","weights":{"drained":1}},{"label":"I can manage the basics","value":"I can manage the basics","weights":{"drained":0.5,"functional":0.5}},{"label":"I can carry and move things easily","value":"I can carry and move things easily","weights":{"functional":1}},{"label":"I am genuinely strong","value":"I am genuinely strong","weights":{"strong":1}},{"label":"I am stronger than I have been for years","value":"I am stronger than I have been for years","weights":{"vital":1}}]},{"id":"vital-stamina","type":"choice","prompt":"How long can you keep going before you have to stop?","domain":"stamina","options":[{"label":"I cannot last more than a short while","value":"I cannot last more than a short while","weights":{"drained":1}},{"label":"I run out well before the day is over","value":"I run out well before the day is over","weights":{"drained":0.75,"functional":0.25}},{"label":"I last the working day","value":"I last the working day","weights":{"functional":1}},{"label":"I could go on considerably longer","value":"I could go on considerably longer","weights":{"functional":0.25,"strong":0.75}},{"label":"I honestly do not know where I would stop","value":"I honestly do not know where I would stop","weights":{"strong":0.25,"vital":0.75}}]},{"id":"vital-recovery","type":"choice","prompt":"How quickly do you get back after something has taken it out of you?","domain":"recovery","options":[{"label":"It takes days, if it comes at all","value":"It takes days, if it comes at all","weights":{"drained":1}},{"label":"It takes a day or two","value":"It takes a day or two","weights":{"drained":0.75,"functional":0.25}},{"label":"A good night puts it right","value":"A good night puts it right","weights":{"functional":1}},{"label":"An hour or two","value":"An hour or two","weights":{"functional":0.25,"strong":0.75}},{"label":"Almost immediately","value":"Almost immediately","weights":{"strong":0.25,"vital":0.75}}]},{"id":"vital-drive","type":"choice","prompt":"How much do you want to do things?","domain":"drive","options":[{"label":"Nothing in me is going anywhere","value":"Nothing in me is going anywhere","weights":{"drained":1}},{"label":"Only when something forces it","value":"Only when something forces it","weights":{"drained":0.5,"functional":0.5}},{"label":"On and off, depending on the day","value":"On and off, depending on the day","weights":{"functional":1}},{"label":"There is a fairly steady push","value":"There is a fairly steady push","weights":{"strong":1}},{"label":"I want to do things before anything asks me to","value":"I want to do things before anything asks me to","weights":{"vital":1}}]},{"id":"vital-morning-evening","type":"choice","prompt":"How much do you change between the morning and the evening?","domain":"rhythm","options":[{"label":"I am a different person by the evening","value":"I am a different person by the evening","weights":{"drained":1}},{"label":"I am markedly emptier","value":"I am markedly emptier","weights":{"drained":0.75,"functional":0.25}},{"label":"A little better in the morning than the evening","value":"A little better in the morning than the evening","weights":{"functional":1}},{"label":"Not much difference either way","value":"Not much difference either way","weights":{"functional":0.25,"strong":0.75}},{"label":"Better in the evening than in the morning","value":"Better in the evening than in the morning","weights":{"strong":0.25,"vital":0.75}}]},{"id":"vital-illness","type":"choice","prompt":"When you are unwell, how much does it take out of you?","domain":"illness","options":[{"label":"Everything — it takes a long time to come back from","value":"Everything — it takes a long time to come back from","weights":{"drained":1}},{"label":"A great deal, and slowly","value":"A great deal, and slowly","weights":{"drained":0.75,"functional":0.25}},{"label":"A fair amount, but I am back within a week or so","value":"A fair amount, but I am back within a week or so","weights":{"functional":1}},{"label":"Not much — I rest properly and carry on","value":"Not much — I rest properly and carry on","weights":{"strong":1}},{"label":"Very little; I take it in hand and keep going","value":"Very little; I take it in hand and keep going","weights":{"vital":1}}]},{"id":"vital-borrowed","type":"choice","prompt":"Are you running on your own energy, or on borrowed momentum?","domain":"source","options":[{"label":"Nearly all of it is borrowed","value":"Nearly all of it is borrowed","weights":{"drained":1}},{"label":"A good deal of it is","value":"A good deal of it is","weights":{"drained":0.75,"functional":0.25}},{"label":"Some of it","value":"Some of it","weights":{"functional":1}},{"label":"Mostly my own","value":"Mostly my own","weights":{"functional":0.25,"strong":0.75}},{"label":"Entirely my own","value":"Entirely my own","weights":{"strong":0.25,"vital":0.75}}]},{"id":"vital-direct","type":"choice","prompt":"How much of your vitality do you actually feel in the body?","domain":"awareness","options":[{"label":"I never feel any, whatever I have","value":"I never feel any, whatever I have","weights":{"drained":1}},{"label":"Only when I have used it all","value":"Only when I have used it all","weights":{"drained":0.75,"functional":0.25}},{"label":"In the morning, faintly","value":"In the morning, faintly","weights":{"functional":1}},{"label":"Most of the time, in the body","value":"Most of the time, in the body","weights":{"functional":0.25,"strong":0.75}},{"label":"It is the first thing I am aware of","value":"It is the first thing I am aware of","weights":{"strong":0.25,"vital":0.75}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["drained","functional","strong","vital"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"drained","label":"Drained","short":"The tank is under the water line","description":"There is not much available at the moment, and asking for more from this state tends to make the hole deeper. This reading is about today and this week; it is not a measurement of what becomes available once things are rested.","shadow":"Reading depletion as a lack of will.","color":"rose","masters":["body","breath"],"calibration":{"dimensions":{"body":0.4,"spirit":0.15,"action":0.15},"practiceLevels":{"body":1,"breath":1},"domainStress":{"energy":"health"},"tags":["depleted","needs-recovery"]}},{"id":"functional","label":"Functional","short":"Enough to do what is in front of you","description":"The reserve covers an ordinary day without either abundance or strain. Nothing dramatic is happening here, which makes it a good place to build from — most sustainable capacity is grown out of a functioning base rather than out of abundance.","shadow":"Mistaking enough for a ceiling.","color":"amber","masters":["body","raja"],"calibration":{"dimensions":{"body":0.25,"action":0.25,"spirit":0.15},"practiceLevels":{"body":1,"raja":1},"tags":["adequate","working"]}},{"id":"strong","label":"Strong","short":"Real capacity, and it comes back quickly","description":"There is depth here and the return is fast, so the system can take a great deal and put it down again. The question at this level is less about the reserve and more about what is being asked of it.","shadow":"Strong enough to keep going, and so never stopping.","color":"teal","masters":["raja","karma"],"calibration":{"dimensions":{"body":0.3,"action":0.25,"connection":0.15},"practiceLevels":{"raja":1,"karma":1},"tags":["resourced","recovering"]}},{"id":"vital","label":"Vital","short":"The energy is there, and it is felt","description":"Capacity is high, it returns quickly, and it is directly felt in the body rather than inferred. Reserve of this kind tends to be spent as much as used, and is worth noticing as a resource rather than as a permanent condition.","shadow":"Reserve spent as though it were unlimited.","color":"emerald","masters":["raja","kriya"],"calibration":{"dimensions":{"body":0.3,"action":0.2,"spirit":0.25},"practiceLevels":{"raja":1},"tags":["vital","well-stocked"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["body","breath"],"deepens_with":["energy-baseline","sleep-signature"]}'::jsonb, 1, true, false, 100, now())
