  updated_at
) VALUES
    ('vulnerability-threshold', 'Vulnerability threshold', 'How close you let people get', 'yogic', 'connection', E'There is a line where disclosure stops being safe, and everyone has one. Where it sits is not a measure of trust or of health — some lines sit very close, some very far, and both are workable.\n\nThis looks at where your line is, what has happened near it, and what the crossing of it actually feels like from the inside.', '🫂', 6, 8, '[{"id":"vuln-disclose","type":"choice","prompt":"How much of what is going on inside you do other people get to know?","domain":"amount","options":[{"label":"Almost nothing of it reaches anyone","value":"Almost nothing of it reaches anyone","weights":{"fortified":1,"selective":0,"open":0,"unprotected":0}},{"label":"A very small amount, to one or two people","value":"A very small amount, to one or two people","weights":{"fortified":0.25,"selective":0.75,"open":0,"unprotected":0}},{"label":"What the moment calls for, and not much more","value":"What the moment calls for, and not much more","weights":{"fortified":0,"selective":0.5,"open":0.5,"unprotected":0}},{"label":"A great deal, once trust has been built","value":"A great deal, once trust has been built","weights":{"fortified":0,"selective":0,"open":0.75,"unprotected":0.25}},{"label":"Nearly everything, almost as it happens","value":"Nearly everything, almost as it happens","weights":{"fortified":0,"selective":0,"open":0,"unprotected":1}}]},{"id":"vuln-known","type":"choice","prompt":"How does it feel to be known properly?","domain":"being-known","options":[{"label":"Being known is the thing I want most","value":"Being known is the thing I want most","weights":{"fortified":0}},{"label":"I want it, and it costs me something","value":"I want it, and it costs me something","weights":{"fortified":0.25}},{"label":"It is mixed, depending on who it is","value":"It is mixed, depending on who it is","weights":{"fortified":0.5}},{"label":"Being known is mostly something I avoid","value":"Being known is mostly something I avoid","weights":{"fortified":0.75}},{"label":"Being known is close to unbearable","value":"Being known is close to unbearable","weights":{"fortified":1}}]},{"id":"vuln-choice","type":"choice","prompt":"Does closeness happen because you chose it, or because it happened to you?","domain":"chosen","options":[{"label":"I never choose it — closeness arrives and I either allow it or I do not","value":"I never choose it — closeness arrives and I either allow it or I do not","weights":{"open":0}},{"label":"I allow it more often than I initiate it","value":"I allow it more often than I initiate it","weights":{"open":0.25}},{"label":"It is roughly half choosing and half allowing","value":"It is roughly half choosing and half allowing","weights":{"open":0.5}},{"label":"I mostly initiate it myself","value":"I mostly initiate it myself","weights":{"open":0.75}},{"label":"I choose closeness deliberately, as a practice","value":"I choose closeness deliberately, as a practice","weights":{"open":1}}]},{"id":"vuln-threshold","type":"choice","prompt":"What happens at the moment it gets close?","domain":"edge","options":[{"label":"Everything shuts, and I say nothing at all","value":"Everything shuts, and I say nothing at all","weights":{"fortified":1,"selective":0,"open":0,"unprotected":0}},{"label":"I notice the moment and talk myself out of it","value":"I notice the moment and talk myself out of it","weights":{"fortified":0.25,"selective":0.75,"open":0,"unprotected":0}},{"label":"I test the water before saying anything real","value":"I test the water before saying anything real","weights":{"fortified":0,"selective":0.5,"open":0.5,"unprotected":0}},{"label":"I say the true thing and find out what happens","value":"I say the true thing and find out what happens","weights":{"fortified":0,"selective":0,"open":0.75,"unprotected":0.25}},{"label":"I go past the point where I usually stop, on purpose","value":"I go past the point where I usually stop, on purpose","weights":{"fortified":0,"selective":0,"open":0,"unprotected":1}}]},{"id":"vuln-past","type":"choice","prompt":"How much do you hand over that you did not mean to?","domain":"over-giving","options":[{"label":"I keep everything in, always","value":"I keep everything in, always","weights":{"unprotected":0}},{"label":"I rarely go past what was asked","value":"I rarely go past what was asked","weights":{"unprotected":0.25}},{"label":"I say what I feel and then judge the effect afterwards","value":"I say what I feel and then judge the effect afterwards","weights":{"unprotected":0.5}},{"label":"I often say or show more than I meant to","value":"I often say or show more than I meant to","weights":{"unprotected":0.75}},{"label":"I hand over far more than the moment ever required","value":"I hand over far more than the moment ever required","weights":{"unprotected":1}}]},{"id":"vuln-reciprocal","type":"choice","prompt":"Does the disclosure run both ways?","domain":"exchange","options":[{"label":"I give and receive very little of either","value":"I give and receive very little of either","weights":{"unprotected":0}},{"label":"I say more than I hear back","value":"I say more than I hear back","weights":{"unprotected":0.25}},{"label":"It is roughly even, at a low level","value":"It is roughly even, at a low level","weights":{"unprotected":0.5}},{"label":"It is even, and at some depth","value":"It is even, and at some depth","weights":{"unprotected":0.75}},{"label":"I say the most in the company of people who also say a lot","value":"I say the most in the company of people who also say a lot","weights":{"unprotected":1}}]},{"id":"vuln-cost","type":"choice","prompt":"What has your current setting cost you?","domain":"price","options":[{"label":"Nothing I can point to","value":"Nothing I can point to","weights":{"fortified":0}},{"label":"Closeness, quietly and repeatedly","value":"Closeness, quietly and repeatedly","weights":{"fortified":0.25}},{"label":"A relationship or two that did not survive it","value":"A relationship or two that did not survive it","weights":{"fortified":0.5}},{"label":"Something I still think about at odd hours","value":"Something I still think about at odd hours","weights":{"fortified":0.75}},{"label":"The thing I most wanted, and did not get","value":"The thing I most wanted, and did not get","weights":{"fortified":1}}]},{"id":"vuln-layer","type":"choice","prompt":"What would it take to go one layer further?","domain":"next-layer","options":[{"label":"I cannot imagine any set of circumstances","value":"I cannot imagine any set of circumstances","weights":{"fortified":1,"selective":0,"open":0,"unprotected":0}},{"label":"Only with one particular person, and only if they started","value":"Only with one particular person, and only if they started","weights":{"fortified":0.25,"selective":0.75,"open":0,"unprotected":0}},{"label":"If the other person went first, I might follow","value":"If the other person went first, I might follow","weights":{"fortified":0,"selective":0.5,"open":0.5,"unprotected":0}},{"label":"If the moment came and I stayed in it rather than leaving","value":"If the moment came and I stayed in it rather than leaving","weights":{"fortified":0,"selective":0,"open":0.75,"unprotected":0.25}},{"label":"I already do this regularly, and it is not remarkable to me","value":"I already do this regularly, and it is not remarkable to me","weights":{"fortified":0,"selective":0,"open":0,"unprotected":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["fortified","selective","open","unprotected"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"fortified","label":"Fortified","short":"Very little gets across the line","description":"The threshold is far back and the line holds reliably. This buys a great deal of safety and costs a particular kind of contact, and the cost is invisible from inside because nothing is arriving to be hurt by. Most of the available movement is in the conditions, not in the resolve.","shadow":"Reading the absence of damage as the absence of anything.","color":"slate","masters":["witnessing","bhakti"],"calibration":{"dimensions":{"connection":0.2,"emotion":0.25,"thought":0.2},"practiceLevels":{"witnessing":1,"bhakti":1},"domainStress":{"contact":"relationship"},"tags":["fortified","guarded"]}},{"id":"selective","label":"Selective","short":"A few people get past the line","description":"Depth happens, but only with a short list, and usually after a long qualifying period. This produces a few relationships of real depth and a wider field of pleasant distance, and the two are rarely distinguished from the outside.","shadow":"The few carrying what the many never hear.","color":"rose","masters":["relationship","witnessing"],"calibration":{"dimensions":{"connection":0.3,"emotion":0.25,"spirit":0.1},"practiceLevels":{"relationship":1,"witnessing":1},"domainStress":{"relation":"relationship"},"tags":["selective","narrow-deep"]}},{"id":"open","label":"Open","short":"Depth is chosen, and chosen well","description":"Closeness is something you go towards, and the line moves depending on the person and the moment. This is a workable setting: the threshold is real, known, and adjustable, which is what makes it a threshold rather than a wall.","shadow":"Discretion worn thin by habit.","color":"teal","masters":["relationship","bhakti"],"calibration":{"dimensions":{"connection":0.35,"spirit":0.15,"emotion":0.15},"practiceLevels":{"relationship":1,"bhakti":1},"tags":["open","chosen-depth"]}},{"id":"unprotected","label":"Unprotected","short":"Very little between you and anyone","description":"The line sits very close, and most of what is there gets said. There is a real generosity in this, and a real exposure, and the two arrive together. What sustains it is not courage but the repeated discovery that the other side holds.","shadow":"Depth given away rather than shared.","color":"amber","masters":["bhakti","relationship"],"calibration":{"dimensions":{"connection":0.4,"emotion":0.2,"spirit":0.1},"practiceLevels":{"bhakti":1,"relationship":1},"domainStress":{"relation":"relationship"},"tags":["unprotected","high-disclosure"]}}]'::jsonb, '{"loops_to_check":["avoidance","over-giving"],"practice_affinity":["relationship","bhakti"],"deepens_with":[]}'::jsonb, 1, true, false, 100, now())
