-- Memory as a field (Loops)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('witchcraft-karma-memory', 'Memory as a field', 'The past as something other than past', 'vedic', 'shadow', E'Some traditions treat what came before as still present — not as history, but as material. In that framing an inherited disposition is a sṃskāra: an impression left somewhere and still available.\n\nThis does not ask whether that is true, and nothing here is evidence for it. It asks something much narrower: how you treat it. Whether it is dismissed, whether it is examined, whether it is worked with, and whether it can eventually be spoken about plainly.', '🜏', 6, 7, '[{"id":"field-usefulness","type":"choice","prompt":"How useful do you find the idea that what came before is still operating?","domain":"stance","options":[{"label":"It does not — I think it is a story","value":"It does not — I think it is a story","weights":{"disbelief":0}},{"label":"Not much","value":"Not much","weights":{"disbelief":0.25}},{"label":"It has been useful occasionally","value":"It has been useful occasionally","weights":{"disbelief":0.5}},{"label":"It has been useful more than once","value":"It has been useful more than once","weights":{"disbelief":0.75}},{"label":"It is one of the more useful frames I have","value":"It is one of the more useful frames I have","weights":{"disbelief":1}}]},{"id":"field-questioning","type":"choice","prompt":"How often do you look at something you do and wonder where it was installed?","domain":"interest","options":[{"label":"Almost never","value":"Almost never","weights":{"curiosity":0}},{"label":"Rarely, and usually about other people","value":"Rarely, and usually about other people","weights":{"curiosity":0.25}},{"label":"Fairly often","value":"Fairly often","weights":{"curiosity":0.5}},{"label":"Most weeks, about myself","value":"Most weeks, about myself","weights":{"curiosity":0.75}},{"label":"It is one of my standing questions","value":"It is one of my standing questions","weights":{"curiosity":1}}]},{"id":"field-practice","type":"choice","prompt":"How much time do you give to something from before this life — a story, a discipline, a silence you did not choose?","domain":"practice","options":[{"label":"None","value":"None","weights":{"active-work":0}},{"label":"Occasionally, when something surfaces","value":"Occasionally, when something surfaces","weights":{"active-work":0.25}},{"label":"A few times a year","value":"A few times a year","weights":{"active-work":0.5}},{"label":"Regularly, as part of how I work","value":"Regularly, as part of how I work","weights":{"active-work":0.75}},{"label":"It is a substantial part of how I live","value":"It is a substantial part of how I live","weights":{"active-work":1}}]},{"id":"field-boundary","type":"choice","prompt":"How careful are you about handing other people’s material back to them?","domain":"restraint","options":[{"label":"I take what applies to me, whoever it came from","value":"I take what applies to me, whoever it came from","weights":{"curiosity":0}},{"label":"I rarely ask whose it was first","value":"I rarely ask whose it was first","weights":{"curiosity":0.25}},{"label":"I ask, sometimes","value":"I ask, sometimes","weights":{"curiosity":0.5}},{"label":"I ask, and I check before I use it","value":"I ask, and I check before I use it","weights":{"curiosity":0.75}},{"label":"I keep other people’s material separate from mine as a matter of course","value":"I keep other people’s material separate from mine as a matter of course","weights":{"curiosity":1}}]},{"id":"field-evidence","type":"choice","prompt":"How do you tell the difference between something inherited and something that is yours?","domain":"evidence","options":[{"label":"I do not distinguish between them","value":"I do not distinguish between them","weights":{"disbelief":1,"curiosity":0,"active-work":0,"integrated":0}},{"label":"I assume whatever feels old must be inherited","value":"I assume whatever feels old must be inherited","weights":{"disbelief":0.25,"curiosity":0.75,"active-work":0,"integrated":0}},{"label":"I ask people, and get several different answers","value":"I ask people, and get several different answers","weights":{"disbelief":0,"curiosity":0.5,"active-work":0.5,"integrated":0}},{"label":"I keep track of what actually repeats, over years","value":"I keep track of what actually repeats, over years","weights":{"disbelief":0,"curiosity":0,"active-work":0.75,"integrated":0.25}},{"label":"I have a rough sense of it, and I still get it wrong fairly often","value":"I have a rough sense of it, and I still get it wrong fairly often","weights":{"disbelief":0,"curiosity":0,"active-work":0,"integrated":1}}]},{"id":"field-keep","type":"choice","prompt":"How much of what you were given, without being asked, have you deliberately kept?","domain":"inheritance","options":[{"label":"Whatever I could not get rid of","value":"Whatever I could not get rid of","weights":{"active-work":0}},{"label":"Very little, deliberately","value":"Very little, deliberately","weights":{"active-work":0.25}},{"label":"Some — a few things I have chosen","value":"Some — a few things I have chosen","weights":{"active-work":0.5}},{"label":"A fair amount, chosen and kept","value":"A fair amount, chosen and kept","weights":{"active-work":0.75}},{"label":"A great deal, chosen deliberately and worked with","value":"A great deal, chosen deliberately and worked with","weights":{"active-work":1}}]},{"id":"field-speech","type":"choice","prompt":"How much of what came before can you talk about plainly?","domain":"speech","options":[{"label":"None of it","value":"None of it","weights":{"integrated":0}},{"label":"Only in general terms, and reluctantly","value":"Only in general terms, and reluctantly","weights":{"integrated":0.25}},{"label":"Some, with people who would understand","value":"Some, with people who would understand","weights":{"integrated":0.5}},{"label":"Most of it, if it comes up","value":"Most of it, if it comes up","weights":{"integrated":0.75}},{"label":"All of it, plainly, to anyone who asks","value":"All of it, plainly, to anyone who asks","weights":{"integrated":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["disbelief","curiosity","active-work","integrated"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"disbelief","label":"Dismissed","short":"The frame does no work","description":"Inherited material is treated as either nothing or as a story, and neither position costs anything. There is no error here — the thing simply is not being used, and a frame that is not used does not need to be defended.","shadow":"Using scepticism as a way of avoiding the material.","color":"slate","masters":["observation","self-inquiry"],"calibration":{"dimensions":{"thought":0.2,"spirit":0.2,"emotion":0.15},"practiceLevels":{"observation":1,"self-inquiry":1},"tags":["disbelief","unexamined-frame"]}},{"id":"curiosity","label":"Curious","short":"The question is being asked","description":"You ask where things came from, which is the part of this that actually produces information. Nothing needs to be believed for the question to be worth asking, and it can be asked without ever becoming credulous.","shadow":"Collecting stories without ever checking one.","color":"amber","masters":["witnessing","self-inquiry"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.25,"emotion":0.15},"practiceLevels":{"witnessing":1,"self-inquiry":1},"tags":["curious","inquiring"]}},{"id":"active-work","label":"Active work","short":"Attention is going into it","description":"Real time is being spent on inherited material — reading, tracking, sitting with it. This is where the frame starts to earn its keep, and also where it starts to need boundaries so that other people’s history does not get absorbed wholesale.","shadow":"Appropriating what belonged to someone else.","color":"orange","masters":["karma","witnessing"],"calibration":{"dimensions":{"spirit":0.3,"thought":0.2,"action":0.2},"practiceLevels":{"karma":1,"witnessing":1},"domainStress":{"lineage":"relationship"},"tags":["active-work","engaged-with"]}},{"id":"integrated","label":"Integrated","short":"It is ordinary material now","description":"What came before is simply part of the material you work with, alongside everything else, and can be discussed without anyone having to believe anything. This is a practical position rather than a metaphysical one.","shadow":"The frame itself becoming a place to live.","color":"indigo","masters":["jnana","witnessing"],"calibration":{"dimensions":{"spirit":0.35,"thought":0.2,"connection":0.15},"practiceLevels":{"jnana":1,"witnessing":1},"tags":["integrated","ordinary-material"]}}]'::jsonb, '{"loops_to_check":["inherited-pattern","generational","disbelief"],"practice_affinity":["witnessing","karma"],"deepens_with":["karmic-patterns","shadow-inventory","ancestral-loops"]}'::jsonb, 1, true, false, 100, now())
