-- Witness capacity (Observation)
INSERT INTO public.assessment_definitions (
  slug,
  title,
  subtitle,
  tradition,
  dimension_category,
  intro,
  cover_emoji,
  estimated_minutes,
  question_count,
  questions,
  scoring_logic,
  result_types,
  engine_hooks,
  version,
  is_active,
  is_featured,
  sort_order,
  updated_at
) VALUES
    ('witness-capacity', 'Witness capacity', 'How much you can observe yourself', 'yogic', 'witness', E'Witnessing is a capacity, not a virtue, and like every capacity it exists on a scale. Some people can watch themselves in real time. Some can only reconstruct it afterwards, and a few have never found the vantage point at all.\n\nAll four positions on that scale are workable, and the one you are in says almost nothing about what is available to you. What it changes is the size of the gap between what happens and what you know about it — and that gap is the only place any of this can be worked on.', '👁️', 7, 6, '[{"id":"witness-catch","type":"choice","prompt":"When something happens inside you, when do you notice it?","domain":"catch","options":[{"label":"I do not notice it at the time at all","value":"I do not notice it at the time at all","weights":{"absent":1,"occasional":0,"steady":0,"relentless":0}},{"label":"I notice it once it has finished","value":"I notice it once it has finished","weights":{"absent":0,"occasional":1,"steady":0,"relentless":0}},{"label":"I notice it as it is happening","value":"I notice it as it is happening","weights":{"absent":0,"occasional":0,"steady":1,"relentless":0}},{"label":"I notice it as it starts, and watch the whole of it","value":"I notice it as it starts, and watch the whole of it","weights":{"absent":0,"occasional":0,"steady":0,"relentless":1}}]},{"id":"witness-hour","type":"choice","prompt":"During an ordinary hour, how much of it are you watching?","domain":"moment","options":[{"label":"Almost none of it","value":"Almost none of it","weights":{"absent":0,"occasional":0,"steady":0,"relentless":0}},{"label":"A few minutes scattered through it","value":"A few minutes scattered through it","weights":{"absent":1,"occasional":0,"steady":0,"relentless":0}},{"label":"A fair share of it","value":"A fair share of it","weights":{"absent":0,"occasional":1,"steady":0,"relentless":0}},{"label":"Most of it","value":"Most of it","weights":{"absent":0,"occasional":0,"steady":1,"relentless":0}},{"label":"Nearly all of it, including the boring parts","value":"Nearly all of it, including the boring parts","weights":{"absent":0,"occasional":0,"steady":0,"relentless":1}}]},{"id":"witness-where","type":"choice","prompt":"When you do watch, where is the watcher standing?","domain":"position","options":[{"label":"I cannot find one, and I have stopped looking","value":"I cannot find one, and I have stopped looking","weights":{"absent":1}},{"label":"In the head, mostly, watching thoughts","value":"In the head, mostly, watching thoughts","weights":{"occasional":1}},{"label":"In the head and the body both","value":"In the head and the body both","weights":{"steady":1}},{"label":"Wide — it includes what is around me as well as what is in me","value":"Wide — it includes what is around me as well as what is in me","weights":{"relentless":1}}]},{"id":"witness-after","type":"choice","prompt":"How long after something happens can you still go back and see it?","domain":"aftermath","options":[{"label":"I cannot do it at all","value":"I cannot do it at all","weights":{"absent":1,"occasional":0,"steady":0,"relentless":0}},{"label":"For a few minutes afterwards","value":"For a few minutes afterwards","weights":{"absent":0,"occasional":1,"steady":0,"relentless":0}},{"label":"For a day or two","value":"For a day or two","weights":{"absent":0,"occasional":0,"steady":1,"relentless":0}},{"label":"Years later, and it is still clear","value":"Years later, and it is still clear","weights":{"absent":0,"occasional":0,"steady":0,"relentless":1}}]},{"id":"witness-effort","type":"choice","prompt":"How much effort does watching yourself actually take?","domain":"effort","options":[{"label":"It is not something I am able to do","value":"It is not something I am able to do","weights":{"steady":0}},{"label":"It takes more than I can sustain","value":"It takes more than I can sustain","weights":{"steady":0.25}},{"label":"It is a real effort most of the time","value":"It is a real effort most of the time","weights":{"steady":0.5}},{"label":"It needs very little","value":"It needs very little","weights":{"steady":0.75}},{"label":"It costs me almost nothing","value":"It costs me almost nothing","weights":{"steady":1}}]},{"id":"witness-idle","type":"choice","prompt":"When you are not doing anything, is the watching still there?","domain":"idle","options":[{"label":"It stops the moment I stop","value":"It stops the moment I stop","weights":{"absent":1,"occasional":0,"steady":0,"relentless":0}},{"label":"It comes and goes","value":"It comes and goes","weights":{"absent":0,"occasional":1,"steady":0,"relentless":0}},{"label":"It is there much of the time","value":"It is there much of the time","weights":{"absent":0,"occasional":0,"steady":1,"relentless":0}},{"label":"It is the thing that is still there when everything else stops","value":"It is the thing that is still there when everything else stops","weights":{"absent":0,"occasional":0,"steady":0,"relentless":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["absent","occasional","steady","relentless"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"absent","label":"Absent","short":"There is no vantage point yet","description":"The internal life is happening without being watched, which is not unusual and is not permanent. Nothing here needs to be built from nothing — the first move is usually the crudest possible one, a few minutes a day of paying attention to something dull, which is enough for the vantage point to start existing.","shadow":"Concluding from a single ordinary day that the capacity is absent.","color":"slate","masters":["observation","body"],"calibration":{"dimensions":{"thought":0.2,"body":0.2,"emotion":0.15},"practiceLevels":{"observation":2,"body":1},"domainStress":{"attention":"observation"},"tags":["unwitnessed","beginning"]}},{"id":"occasional","label":"Occasional","short":"The noticing arrives after the fact","description":"The watching happens, but retrospectively — the event is available afterwards rather than during. This is a real capacity, not a failed version of a better one, and it is the direct result of too much of your attention being allocated elsewhere. The work is moving the noticing forward rather than making it deeper.","shadow":"Analysing the pattern instead of catching the instance.","color":"amber","masters":["observation","witnessing"],"calibration":{"dimensions":{"thought":0.25,"spirit":0.2,"emotion":0.15},"practiceLevels":{"observation":1,"witnessing":1},"tags":["retrospective","catching-up"]}},{"id":"steady","label":"Steady","short":"The watching runs while you are in it","description":"The vantage point holds during the event rather than after it, which means reactions can be watched as they form instead of reconstructed. The difficulty at this level is not the seeing but the staying — capacity that is not deliberately supported tends to narrow, and what was available last year is not automatically available now.","shadow":"Mistaking a capacity that works for one that will keep working.","color":"teal","masters":["witnessing","observation"],"calibration":{"dimensions":{"spirit":0.3,"emotion":0.2,"body":0.15},"practiceLevels":{"witnessing":2},"tags":["sustained-witness","present"]}},{"id":"relentless","label":"Relentless","short":"Very little goes unwatched","description":"The watching is continuous and includes the parts most people exclude — the boring, the embarrassing, the sleep. This is a genuine capacity and it carries a specific difficulty, which is that it is easy to start watching everything and including the people you are with. Awareness that stops arriving at other people eventually becomes a way of being absent from them.","shadow":"Using the watching to stay out of the room.","color":"indigo","masters":["witnessing","jnana"],"calibration":{"dimensions":{"spirit":0.45,"thought":0.2},"practiceLevels":{"witnessing":2,"jnana":1},"domainStress":{"contact":"relationship"},"tags":["continuous-witness","deep"]}}]'::jsonb, '{"loops_to_check":["reactivity","self-talk"],"practice_affinity":["witnessing","observation"],"deepens_with":["presence-quality","mind-wandering"]}'::jsonb, 1, true, false, 100, now())
