  sort_order,
  updated_at
) VALUES
    ('work-dharma', 'Work dharma', 'The clarity of your calling', 'vedic', 'action', E'Dharma in the Gita is not a career. It is what is yours to do — the work that arises from what you actually are, rather than from what happened to be available.\n\nThe most common confusion is between a calling and a preference.', '🧭', 6, 6, '[{"id":"work-why","type":"choice","prompt":"Why are you doing the work you are doing?","domain":"motive","options":[{"label":"I have not really chosen it","value":"I have not really chosen it","weights":{"drifting":1}},{"label":"It pays and the options were worse","value":"It pays and the options were worse","weights":{"surviving":1}},{"label":"I am good at it and it went from there","value":"I am good at it and it went from there","weights":{"ambitious":1}},{"label":"I am building toward something specific","value":"I am building toward something specific","weights":{"ambitious":1}},{"label":"Because this is what I am for","value":"Because this is what I am for","weights":{"called":1}}]},{"id":"work-if","type":"choice","prompt":"If money were not a factor, would you do this?","domain":"counterfactual","options":[{"label":"Absolutely not","value":"Absolutely not","weights":{"drifting":1,"surviving":0,"ambitious":0,"called":0}},{"label":"No — I would do something else entirely","value":"No — I would do something else entirely","weights":{"drifting":0.25,"surviving":0.75,"ambitious":0,"called":0}},{"label":"I would do something adjacent","value":"I would do something adjacent","weights":{"drifting":0,"surviving":0.5,"ambitious":0.5,"called":0}},{"label":"Yes, probably the same thing","value":"Yes, probably the same thing","weights":{"drifting":0,"surviving":0,"ambitious":0.75,"called":0.25}},{"label":"Yes, and this is exactly it","value":"Yes, and this is exactly it","weights":{"drifting":0,"surviving":0,"ambitious":0,"called":1}}]},{"id":"work-friction","type":"choice","prompt":"How often do you dread going to work?","domain":"resistance","options":[{"label":"Most weeks","value":"Most weeks","weights":{"drifting":1}},{"label":"Often","value":"Often","weights":{"drifting":1}},{"label":"About half the time","value":"About half the time","weights":{"drifting":1}},{"label":"Rarely","value":"Rarely","weights":{"drifting":1}},{"label":"Almost never","value":"Almost never","weights":{"drifting":1}}]},{"id":"work-gift","type":"choice","prompt":"What can you do that most people cannot?","domain":"signature","options":[{"label":"Neither, honestly","value":"Neither, honestly","weights":{"drifting":1,"surviving":0,"ambitious":0,"called":0}},{"label":"My gift, and I do not know the need","value":"My gift, and I do not know the need","weights":{"drifting":0.25,"surviving":0.75,"ambitious":0,"called":0}},{"label":"The need, and I do not know my gift","value":"The need, and I do not know my gift","weights":{"drifting":0,"surviving":0.5,"ambitious":0.5,"called":0}},{"label":"Both, approximately","value":"Both, approximately","weights":{"drifting":0,"surviving":0,"ambitious":0.75,"called":0.25}},{"label":"Both, and they fit exactly","value":"Both, and they fit exactly","weights":{"drifting":0,"surviving":0,"ambitious":0,"called":1}}]},{"id":"work-avoid","type":"choice","prompt":"Is there work you know you are avoiding?","domain":"avoidance","options":[{"label":"Nothing in particular","value":"Nothing in particular","weights":{"drifting":1}},{"label":"Starting something","value":"Starting something","weights":{"drifting":1}},{"label":"Finishing something","value":"Finishing something","weights":{"drifting":1}},{"label":"Asking for what I am owed","value":"Asking for what I am owed","weights":{"drifting":1}},{"label":"A conversation I have been putting off","value":"A conversation I have been putting off","weights":{"drifting":1}}]},{"id":"work-scale","type":"choice","prompt":"Does what you do matter to anyone other than you?","domain":"impact","options":[{"label":"Only me, really","value":"Only me, really","weights":{"called":1}},{"label":"A very small number of people","value":"A very small number of people","weights":{"called":1}},{"label":"A community I know","value":"A community I know","weights":{"called":1}},{"label":"A lot of people I will never meet","value":"A lot of people I will never meet","weights":{"called":1}},{"label":"I genuinely do not know","value":"I genuinely do not know","weights":{"called":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["drifting","surviving","ambitious","called"],"primary_rule":"highest_sub_score"}'::jsonb, E'[{"id":"drifting","label":"Drifting","short":"It happened rather than being chosen","description":"The work arrived rather than being chosen, and there is no particular attachment to it. This is the most common state and the one where \\"why am I doing this\\" has not been seriously asked yet.","shadow":"Calling a long tenure a vocation.","color":"slate","masters":["work-career","self-inquiry"],"calibration":{"dimensions":{"action":0.3,"thought":0.2,"spirit":0.15},"practiceLevels":{"self-inquiry":1},"domainStress":{"work":"work-career","direction":"self-inquiry"},"tags":["work","undirected"]}},{"id":"surviving","label":"Surviving","short":"It is the option that was least bad","description":"You are doing it because the alternatives were worse, which is a perfectly good reason and is not the same as a reason you would give if the money stopped mattering. The question is what you would build with the difference.","shadow":"Confusing security with purpose.","color":"amber","masters":["work-career","karma"],"calibration":{"dimensions":{"action":0.3,"body":0.2,"emotion":0.2},"practiceLevels":{"karma":1},"domainStress":{"work":"work-career"},"tags":["work","pragmatic"]}},{"id":"ambitious","label":"Ambitious","short":"Building toward something specific","description":"There is a target and real energy behind it. The strength and the risk are the same thing: the target is doing a lot of the motivating, and it is worth noticing what happens to the motivation as it gets close.","shadow":"Confusing the desire to achieve with the desire to matter.","color":"sky","masters":["work-career","karma"],"calibration":{"dimensions":{"action":0.4,"thought":0.2},"practiceLevels":{"karma":1,"raja":1},"domainStress":{"work":"work-career"},"tags":["work","driven"]}},{"id":"called","label":"Called","short":"It is what you are for","description":"The work and the capacity line up, and the reason you are doing it is not circumstantial. The remaining work is the harder half: doing it well enough to deserve it, and staying honest while it gets comfortable.","shadow":"Certainty about the calling replacing attention to the doing.","color":"emerald","masters":["karma","jnana"],"calibration":{"dimensions":{"action":0.4,"spirit":0.3,"connection":0.2},"practiceLevels":{"karma":2,"jnana":1},"domainStress":{"work":"work-career"},"tags":["work","vocation"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["work-career","karma"],"deepens_with":["inner-compass","detachment-grade"]}'::jsonb, 1, true, false, 100, now())
