    ('yamas', 'Yamas', 'Your relational ethics — the five restraints', 'yogic', 'ethics', E'The first limb is a set of five commitments made towards other people. They are called restraints because each one is a limit you agree to keep, not a quality you acquire.\n\nAlmost nobody keeps all five. Which ones are actually live for you is more useful than knowing the list.', '🕊️', 8, 7, '[{"id":"yama-hardest","type":"choice","prompt":"Of the five — not harming, truthfulness, not taking, restraint, and non-hoarding — which is the one you find hardest?","domain":"priority","options":[{"label":"Not causing harm, in a world I cannot control","value":"Not causing harm, in a world I cannot control","weights":{"ahimsa":1}},{"label":"Telling the truth, when it would be easier not to","value":"Telling the truth, when it would be easier not to","weights":{"satya":1}},{"label":"Not taking what is not mine, including in small ways","value":"Not taking what is not mine, including in small ways","weights":{"asteya":1}},{"label":"Restraint, where desire is strong and unexamined","value":"Restraint, where desire is strong and unexamined","weights":{"brahmacharya":1}},{"label":"Non-hoarding, of things and of people","value":"Non-hoarding, of things and of people","weights":{"aparigraha":1}}]},{"id":"yama-easiest","type":"choice","prompt":"And which one do you barely have to try at?","domain":"effort","options":[{"label":"Not causing harm, in a world I cannot control","value":"Not causing harm, in a world I cannot control","weights":{"ahimsa":1}},{"label":"Telling the truth, when it would be easier not to","value":"Telling the truth, when it would be easier not to","weights":{"satya":1}},{"label":"Not taking what is not mine, including in small ways","value":"Not taking what is not mine, including in small ways","weights":{"asteya":1}},{"label":"Restraint, where desire is strong and unexamined","value":"Restraint, where desire is strong and unexamined","weights":{"brahmacharya":1}},{"label":"Non-hoarding, of things and of people","value":"Non-hoarding, of things and of people","weights":{"aparigraha":1}}]},{"id":"yama-truth","type":"choice","prompt":"How often are you completely honest with yourself?","domain":"satya","options":[{"label":"I edit my own account constantly","value":"I edit my own account constantly","weights":{"satya":0}},{"label":"Mostly I am honest, and I soften things","value":"Mostly I am honest, and I soften things","weights":{"satya":0.25}},{"label":"I am honest when it is not costing me","value":"I am honest when it is not costing me","weights":{"satya":0.5}},{"label":"I am honest even when it costs me","value":"I am honest even when it costs me","weights":{"satya":0.75}},{"label":"I would not recognise a flattering version of myself","value":"I would not recognise a flattering version of myself","weights":{"satya":1}}]},{"id":"yama-taking","type":"choice","prompt":"How easy is it for you to take what is not yours — time, credit, ideas, attention?","domain":"asteya","options":[{"label":"Constantly, and I do not notice","value":"Constantly, and I do not notice","weights":{"asteya":0}},{"label":"Often enough that it shows","value":"Often enough that it shows","weights":{"asteya":0.25}},{"label":"Sometimes, usually without harm","value":"Sometimes, usually without harm","weights":{"asteya":0.5}},{"label":"Rarely — I would rather ask","value":"Rarely — I would rather ask","weights":{"asteya":0.75}},{"label":"It is not something I do","value":"It is not something I do","weights":{"asteya":1}}]},{"id":"yama-restraint","type":"choice","prompt":"Where does your desire actually go when it is not managed?","domain":"brahmacharya","options":[{"label":"It is the loudest thing in the room","value":"It is the loudest thing in the room","weights":{"brahmacharya":1}},{"label":"It sets the agenda more often than not","value":"It sets the agenda more often than not","weights":{"brahmacharya":1}},{"label":"It is one motive among several","value":"It is one motive among several","weights":{"brahmacharya":1}},{"label":"It is present and not in charge","value":"It is present and not in charge","weights":{"brahmacharya":1}},{"label":"It rarely decides anything for me","value":"It rarely decides anything for me","weights":{"brahmacharya":1}}]},{"id":"yama-hoarding","type":"choice","prompt":"What are you holding onto that you would not choose to keep?","domain":"aparigraha","options":[{"label":"Possessions, more than I use","value":"Possessions, more than I use","weights":{"aparigraha":1}},{"label":"Commitments I said yes to","value":"Commitments I said yes to","weights":{"aparigraha":1}},{"label":"People I am holding on to","value":"People I am holding on to","weights":{"aparigraha":1}},{"label":"Options I keep open to avoid choosing","value":"Options I keep open to avoid choosing","weights":{"aparigraha":1}},{"label":"Nothing in particular","value":"Nothing in particular","weights":{"aparigraha":1}}]},{"id":"yama-set","type":"choice","prompt":"Do the five feel like rules, or like a description?","domain":"coherence","options":[{"label":"A set of rules I break regularly","value":"A set of rules I break regularly","weights":{"ahimsa":1,"satya":0,"asteya":0,"brahmacharya":0,"aparigraha":0}},{"label":"Rules I try to follow","value":"Rules I try to follow","weights":{"ahimsa":0,"satya":1,"asteya":0,"brahmacharya":0,"aparigraha":0}},{"label":"Habits I am building","value":"Habits I am building","weights":{"ahimsa":0,"satya":0,"asteya":1,"brahmacharya":0,"aparigraha":0}},{"label":"Mostly how I already live","value":"Mostly how I already live","weights":{"ahimsa":0,"satya":0,"asteya":0,"brahmacharya":1,"aparigraha":0}},{"label":"They have become instinct","value":"They have become instinct","weights":{"ahimsa":0,"satya":0,"asteya":0,"brahmacharya":0,"aparigraha":1}}]}]'::jsonb, '{"method":"weighted_sum_percentage","dimensions":["ahimsa","satya","asteya","brahmacharya","aparigraha"],"primary_rule":"highest_sub_score"}'::jsonb, '[{"id":"ahimsa","label":"Ahiṃsā is the live one","short":"Causing harm is the hard problem","description":"Your resistance is around harm. That usually means you are close enough to other people for it to matter, and you are aware that intention and consequence rarely line up. The difficulty here is not usually wanting to hurt — it is noticing, too late, when you have.","shadow":"Equating non-violence with never disappointing anyone.","color":"slate","masters":["karma","witnessing"],"calibration":{"dimensions":{"connection":0.3,"emotion":0.25,"action":0.2},"practiceLevels":{"karma":1,"witnessing":1},"domainStress":{"relation":"relationship"},"tags":["ethics","harm-sensitive"]}},{"id":"satya","label":"Satya is the live one","short":"Truth is where it gets difficult","description":"Honesty is your hard one. Most of what gets in the way is not fear of lying to others — it is the cost of the truth about yourself, and the amount of rewriting that would follow.","shadow":"Confusing honesty with disclosure.","color":"sky","masters":["jnana","self-inquiry"],"calibration":{"dimensions":{"thought":0.35,"spirit":0.2,"emotion":0.15},"practiceLevels":{"jnana":1,"self-inquiry":1},"tags":["ethics","self-honesty"]}},{"id":"asteya","label":"Asteya is the live one","short":"Taking without noticing is the pattern","description":"The hard one is not taking what is loudly yours to take — it is the small, unnoticed appropriation. Time, attention, credit, ideas. It is rarely a large theft and rarely entirely innocent.","shadow":"Believing intention settles the question.","color":"amber","masters":["karma","jnana"],"calibration":{"dimensions":{"action":0.3,"connection":0.25,"thought":0.2},"practiceLevels":{"karma":1},"domainStress":{"work":"work-career"},"tags":["ethics","appropriation"]}},{"id":"brahmacharya","label":"Brahmacarya is the live one","short":"Desire is doing more steering than you signed up for","description":"Restraint is your live question. Desire here is not a problem in itself — it is that it has become the deciding force in more situations than you would choose if you looked.","shadow":"Confusing restraint with suppression.","color":"orange","masters":["raja","witnessing"],"calibration":{"dimensions":{"body":0.3,"emotion":0.25,"action":0.2},"practiceLevels":{"raja":1,"witnessing":1},"tags":["ethics","desire"]}},{"id":"aparigraha","label":"Aparigraha is the live one","short":"What you keep is running your life","description":"Non-hoarding is the hard one. There is an accumulation in your life — things, commitments, people, open options — that you did not choose and have not released, and it is making decisions on your behalf.","shadow":"Mistaking keeping for loyalty.","color":"indigo","masters":["jnana","karma"],"calibration":{"dimensions":{"action":0.3,"thought":0.25,"connection":0.2},"practiceLevels":{"jnana":1,"karma":1},"domainStress":{"work":"work-career"},"tags":["ethics","accumulation"]}}]'::jsonb, '{"loops_to_check":[],"practice_affinity":["raja","karma"],"deepens_with":["niyamas","klesha-map"]}'::jsonb, 1, true, false, 100, now())
